import type { L } from "@/lib/types";

export const CONSPECTS: Record<string, L> = {
  "ns-1-bits": {"ru":"# Язык лампочек: бит и разряды\n\n**Бит** — одна «лампочка»: **0** (не горит) или **1** (горит). Компьютер хранит всё — числа, текст, фото, музыку — нулями и единицами.\n\nВ железе «лампочка» — это транзистор: ток идёт или нет (процессор, ОЗУ); ячейка с зарядом или без (SSD, флешка); намагниченный участок (HDD); ямка на диске (CD, DVD).\n\n## Сколько сигналов дают лампочки\n\nКаждая новая лампочка **удваивает** число сигналов: **N = 2ⁱ** (i — число лампочек или битов).\n\n| Лампочек i | 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 |\n|---|---|---|---|---|---|---|---|---|\n| Сигналов N | 2 | 4 | 8 | 16 | 32 | 64 | 128 | 256 |\n\n## Разряды и их веса\n\n- В десятичной системе **10 цифр** (0–9), веса растут в 10 раз: …, 1000, 100, 10, 1.\n- В двоичной системе **2 цифры** (0 и 1), веса растут в 2 раза. Считаем **справа налево**.\n\n| 2⁷ | 2⁶ | 2⁵ | 2⁴ | 2³ | 2² | 2¹ | 2⁰ |\n|---|---|---|---|---|---|---|---|\n| 128 | 64 | 32 | 16 | 8 | 4 | 2 | 1 |\n\n> 1101₂ = 8 + 4 + 0 + 1 = **13**\n\n## Лайфхаки для ЕНТ\n\n- Число сигналов — это **степень** двойки, а не умножение: 6 лампочек — 2⁶ = 64, а не 6 · 2 = 12.\n- В двоичной записи только цифры **0 и 1**. Встретилась цифра 2 или больше — запись не двоичная.\n- Нужно число лампочек для N сигналов? Ищи наименьшее i, при котором 2ⁱ ≥ N.\n\n## Частые ошибки\n\n- «3 лампочки — 6 сигналов»: сигналы **перемножаются** (2 · 2 · 2 = 8), а не складываются.\n- Веса подписаны слева направо — надо справа налево.\n- Веса растут «как в обычной системе», в 10 раз, — в двоичной они растут в 2 раза.","kk":"# Шамдар тілі: бит және разрядтар\n\n**Бит** — бір «шам»: **0** (жанбайды) немесе **1** (жанады). Компьютер бәрін — сандарды, мәтінді, суретті, музыканы — нөлдермен және бірліктермен сақтайды.\n\nТемірде «шам» — бұл транзистор: ток жүреді немесе жүрмейді (процессор, жедел жад); заряды бар немесе жоқ ұяшық (SSD, флеш-жинақтауыш); магниттелген аймақ (HDD); дискідегі шұңқыр (CD, DVD).\n\n## Шамдар қанша сигнал береді\n\nӘр жаңа шам сигналдар санын **екі есе арттырады**: **N = 2ⁱ** (i — шам немесе бит саны).\n\n| Шам саны i | 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 |\n|---|---|---|---|---|---|---|---|---|\n| Сигнал саны N | 2 | 4 | 8 | 16 | 32 | 64 | 128 | 256 |\n\n## Разрядтар және олардың салмағы\n\n- Ондық жүйеде **10 цифр** бар (0–9), салмақтар 10 есе өседі: …, 1000, 100, 10, 1.\n- Екілік жүйеде **2 цифр** бар (0 және 1), салмақтар 2 есе өседі. **Оңнан солға** қарай санаймыз.\n\n| 2⁷ | 2⁶ | 2⁵ | 2⁴ | 2³ | 2² | 2¹ | 2⁰ |\n|---|---|---|---|---|---|---|---|\n| 128 | 64 | 32 | 16 | 8 | 4 | 2 | 1 |\n\n> 1101₂ = 8 + 4 + 0 + 1 = **13**\n\n## ҰБТ-ға арналған кеңестер\n\n- Сигналдар саны — екінің **дәрежесі**, көбейту емес: 6 шам — 2⁶ = 64, ал 6 · 2 = 12 емес.\n- Екілік жазбада тек **0 және 1** цифрлары болады. 2 немесе одан үлкен цифр кездессе — жазба екілік емес.\n- N сигнал үшін қанша шам керек? 2ⁱ ≥ N болатын ең кіші i-ді тап.\n\n## Жиі кететін қателер\n\n- «3 шам — 6 сигнал»: сигналдар қосылмайды, **көбейтіледі** (2 · 2 · 2 = 8).\n- Салмақтар солдан оңға қарай жазылған — оңнан солға қарай жазу керек.\n- Салмақтар «қарапайым жүйедегідей» 10 есе өседі деп ойлау — екілік жүйеде олар 2 есе өседі."},
  "ns-2-read": {"ru":"# Как прочитать двоичное число (2 → 10)\n\n## Три шага\n\n1. **Подпиши веса справа налево:** 1, 2, 4, 8, 16, 32…\n2. **Под нулём вес не берём** — зачёркиваем.\n3. **Сложи** оставшиеся веса.\n\n> 1101₂ → веса 8, 4, 2, 1 → 8 + 4 + 1 = **13**\n\n## Таблица весов\n\n| 2⁷ | 2⁶ | 2⁵ | 2⁴ | 2³ | 2² | 2¹ | 2⁰ |\n|---|---|---|---|---|---|---|---|\n| 128 | 64 | 32 | 16 | 8 | 4 | 2 | 1 |\n\n## Лайфхаки для ЕНТ\n\n- **Проверка чётности:** запись оканчивается на 1 — число нечётное, на 0 — чётное. Сверь с ответом.\n- Не помнишь веса — удваивай: 1, 2, 4, 8, 16, 32, 64.\n- Всегда начинай с **правого края**: правая цифра — это «единицы».\n- Если в вариантах есть число, прочитанное наоборот, — это ловушка. Выбирай ответ, посчитанный с правого края.\n\n## Частые ошибки\n\n- Веса подписаны **слева направо**: 1101₂ даёт 11 вместо 13.\n- Забыт вес **1** у последней цифры.\n- Сложены веса и под нулями.","kk":"# Екілік санды қалай оқу керек (2 → 10)\n\n## Үш қадам\n\n1. **Салмақтарды оңнан солға қарай жаз:** 1, 2, 4, 8, 16, 32…\n2. **Нөлдің астындағы салмақты алма** — сызып таста.\n3. Қалған салмақтарды **қос**.\n\n> 1101₂ → салмақтар 8, 4, 2, 1 → 8 + 4 + 1 = **13**\n\n## Салмақтар кестесі\n\n| 2⁷ | 2⁶ | 2⁵ | 2⁴ | 2³ | 2² | 2¹ | 2⁰ |\n|---|---|---|---|---|---|---|---|\n| 128 | 64 | 32 | 16 | 8 | 4 | 2 | 1 |\n\n## ҰБТ-ға арналған кеңестер\n\n- **Жұптылықты тексеру:** жазба 1-мен аяқталса — сан тақ, 0-мен аяқталса — жұп. Жауаппен салыстыр.\n- Салмақтарды ұмытсаң — екі есе арттыр: 1, 2, 4, 8, 16, 32, 64.\n- Әрқашан **оң жақ шетінен** баста: оң жақ цифр — «бірліктер».\n- Жауап нұсқаларында керісінше оқылған сан болса — бұл тұзақ. Оң жақтан есептелген жауапты таңда.\n\n## Жиі кететін қателер\n\n- Салмақтар **солдан оңға қарай** жазылған: 1101₂ үшін 13 орнына 11 шығады.\n- Соңғы цифрдың **1** салмағы ұмытылған.\n- Нөлдердің астындағы салмақтар да қосылған."},
  "ns-3-write": {"ru":"# Как записать число двоичным кодом (10 → 2)\n\n## Способ 1: монеты (веса)\n\nБерём **самую большую** степень двойки, которая помещается в остаток. Взятая — **1**, пропущенная — **0**.\n\n> 19: берём 16 (осталось 3), берём 2 (осталось 1), берём 1 → монеты 16, 2, 1 → **10011₂**\n\n## Способ 2: деление на 2\n\nДелим на 2 и записываем остатки, пока частное не станет 0. Читаем остатки **снизу вверх**.\n\n| Деление | Остаток |\n|---|---|\n| 19 : 2 = 9 | 1 |\n| 9 : 2 = 4 | 1 |\n| 4 : 2 = 2 | 0 |\n| 2 : 2 = 1 | 0 |\n| 1 : 2 = 0 | 1 |\n\nСнизу вверх: **10011₂**.\n\n## Проверка обратным переводом\n\nПодпиши веса справа налево и сложи: 10011₂ = 16 + 2 + 1 = 19. Сошлось — ответ верный.\n\n## Лайфхаки для ЕНТ\n\n- **Умножить на 2 — значит дописать 0 справа:** 19 = 10011₂, 38 = 100110₂.\n- Число чётное — запись оканчивается на 0, нечётное — на 1. Так отсеиваются неверные варианты.\n- Среди вариантов всегда есть запись, прочитанная наоборот. Остатки читаем **снизу вверх**.\n- Для небольших чисел быстрее способ с монетами, для больших — деление.\n\n## Частые ошибки\n\n- Остатки прочитаны **сверху вниз**: 6 даёт 011 вместо 110.\n- Потерян последний остаток: 1 : 2 = 0 и остаток **1** — его тоже записываем.\n- В двоичной записи появилась цифра 2 — остаток всегда 0 или 1.","kk":"# Санды екілік кодпен қалай жазу керек (10 → 2)\n\n## 1-тәсіл: монеталар (салмақтар)\n\nҚалдыққа сыятын **ең үлкен** екінің дәрежесін аламыз. Алынғаны — **1**, өткізіп жібергені — **0**.\n\n> 19: 16 аламыз (қалғаны 3), 2 аламыз (қалғаны 1), 1 аламыз → монеталар 16, 2, 1 → **10011₂**\n\n## 2-тәсіл: 2-ге бөлу\n\n2-ге бөліп, бөлінді 0 болғанша қалдықтарды жазамыз. Қалдықтарды **төменнен жоғары** оқимыз.\n\n| Бөлу | Қалдық |\n|---|---|\n| 19 : 2 = 9 | 1 |\n| 9 : 2 = 4 | 1 |\n| 4 : 2 = 2 | 0 |\n| 2 : 2 = 1 | 0 |\n| 1 : 2 = 0 | 1 |\n\nТөменнен жоғары: **10011₂**.\n\n## Кері аудару арқылы тексеру\n\nСалмақтарды оңнан солға қарай жазып, қос: 10011₂ = 16 + 2 + 1 = 19. Сәйкес келді — жауап дұрыс.\n\n## ҰБТ-ға арналған кеңестер\n\n- **2-ге көбейту — оң жаққа 0 жазу деген сөз:** 19 = 10011₂, 38 = 100110₂.\n- Сан жұп болса — жазба 0-мен, тақ болса — 1-мен аяқталады. Осылай қате нұсқалар алып тасталады.\n- Нұсқалар арасында әрқашан керісінше оқылған жазба болады. Қалдықтарды **төменнен жоғары** оқимыз.\n- Шағын сандар үшін монеталар тәсілі тезірек, үлкен сандар үшін — бөлу.\n\n## Жиі кететін қателер\n\n- Қалдықтар **жоғарыдан төмен** оқылған: 6 үшін 110 орнына 011 шығады.\n- Соңғы қалдық жоғалған: 1 : 2 = 0 және қалдығы **1** — оны да жазамыз.\n- Екілік жазбада 2 цифры пайда болған — қалдық әрқашан 0 немесе 1."},
  "ns-4-traps": {"ru":"# Ловушки ЕНТ: свойства двоичных чисел\n\nВсе хитрости — на одной карточке. Они позволяют отвечать **без полного перевода**.\n\n| Свойство | Правило | Пример |\n|---|---|---|\n| Чётность | Последняя цифра 0 — чётное, 1 — нечётное | 101110₂ — чётное (46), 10111₂ — нечётное (23) |\n| Двоичная запись | Только цифры 0 и 1. Есть 2 и больше — не двоичная | 101201 — не двоичная |\n| Число цифр | Если 2ᵏ ≤ N < 2ᵏ⁺¹, то цифр k + 1 | 64 ≤ 100 < 128, значит 7 цифр |\n| Степень двойки | 2ᵏ — это 1 и k нулей | 2⁴ = 16 = 10000₂ |\n| 2ᵏ − 1 | Это k единиц | 2⁴ − 1 = 15 = 1111₂, 255 = 11111111₂ |\n\n## Баллы ЕНТ в заданиях с несколькими ответами\n\n| Что отмечено | Баллы |\n|---|---|\n| Все верные и ничего лишнего | 2 |\n| Не хватает одного верного и/или есть один лишний | 1 |\n| Два и больше неверных, только один верный из трёх или ни одного верного | 0 |\n\n**Лишняя галочка стоит балла.** Сомневаешься в варианте — не отмечай.\n\n## Лайфхаки для ЕНТ\n\n- Сначала смотри на **последнюю цифру**: чётность отсекает половину вариантов.\n- На границах степеней двойки считай внимательно: 15 — 4 цифры, а 16 — уже 5.\n- Число и его запись наоборот — типичная пара ловушек. Веса считай с правого края.\n\n## Частые ошибки\n\n- Считать, что 2ᵏ в двоичной записи — это k единиц (на деле: единица и k нулей).\n- Путать 2ᵏ и 2ᵏ − 1: 8 = 1000₂, а 7 = 111₂.\n- Ставить лишнюю галочку «на удачу» в задании с несколькими ответами.","kk":"# ҰБТ тұзақтары: екілік сандардың қасиеттері\n\nБарлық айла бір карточкада. Олар **толық аудармай-ақ** жауап беруге мүмкіндік береді.\n\n| Қасиет | Ереже | Мысал |\n|---|---|---|\n| Жұптылық | Соңғы цифр 0 — жұп, 1 — тақ | 101110₂ — жұп (46), 10111₂ — тақ (23) |\n| Екілік жазба | Тек 0 және 1 цифрлары. 2 немесе одан үлкені бар — екілік емес | 101201 — екілік емес |\n| Цифрлар саны | 2ᵏ ≤ N < 2ᵏ⁺¹ болса, цифр саны k + 1 | 64 ≤ 100 < 128, демек 7 цифр |\n| Екінің дәрежесі | 2ᵏ — бұл 1 және k нөл | 2⁴ = 16 = 10000₂ |\n| 2ᵏ − 1 | Бұл k бірлік | 2⁴ − 1 = 15 = 1111₂, 255 = 11111111₂ |\n\n## Бірнеше жауабы бар тапсырмалардағы ҰБТ ұпайы\n\n| Белгіленгені | Ұпай |\n|---|---|\n| Барлық дұрыс жауап және артық ештеңе жоқ | 2 |\n| Бір дұрыс жауап жетпейді және/немесе бір артық бар | 1 |\n| Екі және одан да көп қате, үш дұрыстың тек біреуі немесе бірде-бір дұрыс жоқ | 0 |\n\n**Артық белгі ұпай алып кетеді.** Нұсқаға күмәнің болса — белгілеме.\n\n## ҰБТ-ға арналған кеңестер\n\n- Алдымен **соңғы цифрға** қара: жұптылық нұсқалардың жартысын түсіріп тастайды.\n- Екінің дәрежелерінің шекарасында мұқият есепте: 15 — 4 цифр, ал 16 — 5 цифр.\n- Сан және оның керісінше жазбасы — тұзақтардың әдеттегі жұбы. Салмақтарды оң жақ шетінен есепте.\n\n## Жиі кететін қателер\n\n- Екілік жазбада 2ᵏ — k бірлік деп ойлау (шын мәнінде: бір бірлік және k нөл).\n- 2ᵏ мен 2ᵏ − 1 шатастыру: 8 = 1000₂, ал 7 = 111₂.\n- Бірнеше жауабы бар тапсырмада артық белгіні «тәуекелге салып» қою."},
  "ns-1-binary": {"ru":"# Двоичная система счисления\n\n**Система счисления** — способ записи чисел цифрами. **Позиционная**: значение цифры зависит от её позиции. **Основание** — количество цифр в системе.\n\n| Система | Основание | Цифры |\n|---|---|---|\n| Десятичная | 10 | 0–9 |\n| Двоичная | 2 | 0, 1 |\n\n## Веса разрядов (степени двойки)\n\n| 2⁷ | 2⁶ | 2⁵ | 2⁴ | 2³ | 2² | 2¹ | 2⁰ |\n|---|---|---|---|---|---|---|---|\n| 128 | 64 | 32 | 16 | 8 | 4 | 2 | 1 |\n\n## 2 → 10\nСкладываем веса разрядов, где стоит 1:\n> 1011₂ = 8 + 2 + 1 = **11**\n\n## 10 → 2\nДелим на 2, записываем остатки, читаем **снизу вверх**:\n> 13 → 1, 0, 1, 1 → **1101₂**\n\nБыстрый способ: раскладываем на степени двойки: 37 = 32 + 4 + 1 → 100101₂.\n\n## Лайфхаки для ЕНТ\n- Чётное число оканчивается на **0**, нечётное — на **1**.\n- 2ⁿ в двоичной — это **1 и n нулей**: 8 = 1000₂.\n- 2ⁿ − 1 — это **n единиц**: 7 = 111₂, 15 = 1111₂.\n- Число цифр в двоичной записи N: наименьшее k, при котором 2ᵏ > N.\n- Всегда делай проверку обратным переводом.","kk":"# Екілік санау жүйесі\n\n**Санау жүйесі** — сандарды цифрлармен жазу тәсілі. **Позициялық**: цифрдың мәні оның орнына байланысты. **Негіз** — жүйедегі цифрлар саны.\n\n| Жүйе | Негізі | Цифрлары |\n|---|---|---|\n| Ондық | 10 | 0–9 |\n| Екілік | 2 | 0, 1 |\n\n## Разрядтардың салмағы (екінің дәрежелері)\n\n| 2⁷ | 2⁶ | 2⁵ | 2⁴ | 2³ | 2² | 2¹ | 2⁰ |\n|---|---|---|---|---|---|---|---|\n| 128 | 64 | 32 | 16 | 8 | 4 | 2 | 1 |\n\n## 2 → 10\n1 тұрған разрядтардың салмақтарын қосамыз:\n> 1011₂ = 8 + 2 + 1 = **11**\n\n## 10 → 2\n2-ге бөліп, қалдықтарды жазамыз да, **төменнен жоғары** оқимыз:\n> 13 → 1, 0, 1, 1 → **1101₂**\n\nЖылдам тәсіл: санды екінің дәрежелеріне жіктейміз: 37 = 32 + 4 + 1 → 100101₂.\n\n## ҰБТ-ға арналған кеңестер\n- Жұп сан **0**-мен, тақ сан **1**-мен аяқталады.\n- 2ⁿ екілік жүйеде — **1 және n нөл**: 8 = 1000₂.\n- 2ⁿ − 1 — бұл **n бірлік**: 7 = 111₂, 15 = 1111₂.\n- N санының екілік жазбасындағы цифрлар саны: 2ᵏ > N болатын ең кіші k.\n- Әрқашан кері аудару арқылы тексер."},
  "algo-1-basics": {"ru":"# Алгоритмы и блок-схемы\n\n## Что такое алгоритм\n\n**Алгоритм** — точная последовательность команд для исполнителя, которая приводит к результату.\n\n## Пять свойств\n\n- **Дискретность** — делится на отдельные шаги.\n- **Понятность** — команды есть в системе команд исполнителя.\n- **Определённость** — команда понимается однозначно, результат одинаков при одинаковых данных.\n- **Результативность** — заканчивается за конечное число шагов.\n- **Массовость** — подходит для целого класса задач.\n\n## Фигуры блок-схемы\n\n- Овал — начало и конец.\n- Параллелограмм — ввод и вывод.\n- Прямоугольник — действие.\n- Ромб — условие, два выхода: «Да» и «Нет».\n\n## Три структуры\n\n**Следование**, **ветвление** (выбор пути), **цикл** (повтор, пока условие верно).\n\n## Лайфхаки для ЕНТ\n\n- Выполняй блок-схему **трассировкой**: таблица, в строках — проходы, в столбцах — переменные.\n- Цикл считай по строкам «Да»: проверок на одну больше, чем проходов тела.\n- Внимательно смотри на знак: `<` и `≤` дают разное число проходов.\n- mod — остаток от деления: 36 mod 15 = 6.\n\n## Частые ошибки\n\n- Посчитаны проверки, а не проходы тела цикла.\n- Выведена не та переменная после выхода из цикла.","kk":"# Алгоритмдер және блок-сызбалар\n\n## Алгоритм деген не\n\n**Алгоритм** — орындаушыға арналған, нәтижеге жеткізетін командалардың нақты тізбегі.\n\n## Бес қасиет\n\n- **Дискреттілік** — бөлек қадамдарға бөлінеді.\n- **Түсініктілік** — командалар орындаушының командалар жүйесінде бар.\n- **Анықтылық** — команда бір мәнді түсініледі, бірдей деректерде нәтиже бірдей.\n- **Нәтижелілік** — қадамдардың шектеулі санынан кейін аяқталады.\n- **Жаппайлық** — есептердің тұтас класы үшін жарайды.\n\n## Блок-сызба фигуралары\n\n- Сопақша (овал) — басы мен соңы.\n- Параллелограмм — енгізу және шығару.\n- Тіктөртбұрыш — әрекет.\n- Ромб — шарт, екі шығыс: «Иә» және «Жоқ».\n\n## Үш құрылым\n\n**Тізбектеу**, **тармақталу** (жол таңдау), **цикл** (шарт ақиқат болғанша қайталау).\n\n## ҰБТ-ға арналған кеңестер\n\n- Блок-сызбаны **трассировкамен** орында: кесте, жолдарда — өтулер, бағандарда — айнымалылар.\n- Циклді «Иә» жолдары бойынша сана: тексеру дене өтуінен біреуге көп.\n- Белгіге мұқият қара: `<` және `≤` өтулердің әртүрлі санын береді.\n- mod — бөлгендегі қалдық: 36 mod 15 = 6.\n\n## Жиі кететін қателер\n\n- Цикл денесінің өтулері емес, тексерулер саналған.\n- Циклден шыққаннан кейін қате айнымалы шығарылған."},
  "base-1-computer": {"ru":"# Что такое компьютер\n\n## Главное\n\n**Компьютер** — устройство, которое принимает информацию, обрабатывает её по программе, хранит и выдаёт результат. Слово от *compute* — «вычислять».\n\n## Четыре действия\n\n**Ввод** → **обработка** (процессор) → **вывод**. **Хранение** — запись результата в память.\n\n## Где встречается\n\nСмартфон, планшет, ноутбук, умные часы, банкомат, касса, машина, сервер.\n\n## Железо и программы\n\n- **Железо** = **аппаратное обеспечение** (hardware) — всё, что можно потрогать.\n- **Программы** = **программное обеспечение** (software) — списки команд, потрогать нельзя.\n- Без программ железо ничего не делает.\n\n## История\n\nАбак (счёты) → машина Паскаля (1642) → ЭНИАК (1946) → IBM PC (1981) → iPhone (2007).\n\n## Лайфхаки для ЕНТ\n\n- Спроси: информация идёт **в** компьютер, обрабатывается, записывается или показывается?\n- Монитор и клавиатура — не «весь компьютер», а его детали.\n- Браузер, игра, калькулятор — программы, а не железо.\n- Хранение (запись в память) — отдельное действие, не путай его с выводом на экран.","kk":"# Компьютер дегеніміз не\n\n## Негізгісі\n\n**Компьютер** — ақпаратты қабылдайтын, программа бойынша өңдейтін, сақтайтын және нәтиже беретін құрылғы. Сөз *compute* — «есептеу» дегеннен шыққан.\n\n## Төрт әрекет\n\n**Енгізу** → **өңдеу** (процессор) → **шығару**. **Сақтау** — нәтижені жадқа жазу.\n\n## Қайда кездеседі\n\nСмартфон, планшет, ноутбук, ақылды сағат, банкомат, касса, көлік, сервер.\n\n## Аппараттық және программалық қамтамасыз ету\n\n- **Аппараттық қамтамасыз ету** (hardware, «темір») — қолмен ұстауға болатынның бәрі.\n- **Программалық қамтамасыз ету** (software) — программалар, яғни командалар тізімі, қолмен ұстауға болмайды.\n- Программасыз құрылғылар ештеңе істемейді.\n\n## Тарих\n\nАбак (есеп шоты) → Паскаль машинасы (1642) → ЭНИАК (1946) → IBM PC (1981) → iPhone (2007).\n\n## ҰБТ-ға арналған кеңестер\n\n- Сұра: ақпарат компьютерге **кіріп** жатыр ма, өңделіп жатыр ма, жазылып жатыр ма, әлде көрсетіліп жатыр ма?\n- Монитор мен пернетақта — «бүкіл компьютер» емес, оның бөлшектері.\n- Браузер, ойын, калькулятор — программа, «темір» емес.\n- Сақтау (жадқа жазу) — бөлек әрекет, оны экранға шығарумен шатастырма."},
  "base-2-inside": {"ru":"# Что внутри компьютера\n\n## Кухня компьютера\n\n- **Процессор** — повар: считает и выполняет команды. Ядра — несколько «поваров», ГГц — скорость каждого.\n- **ОЗУ** — рабочий стол: быстрая, небольшая (8–32 ГБ), **очищается при выключении**.\n- **Накопитель** (SSD, HDD) — шкаф: большой (256 ГБ – ТБ), хранит данные **без питания**.\n- **Материнская плата** соединяет все детали.\n- **Видеокарта** рисует картинку (в телефонах она встроена в процессор).\n- **Блок питания** превращает ток из розетки (220 В) в постоянный ток низкого напряжения для деталей. **Кулер** охлаждает процессор.\n\n## Порты\n\nUSB (Type-C — любой стороной), HDMI (картинка и звук), аудио 3,5 мм, Ethernet (сеть).\n\n## Лайфхаки для ЕНТ\n\n- Две «памяти»: ОЗУ — быстрая и забывчивая, накопитель — большой и надёжный.\n- В описании «8/256 ГБ»: 8 — ОЗУ, 256 — накопитель.\n- Тормозит при многих вкладках — смотри на ОЗУ, а не на SSD.\n\n## Частые ошибки\n\n- Путают ОЗУ и накопитель.\n- Думают, что блок питания охлаждает процессор: это делает кулер.","kk":"# Компьютердің ішінде не бар\n\n## Компьютердің ас үйі\n\n- **Процессор** — аспаз: есептейді және командаларды орындайды. Ядролар — бірнеше «аспаз», ГГц — әрқайсысының жылдамдығы.\n- **Жедел жад** — жұмыс үстелі: жылдам, шағын (8–32 ГБ), **өшірген кезде тазаланады**.\n- **Жинақтауыш** (SSD, HDD) — шкаф: үлкен (256 ГБ – ТБ), деректерді **қуатсыз** сақтайды.\n- **Аналық тақша** барлық бөлшекті қосады.\n- **Бейнекарта** сурет салады (телефондарда ол процессорға кіріктірілген).\n- **Қуат блогы** розеткадағы токты (220 В) бөлшектерге арналған төмен кернеулі тұрақты токқа айналдырады. **Салқындатқыш (кулер)** процессорды салқындатады.\n\n## Порттар\n\nUSB (Type-C — кез келген жағымен), HDMI (сурет және дыбыс), аудио 3,5 мм, Ethernet (желі).\n\n## ҰБТ-ға арналған кеңестер\n\n- Екі «жад»: жедел жад — жылдам, бірақ ұмытшақ, жинақтауыш — үлкен және сенімді.\n- «8/256 ГБ» сипаттамасында: 8 — жедел жад, 256 — жинақтауыш.\n- Көп қойынды ашылғанда баяуласа — SSD-ге емес, жедел жадқа қара.\n\n## Жиі кететін қателер\n\n- Жедел жад мен жинақтауышты шатастырады.\n- Қуат блогы процессорды салқындатады деп ойлайды: мұны салқындатқыш (кулер) істейді."},
  "base-3-devices": {"ru":"# Устройства ввода и вывода\n\n## Два направления\n\nСмотри на стрелку: **ввод** — информация идёт **в** компьютер, **вывод** — **из** компьютера. Посередине работает процессор.\n\n## Группы устройств\n\n- **Ввод:** клавиатура, мышь, тачпад, микрофон, веб-камера, сканер, геймпад.\n- **Вывод:** монитор, принтер, колонки, наушники, проектор.\n- **Ввод-вывод:** сенсорный экран, гарнитура, сетевая карта.\n\n## Где встречается\n\nБанкомат, касса, умные часы, машина, игровая приставка: везде внутри процессор, а снаружи устройства ввода и вывода.\n\n## Лайфхаки для ЕНТ\n\n- Направление считают **от компьютера**, а не от человека.\n- Сканер: ввод (картинка с бумаги идёт в компьютер). Принтер: вывод.\n- Наушники без микрофона — только вывод.\n- Монитор состоит из **пикселей**; Full HD — 1920 × 1080.\n\n## Частые ошибки\n\n- Сканер принимают за вывод «из-за бумаги».\n- Любое устройство с экраном считают вводом-выводом: только сенсорный экран ловит касания.","kk":"# Енгізу және шығару құрылғылары\n\n## Екі бағыт\n\nКөрсеткіге қара: **енгізу** — ақпарат компьютерге **кіреді**, **шығару** — компьютерден **шығады**. Ортасында процессор жұмыс істейді.\n\n## Құрылғы топтары\n\n- **Енгізу:** пернетақта, тінтуір, тачпад, микрофон, веб-камера, сканер, геймпад.\n- **Шығару:** монитор, принтер, дыбыс колонкалары, құлаққап, проектор.\n- **Енгізу-шығару:** сенсорлық экран, гарнитура, желілік карта.\n\n## Қайда кездеседі\n\nБанкомат, касса, ақылды сағат, көлік, ойын приставкасы: бәрінің ішінде процессор, ал сыртында енгізу және шығару құрылғылары бар.\n\n## ҰБТ-ға арналған кеңестер\n\n- Бағытты **компьютерге қатысты** анықтайды, адамға қатысты емес.\n- Сканер: енгізу (қағаздағы сурет компьютерге кіреді). Принтер: шығару.\n- Микрофонсыз құлаққап — тек шығару.\n- Монитор **пиксельдерден** тұрады; Full HD — 1920 × 1080.\n\n## Жиі қателер\n\n- Сканерді «қағазға байланысты» шығару деп қателеседі.\n- Экраны бар кез келген құрылғыны енгізу-шығару деп санайды: тек сенсорлық экран жанасуды қабылдайды."},
  "base-4-media": {"ru":"# Носители информации\n\n**Носитель** — устройство, где данные хранятся и после выключения компьютера («шкаф»). **ОЗУ** — «рабочий стол»: быстрая, но **энергозависимая** (при выключении очищается).\n\n## Виды\n- **HDD** — вращающиеся магнитные пластины и головка; дёшево, много места, шумит, боится ударов.\n- **SSD** — микросхемы флеш-памяти, без движущихся частей; быстро и тихо.\n- **Флешка, карта SD/microSD** — тоже флеш-память, переносные.\n- **CD 700 МБ, DVD 4,7 ГБ** — дорожку читает лазер.\n- **Облако** — файлы на серверах в интернете; нужен интернет.\n\n## Размеры\n1 КБ = 1024 Б, 1 МБ = 1024 КБ, 1 ГБ = 1024 МБ, 1 ТБ = 1024 ГБ.\nФото ≈ 4 МБ, песня ≈ 5 МБ, фильм ≈ 2 ГБ.\n**Сколько файлов = объём ÷ размер файла**, единицы одинаковые.\n\n## Ловушки ЕНТ\n- «ОЗУ 8 ГБ» — это стол, а «память 256 ГБ» — шкаф: их путают.\n- Не сохранено — пропадёт при выключении.\n- 1 ТБ = 1024 ГБ, а не 1000.","kk":"# Ақпарат тасығыштар\n\n**Тасығыш** — компьютер өшкеннен кейін де деректер сақталатын құрылғы («шкаф»). **Жедел жад** — «жұмыс үстелі»: жылдам, бірақ **энергияға тәуелді** (өшкенде тазаланады).\n\n## Түрлері\n- **HDD** — айналатын магниттік пластиналар және бас; арзан, орын көп, шу шығарады, соққыдан қорқады.\n- **SSD** — флеш-жад микросхемалары, қозғалмалы бөлшексіз; жылдам және тыныш.\n- **Флешка, SD/microSD картасы** — олар да флеш-жад, тасымалды.\n- **CD 700 МБ, DVD 4,7 ГБ** — жолды лазер оқиды.\n- **Бұлт** — интернеттегі серверлердегі файлдар; интернет керек.\n\n## Өлшемдер\n1 КБ = 1024 Б, 1 МБ = 1024 КБ, 1 ГБ = 1024 МБ, 1 ТБ = 1024 ГБ.\nФото ≈ 4 МБ, ән ≈ 5 МБ, фильм ≈ 2 ГБ.\n**Файл саны = көлем ÷ файл өлшемі**, өлшем бірліктері бірдей.\n\n## ҰБТ-дағы тұзақтар\n- «Жедел жад 8 ГБ» — бұл үстел, ал «жад 256 ГБ» — шкаф: оларды шатастырады.\n- Сақталмаған — өшкенде жоғалады.\n- 1 ТБ = 1024 ГБ, 1000 емес."},
  "base-5-cpu": {"ru":"# Как компьютер вычисляет\n\n- **Программа** — список простых команд. Процессор выполняет их по очереди.\n- Цикл команды: **выборка** (взять из памяти) → **декодирование** (расшифровать) → **выполнение** (посчитать) → **запись** (сохранить результат).\n- **Такт** — один «тик» процессора. **Частота**: 1 ГГц = 1 млрд тактов в секунду; 3 ГГц = 3 млрд.\n- **Ядро** — отдельный «повар» процессора. Много ядер удобно, когда задач много сразу.\n- **Лесенка памяти** (сверху вниз: от быстрой и маленькой к большой и медленной): регистры → кэш → ОЗУ → SSD/HDD → облако.\n- **Энергозависимая** память (регистры, кэш, ОЗУ) очищается при выключении. **Энергонезависимая** (SSD, HDD, флешка) хранит данные без питания.\n\n**Лайфхаки ЕНТ:** ГБ ОЗУ и ГБ диска — разные вещи: ОЗУ — «стол» для работы, диск — «шкаф» для хранения. Больше ОЗУ не значит больше места для файлов. Процессор ничего не хранит надолго. Несохранённое живёт только в ОЗУ: нажимай Ctrl+S.","kk":"# Компьютер қалай есептейді\n\n- **Программа** — қарапайым командалар тізімі. Процессор оларды кезекпен орындайды.\n- Команда циклі: **алу** (жадтан алу) → **декодтау** (шифрын ашу) → **орындау** (есептеу) → **жазу** (нәтижені сақтау).\n- **Такт** — процессордың бір «тығы». **Жиілік**: 1 ГГц = секундына 1 млрд такт; 3 ГГц = 3 млрд.\n- **Ядро** — процессордың бөлек «аспазы». Тапсырма көп болғанда көп ядро ыңғайлы.\n- **Жад баспалдағы** (жоғарыдан төмен: жылдам әрі шағын жадтан үлкен әрі баяу жадқа): регистрлер → кэш жады → жедел жад → SSD/HDD → бұлт.\n- **Энергияға тәуелді** жад (регистрлер, кэш, жедел жад) өшірілгенде тазаланады. **Энергияға тәуелсіз** жад (SSD, HDD, флешка) деректі токсыз сақтайды.\n\n**ҰБТ лайфхактары:** жедел жадтың ГБ-ы мен дискінің ГБ-ы — әртүрлі нәрсе: жедел жад — жұмыс «үстелі», диск — сақтау «шкафы». Жедел жадтың көп болуы файлға орын көп дегенді білдірмейді. Процессор ештеңені ұзақ сақтамайды. Сақталмағаны тек жедел жадта тұрады: Ctrl+S бас."},
  "base-6-os": {"ru":"# Операционная система и файлы\n\n## Операционная система (ОС)\n\nГлавная программа компьютера: загружается при включении раньше всех программ, работает всё время. Как администратор в мастерской: **запускает** программы, **делит** процессор и память, **управляет** устройствами, **хранит** файлы, **защищает** данные, **показывает** окна.\n\nСлои: пользователь → программы → **ОС** → аппаратура.\n\n## Примеры\n\n- **Windows** (Microsoft), **macOS** (Apple), **Linux** (бесплатная, серверы).\n- **Android** (Google), **iOS** (Apple, iPhone).\n\n## Файлы и папки\n\n- **Файл** — данные с именем, **папка** — «ящик» для файлов и других папок.\n- Путь: `C:\\Информатика\\Практика\\task.docx` — диск, папки, файл. В Linux и macOS разделитель — `/`.\n- **Расширение** — после последней точки: `.docx`, `.pdf`, `.jpg`, `.png`, `.mp3`, `.mp4`, `.exe`, `.py`, `.html`, `.zip`.\n\n## Лайфхаки для ЕНТ\n\n- ОС запускает другие программы. Chrome, Word, Telegram — **программы**, а не ОС.\n- Samsung, Apple, Microsoft — компании.\n\n## Частые ошибки\n\n- `photo.jpg.exe` — это **программа**: смотрим на последнее расширение.\n- Переименование `.mp3` в `.jpg` не меняет содержимое файла.","kk":"# Операциялық жүйе және файлдар\n\n## Операциялық жүйе (ОЖ)\n\nКомпьютердің басты программасы: қосылғанда бәрінен бұрын жүктеледі, үнемі жұмыс істейді. Шеберханадағы әкімші сияқты: программаларды **іске қосады**, процессор мен жадты **бөледі**, құрылғыларды **басқарады**, файлдарды **сақтайды**, деректерді **қорғайды**, терезелерді **көрсетеді**.\n\nҚабаттар: пайдаланушы → программалар → **ОЖ** → аппаратура.\n\n## Мысалдар\n\n- **Windows** (Microsoft), **macOS** (Apple), **Linux** (тегін, серверлер).\n- **Android** (Google), **iOS** (Apple, iPhone).\n\n## Файлдар мен қалталар\n\n- **Файл** — аты бар деректер, **қалта** — файлдар мен басқа қалталарға арналған «жәшік».\n- Жол: `C:\\Информатика\\Практика\\task.docx` — диск, қалталар, файл. Linux пен macOS-та бөлгіш — `/`.\n- **Кеңейтілім** — соңғы нүктеден кейін: `.docx`, `.pdf`, `.jpg`, `.png`, `.mp3`, `.mp4`, `.exe`, `.py`, `.html`, `.zip`.\n\n## ҰБТ-ға арналған кеңестер\n\n- ОЖ басқа программаларды іске қосады. Chrome, Word, Telegram — **программалар**, ОЖ емес.\n- Samsung, Apple, Microsoft — компаниялар.\n\n## Жиі кететін қателер\n\n- `photo.jpg.exe` — бұл **программа**: соңғы кеңейтілімге қараймыз.\n- `.mp3` атын `.jpg` деп өзгерту файлдың мазмұнын өзгертпейді."},
  "base-7-keys": {"ru":"**Клавиатура** — устройство ввода. Группы клавиш: буквы и цифры; функциональные F1–F12; управляющие Ctrl, Alt, Shift, Win; стрелки; специальные Enter, Backspace, Delete, Tab, Esc.\n\n**Backspace** стирает слева от курсора, **Delete** — справа. **Caps Lock** — режим заглавных, а Shift в этом режиме делает букву строчной.\n\n**Раскладка** — карта «клавиша → буква». Сменить язык: **Alt + Shift** или **Win + Пробел**. Перед паролем смотри на язык и Caps Lock.\n\n**Горячие клавиши** (зажми первую, нажми вторую):\n- Ctrl + C — копировать, Ctrl + V — вставить, Ctrl + X — вырезать;\n- Ctrl + Z — отменить, Ctrl + Y — вернуть отменённое;\n- Ctrl + A — выделить всё, Ctrl + S — сохранить, Ctrl + F — найти, Ctrl + P — печать;\n- Alt + Tab — переключить окно, Win + D — рабочий стол, Win + E — Проводник, Win + L — заблокировать, Ctrl + Shift + Esc — Диспетчер задач.\n\n**Буфер обмена**: Ctrl + V вставляет последнее скопированное или вырезанное, сколько угодно раз. Буфер живёт в оперативной памяти и очищается при выключении. На Mac вместо Ctrl — ⌘ Cmd.","kk":"**Пернетақта** — енгізу құрылғысы. Пернелер топтары: әріптер мен сандар; функциялық F1–F12; басқару пернелері Ctrl, Alt, Shift, Win; көрсеткі пернелер; арнайы Enter, Backspace, Delete, Tab, Esc.\n\n**Backspace** курсордың сол жағын, **Delete** оң жағын өшіреді. **Caps Lock** — бас әріптер режимі, ал бұл режимде Shift әріпті кіші етеді.\n\n**Орналасым** — «перне → әріп» картасы. Тілді ауыстыру: **Alt + Shift** немесе **Win + Бос орын**. Құпиясөзді терер алдында тілге және Caps Lock-қа қара.\n\n**Жылдам пернелер** (біріншісін басып тұр, екіншісін бас):\n- Ctrl + C — көшіру, Ctrl + V — қою, Ctrl + X — қиып алу;\n- Ctrl + Z — болдырмау, Ctrl + Y — болдырмағанды қайтару;\n- Ctrl + A — бәрін бөлектеу, Ctrl + S — сақтау, Ctrl + F — іздеу, Ctrl + P — басып шығару;\n- Alt + Tab — терезені ауыстыру, Win + D — жұмыс үстелі, Win + E — файл менеджері (Explorer), Win + L — құлыптау, Ctrl + Shift + Esc — Тапсырмалар диспетчері.\n\n**Алмасу буфері**: Ctrl + V соңғы көшірілгенді немесе қиып алынғанды қалағанша қояды. Буфер жедел жадта тұрады және компьютер өшкенде тазарады. Mac-та Ctrl орнына — ⌘ Cmd."},
  "base-8-info": {"ru":"**Информация** бывает разной: текст, число, звук, изображение, видео. Компьютер хранит всё **числами**, а числа — **нулями и единицами** (ток есть — 1, тока нет — 0).\n\n**Бит** — один ответ «да/нет» (0 или 1). **Байт** = 8 бит ≈ одна буква.\n\n**Единицы** (каждая в 1024 раза больше предыдущей):\n- 1 КБ = 1024 байта\n- 1 МБ = 1024 КБ\n- 1 ГБ = 1024 МБ\n- 1 ТБ = 1024 ГБ\n\n**К мелкой единице — умножаем, к крупной — делим.** В задачах ЕНТ пишут Кбайт, Мбайт, Гбайт.\n\n**Ориентиры:** SMS — около 140 Б, страница текста — 2 КБ, фото — 3–5 МБ, песня — 4–8 МБ, фильм — 1,5–4 ГБ.\n\n**Ловушки:**\n- бит ≠ байт: интернет — Мбит/с, файлы — МБ (100 Мбит/с ≈ 12,5 МБ/с);\n- 1 КБ = 1024 байта, а не 1000;\n- сравнивать и делить можно только в одной единице.\n\nДальше: урок «Язык лампочек» — как записать число нулями и единицами.","kk":"**Ақпарат** әртүрлі болады: мәтін, сан, дыбыс, кескін, бейне. Компьютер бәрін **сандармен**, ал сандарды **нөлдер мен бірлер** арқылы сақтайды (ток бар — 1, ток жоқ — 0).\n\n**Бит** — «иә/жоқ» деген бір жауап (0 немесе 1). **Байт** = 8 бит ≈ бір әріп.\n\n**Бірліктер** (әрқайсысы алдыңғысынан 1024 есе үлкен):\n- 1 КБ = 1024 байт\n- 1 МБ = 1024 КБ\n- 1 ГБ = 1024 МБ\n- 1 ТБ = 1024 ГБ\n\n**Кіші бірлікке — көбейтеміз, ірі бірлікке — бөлеміз.** ҰБТ есептерінде Кбайт, Мбайт, Гбайт деп жазады.\n\n**Бағдарлар:** SMS — шамамен 140 Б, мәтін беті — 2 КБ, фото — 3–5 МБ, ән — 4–8 МБ, фильм — 1,5–4 ГБ.\n\n**Тұзақтар:**\n- бит ≠ байт: интернет — Мбит/с, файлдар — МБ (100 Мбит/с ≈ 12,5 МБ/с);\n- 1 КБ = 1024 байт, 1000 емес;\n- салыстыруды және бөлуді тек бір бірлікте жасауға болады.\n\nӘрі қарай: «Шамдар тілі» сабағы — санды нөлдер мен бірлер арқылы қалай жазуға болатынын үйренесің."},
  "data-1-sheets": {"ru":"# Электронные таблицы и формулы\n\n## Ячейки и диапазоны\n\n- **Столбцы** — буквы (A, B, C…), **строки** — номера (1, 2, 3…).\n- Адрес ячейки: **сначала буква, потом номер** — B3, а не 3B.\n- **Диапазон** — прямоугольник из ячеек: A1:B3 (левый верхний и правый нижний угол). Крайние столбец и строка тоже входят.\n- Число ячеек = **столбцы × строки**: A1:B3 → 2 × 3 = 6; C2:E4 → 3 × 3 = 9.\n\n## Формулы\n\n- Формула начинается со знака **=**: `=A1+B1`. Без него — обычный текст.\n- Порядок действий: **скобки → ^ → * и / → + и −**. Умножение — `*`.\n- Значение формулы: подставь числа вместо адресов, затем считай по порядку.\n\n## Функции\n\n- `СУММ (SUM)`, `СРЗНАЧ (AVERAGE)`, `МИН (MIN)`, `МАКС (MAX)`, `СЧЁТ (COUNT)` — по числам; `СТРОЧН`, `ПРОПИСН` — регистр букв; `ДЛСТР (LEN)` — длина текста (пробел тоже символ).\n- `A1:A4` — весь диапазон, `A1;A4` — только две ячейки.\n\n## Диаграммы\n\nКруговая — доли целого; столбчатая — сравнение; график — изменение во времени.\n\n## Лайфхаки ЕНТ\n\n- В диапазоне текст и пустые ячейки функции **пропускают**: СЧЁТ и СРЗНАЧ работают только по числам.\n- `+` с текстом даёт **#ЗНАЧ!**, деление на 0 или на пустую ячейку — **#ДЕЛ/0!**.\n- В «нескольких верных» не отмечай сомнительный вариант.","kk":"# Электрондық кестелер және формулалар\n\n## Ұяшықтар және диапазондар\n\n- **Бағандар** — әріптер (A, B, C…), **жолдар** — нөмірлер (1, 2, 3…).\n- Ұяшық мекенжайы: **алдымен әріп, содан кейін нөмір** — B3, ал 3B емес.\n- **Диапазон** — ұяшықтардан тұратын тіктөртбұрыш: A1:B3 (сол жақ жоғарғы және оң жақ төменгі бұрыш). Шеткі баған мен жол да кіреді.\n- Ұяшықтар саны = **бағандар × жолдар**: A1:B3 → 2 × 3 = 6; C2:E4 → 3 × 3 = 9.\n\n## Формулалар\n\n- Формула **=** белгісінен басталады: `=A1+B1`. Онсыз — қарапайым мәтін.\n- Амалдардың реті: **жақша → ^ → * және / → + және −**. Көбейту — `*`.\n- Формуланың мәні: мекенжайлардың орнына сандарды қойып, ретімен есепте.\n\n## Функциялар\n\n- `СУММ (SUM)`, `СРЗНАЧ (AVERAGE)`, `МИН (MIN)`, `МАКС (MAX)`, `СЧЁТ (COUNT)` — сандар бойынша; `СТРОЧН`, `ПРОПИСН` — әріп регистрі; `ДЛСТР (LEN)` — мәтін ұзындығы (бос орын да символ).\n- `A1:A4` — бүкіл диапазон, `A1;A4` — тек екі ұяшық.\n\n## Диаграммалар\n\nДөңгелек — бүтіннің үлестері; бағанды — салыстыру; график — уақыт бойынша өзгеру.\n\n## ҰБТ-ға арналған кеңестер\n\n- Диапазондағы мәтін мен бос ұяшықтарды функциялар **өткізіп жібереді**: СЧЁТ пен СРЗНАЧ тек сандар бойынша жұмыс істейді.\n- Мәтіні бар `+` **#ЗНАЧ!** береді, 0-ге немесе бос ұяшыққа бөлу — **#ДЕЛ/0!**.\n- «Бірнеше дұрыс жауап» тапсырмасында күмәнді нұсқаны белгілеме."},
  "data-2-refs": {"ru":"# Ссылки и функции в электронных таблицах\n\n## Что происходит при копировании\n\nФормула запоминает, **на сколько клеток** от неё лежат нужные ячейки. При копировании каждая **относительная** ссылка сдвигается на столько же, на сколько сдвинули формулу.\n\n> `=A1+B1` из C1 в C2 → `=A2+B2`; из C1 в D3 → `=B3+C3`\n\n## Виды ссылок\n\n| Запись | Столбец | Строка |\n|---|---|---|\n| A1 | сдвигается | сдвигается |\n| $A$1 | стоит | стоит |\n| $A1 | стоит | сдвигается |\n| A$1 | сдвигается | стоит |\n\n**$ держит то, что стоит сразу после него.** Курс доллара, процент НДС в одной ячейке — только `$D$2`.\n\n## Функции\n\n- `=ЕСЛИ(B2>=50;\"сдал\";\"не сдал\")` — выбор из двух значений;\n- `=СЧЁТЕСЛИ(B2:B6;\">=50\")` — сколько ячеек подходят;\n- `=СУММЕСЛИ(A2:A7;\"молоко\";B2:B7)` — сумма по условию.\n\nПроцент: `=D2*12/100+D2` — цена с наценкой 12%.\n\n## Лайфхаки ЕНТ\n\n- Сначала найди сдвиг (на сколько столбцов и строк), потом сдвигай **каждую** ссылку отдельно.\n- Смотри на $: он отменяет сдвиг по той части, перед которой стоит.\n- Диапазон `B2:B6` при копировании тоже сдвигается.\n\n## Частые ошибки\n\n- Сдвинута абсолютная ссылка или потеряны знаки $.\n- Столбец сдвинут при копировании вниз (а он стоит на месте).\n- Не учтено, что в `>=` граница входит в условие.","kk":"# Электрондық кестелердегі сілтемелер мен функциялар\n\n## Көшіргенде не болады\n\nФормула қажетті ұяшықтардың өзінен **қанша ұяшық** қашықтықта тұрғанын есте сақтайды. Көшіргенде әр **салыстырмалы** сілтеме формуланың өзі қанша жылжыса, сонша жылжиды.\n\n> C1-ден C2-ге `=A1+B1` → `=A2+B2`; C1-ден D3-ке → `=B3+C3`\n\n## Сілтеме түрлері\n\n| Жазба | Баған | Жол |\n|---|---|---|\n| A1 | жылжиды | жылжиды |\n| $A$1 | тұр | тұр |\n| $A1 | тұр | жылжиды |\n| A$1 | жылжиды | тұр |\n\n**$ өзінен кейін тұрғанды ұстайды.** Доллар бағамы, ҚҚС пайызы бір ұяшықта тұрса — тек `$D$2`.\n\n## Функциялар\n\n- `=IF(B2>=50;\"өтті\";\"өтпеді\")` — екі мәннің бірін таңдау (орысша ЕСЛИ);\n- `=COUNTIF(B2:B6;\">=50\")` — қанша ұяшық сәйкес келеді (орысша СЧЁТЕСЛИ);\n- `=SUMIF(A2:A7;\"сүт\";B2:B7)` — шарт бойынша қосынды (орысша СУММЕСЛИ).\n\nПайыз: `=D2*12/100+D2` — 12% үстемесі бар баға.\n\n## ҰБТ-ға арналған кеңестер\n\n- Алдымен жылжуды тап (қанша баған және қанша жол), содан кейін **әр** сілтемені бөлек жылжыт.\n- $ белгісіне қара: ол өзі тұрған бөліктің жылжуын тоқтатады.\n- `B2:B6` диапазоны да көшіргенде жылжиды.\n\n## Жиі кететін қателер\n\n- Абсолютті сілтеме жылжытылған немесе $ белгілері жоғалған.\n- Төмен көшіргенде баған жылжытылған (ол орнында тұрады).\n- `>=` шартында шек мәнінің кіретіні ескерілмеген."},
  "data-2a-absolute": {"ru":"# Абсолютная ссылка: знак $\n\n**Абсолютная** ссылка `$D$2` не меняется при копировании: ни столбец, ни строка. Знак **$** ставят и перед буквой, и перед цифрой (в Excel — клавиша F4).\n\nНужна, когда число общее для всех строк (курс валюты, процент наценки) и лежит в одной ячейке.\n\n> `=B2*$D$2` из C2 в C4 → `=B4*$D$2`\n\n## Лайфхаки ЕНТ\n\n1. Сдвигай только ссылки без $.\n2. Ссылку `$D$2` переписывай как есть.\n3. Нужно значение — подставь числа в новую формулу.\n\n## Частая ошибка\n\nОдин знак (`$D2`) закрепляет только столбец: строка поедет, и курс будет искаться в пустой ячейке.","kk":"# Абсолютті сілтеме: $ белгісі\n\n**Абсолютті** `$D$2` сілтемесі көшіргенде өзгермейді: баған да, жол да. **$** белгісін әріптің де, санның да алдына қояды (Excel-де — F4 пернесі).\n\nСан барлық жолға ортақ (валюта бағамы, үстеме пайызы) және бір ұяшықта тұрғанда керек.\n\n> C2 ұяшығынан C4 ұяшығына `=B2*$D$2` → `=B4*$D$2`\n\n## ҰБТ-ға арналған кеңестер\n\n1. Тек $ жоқ сілтемелерді жылжыт.\n2. `$D$2` сілтемесін сол күйінде жаз.\n3. Мән керек болса — жаңа формулаға сандарды қой.\n\n## Жиі кететін қате\n\nБір белгі (`$D2`) тек бағанды бекітеді: жол жылжиды, бағам бос ұяшықтан ізделеді."},
  "data-2a-mixed": {"ru":"# Смешанная ссылка: $A1 и A$1\n\n**$ держит то, что стоит сразу после него.**\n\n- `$A1` — столбец стоит, номер строки едет;\n- `A$1` — строка стоит, буква столбца едет.\n\nТаблица умножения одной формулой: `=$A2*B$1`. Из B2 в C3 она станет `=$A3*C$1`.\n\n## Лайфхаки ЕНТ\n\n1. Найди сдвиг: на сколько столбцов и строк.\n2. В каждой ссылке сдвигай только то, перед чем нет $.\n3. Нужно значение — подставь числа в новую формулу.\n\n## Частая ошибка\n\nПерепутаны части: в `A$1` закреплена строка, а не столбец.","kk":"# Аралас сілтеме: $A1 және A$1\n\n**$ өзінен кейін тұрғанды ұстайды.**\n\n- `$A1` — баған тұр, жол нөмірі жылжиды;\n- `A$1` — жол тұр, баған әрпі жылжиды.\n\nКөбейту кестесі бір формуламен: `=$A2*B$1`. B2 ұяшығынан C3 ұяшығына ол `=$A3*C$1` болады.\n\n## ҰБТ-ға арналған кеңестер\n\n1. Жылжуды тап: қанша баған және қанша жол.\n2. Әр сілтемеде тек алдында $ жоқ бөлікті жылжыт.\n3. Мән керек болса — жаңа формулаға сандарды қой.\n\n## Жиі кететін қате\n\nБөліктер шатастырылған: `A$1` ішінде баған емес, жол бекітілген."},
  "data-2a-relative": {"ru":"# Относительная ссылка\n\n**Ссылка** — адрес ячейки в формуле: `A1`, `B3`. **Относительная** ссылка помнит путь от формулы («на 2 ячейки левее»), а не сам адрес.\n\nПри копировании **каждая** ссылка сдвигается на столько же, на сколько сдвинули формулу:\n\n> `=A1+B1` из C1 в C2 → `=A2+B2`; из C1 в D3 → `=B3+C3`\n\n## Лайфхаки ЕНТ\n\n1. Найди сдвиг: на сколько столбцов и на сколько строк.\n2. Сдвинь букву и номер **в каждой** ссылке отдельно.\n3. Число в формуле (`*2`) — не ссылка, оно не меняется.\n\n## Частая ошибка\n\nСдвинуты только строки или только столбцы, а надо и то и другое.","kk":"# Салыстырмалы сілтеме\n\n**Сілтеме** — формуладағы ұяшық мекенжайы: `A1`, `B3`. **Салыстырмалы** сілтеме мекенжайды емес, формула тұрған орыннан бастап бағытты («2 ұяшық солда») есте сақтайды.\n\nКөшіргенде **әр** сілтеме формуланың өзі қанша жылжыса, сонша жылжиды:\n\n> C1 ұяшығынан C2 ұяшығына `=A1+B1` → `=A2+B2`; C1 ұяшығынан D3 ұяшығына → `=B3+C3`\n\n## ҰБТ-ға арналған кеңестер\n\n1. Жылжуды тап: қанша баған және қанша жол.\n2. **Әр** сілтемедегі әріпті де, нөмірді де бөлек жылжыт.\n3. Формуладағы сан (`*2`) сілтеме емес, ол өзгермейді.\n\n## Жиі кететін қате\n\nТек жолдар немесе тек бағандар жылжытылған, ал екеуі де керек."},
  "data-3-functions": {"ru":"# Функции СУММ, СРЗНАЧ, МАКС, МИН, СЧЁТ\n\n## Как записывается функция\n\n`=ИМЯ(аргументы)`. Аргументы — диапазон (`A1:A5`), ячейка (`C1`), число, другая функция; между ними **«;»**. Английские имена: SUM, AVERAGE, MAX, MIN, COUNT, COUNTA.\n\n## Шесть функций\n\n- `СУММ` — сумма чисел;\n- `СРЗНАЧ` — сумма / **количество чисел**;\n- `МАКС`, `МИН` — наибольшее и наименьшее;\n- `СЧЁТ` — сколько **чисел**;\n- `СЧЁТЗ` — сколько **непустых** ячеек (числа и текст).\n\n## Что считается числом\n\n- **Ноль** — число: он участвует в СРЗНАЧ, СЧЁТ, МИН.\n- **Пустая ячейка** и **текст** в диапазоне пропускаются (кроме СЧЁТЗ).\n- Среднее делят на количество **чисел**, а не ячеек.\n\n## Лайфхаки ЕНТ\n\n- Выпиши числа диапазона, вычеркни пустое и текст, потом считай.\n- Если ячейка попала в два диапазона одной функции, она считается **дважды**.\n- Обратная задача: сумма = среднее · количество чисел.\n- При копировании диапазон в функции сдвигается так же, как ссылки.\n\n## Частые ошибки\n\n- Деление на число всех ячеек вместо чисел.\n- `B2;B9` вместо `B2:B9`: две ячейки, а не диапазон.\n- Забытый знак «=» или скобки.","kk":"# SUM, AVERAGE, MAX, MIN, COUNT функциялары\n\n## Функция қалай жазылады\n\n`=АТЫ(аргументтер)`. Аргумент — диапазон (`A1:A5`), ұяшық (`C1`), сан, басқа функция; олардың арасында **«;»**. Орысша аттары: СУММ, СРЗНАЧ, МАКС, МИН, СЧЁТ, СЧЁТЗ.\n\n## Алты функция\n\n- `SUM` — сандардың қосындысы;\n- `AVERAGE` — қосынды / **сандардың саны**;\n- `MAX`, `MIN` — ең үлкен және ең кіші сан;\n- `COUNT` — неше **сан** бар;\n- `COUNTA` — неше **бос емес** ұяшық бар (сан және мәтін).\n\n## Не сан болып есептеледі\n\n- **Нөл** — сан: ол AVERAGE, COUNT, MIN функцияларына қатысады.\n- Диапазондағы **бос ұяшық** пен **мәтін** өткізіледі (COUNTA-дан басқа).\n- Орташа мәнді **сандардың санына** бөледі, ұяшықтардың санына емес.\n\n## ҰБТ-ға арналған кеңестер\n\n- Диапазондағы сандарды жазып ал, бос ұяшық пен мәтінді сызып таста, содан кейін есепте.\n- Ұяшық бір функцияның екі диапазонына түссе, ол **екі рет** есептеледі.\n- Кері есеп: қосынды = орташа мән · сандар саны.\n- Көшіргенде функциядағы диапазон да сілтемелер сияқты жылжиды.\n\n## Жиі кететін қателер\n\n- Сандарға емес, барлық ұяшыққа бөлу.\n- `B2:B9` орнына `B2;B9`: диапазон емес, екі ұяшық.\n- «=» белгісін немесе жақшаны ұмыту."},
  "data-4-if": {"ru":"# Функция ЕСЛИ и условия\n\n## ЕСЛИ\n\n`=ЕСЛИ(условие; если_верно; если_неверно)` (IF). Условие верно — берётся вторая часть, неверно — третья. Результат: число, текст или вычисление. Если третью часть опустить, при неверном условии будет ЛОЖЬ.\n\n## Условие\n\nЗнаки: `>`, `<`, `>=`, `<=`, `=`, `<>` (не равно; не `==` и не `!=`). `>=` и `<=` включают границу. **Текст — в кавычки**, числа и условие целиком — без. Без `=` в начале это не формула.\n\n## Вложенные ЕСЛИ\n\nПроверки идут **сверху вниз**, первое верное условие — ответ. Сначала самое строгое (>= 85, потом >= 65). Результатов на один больше, чем ЕСЛИ; скобок в конце столько же, сколько ЕСЛИ.\n\n## По условию\n\n- `=СЧЁТЕСЛИ(диапазон; \">=60\")` — сколько;\n- `=СУММЕСЛИ(диапазон; условие; диапазон_суммы)` — сумма;\n- `И(…;…)` — верны все, `ИЛИ(…;…)` — верно хотя бы одно.\n\n## Лайфхаки ЕНТ\n\n- Подставь число и иди по условиям сверху вниз.\n- Смотри на строгость знака: 60 >= 60 верно, 60 > 60 неверно.\n- В СУММЕСЛИ сверь, какой диапазон ищем, а какой складываем.\n\n## Частые ошибки\n\n- Текст без кавычек (#ИМЯ?), `==` вместо `=`.\n- Условия вложенного ЕСЛИ в обратном порядке.\n- Перепутаны диапазоны или забыто, что граница входит.","kk":"# IF функциясы және шарттар\n\n## IF\n\n`=IF(шарт; ақиқат_болса; жалған_болса)` (орысша ЕСЛИ). Шарт ақиқат болса — екінші бөлік, жалған болса — үшінші бөлік алынады. Үшінші бөлік жазылмаса, шарт жалған болғанда ЛОЖЬ (FALSE) шығады.\n\n## Шарт\n\nБелгілер: `>`, `<`, `>=`, `<=`, `=`, `<>` (тең емес; `==` және `!=` емес). `>=` және `<=` шекараны қосады. **Мәтін — тырнақшада**, сандар мен шарттың өзі — тырнақшасыз. Басында `=` болмаса, бұл формула емес.\n\n## Кірістірілген IF\n\nТексерулер **жоғарыдан төмен** жүреді, бірінші ақиқат шарт — жауап. Алдымен ең қатаңы (>= 85). Нәтижелер IF-тен біреуге көп; соңындағы жақша саны IF санындай.\n\n## Шарт бойынша\n\n- `=COUNTIF(диапазон; \">=60\")` — қанша;\n- `=SUMIF(диапазон; шарт; қосынды_диапазоны)` — қосынды;\n- `AND(…;…)` — бәрі ақиқат, `OR(…;…)` — кемінде біреуі ақиқат.\n\n## ҰБТ-ға арналған кеңестер\n\n- Санды қой да, шарттармен жоғарыдан төмен жүр.\n- Белгінің қатаңдығына назар аудар: 60 >= 60 ақиқат, 60 > 60 жалған.\n- SUMIF-те қай диапазон ізделетінін, қайсысы қосылатынын тексер.\n\n## Жиі кететін қателер\n\n- Мәтін тырнақшасыз (#ИМЯ?), `=` орнына `==`.\n- Кірістірілген IF шарттары кері ретпен.\n- Диапазондар шатастырылған немесе шекараның кіретіні ұмытылған."},
  "data-5-text": {"ru":"# Текстовые функции\n\n## Текст в формулах\n\nТекст — цепочка символов: буквы, цифры, знаки и **пробелы**. Позиции считаются **с 1**. Готовый текст в формуле берут в **кавычки**, адрес ячейки — без них.\n\n## Функции\n\n- `СТРОЧН`, `ПРОПИСН` — все буквы строчные или ЗАГЛАВНЫЕ;\n- `ДЛСТР(текст)` — число символов (пробел и дефис тоже);\n- `A1&B1` и `СЦЕПИТЬ(A1;\" \";B1)` — склейка; пробел кладут в кавычки;\n- `ЛЕВСИМВ(текст;n)`, `ПРАВСИМВ(текст;n)` — n символов слева или справа;\n- `ПСТР(текст;с_какого;n)` — кусок из середины;\n- `ЗАМЕНИТЬ(текст;с_какого;сколько;новый)` — замена по позиции;\n- `ПОДСТАВИТЬ(текст;старый;новый;[номер])` — замена по образцу, **различает регистр**.\n\n## Лайфхаки ЕНТ\n\n- Вложенные функции читай изнутри наружу.\n- Имя файла без расширения: `ЛЕВСИМВ(A1;ДЛСТР(A1)-5)`.\n- Сколько раз встречается буква: `ДЛСТР(A1)-ДЛСТР(ПОДСТАВИТЬ(A1;\"a\";\"\"))`.\n- Пустые кавычки `\"\"` означают «ничего» (удаление).\n\n## Частые ошибки\n\n- Не посчитан пробел или дефис.\n- Нет кавычек вокруг текста (ошибка #ИМЯ?).\n- Между словами забыт пробел при склейке.\n- В ПОДСТАВИТЬ перепутан регистр буквы.","kk":"# Мәтіндік функциялар\n\n## Формулалардағы мәтін\n\nМәтін — символдар тізбегі: әріптер, цифрлар, белгілер және **бос орындар**. Орындар **1-ден** саналады. Формуладағы дайын мәтін **тырнақшада** тұрады, ұяшық мекенжайы — тырнақшасыз.\n\n## Функциялар\n\n- `LOWER`, `UPPER` — барлық әріп кіші немесе БАС әріп болады;\n- `LEN(мәтін)` — символдар саны (бос орын мен дефис те);\n- `A1&B1` және `CONCATENATE(A1;\" \";B1)` — біріктіру; бос орынды тырнақшаға салады;\n- `LEFT(мәтін;n)`, `RIGHT(мәтін;n)` — сол немесе оң жақтан n символ;\n- `MID(мәтін;қай_орыннан;n)` — ортасынан бөлік;\n- `REPLACE(мәтін;қай_орыннан;қанша;жаңа)` — орны бойынша ауыстыру;\n- `SUBSTITUTE(мәтін;ескі;жаңа;[нөмір])` — үлгі бойынша ауыстыру, **регистрді ажыратады**.\n\n## ҰБТ-ға арналған кеңестер\n\n- Кірістірілген функцияларды ішінен сыртына қарай оқы.\n- Кеңейтілімсіз файл атауы: `LEFT(A1;LEN(A1)-5)`.\n- Әріп неше рет кездеседі: `LEN(A1)-LEN(SUBSTITUTE(A1;\"a\";\"\"))`.\n- `\"\"` — бос мәтін (жою).\n\n## Жиі кететін қателер\n\n- Бос орын немесе дефис саналмаған.\n- Мәтіннің айналасында тырнақша жоқ (#ИМЯ? қатесі).\n- Біріктіргенде сөздердің арасындағы бос орын ұмытылған.\n- SUBSTITUTE функциясында әріптің регистрі шатастырылған."},
  "data-6-copy": {"ru":"# Копирование формул: задачи ЕНТ\n\n## Три шага «в уме»\n\n1. **Сдвиг** = новая ячейка − старая (столбцы: A=1, B=2, C=3…; вправо и вниз — плюс, **влево и вверх — минус**).\n2. **Каждая ссылка отдельно**: то, перед чем стоит **$**, остаётся, остальное едет на сдвиг.\n3. **Значение**: подставь числа в новую формулу.\n\n> `=C4+D3` из E4 в C2 (−2, −2) → `=A2+B1`\n\n## Диапазон и функции\n\n- Диапазон — **две ссылки**, каждая едет сама: `=СУММ(B2:B4)` вниз → `=СУММ(B3:B5)` (скользящее окно).\n- `=СУММ($B$2:B2)` вниз — растущий итог (начало стоит, конец ползёт).\n- Доля от итога: `=B2*100/B$5` — строка итога закреплена, столбец свободен.\n\n## Ловушки ЕНТ\n\n- **Вырезать (Ctrl+X) ≠ копировать (Ctrl+C):** при переносе ссылки **не сдвигаются**.\n- Ссылка ушла левее A или выше строки 1 — ошибка **#ССЫЛКА!** (в английской версии #REF!).\n- Забыли $ у делителя — он «уезжает» вниз: на пустую ячейку (#ДЕЛ/0!) или на чужое число (неверная доля).\n- Обратная задача: сдвиг назад, закреплённое не трогаем.","kk":"# Формулаларды көшіру: ҰБТ есептері\n\n## «Ойша» үш қадам\n\n1. **Жылжу** = жаңа ұяшық − ескі ұяшық (бағандар: A=1, B=2, C=3…; оңға және төмен — плюс, **солға және жоғары — минус**).\n2. **Әр сілтеме бөлек**: алдында **$** тұрғаны қалады, қалғаны жылжуға кетеді.\n3. **Мән**: жаңа формулаға сандарды қой.\n\n> E4 ұяшығынан C2 ұяшығына (−2, −2) `=C4+D3` → `=A2+B1`\n\n## Диапазон және функциялар\n\n- Диапазон — **екі сілтеме**, әрқайсысы өзі жылжиды: `=SUM(B2:B4)` төмен → `=SUM(B3:B5)` (сырғитын терезе).\n- `=SUM($B$2:B2)` төмен — өсетін қорытынды (басы тұр, соңы жылжиды).\n- Қорытындыдан үлес: `=B2*100/B$5` — қорытынды жолы бекітілген, баған еркін.\n\n## ҰБТ тұзақтары\n\n- **Қиып алу (Ctrl+X) ≠ көшіру (Ctrl+C):** қиып алып қойғанда сілтемелер **жылжымайды**.\n- Сілтеме A бағанынан солға немесе 1-жолдан жоғары кетсе — **#REF!** қатесі (орысша #ССЫЛКА!).\n- Бөлгіштегі $ ұмытылса, ол төмен «кетіп қалады»: бос ұяшыққа (#DIV/0!, орысша #ДЕЛ/0!) немесе басқа санға (үлес қате шығады).\n- Кері есеп: жылжуды артқа қайтар, бекітілгенге тиіспе."},
  "data-7-charts": {"ru":"# Диаграммы, сортировка и фильтр\n\n## Диаграмма\n\n- Строится по **выделенному диапазону**: первый столбец — подписи, первая строка — названия рядов (легенда).\n- **Круговая** — доли целого, **один ряд**: сектор = значение ÷ сумма × 360°. **Столбчатая** — сравнение, **график** — изменение во времени.\n- Число в ячейке изменено — диаграмма обновляется сама. «Строка/столбец» меняет роли рядов и подписей.\n\n## Сортировка\n\n- Переставляет **строки целиком** по ключевому столбцу; заголовок на месте.\n- Равные значения упорядочивает **второй уровень**: «по классу, затем по баллу».\n- Нельзя сортировать один столбец таблицы: данные перепутаются. Числа-текст: «10» раньше «9». Пустые — в конец.\n\n## Фильтр\n\n- **Скрывает** неподходящие строки, но не удаляет; номера строк идут с пропусками.\n- Условия в разных столбцах работают вместе.\n- СУММ считает и скрытые строки, ПРОМЕЖУТОЧНЫЕ.ИТОГИ — только видимые.\n\n## Условное форматирование\n\n- Цвет по правилу; меняется только вид. Формула `=$C2>=85` красит всю строку ($ закрепляет столбец).\n- Ручная заливка сама не меняется.\n\n## Лайфхак ЕНТ\n\nСначала определи, **что выделено**, потом — что делает инструмент.","kk":"# Диаграммалар, сұрыптау және сүзгі\n\n## Диаграмма\n\n- **Белгіленген диапазон** бойынша салынады: бірінші баған — белгілер, бірінші жол — қатар атаулары (легенда).\n- **Дөңгелек** — бүтіннің үлестері, **бір қатар**: сектор = мән ÷ қосынды × 360°. **Бағанды** — салыстыру, **график** — уақыт бойынша өзгеру.\n- Сан өзгерсе — диаграмма өзі жаңарады. «Жол/баған» қатар мен белгілердің рөлін ауыстырады.\n\n## Сұрыптау\n\n- **Жолдарды түгел** кілт баған бойынша ауыстырады; тақырып орнында.\n- Тең мәндерді **екінші деңгей** реттейді: «сынып бойынша, содан кейін балл бойынша».\n- Кестенің бір бағанын сұрыптауға болмайды: деректер шатасады. Мәтін түріндегі сандар: «10» «9» алдында. Бос ұяшықтар — соңында.\n\n## Сүзгі\n\n- Сәйкес келмейтін жолдарды **жасырады**, жоймайды; жол нөмірлері үзіліспен жүреді.\n- Әртүрлі бағандардағы шарттар бірге жұмыс істейді.\n- SUM жасырын жолдарды да санайды, SUBTOTAL — тек көрінетіндерді.\n\n## Шартты пішімдеу\n\n- Ереже бойынша түс; тек сыртқы түрі өзгереді. `=$C2>=85` формуласы бүкіл жолды бояйды ($ бағанды бекітеді).\n- Қолмен боялған бояу өздігінен өзгермейді.\n\n## ҰБТ кеңесі\n\nАлдымен **не белгіленгенін** анықта, содан кейін — құрал не істейтінін."},
  "db-1-relational": {"ru":"# Реляционные базы данных\n\n## Основные понятия\n\n- **База данных (БД)** — организованное хранилище данных.\n- **СУБД** — программа для работы с БД: Access, SQLite, MySQL, PostgreSQL.\n- **Таблица**: строка = **запись**, столбец = **поле** (атрибут). Шапка записью не считается.\n- **Значение** — на пересечении записи и поля. Типы полей: числовой, текстовый, дата, логический.\n\n## Модели данных\n\n- **Иерархическая** — дерево, у каждой записи (кроме верхней) один «родитель» (папки).\n- **Сетевая** — граф, «родителей» может быть несколько.\n- **Реляционная** — таблицы, связанные через значения полей.\n\n## Ключи и связи\n\n- **Первичный ключ** — поле с неповторяющимися значениями (ИИН, номер билета; не фамилия). **Составной ключ** — пара полей.\n- **Внешний ключ** — поле, которое ссылается на ключ другой таблицы.\n- Связи: **1 : 1** (страна — столица), **1 : N** (класс — ученики), **N : M** (ученик — кружок, через промежуточную таблицу).\n\n## Лайфхаки ЕНТ\n\n- Записей = строки без шапки. Значений = записи × поля.\n- Тип связи: спроси «сколько?» в обе стороны.","kk":"# Реляциялық деректер қоры\n\n## Негізгі ұғымдар\n\n- **Деректер қоры (ДҚ)** — деректердің ұйымдастырылған қоймасы.\n- **ДҚБЖ** — ДҚ-мен жұмыс істейтін программа: Access, SQLite, MySQL, PostgreSQL.\n- **Кесте**: жол = **жазба**, баған = **өріс** (атрибут). Тақырып жолы жазба емес.\n- **Мән** — жазба мен өрістің қиылысында. Өріс түрлері: сандық, мәтіндік, күн, логикалық.\n\n## Деректер модельдері\n\n- **Иерархиялық** — ағаш, әр жазбаның (ең жоғарғысынан басқа) бір «жоғарғы» жазбасы бар (папкалар).\n- **Желілік** — граф, «жоғарғы» жазбалар бірнешеу болуы мүмкін.\n- **Реляциялық** — өріс мәндері арқылы байланысқан кестелер.\n\n## Кілттер және байланыстар\n\n- **Бастапқы кілт** — мәндері қайталанбайтын өріс (ЖСН, билет нөмірі; тегі емес). **Құрама кілт** — өрістер жұбы.\n- **Сыртқы кілт** — басқа кестенің кілтіне сілтеме жасайтын өріс.\n- Байланыстар: **1 : 1** (ел — елорда), **1 : N** (сынып — оқушылар), **N : M** (оқушы — үйірме, аралық кесте арқылы).\n\n## ҰБТ-ға арналған кеңестер\n\n- Жазбалар = тақырып жолынсыз жолдар. Мәндер = жазбалар × өрістер.\n- Байланыс түрі: екі бағытта да «қанша?» деп сұра."},
  "db-10-ddl": {"ru":"# Создание и изменение таблиц\n\n## Создание\n\n- `CREATE TABLE Books (ID INTEGER PRIMARY KEY, Title TEXT, Year INTEGER);` — поля с типами через запятую, **после последнего запятой нет**.\n- Типы: `INTEGER` — целые, `REAL` — дробные, `TEXT` — текст, `DATE` — дата. Телефон, ИИН — `TEXT`.\n- `PRIMARY KEY` — ключ: не повторяется и не бывает пустым. Новая таблица пуста.\n\n## Добавление\n\n- `INSERT INTO Books VALUES (1, 'Алгебра', 2021);` — значения **в порядке полей**, их столько же, сколько полей.\n- `INSERT INTO Books (ID, Title) VALUES (2, 'Физика');` — остальные поля получают **NULL**.\n- Повтор ключа или неверное число значений — **ошибка**, таблица не меняется.\n\n## Изменение и удаление\n\n- `UPDATE Books SET Copies = Copies + 5 WHERE …;` — новое значение считается из старого. Без WHERE изменятся **все** записи.\n- `DELETE FROM Books WHERE …;` — убирает записи; без WHERE — **все**, таблица остаётся пустой.\n- `DROP TABLE Books;` — убирает **таблицу целиком**, потом запрос к ней — ошибка.\n- `ALTER TABLE Books ADD COLUMN Author TEXT;` — новое поле, в старых записях NULL.\n\n## Лайфхаки для ЕНТ\n\nВ задачах «что останется» выполняй команды **по очереди**. WHERE без совпадений — не ошибка, а 0 записей.","kk":"# Кестелерді құру және өзгерту\n\n## Құру\n\n- `CREATE TABLE Books (ID INTEGER PRIMARY KEY, Title TEXT, Year INTEGER);` — түрлері бар өрістер үтір арқылы, **соңғысынан кейін үтір жоқ**.\n- Түрлер: `INTEGER` — бүтін, `REAL` — нақты, `TEXT` — мәтін, `DATE` — күн. Телефон мен ЖСН — `TEXT`.\n- `PRIMARY KEY` — кілт: қайталанбайды және бос болмайды. Жаңа кесте бос.\n\n## Қосу\n\n- `INSERT INTO Books VALUES (1, 'Алгебра', 2021);` — мәндер **өрістер ретімен**, саны өрістер санына тең.\n- `INSERT INTO Books (ID, Title) VALUES (2, 'Физика');` — қалған өрістер **NULL** алады.\n- Кілттің қайталануы немесе мәндер санының дұрыс болмауы — **қате**, кесте өзгермейді.\n\n## Өзгерту және жою\n\n- `UPDATE Books SET Copies = Copies + 5 WHERE …;` — жаңа мән ескісінен есептеледі. WHERE болмаса, **барлық** жазба өзгереді.\n- `DELETE FROM Books WHERE …;` — жазбаларды алады; WHERE болмаса — **барлығын**, кесте бос қалады.\n- `DROP TABLE Books;` — **кестені түгелдей** алады, одан кейін оған сұраныс — қате.\n- `ALTER TABLE Books ADD COLUMN Author TEXT;` — жаңа өріс, ескі жазбаларда NULL.\n\n## ҰБТ-ға кеңестер\n\n«Не қалады» есептерінде командаларды **кезекпен** орында. Сәйкес жазбасы жоқ WHERE — қате емес, 0 жазба."},
  "db-2-select": {"ru":"# Запросы SELECT\n\n## Общий вид\n\n`SELECT поля FROM таблица WHERE условие ORDER BY поле;`\n\n- `SELECT *` — все поля; `SELECT DISTINCT` — без повторов.\n- Порядок частей строгий: SELECT → FROM → WHERE → ORDER BY.\n\n## Условия WHERE\n\n- Сравнения: `=` `<>` `>` `<` `>=` `<=` (равно — один `=`).\n- **AND** — верны оба, **OR** — хотя бы одно, **NOT** — не. AND выполняется раньше OR; сомневаешься — ставь скобки.\n- **BETWEEN a AND b** — от a до b, **границы входят**.\n- **IN (1, 2, 3)** — значение из списка.\n- **LIKE** — шаблон: `%` любое число символов, `_` ровно один.\n- Текст — в одинарных кавычках: `'Дана'`; числа — без них.\n\n## Сортировка\n\n`ORDER BY Mark DESC, Name` — DESC по убыванию, ASC (по умолчанию) по возрастанию; второе поле работает при равенстве первого.\n\n## Лайфхаки для ЕНТ\n\n- Считая записи, иди по таблице сверху вниз и вычёркивай неподходящие.\n- Видишь BETWEEN — проверь строки на самих границах.\n- «Первая строка после ORDER BY»: сначала WHERE, потом сортировка.\n\n## Частые ошибки\n\n- Границы BETWEEN не посчитаны.\n- AND и OR перепутаны: `Class = 9 AND Class = 11` не выведет ничего.","kk":"# SELECT сұраныстары\n\n## Жалпы түрі\n\n`SELECT өрістер FROM кесте WHERE шарт ORDER BY өріс;`\n\n- `SELECT *` — барлық өріс; `SELECT DISTINCT` — қайталаусыз.\n- Бөліктер реті қатаң: SELECT → FROM → WHERE → ORDER BY.\n\n## WHERE шарттары\n\n- Салыстырулар: `=` `<>` `>` `<` `>=` `<=` (тең — бір `=`).\n- **AND** — екеуі де орындалады, **OR** — кемінде біреуі, **NOT** — емес. AND OR-дан бұрын орындалады; күмәндансаң — жақша қой.\n- **BETWEEN a AND b** — a мен b аралығы, **шектер кіреді**.\n- **IN (1, 2, 3)** — тізімдегі мән.\n- **LIKE** — үлгі: `%` — кез келген сандағы таңбалар, `_` — дәл бір таңба.\n- Мәтін — бір тырнақшада: `'Дана'`; сандар — тырнақшасыз.\n\n## Сұрыптау\n\n`ORDER BY Mark DESC, Name` — DESC кему бойынша, ASC (әдепкі) өсу бойынша; екінші өріс бірінші тең болғанда жұмыс істейді.\n\n## ҰБТ-ға арналған кеңестер\n\n- Жазбаларды санағанда, кестені жоғарыдан төмен қарай қарап шығып, сәйкес келмейтіндерін сызып таста.\n- BETWEEN көрсең — шектердің өзіндегі жолдарды тексер.\n- «ORDER BY-дан кейінгі бірінші жол»: алдымен WHERE, содан кейін сұрыптау.\n\n## Жиі кететін қателер\n\n- BETWEEN шектері есепке алынбаған.\n- AND және OR шатастырылған: `Class = 9 AND Class = 11` ештеңе шығармайды."},
  "db-3-modify": {"ru":"# Изменение данных и итоги\n\n## Команды\n\n- `CREATE TABLE T (поле ТИП, …, PRIMARY KEY)` — создать таблицу. Типы: INTEGER (целое), REAL (дробное), TEXT / VARCHAR(n) (текст), DATE (дата).\n- `INSERT INTO T (поля) VALUES (значения);` — добавить запись. **Порядок значений = порядок полей.**\n- `UPDATE T SET поле = значение WHERE условие;` — изменить.\n- `DELETE FROM T WHERE условие;` — удалить.\n- **Без WHERE** UPDATE и DELETE затронут **все** записи.\n\n## Итоговые функции\n\n`COUNT(*)` — число записей, `SUM` — сумма, `AVG` — среднее (сумма : количество), `MIN` / `MAX` — наименьшее / наибольшее. Сначала WHERE, потом итог. `AS` — название столбца.\n\n`GROUP BY поле` — итог по каждой группе: одна строка на группу.\n\n## Лайфхаки для ЕНТ\n\n- В заданиях «сколько записей останется» считай записи по условию и вычитай из общего числа. Запись, подходящую под оба условия OR, считай один раз.\n- «Что вернёт SUM / AVG после UPDATE» — сначала примени UPDATE, потом считай.\n\n## Частые ошибки\n\n- Перепутан порядок значений в VALUES.\n- Забыт WHERE: изменены или удалены все записи.\n- Среднее посчитано как (MIN + MAX) : 2.","kk":"# Деректерді өзгерту және қорытындылар\n\n## Командалар\n\n- `CREATE TABLE T (өріс ТИП, …, PRIMARY KEY)` — кесте құру. Типтер: INTEGER (бүтін), REAL (нақты), TEXT / VARCHAR(n) (мәтін), DATE (күн).\n- `INSERT INTO T (өрістер) VALUES (мәндер);` — жазба қосу. **Мәндер реті = өрістер реті.**\n- `UPDATE T SET өріс = мән WHERE шарт;` — өзгерту.\n- `DELETE FROM T WHERE шарт;` — жою.\n- **WHERE болмаса** UPDATE және DELETE **барлық** жазбаға әсер етеді.\n\n## Қорытынды функциялар\n\n`COUNT(*)` — жазбалар саны, `SUM` — қосынды, `AVG` — орташа мән (қосынды : сан), `MIN` / `MAX` — ең кіші / ең үлкен. Алдымен WHERE, содан кейін қорытынды. `AS` — баған атауы.\n\n`GROUP BY өріс` — әр топ бойынша қорытынды: әр топқа бір жол.\n\n## ҰБТ-ға арналған кеңестер\n\n- «Неше жазба қалады» тапсырмаларында шартқа сәйкес жазбаларды санап, жалпы саннан алып таста. OR-дың екі шартына да сәйкес келетін жазбаны бір рет сана.\n- «UPDATE-тен кейін SUM / AVG не қайтарады» — алдымен UPDATE-ті қолдан, содан кейін сана.\n\n## Жиі кететін қателер\n\n- VALUES ішіндегі мәндер реті шатастырылған.\n- WHERE ұмытылған: барлық жазба өзгерген немесе жойылған.\n- Орташа мән (MIN + MAX) : 2 түрінде есептелген."},
  "db-4-keys": {"ru":"# Ключи и связи таблиц\n\n## Первичный ключ\n- Поле (или несколько полей), по которому запись находится однозначно: ИИН, номер билета, госномер, табельный номер.\n- Три свойства: **не повторяется**, **не бывает пустым**, **не меняется**. Фамилия, класс, телефон не подходят.\n- В таблице **один** первичный ключ, но он может быть **составным**: минимальный набор полей, который вместе не повторяется, например (ученик, предмет, четверть).\n\n## Внешний ключ\n- Поле со значениями ключа **другой** таблицы («Код класса» в «Учениках»).\n- Значения **могут повторяться**, но обязаны **существовать** в таблице-источнике (ссылочная целостность).\n\n## Связи\n- **1 : N**: внешний ключ стоит в таблице со стороны «многие».\n- **1 : 1**: значения внешнего ключа не повторяются.\n- **N : M**: таблица-связка с двумя внешними ключами; её ключ составной, и в ней могут лежать свои данные (оценка, дата).\n\n## Лайфхаки ЕНТ\n- Ключ ищи среди полей без повторов и пустых значений; если таких нет, пробуй пару, потом тройку.\n- Повторы во внешнем ключе — не ошибка.\n- Записей в связке столько, сколько связей, а не людей. Максимум записей — произведение числа значений в полях ключа.","kk":"# Кестелердің кілттері және байланыстары\n\n## Бастапқы кілт\n- Жазбаны бір мәнді табуға болатын өріс (немесе бірнеше өріс): ЖСН, билет нөмірі, мемлекеттік нөмір, табель нөмірі.\n- Үш қасиеті: **қайталанбайды**, **бос болмайды**, **өзгермейді**. Тегі, сынып, телефон жарамайды.\n- Кестеде бастапқы кілт **біреу**, бірақ ол **құрама** болуы мүмкін: бірге қайталанбайтын өрістердің ең аз жиыны, мысалы (оқушы, пән, тоқсан).\n\n## Сыртқы кілт\n- **Басқа** кестенің кілт мәндері бар өріс («Оқушылар» кестесіндегі «Сынып коды»).\n- Мәндері **қайталана алады**, бірақ сілтеме жасалатын кестеде **болуы** шарт (сілтемелік тұтастық).\n\n## Байланыстар\n- **1 : N**: сыртқы кілт «көп» жағындағы кестеде тұрады.\n- **1 : 1**: сыртқы кілттің мәндері қайталанбайды.\n- **N : M**: екі сыртқы кілті бар аралық кесте; оның кілті құрама, және онда өз деректері болуы мүмкін (баға, күні).\n\n## ҰБТ-ға арналған кеңестер\n- Кілтті қайталанбайтын және бос емес өрістерден ізде; олар жоқ болса, жұпты, содан кейін үштікті тексер.\n- Сыртқы кілттегі қайталану — қате емес.\n- Аралық кестеде жазба саны адам санына емес, байланыс санына тең. Жазбалардың ең көп саны — кілт өрістеріндегі мәндер сандарының көбейтіндісі."},
  "db-5-design": {"ru":"# Проектирование базы данных\n\n## От задачи к таблицам\n- **Сущность** — то, о чём хранят данные (ученик, товар): одна сущность — одна таблица.\n- **Атрибут** — свойство сущности, он становится **полем**. Один объект — одна **запись**. Есть свои свойства — значит, сущность.\n\n## Типы данных\n- Целый, вещественный, текстовый, дата, логический.\n- Считают со значением — число. Не считают (телефон, ИИН, почтовый индекс 010000) — **текст**: ведущие нули не теряются.\n- Текст сортируется по символам: «100» идёт раньше «25».\n\n## Избыточность и аномалии\n- Одни и те же сведения в нескольких строках — **избыточность**.\n- Аномалии: **изменения** (поправили не везде), **добавления** (нельзя ввести кружок без ученика), **удаления** (вместе со строкой пропали нужные сведения).\n- Лечение: повторяющиеся поля — в новую таблицу с ключом, в старой — внешний ключ.\n\n## Лайфхаки ЕНТ\n- Записей в новой таблице столько, сколько разных значений; поля считай с ключами: вынесли k полей → в новой k + 1, в старой на k − 1 меньше.\n- Ячеек = записи · поля по каждой таблице; после разбиения их не всегда меньше.\n- СУБД: SQLite (файл), Access (формы и отчёты), MySQL и PostgreSQL (серверные). SQL — язык, а не СУБД.","kk":"# Деректер қорын жобалау\n\n## Есептен кестелерге\n- **Нысан** — деректері сақталатын объект (оқушы, тауар): бір нысан — бір кесте.\n- **Атрибут** — нысанның қасиеті, ол **өріске** айналады. Бір объект — бір **жазба**. Өз қасиеттері бар — демек, нысан.\n\n## Деректер түрлері\n- Бүтін, нақты, мәтіндік, күн, логикалық.\n- Мәнмен есептесе — сан. Есептемесе (телефон, ЖСН, 010000 пошталық индексі) — **мәтін**: алдыңғы нөлдер жоғалмайды.\n- Мәтін таңбалар бойынша сұрыпталады: «100» мәні «25» мәнінен бұрын тұрады.\n\n## Артықтық және аномалиялар\n- Бірдей мәліметтердің бірнеше жолда болуы — **артықтық**.\n- Аномалиялар: **өзгерту** (бәрінде түзетпеді), **қосу** (оқушысыз үйірмені енгізу мүмкін емес), **жою** (жолмен бірге қажетті мәліметтер жоғалды).\n- Емі: қайталанатын өрістер — кілті бар жаңа кестеге, ескі кестеде — сыртқы кілт.\n\n## ҰБТ-ға арналған кеңестер\n- Жаңа кестедегі жазба әртүрлі мәндер санындай; өрістерді кілттерімен қоса сана: k өріс шықса → жаңасында k + 1, ескісінде k − 1 өріс кем.\n- Ұяшық = жазбалар · өрістер, әр кесте бойынша; бөлгеннен кейін ол әрдайым азая бермейді.\n- ДҚБЖ: SQLite (файл), Access (формалар мен есептер), MySQL және PostgreSQL (серверлік). SQL — ДҚБЖ емес, тіл."},
  "db-6-where": {"ru":"# Условия WHERE\n\n## Порядок вычисления\n\nСкобки → **NOT** → **AND** → **OR**. `A OR B AND C` — это `A OR (B AND C)`. Сомневаешься — ставь скобки.\n\n## NOT и де Морган\n\n- `NOT (A OR B)` = `NOT A AND NOT B`; `NOT (A AND B)` = `NOT A OR NOT B`.\n- `BETWEEN a AND b` = `>= a AND <= b` (границы входят); `NOT BETWEEN a AND b` = меньше a или больше b; `NOT IN`, `NOT LIKE`, `IS NOT NULL`.\n- Переворачивая знак: `>` → `<=`, `=` → `<>`.\n\n## LIKE\n\n- `%` — любое число символов (даже ноль), `_` — ровно один.\n- `'А%'` начало, `'%с'` конец, `'%и%'` внутри, `'_а%'` вторая буква а, `'А____'` ровно 5 букв.\n\n## NULL — пустое значение\n\n- Это не 0 и не пустая строка, а «неизвестно».\n- Любое сравнение с NULL **не истинно**: `= NULL` не работает никогда. Пустоту ловят `IS NULL` / `IS NOT NULL`.\n- `Score >= 70` и `Score < 70` вместе дают **не всю** таблицу: строки с NULL выпадают. То же с `<>` и NOT.\n\n## Лайфхаки для ЕНТ\n\n- Считая записи, иди по таблице сверху вниз и проверяй условие для каждой строки.\n- Видишь NOT перед скобкой — раскрой по де Моргану.\n- Видишь пустую ячейку или NULL — сравнения её не берут.","kk":"# WHERE шарттары\n\n## Есептеу реті\n\nЖақшалар → **NOT** → **AND** → **OR**. `A OR B AND C` — бұл `A OR (B AND C)`. Күмәндансаң — жақша қой.\n\n## NOT және де Морган\n\n- `NOT (A OR B)` = `NOT A AND NOT B`; `NOT (A AND B)` = `NOT A OR NOT B`.\n- `BETWEEN a AND b` = `>= a AND <= b` (шектер кіреді); `NOT BETWEEN a AND b` = a мәнінен кем немесе b мәнінен артық; `NOT IN`, `NOT LIKE`, `IS NOT NULL`.\n- Белгіні төңкергенде: `>` → `<=`, `=` → `<>`.\n\n## LIKE\n\n- `%` — кез келген сандағы таңба (бірде-біреуі болмауы да мүмкін), `_` — дәл бір таңба.\n- `'А%'` басы, `'%с'` соңы, `'%и%'` ішінде, `'_а%'` екінші әріп а, `'А____'` дәл 5 әріп.\n\n## NULL — бос мән\n\n- Бұл 0 емес және бос жол емес, «белгісіз».\n- NULL мәнімен кез келген салыстыру **ақиқат емес**: `= NULL` ешқашан жұмыс істемейді. Бос мәнді `IS NULL` / `IS NOT NULL` ұстайды.\n- `Score >= 70` және `Score < 70` бірге бүкіл кестені **бермейді**: NULL бар жолдар түсіп қалады. `<>` және NOT-пен де солай.\n\n## ҰБТ-ға арналған кеңестер\n\n- Жазбаларды санағанда, кестені жоғарыдан төмен қарай жүріп, әр жол үшін шартты тексер.\n- Жақшаның алдында NOT көрсең — де Морган бойынша аш.\n- Бос ұяшық немесе NULL көрсең — салыстырулар оны алмайды."},
  "db-7-order": {"ru":"# Сортировка и уникальные значения\n\n## Общий вид\n\n`SELECT DISTINCT поля FROM таблица WHERE условие ORDER BY поле DESC LIMIT n OFFSET m;`\n\nПорядок работы базы: **FROM → WHERE → DISTINCT → ORDER BY → LIMIT**.\n\n## ORDER BY\n\n- **ASC** — по возрастанию (по умолчанию), **DESC** — по убыванию.\n- Числа — по величине, текст — по алфавиту.\n- Два ключа: `ORDER BY Pts DESC, Name` — при равных очках решает имя. **DESC действует только на своё поле.**\n- Без ORDER BY порядок строк не гарантирован.\n\n## DISTINCT\n\nОставляет каждую строку один раз. Повтор — совпадение **всех** выбранных полей: `DISTINCT Class, Sport` — уникальные пары.\n\n## LIMIT и OFFSET\n\n- `LIMIT n` — не больше n строк.\n- `OFFSET m` — пропустить первые m строк: `LIMIT 3 OFFSET 2` — строки с 3-й по 5-ю.\n- «Лучший» — `ORDER BY … DESC LIMIT 1`. В Access и MS SQL — `TOP n`.\n\n## Лайфхаки для ЕНТ\n\n- Выписывай строки после каждого шага: WHERE, DISTINCT, сортировка, OFFSET, LIMIT.\n- «Какая строка третья?» — выстрой всех по порядку и пронумеруй.\n\n## Частые ошибки\n\n- `ORDER BY Pts, Name DESC` — очки по возрастанию!\n- LIMIT без ORDER BY — это не «лучшие».\n- Пары DISTINCT считают по таблице, а не умножением.","kk":"# Сұрыптау және бірегей мәндер\n\n## Жалпы түрі\n\n`SELECT DISTINCT өрістер FROM кесте WHERE шарт ORDER BY өріс DESC LIMIT n OFFSET m;`\n\nДеректер қорының жұмыс реті: **FROM → WHERE → DISTINCT → ORDER BY → LIMIT**.\n\n## ORDER BY\n\n- **ASC** — өсу бойынша (әдепкі), **DESC** — кему бойынша.\n- Сандар — шамасы бойынша, мәтін — әліпби бойынша.\n- Екі кілт: `ORDER BY Pts DESC, Name` — ұпай тең болса, есім шешеді. **DESC тек өз өрісіне әсер етеді.**\n- ORDER BY болмаса, жолдардың реті кепілдендірілмейді.\n\n## DISTINCT\n\nӘр жолды бір реттен қалдырады. Қайталау — таңдалған **барлық** өрістің сәйкес келуі: `DISTINCT Class, Sport` — бірегей жұптар.\n\n## LIMIT және OFFSET\n\n- `LIMIT n` — n жолдан артық емес.\n- `OFFSET m` — алғашқы m жолды өткізіп жіберу: `LIMIT 3 OFFSET 2` — 3-тен 5-ке дейінгі жолдар.\n- «Үздік» — `ORDER BY … DESC LIMIT 1`. Access және MS SQL жүйелерінде — `TOP n`.\n\n## ҰБТ-ға арналған кеңестер\n\n- Әр қадамнан кейін жолдарды жаз: WHERE, DISTINCT, сұрыптау, OFFSET, LIMIT.\n- «Үшінші жол қайсы?» — бәрін ретімен тізіп, нөмірле.\n\n## Жиі кететін қателер\n\n- `ORDER BY Pts, Name DESC` — ұпай өсу бойынша!\n- ORDER BY жоқ LIMIT — «үздіктер» емес.\n- DISTINCT жұптарын кестеден санайды, көбейтумен емес."},
  "db-8-group": {"ru":"# Итоги: COUNT, SUM, AVG, GROUP BY\n\n## Итоговые функции и NULL\n\n- `COUNT(*)` — число **всех** строк.\n- `COUNT(поле)`, `SUM`, `AVG`, `MIN`, `MAX` берут только **непустые** значения: NULL пропускается.\n- `AVG` = сумма : число заполненных ячеек, а не число строк.\n- `COUNT(*) − COUNT(поле)` — число NULL.\n\n## GROUP BY и HAVING\n\n- `GROUP BY поле1, поле2` — одна строка на каждую группу (пару значений).\n- В SELECT — только поля группировки и итоговые функции.\n- NULL в поле группировки — отдельная группа.\n- **WHERE** отбирает строки **до** группировки, **HAVING** — группы **после**. Условие на итог — только в HAVING.\n- Порядок записи: SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY. Выполняется: FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY.\n\n## Лайфхаки для ЕНТ\n\n- «Сколько строк вернёт запрос»: вычеркни строки по WHERE, разложи остальные по группам, оставь группы по HAVING, посчитай их. Группа, все строки которой убрал WHERE, исчезает.\n\n## Частые ошибки\n\n- `WHERE SUM(...) > N` — ошибка, нужен HAVING.\n- Среднее по столбцу с NULL делят на число всех строк.\n- В SELECT стоит поле без функции, которого нет в GROUP BY.","kk":"# Қорытындылар: COUNT, SUM, AVG, GROUP BY\n\n## Қорытынды функциялар және NULL\n\n- `COUNT(*)` — **барлық** жолдар саны.\n- `COUNT(өріс)`, `SUM`, `AVG`, `MIN`, `MAX` тек **бос емес** мәндерді алады: NULL өткізіліп жіберіледі.\n- `AVG` = қосынды : толтырылған ұяшықтар саны, жолдар саны емес.\n- `COUNT(*) − COUNT(өріс)` — NULL саны.\n\n## GROUP BY және HAVING\n\n- `GROUP BY өріс1, өріс2` — әр топқа (мәндер жұбына) бір жол.\n- SELECT-те — тек топтау өрістері мен қорытынды функциялар.\n- Топтау өрісіндегі NULL — бөлек топ.\n- **WHERE** жолдарды топтауға **дейін**, **HAVING** топтарды **кейін** іріктейді. Қорытындыға шарт — тек HAVING-те.\n- Жазу реті: SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY. Орындалу реті: FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY.\n\n## ҰБТ-ға арналған кеңестер\n\n- «Сұраныс неше жол қайтарады»: WHERE бойынша жолдарды сызып таста, қалғандарын топтарға бөл, HAVING бойынша топтарды қалдыр, оларды сана. WHERE барлық жолын алып тастаған топ жоғалады.\n\n## Жиі кететін қателер\n\n- `WHERE SUM(...) > N` — қате, HAVING керек.\n- NULL бар баған бойынша орташа мән барлық жолдар санына бөлінеді.\n- SELECT-те функциясыз өріс тұр және ол GROUP BY-да жоқ."},
  "db-9-join": {"ru":"# Запросы к двум таблицам\n\n## Связь по ключу\n\nСведения лежат в разных таблицах и связаны **внешним ключом**: `Students.ClassID` → `Classes.ClassID`. Склеивают по ключу: внешний ключ равен первичному.\n\n## JOIN … ON\n\n`SELECT Students.Name, Classes.Teacher FROM Students JOIN Classes ON Students.ClassID = Classes.ClassID WHERE Classes.Grade = 10;`\n\n- **Таблица.поле** обязательно, если имя есть в обеих таблицах, иначе ошибка.\n- Порядок работы: FROM + JOIN → WHERE → GROUP BY, HAVING → SELECT → ORDER BY. WHERE видит поля обеих таблиц.\n- `JOIN` = `INNER JOIN`: строка без пары (пустой ключ, класс без учеников) в результат не попадает. `LEFT JOIN` сохраняет все строки левой таблицы.\n\n## Лайфхаки для ЕНТ\n\n- Строк в результате — столько, сколько нашлось **пар**: клиент с тремя заказами даёт три строки (DISTINCT уберёт повторы).\n- `FROM A, B` без условия даёт **n · m** строк (6 · 4 = 24). `FROM A, B WHERE A.k = B.k` — то же, что `JOIN`.\n\n## Частые ошибки\n\n- Забыто ON или условие связи.\n- Склейка по несвязанным полям (`Name = Teacher`): пар нет, результат пуст.\n- `ClassID` без указания таблицы.","kk":"# Екі кестеге сұраныстар\n\n## Кілт бойынша байланыс\n\nМәліметтер әртүрлі кестелерде жатыр және **сыртқы кілтпен** байланысқан: `Students.ClassID` → `Classes.ClassID`. Кілт бойынша біріктіреді: сыртқы кілт бастапқы кілтке тең.\n\n## JOIN … ON\n\n`SELECT Students.Name, Classes.Teacher FROM Students JOIN Classes ON Students.ClassID = Classes.ClassID WHERE Classes.Grade = 10;`\n\n- Атау екі кестеде де болса, **Кесте.өріс** жазылуы міндетті, әйтпесе қате шығады.\n- Жұмыс реті: FROM + JOIN → WHERE → GROUP BY, HAVING → SELECT → ORDER BY. WHERE екі кестенің де өрістерін көреді.\n- `JOIN` = `INNER JOIN`: жұбы жоқ жол (бос кілт, оқушысы жоқ сынып) нәтижеге кірмейді. `LEFT JOIN` сол жақ кестенің барлық жолын сақтайды.\n\n## ҰБТ-ға арналған кеңестер\n\n- Нәтижедегі жолдар саны табылған **жұптар** санына тең: үш тапсырысы бар клиент үш жол береді (DISTINCT қайталауды алып тастайды).\n- Шартсыз `FROM A, B` **n · m** жол береді (6 · 4 = 24). `FROM A, B WHERE A.k = B.k` — `JOIN` дегенмен бірдей.\n\n## Жиі кететін қателер\n\n- ON немесе байланыс шарты ұмытылған.\n- Байланыспаған өрістер бойынша біріктіру (`Name = Teacher`): жұп жоқ, нәтиже бос.\n- `ClassID` кесте көрсетілместен жазылған."},
  "doc-1-text": {"ru":"**Структура**: документ → абзацы → слова → символы. **Символ** — минимальный объект текста. Абзац кончается клавишей **Enter**; **Shift + Enter** — новая строка внутри абзаца; **Ctrl + Enter** — новая страница.\n\n**Три уровня оформления**: символ (шрифт, кегль в пунктах, полужирный, курсив, подчёркивание); абзац (выравнивание, красная строка, интервал, отступы: действуют на весь абзац); страница (поля, ориентация, A4 = 210 × 297 мм, колонтитулы).\n\n**Клавиши**: Ctrl + B / I / U — полужирный, курсив, подчёркнутый; Ctrl + L / E / R / J — по левому краю, по центру, по правому краю, по ширине; Ctrl + H — найти и заменить.\n\n**Стили**: изменишь стиль — изменятся все абзацы с ним. Оглавление собирается по стилям заголовков и обновляется вручную (F9).\n\n**Объекты**: список (маркированный — порядок неважен, нумерованный — важен); таблица (объединение уменьшает число ячеек); колонтитул и номер страницы повторяются на каждой странице.\n\n**Форматы**: DOCX, DOC — Word; ODT — LibreOffice; RTF — обмен; TXT — только символы; PDF — вид страницы неизменен.\n\n**Ловушки**: Enter — только в конце абзаца; не выравнивать пробелами; не нумеровать вручную; заголовок «на глаз» в оглавление не попадёт.","kk":"**Құрылым**: құжат → абзацтар → сөздер → символдар. **Символ** — мәтіннің ең кіші нысаны. Абзац **Enter** пернесімен аяқталады; **Shift + Enter** — абзац ішіндегі жаңа жол; **Ctrl + Enter** — жаңа бет.\n\n**Ресімдеудің үш деңгейі**: символ (қаріп, пунктпен кегль, қалың, көлбеу, асты сызылған); абзац (туралау, қызыл жол, интервал, шегіністер: бүкіл абзацқа әсер етеді); бет (өрістер, бағдар, A4 = 210 × 297 мм, колонтитулдар).\n\n**Пернелер**: Ctrl + B / I / U — қалың, көлбеу, асты сызылған; Ctrl + L / E / R / J — сол жиек, орта, оң жиек, ені бойынша; Ctrl + H — табу және ауыстыру.\n\n**Стильдер**: стильді өзгертсең, оның барлық абзацы өзгереді. Мазмұны тақырып стильдері бойынша жиналады және қолмен жаңартылады (F9).\n\n**Нысандар**: тізім (таңбаланған — реті маңызды емес, нөмірленген — маңызды); кесте (біріктіру ұяшық санын азайтады); колонтитул мен бет нөмірі әр бетте қайталанады.\n\n**Пішімдер**: DOCX, DOC — Word; ODT — LibreOffice; RTF — алмасу; TXT — тек символдар; PDF — беттің көрінісі өзгермейді.\n\n**Тұзақтар**: Enter — тек абзацтың соңында; бос орынмен туралама; қолмен нөмірлеме; «көзбен» ресімделген тақырып мазмұнына кірмейді."},
  "ent-1-strategy": {"ru":"# Стратегия ЕНТ\n\n## Формат\n\n| Тип | Заданий | Баллы |\n|---|---|---|\n| Один верный из 4 | 25 | по 1 |\n| Контекстные | 5 | по 1 |\n| Несколько верных из 6 | 5 | до 2 |\n| Соответствие | 5 | до 2 |\n\nВсего **40 заданий**, до **50 баллов**, порог по предмету — **5 баллов**. В среднем **2 минуты на задание** (40 × 2 = 80 минут). На экзамене: встроенный калькулятор и лист А4.\n\n## Баллы за несколько ответов\n\n- все верные, лишних нет — **2**;\n- не хватает одного верного и/или есть один лишний — **1**;\n- два и более неверных, только один верный из трёх или ни одного верного — **0**.\n\n**Лишняя галочка стоит балла.**\n\n## Лайфхаки для ЕНТ\n\n- **Два круга:** лёгкое сразу, трудное пометить и вернуться.\n- «Один верный»: пустым не оставляй, отметь самый вероятный.\n- Единицы приводи к одной **до** расчёта (1 Кбайт = 1024 байта).\n- Контекстное: сначала вся программа, потом одна трассировка на черновике.\n\n## Частые ошибки\n\n- Застрять на одном задании.\n- Отметить два сомнительных варианта «на удачу».\n- Делить величины в разных единицах.","kk":"# ҰБТ стратегиясы\n\n## Формат\n\n| Түрі | Саны | Ұпай |\n|---|---|---|\n| 4 нұсқадан бір дұрыс жауап | 25 | 1-ден |\n| Контекстік | 5 | 1-ден |\n| 6 нұсқадан бірнеше дұрыс жауап | 5 | 2-ге дейін |\n| Сәйкестендіру | 5 | 2-ге дейін |\n\nБарлығы **40 тапсырма**, **50 ұпайға дейін**, пән бойынша шекті ұпай — **5**. Орта есеппен **бір тапсырмаға 2 минут** (40 × 2 = 80 минут). Емтиханда: кіріктірілген калькулятор және А4 парағы.\n\n## Бірнеше жауап үшін ұпай\n\n- дұрыс жауаптың бәрі, артығы жоқ — **2**;\n- бір дұрыс жауап жетпейді және/немесе бір артық бар — **1**;\n- екі және одан көп қате, үш дұрыстың тек біреуі немесе бірде-бір дұрыс жоқ — **0**.\n\n**Артық белгі ұпай алып кетеді.**\n\n## ҰБТ-ға арналған кеңестер\n\n- **Екі айналым:** жеңілін бірден, қиынына белгі қойып, кейін оралу.\n- «Бір дұрыс жауап»: бос қалдырма, ең ықтималын белгіле.\n- Бірліктерді есептеуден **бұрын** бір бірлікке келтір (1 Кбайт = 1024 байт).\n- Контекстік тапсырма: алдымен бүкіл программа, сосын қараламада бір трассировка.\n\n## Жиі кететін қателер\n\n- Бір тапсырмада тұрып қалу.\n- Екі күмәнді нұсқаны болжаммен белгілеу.\n- Әртүрлі бірліктегі шамаларды бөлу."},
  "info-1-units": {"ru":"# Единицы измерения информации\n\n## Бит и байт\n\n- **Бит** — одна «лампочка»: 0 или 1.\n- **1 байт = 8 бит.**\n\n## Лестница единиц\n\n| Единица | Состоит из |\n|---|---|\n| 1 Кбайт | 1024 байта = 2¹⁰ байт |\n| 1 Мбайт | 1024 Кбайт |\n| 1 Гбайт | 1024 Мбайт |\n| 1 Тбайт | 1024 Гбайт |\n\n## Что сколько весит\n\n- СМС — около 140 байт; страница текста — около 2 Кбайт.\n- Фото и песня — по 3–5 Мбайт; фильм — около 2 Гбайт.\n- CD — 700 Мбайт, DVD — 4,7 Гбайт; флешка — десятки Гбайт; SSD и HDD — от сотен Гбайт до Тбайт.\n- Почему 1024: компьютер считает двойками, 1024 = 2¹⁰ — ближайшая к тысяче степень двойки.\n\n## Как переводить\n\n- **Вниз** (к мелким единицам) — **умножаем**: ×1024, а из байтов в биты ×8.\n- **Вверх** — **делим**: :1024, а из бит в байты :8.\n- Через степени двойки: 1024 = 2¹⁰, 8 = 2³, значит 1 Мбайт = 2²⁰ байт = 2²³ бит.\n\n## Лайфхаки для ЕНТ\n\n- Сравнивая величины, переводи их в **одну** единицу.\n- «Сколько файлов поместится» — переведи ёмкость в единицы файла и подели.\n- Степени двойки считать проще, чем умножать большие числа.\n\n## Частые ошибки\n\n- 1 Кбайт = **1000** байт — нет, на ЕНТ **1024**.\n- Из байтов в биты умножают на **8**, а не на 1024.\n- **Кбайт** и **Кбит** — разные единицы: Кбайт в 8 раз крупнее.\n- Скорость интернета в **Мбит/с**: 100 Мбит/с = 12,5 Мбайт/с.","kk":"# Ақпараттың өлшем бірліктері\n\n## Бит және байт\n\n- **Бит** — бір «шам»: 0 немесе 1.\n- **1 байт = 8 бит.**\n\n## Бірліктер баспалдағы\n\n| Бірлік | Құрамы |\n|---|---|\n| 1 Кбайт | 1024 байт = 2¹⁰ байт |\n| 1 Мбайт | 1024 Кбайт |\n| 1 Гбайт | 1024 Мбайт |\n| 1 Тбайт | 1024 Гбайт |\n\n## Не қанша көлем алады\n\n- SMS — шамамен 140 байт; мәтін беті — шамамен 2 Кбайт.\n- Фото мен ән — 3–5 Мбайттан; фильм — шамамен 2 Гбайт.\n- CD — 700 Мбайт, DVD — 4,7 Гбайт; флеш-жад — ондаған Гбайт; SSD және HDD — жүздеген Гбайттан Тбайтқа дейін.\n- Неге 1024: компьютер екілікпен санайды, 1024 = 2¹⁰ — мыңға ең жақын екінің дәрежесі.\n\n## Қалай аудару керек\n\n- **Төмен** (ұсақ бірліктерге) — **көбейтеміз**: ×1024, ал байттан битке ×8.\n- **Жоғары** — **бөлеміз**: :1024, ал биттен байтқа :8.\n- Екінің дәрежесі арқылы: 1024 = 2¹⁰, 8 = 2³, демек 1 Мбайт = 2²⁰ байт = 2²³ бит.\n\n## ҰБТ-ға арналған кеңестер\n\n- Шамаларды салыстырғанда, оларды **бір** бірлікке аудар.\n- «Неше файл сияды» — сыйымдылықты файл бірлігіне аударып, бөл.\n- Екінің дәрежелерімен есептеу үлкен сандарды көбейтуден оңай.\n\n## Жиі кететін қателер\n\n- 1 Кбайт = **1000** байт деу — қате, ҰБТ-да **1024**.\n- Байттан битке **8**-ге көбейтеді, ал 1024-ке емес.\n- **Кбайт** пен **Кбит** — әртүрлі бірліктер: Кбайт 8 есе үлкен.\n- Интернет жылдамдығы **Мбит/с**-пен: 100 Мбит/с = 12,5 Мбайт/с."},
  "info-2-formula": {"ru":"# Сколько информации в сообщении\n\n## Алфавитный подход\n\n- **N** — мощность алфавита (сколько символов), **i** — вес одного символа в битах, **K** — число символов в сообщении, **I** — объём сообщения.\n- **N = 2ⁱ**: 2 → 1 бит, 4 → 2, 8 → 3, 16 → 4, 32 → 5, 64 → 6, 128 → 7, 256 → 8.\n- Код **равномерный** (все коды одной длины). Если N не степень двойки — берём **наименьшее i, при котором 2ⁱ ≥ N** (33 → 6 бит, 100 → 7 бит). Округляем **только вверх**.\n- **I = K · i** бит. В байтах: I : 8 (1 байт = 8 бит).\n\n## Содержательный подход\n\nВыбор одного из N равновероятных вариантов несёт i бит, где 2ⁱ ≥ N. Число от 1 до 64 угадывается за 6 вопросов «да/нет».\n\n## Количество кодов\n\nИз m символов можно составить **mᵏ** разных кодов длины k: 4 лампочки — 2⁴ = 16, 2 флажка трёх цветов — 3² = 9.\n\n## Лайфхаки для ЕНТ\n\n- Пароли: N → i → биты пароля → **округли до целых байт** → умножь на число паролей.\n- Сначала округляем **каждый** пароль, потом умножаем.\n- Ответ «без округления» среди вариантов — почти всегда ловушка.\n\n## Частые ошибки\n\n- i = 5 для 33 символов (округлили вниз).\n- Умножили K · N вместо K · i.\n- Забыли перевести биты в байты (: 8).","kk":"# Хабарламада қанша ақпарат бар\n\n## Әліпбилік (алфавиттік) тәсіл\n\n- **N** — әліпбидің қуаты (символдар саны), **i** — бір символдың ақпараттық салмағы (бит), **K** — хабарламадағы символ саны, **I** — хабарлама көлемі.\n- **N = 2ⁱ**: 2 → 1 бит, 4 → 2, 8 → 3, 16 → 4, 32 → 5, 64 → 6, 128 → 7, 256 → 8.\n- Код **біркелкі** (барлық кодтың ұзындығы бірдей). N екінің дәрежесі болмаса, **2ⁱ ≥ N болатын ең кіші i** аламыз (33 → 6 бит, 100 → 7 бит). Тек **жоғары** дөңгелектейміз.\n- **I = K · i** бит. Байтпен: I : 8 (1 байт = 8 бит).\n\n## Мазмұндық тәсіл\n\nN тең ықтимал нұсқаның біреуін таңдау i бит береді, мұндағы 2ⁱ ≥ N. 1-ден 64-ке дейінгі санды 6 «иә/жоқ» сұрағымен табуға болады.\n\n## Кодтар саны\n\nm символдан ұзындығы k **mᵏ** түрлі код құрастыруға болады: 4 шам — 2⁴ = 16, үш түсті 2 жалауша — 3² = 9.\n\n## ҰБТ-ға арналған кеңестер\n\n- Құпиясөздер: N → i → құпиясөздің биттері → **бүтін байтқа дейін дөңгелекте** → құпиясөздер санына көбейт.\n- Алдымен **әрбір** құпиясөзді дөңгелектейміз, содан кейін көбейтеміз.\n- Жауап нұсқаларындағы «дөңгелектеусіз» жауап — көбіне тұзақ.\n\n## Жиі кететін қателер\n\n- 33 символ үшін i = 5 (төмен қарай дөңгелектеу).\n- K · i орнына K · N көбейту.\n- Биттерді байтқа аударуды ұмыту (: 8)."},
  "info-3-text": {"ru":"# Кодирование текста\n\n## Главное\n\n- Компьютер хранит не буквы, а **числа** — коды символов из **кодовой таблицы**.\n- Символ — это буква, цифра, **пробел**, знак препинания, кавычка.\n\n## Таблицы\n\n- **ASCII** — 1 байт на символ: A = 65, a = 97, «0» = 48, пробел = 32.\n- **KZ-1048** — 1 байт на символ, есть казахские буквы Ә, Ғ, Қ, Ң, Ө, Ұ, Ү, Һ, І.\n- **Unicode** — все языки мира; в задачах ЕНТ 16 бит = 2 байта на символ.\n- **UTF-8** — длина разная: латиница 1 байт, кириллица 2 байта.\n\n## Формула\n\n**I = K · i** — объём = число символов × размер символа. 1 байт = 8 бит, 1 Кбайт = 1024 байта.\n\n## Лайфхаки для ЕНТ\n\n- Буквы идут по алфавиту: код B = код A + 1. Строчная буква = заглавная + 32.\n- «Вычеркнули слово»: убрано (буквы слова + 1 пробел) символов. Дели изменение объёма на размер символа.\n- Python: `ord('A')` → 65, `chr(65)` → 'A'.\n\n## Частые ошибки\n\n- Не посчитаны пробелы и знаки препинания.\n- Биты спутаны с байтами: Unicode 16 бит — это 2 байта, а не 16.\n- Код символа «0» принят за 0 (на самом деле 48).","kk":"# Мәтінді кодтау\n\n## Басты ойлар\n\n- Компьютер әріптерді емес, **сандарды** — **кодтау кестесіндегі** символ кодтарын сақтайды.\n- Символ — бұл әріп, цифр, **бос орын**, тыныс белгісі, тырнақша.\n\n## Кестелер\n\n- **ASCII** — бір символға 1 байт: A = 65, a = 97, «0» = 48, бос орын = 32.\n- **KZ-1048** — бір символға 1 байт, қазақ әріптері Ә, Ғ, Қ, Ң, Ө, Ұ, Ү, Һ, І бар.\n- **Unicode** — дүние жүзінің барлық тілі; ҰБТ есептерінде бір символға 16 бит = 2 байт.\n- **UTF-8** — ұзындығы әртүрлі: латын әріптері 1 байт, кирилл әріптері 2 байт.\n\n## Формула\n\n**I = K · i** — көлем = символдар саны × бір символдың өлшемі. 1 байт = 8 бит, 1 Кбайт = 1024 байт.\n\n## ҰБТ-ға арналған кеңестер\n\n- Әріптер әліпби бойынша қатарынан тұр: B коды = A коды + 1. Кіші әріп = бас әріп + 32.\n- «Сөзді сызып тастады»: (сөздің әріптері + 1 бос орын) символ алынған. Көлем өзгерісін бір символдың өлшеміне бөл.\n- Python: `ord('A')` → 65, `chr(65)` → 'A'.\n\n## Жиі кететін қателер\n\n- Бос орындар мен тыныс белгілері саналмаған.\n- Биттер мен байттар шатастырылған: Unicode 16 бит — бұл 2 байт, 16 емес.\n- «0» символының коды 0 деп алынған (шын мәнінде 48)."},
  "info-4-media": {"ru":"# Кодирование изображений и звука\n\n## Растровое изображение\n\n- **Пиксель** — один квадратик. Разрешение — ширина × высота.\n- **Глубина цвета i** — число бит на пиксель. Палитра: **N = 2ⁱ** цветов. 8 бит — 256 цветов, 16 бит — 65 536, 24 бита — 16 777 216.\n- **I = ширина × высота × i** бит. Потом биты : 8 = байты, байты : 1024 = Кбайт.\n\n## Цвет RGB\n\n- Три канала (красный, зелёный, синий) по 8 бит = 24 бита. Код **#RRGGBB** в шестнадцатеричной системе: FF₁₆ = 255.\n- #FF0000 красный, #00FF00 зелёный, #0000FF синий, #FFFF00 жёлтый, #FFFFFF белый.\n\n## Растр и вектор\n\n- Растр — сетка пикселей (фото). Вектор — формулы фигур, без потерь при увеличении.\n\n## Звук и видео\n\n- **I = f · i · k · t** бит: f — частота дискретизации (Гц), i — глубина (бит), k — каналы (моно 1, стерео 2), t — секунды.\n- Видео — кадры (картинки) плюс звук. Телефонный разговор — 8000 Гц, CD — 44 100 Гц, 16 бит, стерео.\n\n## Реальные файлы\n\n- Формулы дают размер **без сжатия**. JPEG, MP3, MP4 сжимают: фото 12 Мп — 34 МБ «сырое» и около 4 МБ в JPEG; песня 3 мин — около 30 МБ без сжатия и около 5 МБ в MP3.\n- Камера и микрофон превращают свет и звук в числа; растр — фото и скриншоты, вектор — шрифты, логотипы, карты.\n\n## Лайфхаки для ЕНТ\n\n- Объём зависит от **i**, а не от числа цветов N: 256 → 16 цветов — это 8 → 4 бита, файл меньше в **2** раза, а не в 16.\n- Минуты переведи в секунды. Порядок: i по N → перемножь всё → ÷ 8 → ÷ 1024.\n- Цвета по объёму: i = I : (ширина × высота), N = 2ⁱ.\n\n## Частые ошибки\n\n- Умножить на N вместо i; забыть ÷ 8 или ÷ 1024.\n- Не перевести минуты в секунды; забыть второй канал стерео.","kk":"# Кескінді және дыбысты кодтау\n\n## Растрлық кескін\n\n- **Пиксель** — бір төртбұрыш. Ажыратымдылық — ені × биіктігі.\n- **Түс тереңдігі i** — бір пиксельге келетін бит саны. Палитра: **N = 2ⁱ** түс. 8 бит — 256 түс, 16 бит — 65 536, 24 бит — 16 777 216.\n- **I = ені × биіктігі × i** бит. Содан кейін бит : 8 = байт, байт : 1024 = Кбайт.\n\n## RGB түсі\n\n- Үш арна (қызыл, жасыл, көк) 8 биттен = 24 бит. Он алтылық жүйедегі **#RRGGBB** коды: FF₁₆ = 255.\n- #FF0000 қызыл, #00FF00 жасыл, #0000FF көк, #FFFF00 сары, #FFFFFF ақ.\n\n## Растр және вектор\n\n- Растр — пиксельдер торы (фото). Вектор — фигура формулалары, үлкейткенде шығынсыз.\n\n## Дыбыс және бейне\n\n- **I = f · i · k · t** бит: f — дискреттеу жиілігі (Гц), i — тереңдік (бит), k — арналар (моно 1, стерео 2), t — секунд.\n- Бейне — кадрлар (суреттер) және дыбыс. Телефон әңгімесі — 8000 Гц, CD — 44 100 Гц, 16 бит, стерео.\n\n## Нақты файлдар\n\n- Формулалар **сығусыз** көлемді береді. JPEG, MP3, MP4 сығады: 12 Мп фото — шикі күйінде 34 МБ, JPEG-те шамамен 4 МБ; 3 минуттық ән — сығусыз шамамен 30 МБ, MP3-те шамамен 5 МБ.\n- Камера мен микрофон жарық пен дыбысты санға айналдырады; растр — фото мен скриншот, вектор — қаріп, логотип, карта.\n\n## ҰБТ-ға арналған кеңестер\n\n- Көлем түс саны N-ге емес, **i**-ге байланысты: 256 → 16 түс — бұл 8 → 4 бит, файл **2** есе кішірейеді, 16 есе емес.\n- Минутты секундқа аудар. Реті: N бойынша i → бәрін көбейт → ÷ 8 → ÷ 1024.\n- Көлем бойынша түс: i = I : (ені × биіктігі), N = 2ⁱ.\n\n## Жиі кететін қателер\n\n- i-дің орнына N-ге көбейту; ÷ 8 немесе ÷ 1024 ұмыту.\n- Минутты секундқа аудармау; стереоның екінші арнасын ұмыту."},
  "info-5-alphabet": {"ru":"# Алфавитный подход: N = 2ⁱ\n\n## Главное\n- **N = 2ⁱ**: N — число символов (мощность алфавита), i — вес символа в битах. Каждый новый бит **удваивает** число кодов.\n- Нужен вес: наименьшее i, при котором 2ⁱ ≥ N (только вверх). Нужен алфавит: N = 2ⁱ.\n- Степени двойки: 2⁵ = 32, 2⁶ = 64, 2⁷ = 128, 2⁸ = 256, 2¹⁰ = 1024.\n\n## Сколько кодов\n- Код из k позиций, на каждой m вариантов: **mᵏ** кодов. Основание — алфавит, показатель — длина.\n- Разные алфавиты на позициях — **перемножай**: 26² · 10³ = 676 000.\n- Номер любого из N кодов умещается в i бит, где 2ⁱ ≥ N.\n- Длина кода для N объектов: наименьшее k, при котором mᵏ ≥ N (подбор по таблице степеней).\n- Коды из двух сигналов длиной от 1 до k: 2 + 4 + … + 2ᵏ = 2ᵏ⁺¹ − 2 (до 4 — 30).\n\n## Ловушки ЕНТ\n- Основание и показатель: 10³ = 1000, а не 3¹⁰.\n- m · k вместо mᵏ: 4 светофора по 3 сигнала — 3⁴ = 81, а не 12.\n- Ограничения — по позициям: четырёхзначных чисел 9 · 10³ = 9000; из 3 разных цифр 10 · 9 · 8 = 720.\n- Бит добавили — кодов вдвое больше, а не на 1.\n- Каждый светофор по 2 бита — это 8 бит, а на 81 комбинацию хватит 7.","kk":"# Әліпбилік тәсіл: N = 2ⁱ\n\n## Негізгісі\n- **N = 2ⁱ**: N — символ саны (әліпбидің қуаты), i — символдың салмағы (бит). Әрбір жаңа бит кодтар санын **екі есе** арттырады.\n- Салмақ керек: 2ⁱ ≥ N болатын ең кіші i (тек жоғары). Әліпби керек: N = 2ⁱ.\n- Екінің дәрежелері: 2⁵ = 32, 2⁶ = 64, 2⁷ = 128, 2⁸ = 256, 2¹⁰ = 1024.\n\n## Қанша код бар\n- Әр орында m нұсқасы бар k орынды код: **mᵏ** код. Негіз — әліпби, көрсеткіш — ұзындық.\n- Орындарда әртүрлі әліпби болса — **көбейт**: 26² · 10³ = 676 000.\n- N кодтың кез келгенінің нөмірі i битке сияды, мұндағы 2ⁱ ≥ N.\n- N нысанға керек код ұзындығы: mᵏ ≥ N болатын ең кіші k (дәрежелер кестесі бойынша таңдау).\n- Ұзындығы 1-ден k-ға дейінгі екі сигналды кодтар: 2 + 4 + … + 2ᵏ = 2ᵏ⁺¹ − 2 (4-ке дейін — 30).\n\n## ҰБТ тұзақтары\n- Негіз бен көрсеткіш: 10³ = 1000, 3¹⁰ емес.\n- mᵏ орнына m · k: әрқайсысында 3 сигналы бар 4 бағдаршам — 3⁴ = 81, 12 емес.\n- Шектеулер — әр орын бойынша: төрт таңбалы сандар 9 · 10³ = 9000; 3 әртүрлі цифрдан 10 · 9 · 8 = 720.\n- Бит қосылса — код екі есе көп, 1-ге емес.\n- Әр бағдаршамға 2 бит — 8 бит, ал 81 комбинацияға 7 бит жетеді."},
  "info-6-text-volume": {"ru":"# Объём текста: задачи ЕНТ\n\n## Три шага\n\n1. **Число символов:** K = страниц · строк на странице · символов в строке (пробелы и знаки препинания — тоже символы).\n2. **Размер символа i:** 8 бит = 1 байт, 16 бит = 2 байта (или i из N = 2ⁱ).\n3. **Объём:** I = K · i, затем переведи в нужные единицы.\n\n## Единицы\n\n- 1 байт = 8 бит; 1 Кбайт = 1024 байта = 8192 бита.\n- Биты → байты: ÷ 8; байты → Кбайты: ÷ 1024.\n- Считай i сразу в байтах и раскладывай числа на степени двойки: 32 · 64 = 2¹¹.\n\n## Записи (пароли, номера)\n\n- Запись: символов · i бит → ÷ 8 → **округли вверх** до целого байта → · число записей.\n- Дополнительные сведения (уже в байтах) прибавляй **после** округления.\n\n## Лайфхаки и ловушки\n\n- «Сколько поместится» — округляй **вниз**; «сколько нужно места» — **вверх**.\n- Перекодировка 16 → 8 бит: объём вдвое меньше, а уменьшение в байтах равно K.\n- В ответе Кбайты: делим на **1024**, не на 1000; не путай Кбит и Кбайт.","kk":"# Мәтін көлемі: ҰБТ есептері\n\n## Үш қадам\n\n1. **Символдар саны:** K = беттер саны · беттегі жол саны · жолдағы символ саны (бос орындар мен тыныс белгілері де — символ).\n2. **Символ өлшемі i:** 8 бит = 1 байт, 16 бит = 2 байт (немесе N = 2ⁱ бойынша i).\n3. **Көлем:** I = K · i, содан кейін керекті бірлікке аудар.\n\n## Бірліктер\n\n- 1 байт = 8 бит; 1 Кбайт = 1024 байт = 8192 бит.\n- Бит → байт: ÷ 8; байт → Кбайт: ÷ 1024.\n- i-ді бірден байтпен алып, сандарды екінің дәрежелеріне жікте: 32 · 64 = 2¹¹.\n\n## Жазбалар (құпиясөздер, нөмірлер)\n\n- Жазба: символ · i бит → ÷ 8 → бүтін байтқа дейін **жоғары дөңгелекте** → · жазба саны.\n- Қосымша мәліметтерді (байтпен берілген) дөңгелектегеннен **кейін** қос.\n\n## Кеңестер мен тұзақтар\n\n- «Қанша сияды» — **төмен** дөңгелекте; «қанша орын керек» — **жоғары**.\n- 16 → 8 бит қайта кодтау: көлем екі есе азаяды, ал байтпен азаю K-ға тең.\n- Жауапта Кбайт: **1024**-ке бөлеміз, 1000-ға емес; Кбит пен Кбайтты шатастырма."},
  "info-7-encodings": {"ru":"# Кодировки: ASCII, KZ-1048, Unicode\n\n## Главное\n\n- **Кодировка** — таблица «символ ↔ номер» и способ записи номера байтами.\n- Байты прочитаны по чужой таблице — получаются «кракозябры».\n\n## Таблицы\n\n- **ASCII** — 128 кодов (7 бит), хранится в 1 байте: 0–31 управляющие, 32 пробел, 48–57 цифры, 65–90 A–Z, 97–122 a–z.\n- **KZ-1048** — 256 кодов, 1 байт на символ: ASCII + кириллица + Ә Ғ Қ Ң Ө Ұ Ү Һ І.\n- **Unicode** — номер U+… для 150 000+ символов всех языков.\n- **UTF-8** — 1–4 байта: ASCII — 1, кириллица — 2, ₸ — 3, эмодзи — 4.\n- **UTF-16** — 2 байта, редкие символы — 4. В задачах ЕНТ «Unicode» без уточнения — 16 бит.\n\n## Как считать\n\n- Раздели текст на группы (кириллица, латиница, цифры, пробелы), умножь каждую на размер символа, сложи.\n- Текст из кириллицы, латиницы, цифр и знаков: UTF-8 длиннее KZ-1048 на столько байт, сколько в нём кириллических букв.\n- Строчная = заглавная + 32 (в hex: + 20₁₆): A = 41₁₆ = 65. 1 Кбайт = 1024 байта.\n\n## Частые ошибки\n\n- UTF-8 — не «8 бит на символ»; Unicode — не «всегда 2 байта».\n- Не посчитаны пробелы и знаки; биты спутаны с байтами.","kk":"# Кодтаулар: ASCII, KZ-1048, Unicode\n\n## Басты ойлар\n\n- **Кодтау** — «символ ↔ нөмір» кестесі және нөмірді байттармен жазу тәсілі.\n- Байттар бөтен кесте бойынша оқылса — түсініксіз таңбалар («кракозябры») шығады.\n\n## Кестелер\n\n- **ASCII** — 128 код (7 бит), 1 байтта сақталады: 0–31 басқарушы, 32 бос орын, 48–57 цифрлар, 65–90 A–Z, 97–122 a–z.\n- **KZ-1048** — 256 код, бір символға 1 байт: ASCII + кирилл + Ә Ғ Қ Ң Ө Ұ Ү Һ І.\n- **Unicode** — барлық тілдің 150 000+ символына U+… нөмірі.\n- **UTF-8** — 1–4 байт: ASCII — 1, кирилл — 2, ₸ — 3, эмодзи — 4.\n- **UTF-16** — 2 байт, сирек символдар — 4. ҰБТ есептерінде нақтылаусыз «Unicode» — 16 бит.\n\n## Қалай есептеу\n\n- Мәтінді топтарға бөл (кирилл, латын, цифрлар, бос орындар), әр топты символ өлшеміне көбейтіп, қос.\n- Мәтін кирилл, латын әріптерінен, цифрлардан және белгілерден тұрса, UTF-8 KZ-1048-ден ондағы кирилл әріптерінің санындай байтқа ұзын.\n- Кіші әріп = бас әріп + 32 (hex: + 20₁₆): A = 41₁₆ = 65. 1 Кбайт = 1024 байт.\n\n## Жиі кететін қателер\n\n- UTF-8 — «бір символға 8 бит» емес; Unicode — «әрдайым 2 байт» емес.\n- Бос орындар мен белгілер саналмаған; биттер мен байттар шатастырылған."},
  "info-8-graphics": {"ru":"# Растровая графика: пиксели и палитра\n\n## Что хранится в пикселе\n- Пиксель хранит **номер цвета** в палитре (таблице). Палитра из N цветов: **N = 2ⁱ**, i — глубина цвета в битах.\n- Серый — когда R = G = B (256 оттенков, i = 8). Чёрно-белое: i = 1. Полноцвет: 24 бита = 3 байта, High Color: 16 бит.\n- Код **#RRGGBB**: пара цифр — число 0–255 (первая · 16 + вторая). #FF8000 = 255, 128, 0.\n- Экран — RGB (свет), печать — CMYK (краски).\n\n## Объём и видеопамять\n- Страница экрана и картинка: **I = W · H · i** бит; бит : 8 = байт; байт : 1024 = Кбайт.\n- Страниц в видеопамяти: память : страница, берём **целую часть**.\n- Обратная задача: i = (объём в битах) : (W · H), потом N = 2ⁱ.\n\n## Форматы\n- PNG, GIF — без потерь; JPEG — с потерями (фото); SVG — вектор (логотипы, чертежи, любой масштаб); BMP — без сжатия. Про сжатие ни слова — считаем без него.\n\n## Ловушки ЕНТ\n- «Хватит кодов» — i вверх (100 цветов → 7 бит); «влезет в память» — i вниз (2,5 бита → 2 бита → 4 цвета).\n- Считай по i, а не по N; не забудь ÷ 8 и ÷ 1024.","kk":"# Растрлық графика: пиксельдер және палитра\n\n## Пикселде не сақталады\n- Пиксель палитрадағы (кестедегі) **түс нөмірін** сақтайды. N түсті палитра: **N = 2ⁱ**, i — түс тереңдігі (бит).\n- Сұр — R = G = B болғанда (256 реңк, i = 8). Қара-ақ: i = 1. Толық түс: 24 бит = 3 байт, High Color: 16 бит.\n- **#RRGGBB** коды: цифрлар жұбы — 0–255 саны (бірінші · 16 + екінші). #FF8000 = 255, 128, 0.\n- Экран — RGB (жарық), басып шығару — CMYK (бояу).\n\n## Көлем және видеожад\n- Экран беті мен сурет: **I = W · H · i** бит; бит : 8 = байт; байт : 1024 = Кбайт.\n- Видеожадтағы беттер: жад : бет, **бүтін бөлігін** аламыз.\n- Кері есеп: i = (биттегі көлем) : (W · H), содан кейін N = 2ⁱ.\n\n## Пішімдер\n- PNG, GIF — шығынсыз; JPEG — шығынмен (фото); SVG — вектор (логотип, сызба, кез келген масштаб); BMP — сығусыз. Сығу туралы сөз жоқ болса — сығусыз есептейміз.\n\n## ҰБТ тұзақтары\n- «Кодтар жетеді» — i жоғары (100 түс → 7 бит); «жадқа сияды» — i төмен (2,5 бит → 2 бит → 4 түс).\n- i бойынша есепте, N бойынша емес; ÷ 8 және ÷ 1024 ұмытпа."},
  "info-9-sound": {"ru":"# Звук и видео: оцифровка и объём\n\n## Звук\n\n- **Дискретизация**: громкость измеряют **f** раз в секунду (Гц; **1 кГц = 1000 Гц**). **i** — глубина кодирования, бит (N = 2ⁱ уровней). **k** — каналы: моно 1, стерео 2.\n- Поток **v = f · i · k** бит/с. Объём **I = v · t = f · i · k · t** бит.\n- Любая величина может быть искомой: t = I / (f · i · k); i = I / (f · k · t); f = I / (i · k · t).\n\n## Видео\n\n- Число кадров = кадр/с · t. Объём кадра = ширина · высота · i. Видео = кадры · объём кадра (+ звук, если он есть в условии).\n\n## Сжатие\n\n- Без потерь: FLAC, ZIP (WAV — без сжатия). С потерями: MP3, MP4, JPEG. Если про сжатие не сказано, считай по формулам.\n\n## Лайфхаки для ЕНТ\n\n- Порядок: кГц → Гц, минуты → секунды, всё в биты, в конце ÷ 8 и ÷ 1024.\n- Изменения f, i, k, t **перемножаются**: ÷ 2 по трём параметрам даёт ÷ 8, а не ÷ 6.\n- Искать время — **делить**. «Сколько полных секунд» — округлять вниз.\n\n## Частые ошибки\n\n- 1 кГц = 1024 Гц (на самом деле 1000); забытый второй канал; ответ в секундах вместо минут; сложение вместо умножения.","kk":"# Дыбыс және бейне: цифрлау және көлем\n\n## Дыбыс\n\n- **Дискреттеу**: қаттылық секундына **f** рет өлшенеді (Гц; **1 кГц = 1000 Гц**). **i** — кодтау тереңдігі, бит (N = 2ⁱ деңгей). **k** — арналар: моно 1, стерео 2.\n- Ағын **v = f · i · k** бит/с. Көлем **I = v · t = f · i · k · t** бит.\n- Кез келген шама ізделуі мүмкін: t = I / (f · i · k); i = I / (f · k · t); f = I / (i · k · t).\n\n## Бейне\n\n- Кадр саны = кадр/с · t. Кадр көлемі = ені · биіктігі · i. Бейне = кадрлар · кадр көлемі (+ шартта дыбыс болса, дыбыс).\n\n## Сығу\n\n- Шығынсыз: FLAC, ZIP (WAV — сығусыз). Шығынмен: MP3, MP4, JPEG. Сығу туралы айтылмаса, формулалармен есепте.\n\n## ҰБТ-ға арналған кеңестер\n\n- Реті: кГц → Гц, минут → секунд, бәрін битке, соңында ÷ 8 және ÷ 1024.\n- f, i, k, t өзгерістері **көбейтіледі**: үш параметр 2 есе азайса, ÷ 8 шығады, ÷ 6 емес.\n- Уақытты іздеу — **бөлу**. «Неше толық секунд» — төмен қарай дөңгелектеу.\n\n## Жиі кететін қателер\n\n- 1 кГц = 1024 Гц (шын мәнінде 1000); екінші арнаны ұмыту; минуттың орнына секундпен жауап беру; көбейтудің орнына қосу."},
  "it-1-trends": {"ru":"# ИИ, облака и интернет вещей\n\n## Искусственный интеллект\n- **ИИ учится на данных:** данные → обучение → **модель** → ответ.\n- Матрёшка: ИИ ⊃ **машинное обучение** ⊃ **нейронные сети**. **Генеративный ИИ** создаёт тексты и картинки.\n- **Галлюцинация** — уверенный, но неверный ответ. Проверяй факты, не выдавай чужое за своё, не отправляй личное.\n\n## Облачные технологии\nХранение и вычисления на **удалённых серверах** через интернет. Плюсы: доступ отовсюду, не нужно своё железо. Минусы: нужен интернет, данные у провайдера.\n\n- **SaaS** — готовая программа (Google Docs).\n- **PaaS** — платформа для своих программ.\n- **IaaS** — серверы, диски, сеть в аренду.\n\n## Интернет вещей (IoT)\nУстройства с **датчиками**, сами передают данные по сети: умный дом, умный счётчик.\n\n## Ещё\n- **Big Data** — очень много данных.\n- **Блокчейн** — цепочка блоков с хешем предыдущего: запись не изменить незаметно.\n- **AR** добавляет цифровое к реальному, **VR** — целиком цифровой мир.\n- **eGov** — услуги онлайн, **ЭЦП** — подпись документа в электронном виде.\n\n## Ловушки ЕНТ\n- Калькулятор и архиватор работают по правилам — это **не** машинное обучение.\n- Устройство без выхода в сеть — **не** интернет вещей.","kk":"# ЖИ, бұлтты технологиялар және заттар интернеті\n\n## Жасанды интеллект\n- **ЖИ деректерден үйренеді:** деректер → оқыту → **модель** → жауап.\n- Матрёшка: ЖИ ⊃ **машиналық оқыту** ⊃ **нейрондық желілер**. **Генеративті ЖИ** мәтін мен сурет жасайды.\n- **Галлюцинация** — сенімді, бірақ қате жауап. Фактіні тексер, біреудің жұмысын өзіңдікі деп көрсетпе, жеке деректерді жіберме.\n\n## Бұлтты технологиялар\nИнтернет арқылы **қашықтағы серверлерде** сақтау және есептеу. Артықшылығы: кез келген жерден қолжетімді, өз жабдығың керек емес. Кемшілігі: интернет керек, деректер провайдерде.\n\n- **SaaS** — дайын программа (Google Docs).\n- **PaaS** — өз программаларына арналған платформа.\n- **IaaS** — жалға берілетін серверлер, дискілер, желі.\n\n## Заттар интернеті (IoT)\n**Датчиктері** бар құрылғылар деректерді желі арқылы өздері жібереді: ақылды үй, ақылды есептегіш.\n\n## Тағы\n- **Big Data** — өте көп деректер.\n- **Блокчейн** — алдыңғы блоктың хеші бар блоктар тізбегі: жазбаны байқатпай өзгертуге болмайды.\n- **AR** шынайыға цифрлықты қосады, **VR** — толық цифрлық әлем.\n- **eGov** — онлайн қызметтер, **ЭЦҚ** — құжатқа электрондық түрде қол қою.\n\n## ҰБТ тұзақтары\n- Калькулятор мен архиватор ережелермен жұмыс істейді — бұл машиналық оқыту **емес**.\n- Желіге шықпайтын құрылғы — заттар интернеті **емес**."},
  "it-2-startup": {"ru":"# IT-стартап\n\n## Что такое стартап\n\n**Стартап** — молодая компания, которая ищет **масштабируемую бизнес-модель** для новой идеи. Признаки: неопределённость и возможность быстрого роста.\n\n## Этапы (порядок для ЕНТ)\n\n1. Идея и проблема пользователя\n2. Исследование рынка и целевой аудитории\n3. **MVP** — минимально жизнеспособный продукт, простейшая версия\n4. Тестирование с пользователями, обратная связь\n5. Доработка (итерации; **pivot** — смена курса)\n6. Масштабирование\n\n## Команда\n\nМенеджер (идея, план), разработчик (программа), дизайнер (интерфейс), маркетолог (продвижение).\n\n## Монетизация — как продукт зарабатывает\n\nПодписка, freemium (база бесплатно, расширение платно), реклама, разовая покупка, комиссия.\n\n## Финансирование — откуда деньги на старт\n\nСобственные средства, грант, бизнес-ангелы, венчурные инвесторы, краудфандинг. **Питч** — короткая презентация идеи инвестору.\n\n## Метрики\n\nЧисло пользователей; **удержание = вернувшиеся / все · 100%**.\n\n## Частые ошибки\n\n- Путают монетизацию (доход от продукта) и финансирование (деньги на старт).\n- Считают MVP «сырой версией» — это продукт с минимумом функций.\n- Ставят масштабирование до тестирования.","kk":"# IT-стартап\n\n## Стартап дегеніміз не\n\n**Стартап** — жаңа идеяға арналған **масштабталатын бизнес-модель** іздейтін жас компания. Белгілері: белгісіздік және жылдам өсу мүмкіндігі.\n\n## Кезеңдер (ҰБТ-дағы реті)\n\n1. Идея және пайдаланушы мәселесі\n2. Нарықты және мақсатты аудиторияны зерттеу\n3. **MVP** — минималды өміршең өнім, ең қарапайым нұсқа\n4. Пайдаланушылармен тестілеу, кері байланыс\n5. Жетілдіру (итерациялар; **pivot** — бағытты өзгерту)\n6. Масштабтау\n\n## Команда\n\nМенеджер (идея, жоспар), әзірлеуші (программа), дизайнер (интерфейс), маркетолог (жылжыту).\n\n## Монетизация — өнім қалай табыс табады\n\nЖазылым, фримиум (негізі тегін, кеңейтімі ақылы), жарнама, бір реттік сатып алу, комиссия.\n\n## Қаржыландыру — бастапқы ақша қайдан\n\nӨз қаражаты, грант, бизнес-ангелдер, венчурлық инвесторлар, краудфандинг. **Питч** — идеяның инвесторға арналған қысқа таныстырылымы.\n\n## Метрикалар\n\nПайдаланушылар саны; **ұстап қалу = оралғандар / барлығы · 100%**.\n\n## Жиі кететін қателер\n\n- Монетизацияны (өнімнен түсетін табыс) және қаржыландыруды (бастапқы ақша) шатастырады.\n- MVP-ді «шикі нұсқа» деп ойлайды — бұл функциясы аз өнім.\n- Масштабтауды тестілеуден бұрын қояды."},
  "it-3-3d": {"ru":"# 3D-моделирование\n\n## Из чего состоит модель\n- **Вершина** — точка (x, y, z); **ребро** — отрезок между двумя вершинами; **грань** — плоский многоугольник (чаще треугольник).\n- **Примитивы** — готовые простые фигуры: куб, сфера, цилиндр, конус, плоскость.\n\n## Операции\n- перемещение (прибавить к координатам), поворот, масштабирование (умножить координаты), выдавливание (extrude);\n- **булевы:** объединение — склеить, вычитание — вырезать (A − B ≠ B − A), пересечение — оставить общее.\n\n## От модели до картинки\nМодель → материал и текстура → свет → камера → **рендеринг** (готовое изображение).\n\n## Программы и печать\n- Blender — бесплатная, с открытым кодом; Tinkercad — онлайн для начинающих; 3ds Max и Maya — профессиональные платные.\n- 3D-печать: модель → слайсер (нарезка на слои) → принтер печатает слой за слоем. Слоёв = высота : толщина слоя (в одних единицах, мм).\n\n## Формулы\n- **Эйлер:** В − Р + Г = 2 (куб: 8 − 12 + 6 = 2).\n- Призма с n-угольным основанием: В = 2n, Р = 3n, Г = n + 2. Пирамида: В = n + 1, Р = 2n, Г = n + 1.\n- Масштаб ×k: длины ×k, площади ×k², объём ×k³.\n\n## Частые ошибки\n- У призмы забыты два основания при подсчёте граней.\n- В вычитании перепутан порядок тел.","kk":"# 3D жобалау\n\n## Модель неден тұрады\n- **Төбе** — нүкте (x, y, z); **қыр** — екі төбенің арасындағы кесінді; **жақ** — жазық көпбұрыш (көбіне үшбұрыш).\n- **Примитивтер** — дайын қарапайым фигуралар: куб, сфера, цилиндр, конус, жазықтық.\n\n## Амалдар\n- орын ауыстыру (координаталарға қосу), бұру, масштабтау (координаталарды көбейту), экструзия (extrude);\n- **Буль амалдары:** біріктіру — желімдеу, алу — кесіп алу (A − B ≠ B − A), қиылысу — ортақ бөлікті қалдыру.\n\n## Модельден суретке дейін\nМодель → материал және текстура → жарық → камера → **рендеринг** (дайын кескін).\n\n## Программалар және басып шығару\n- Blender — тегін, ашық коды бар; Tinkercad — жаңадан бастаушыларға арналған онлайн; 3ds Max және Maya — кәсіби ақылы.\n- 3D басып шығару: модель → слайсер (қабаттарға кесу) → принтер қабат-қабатымен басады. Қабат саны = биіктік : қабат қалыңдығы (бір бірлікте, мм).\n\n## Формулалар\n- **Эйлер:** Т − Қ + Ж = 2 (куб: 8 − 12 + 6 = 2).\n- Негізі n-бұрышты призма: Т = 2n, Қ = 3n, Ж = n + 2. Пирамида: Т = n + 1, Қ = 2n, Ж = n + 1.\n- Масштаб ×k: ұзындық ×k, аудан ×k², көлем ×k³.\n\n## Жиі кететін қателер\n- Призмада жақтарды санағанда екі негіз ұмытылған.\n- Алу амалында денелердің реті шатастырылған."},
  "it-4-ai": {"ru":"# Как учится искусственный интеллект\n\n## Виды обучения\n- Путь: данные → обучение → модель → ответ.\n- **С учителем:** у примеров есть **метки** (правильные ответы): спам, лица, перевод.\n- **Без учителя:** меток нет, программа сама группирует похожее (**кластеризация**).\n- **С подкреплением:** пробы и награда (игровой бот).\n\n## Нейрон\n- **s = x₁·w₁ + x₂·w₂ + …** — взвешенная сумма; **s ≥ T → 1**, иначе **0**. Вход 0 «выключается».\n- **Обучение — подбор весов**; нейросеть — слои нейронов.\n\n## Качество и ошибки\n- Судят по **новым (тестовым) данным**. Высокая точность на обучающих и низкая на новых — **переобучение**; низкая везде — недообучение.\n- Однобокие данные дают **предвзятые** ответы; LLM может **галлюцинировать**.\n- Точность = верные ÷ все · 100%.\n\n## Этика и закон\nПроверяй факты, не отправляй личное, помечай созданное ИИ. Закон РК «Об ИИ» № 230-VIII действует с 18 января 2026 года.\n\n## Ловушки ЕНТ\n- «100% на обучающих» ≠ хорошая модель.\n- Метки есть только при обучении с учителем.","kk":"# Жасанды интеллект қалай үйренеді\n\n## Оқыту түрлері\n- Жол: деректер → оқыту → модель → жауап.\n- **Мұғаліммен:** мысалдарда **белгілер** (дұрыс жауаптар) бар: спам, беттер, аударма.\n- **Мұғалімсіз:** белгілер жоқ, программа ұқсастарды өзі топтайды (**кластерлеу**).\n- **Күшейту арқылы:** байқап көру және сый (ойын боты).\n\n## Нейрон\n- **s = x₁·w₁ + x₂·w₂ + …** — салмақталған қосынды; **s ≥ T → 1**, әйтпесе **0**. 0 кіріс «өшеді».\n- **Оқыту — салмақтарды іріктеу**; нейрондық желі — нейрондар қабаттары.\n\n## Сапа және қателер\n- **Жаңа (сынақ) деректер** бойынша бағалайды. Оқытуда дәлдік жоғары, жаңада төмен — **шамадан тыс үйрену**; барлық жерде төмен — жеткіліксіз үйрену.\n- Біржақты деректер **біржақты** жауап береді; LLM **галлюцинация** жасауы мүмкін.\n- Дәлдік = дұрыс жауаптар ÷ барлығы · 100%.\n\n## Этика және заң\nФактіні тексер, жеке деректі жіберме, ЖИ жасағанды белгіле. ҚР «Жасанды интеллект туралы» заңы (№ 230-VIII) 2026 жылғы 18 қаңтардан қолданылады.\n\n## ҰБТ тұзақтары\n- «Оқытуда 100%» ≠ жақсы модель.\n- Белгілер тек мұғаліммен оқытуда болады."},
  "it-5-data": {"ru":"# Большие данные, облака и IoT\n\n## Big Data — «три V»\n- **Объём** (Volume): очень много данных;\n- **Скорость** (Velocity): идут потоком, нужны сразу;\n- **Разнообразие** (Variety): текст, фото, видео, показания датчиков.\n\nБольшая таблица ещё не Big Data. Данные делят между многими серверами. Четвёртая V — достоверность.\n\n## Облака\n- **SaaS** — готовая программа, **PaaS** — среда для своих приложений, **IaaS** — серверы, диски, сеть.\n- В IaaS ОС ставишь **сам**, в PaaS — только своё приложение.\n- **Публичное** облако — для многих клиентов, **частное** — для одной организации, **гибридное** — оба вместе.\n\n## IoT\nДатчик → шлюз → облако → решение → исполнительное устройство. **Edge** — обработка рядом с датчиком: быстро и без интернета.\n**Цифровой двойник** — модель объекта, которую обновляют данные датчиков.\n\n## Безопасность IoT\nУгрозы: заводской пароль, старая микропрограмма, ботнет. Защита: свой пароль, обновления, отдельная сеть, отключить лишнее.\n\n## Расчёты\nОбъём = датчики · показания · байты; 1 КБ = 1024 байта.\n\n## Ловушки ЕНТ\n- Много строк — ещё не Big Data: нужны и скорость, и разнообразие.\n- «Умное» ≠ «защищённое».\n- Чертёж и фото — не цифровой двойник.","kk":"# Үлкен деректер, бұлт және IoT\n\n## Big Data — «үш V»\n- **Көлем** (Volume): деректер өте көп;\n- **Жылдамдық** (Velocity): ағынмен келеді, бірден керек;\n- **Әртүрлілік** (Variety): мәтін, сурет, бейне, датчик көрсеткіштері.\n\nҮлкен кесте әлі Big Data емес. Деректерді көптеген серверге бөледі. Төртінші V — сенімділік.\n\n## Бұлттар\n- **SaaS** — дайын программа, **PaaS** — өз қосымшаларына арналған орта, **IaaS** — серверлер, дискілер, желі.\n- IaaS-та ОЖ-ді **өзің** орнатасың, PaaS-та — тек өз қосымшаңды.\n- **Жалпыға ортақ** бұлт — көп клиентке, **жеке** — бір ұйымға, **гибридті** — екеуі бірге.\n\n## IoT\nДатчик → шлюз → бұлт → шешім → атқарушы құрылғы. **Edge** — датчиктің қасында өңдеу: жылдам әрі интернетсіз.\n**Цифрлық егіз** — датчик деректері жаңартып тұратын нысан моделі.\n\n## IoT қауіпсіздігі\nҚауіптер: зауыттық құпиясөз, ескі микропрограмма, ботнет. Қорғаныс: өз құпиясөзің, жаңартулар, бөлек желі, артығын өшіру.\n\n## Есептеулер\nКөлем = датчиктер · көрсеткіштер · байттар; 1 КБ = 1024 байт.\n\n## ҰБТ тұзақтары\n- Жолдың көп болуы әлі Big Data емес: жылдамдық пен әртүрлілік те керек.\n- «Ақылды» ≠ «қорғалған».\n- Сызба мен фото — цифрлық егіз емес."},
  "it-6-business": {"ru":"# Бизнес-модель и питч стартапа\n\n## Бизнес-модель\nКто клиент, какая проблема, что предлагаем, откуда доход, на что расходы. Пользователь и платящий клиент — не всегда один человек (школьник и родитель).\n\n## Деньги\n- **Прибыль = доход − расходы** (отрицательная — убыток).\n- Расходы: **переменные** (растут с продажами) и **постоянные** (аренда).\n- **Безубыточность** = постоянные расходы / (цена − переменные на 1 штуку).\n- **Freemium**: доход = пользователи · доля платящих · цена.\n\n## Юнит-экономика\n- **ARPU** — доход с клиента за месяц; **отток** — доля ушедших за месяц.\n- **Срок жизни = 1 / отток**; **LTV = ARPU · срок**.\n- **CAC** = расходы на привлечение / число клиентов. Выгодно, если **LTV > CAC**.\n\n## Инвестор\n**Оценка после = оценка до + вложение.** **Доля = вложение / оценка после.** Доля основателей уменьшается (размытие доли).\n\n## Питч (3 минуты ≈ 180 с)\nПроблема → решение → рынок → как зарабатываем → результаты → команда → просьба.\n\n## Частые ошибки\n- Доход принимают за прибыль.\n- Делят вложение на оценку до вложения.\n- Берут процент не от того шага воронки.\n- Сравнивают с CAC не LTV, а ARPU.","kk":"# Стартаптың бизнес-моделі және питчі\n\n## Бизнес-модель\nКлиент кім, қандай мәселе, не ұсынамыз, табыс қайдан, шығын неге. Пайдаланушы мен төлейтін клиент әрдайым бір адам емес (оқушы және ата-ана).\n\n## Ақша\n- **Пайда = табыс − шығындар** (теріс болса — залал).\n- Шығындар: **айнымалы** (сатылыммен өседі) және **тұрақты** (жалдау ақысы).\n- **Залалсыздық нүктесі** = тұрақты шығындар / (баға − 1 дана үшін айнымалы шығын).\n- **Фримиум**: табыс = пайдаланушылар · төлейтіндер үлесі · баға.\n\n## Юнит-экономика\n- **ARPU** — клиенттен бір айдағы табыс; **кету** — бір айда кеткендер үлесі.\n- **Өмір сүру мерзімі = 1 / кету**; **LTV = ARPU · мерзім**.\n- **CAC** = тартуға кеткен шығын / клиент саны. **LTV > CAC** болса, тиімді.\n\n## Инвестор\n**Кейінгі баға = дейінгі баға + салым.** **Үлес = салым / кейінгі баға.** Негізін салушылар үлесі азаяды (dilution).\n\n## Питч (3 минут ≈ 180 с)\nМәселе → шешім → нарық → қалай табыс табамыз → нәтижелер → команда → өтініш.\n\n## Жиі кететін қателер\n- Табысты пайда деп алады.\n- Салымды инвестицияға дейінгі бағаға бөледі.\n- Пайызды воронканың басқа қадамынан алады.\n- CAC көрсеткішімен LTV емес, ARPU салыстырады."},
  "it-7-print": {"ru":"# 3D-печать и форматы моделей\n\n## Способы и технологии\n- **Аддитивное** производство (3D-печать) наращивает деталь слоями; **вычитающее** (станок с ЧПУ) срезает лишнее.\n- **FDM** — расплавленная нить через сопло (PLA, ABS, PETG); **SLA** — жидкая смола и УФ-свет, гладко и точно; **SLS** — лазер спекает порошок, поддержки не нужны.\n\n## Слайсер\nСлой h (тоньше — глаже, но дольше), заполнение в % (больше — прочнее и дороже), стенки, скорость, поддержки под нависаниями круче ~45°.\n\n## Файлы\nМодель → слайсер → **G-code** → принтер.\n- **STL** — только треугольники, без цвета и единиц; двоичный: 84 + 50 · n байт.\n- **OBJ** — текст: v (вершины), f (грани), материалы в .mtl.\n- **3MF** — архив: модель, цвета, материалы, единицы.\n- **G-code** — команды принтеру, не модель.\n\n## Формулы\n- слоёв N = H : h (в одних единицах);\n- расход Q = h · w · v (мм³/с);\n- время t = V : Q; 1 см³ = 1000 мм³;\n- масса m = ρ · V · доля заполнения.\n\n## Ловушки\nЕдиницы (см³ и мм³), STL ≠ G-code, FDM ≠ SLA, «сколько хватит» — округлять вниз.","kk":"# 3D басып шығару және модель пішімдері\n\n## Тәсілдер мен технологиялар\n- **Аддитивті** өндіріс (3D басып шығару) бөлшекті қабаттап өсіреді; **алу арқылы** өндіріс (СББ станогы) артығын кеседі.\n- **FDM** — саптама арқылы балқытылған жіп (PLA, ABS, PETG); **SLA** — сұйық шайыр және УК жарық, тегіс әрі дәл; **SLS** — лазер ұнтақты біріктіреді, тіректер қажет емес.\n\n## Слайсер\nҚабат h (жұқа болса — тегіс, бірақ ұзақ), пайызбен толтыру (көп болса — беріктеу және қымбатырақ), қабырғалар, жылдамдық, шамамен 45°-тан тік салбырау астындағы тіректер.\n\n## Файлдар\nМодель → слайсер → **G-code** → принтер.\n- **STL** — тек үшбұрыштар, түссіз әрі бірліксіз; екілік түрі: 84 + 50 · n байт.\n- **OBJ** — мәтін: v (төбелер), f (жақтар), материалдар .mtl ішінде.\n- **3MF** — архив: модель, түстер, материалдар, бірліктер.\n- **G-code** — принтерге командалар, модель емес.\n\n## Формулалар\n- қабат саны N = H : h (бір бірлікте);\n- шығын Q = h · w · v (мм³/с);\n- уақыт t = V : Q; 1 см³ = 1000 мм³;\n- масса m = ρ · V · толтыру үлесі.\n\n## Тұзақтар\nБірліктер (см³ және мм³), STL ≠ G-code, FDM ≠ SLA, «қанша жетеді» — төмен қарай дөңгелектеу."},
  "logic-1-ops": {"ru":"# Высказывания и логические операции\n\n## Высказывание\nУтверждение, которое истинно (**1**) или ложно (**0**). Вопросы и команды — не высказывания.\n\n## Пять операций\n- **¬A** (НЕ, `not`) — переворачивает значение.\n- **A ∧ B** (И, `and`) — 1, только если оба равны 1.\n- **A ∨ B** (ИЛИ, `or`) — 0, только если оба равны 0. Помни: 1 ∨ 1 = 1.\n- **A → B** (если A, то B) — 0, только при A = 1 и B = 0.\n- **A ↔ B** — 1, если значения A и B одинаковы.\n\n## Приоритет\nСначала скобки, потом **¬**, **∧**, **∨**, **→**, **↔**. Считай по приоритету, а не слева направо.\n\n## Лайфхаки для ЕНТ\n- У каждой операции есть **особый случай**: у ∧ единственная 1, у ∨ и → единственный 0.\n- Записывай значение над каждым знаком и считай по шагам.\n- В задачах «найди значения» подставляй варианты и проверяй каждый.\n\n## Частые ошибки\n- Счёт слева направо без учёта приоритета.\n- «1 ∨ 1 = 2» — на самом деле 1.\n- Считать A → B ложной при A = 0: она ложна только при 1 → 0.\n- ¬ перед скобкой переворачивает всю скобку.","kk":"# Пікірлер және логикалық амалдар\n\n## Пікір\nАқиқат (**1**) немесе жалған (**0**) болатын тұжырым. Сұрақтар мен бұйрықтар — пікір емес.\n\n## Бес амал\n- **¬A** (ЕМЕС, `not`) — мәнді керісінше өзгертеді.\n- **A ∧ B** (ЖӘНЕ, `and`) — екеуі де 1 болғанда ғана 1.\n- **A ∨ B** (НЕМЕСЕ, `or`) — екеуі де 0 болғанда ғана 0. Есіңде болсын: 1 ∨ 1 = 1.\n- **A → B** (егер A болса, онда B) — тек A = 1 және B = 0 болғанда 0.\n- **A ↔ B** — A мен B мәндері бірдей болса, 1.\n\n## Басымдық\nАлдымен жақшалар, сосын **¬**, **∧**, **∨**, **→**, **↔**. Солдан оңға емес, басымдық бойынша есепте.\n\n## ҰБТ-ға арналған кеңестер\n- Әр амалдың **ерекше жағдайы** бар: ∧ тек бір жағдайда 1 береді, ∨ және → тек бір жағдайда 0 береді.\n- Әр белгінің үстіне мәнін жазып, қадам-қадаммен есепте.\n- «Мәндерін тап» есептерінде нұсқаларды қойып, әрқайсысын тексер.\n\n## Жиі кететін қателер\n- Басымдықты ескермей, солдан оңға есептеу.\n- «1 ∨ 1 = 2» — шын мәнінде 1.\n- A → B амалын A = 0 болғанда жалған деп санау: ол тек 1 → 0 болғанда жалған.\n- Жақшаның алдындағы ¬ бүкіл жақшаның мәнін керісінше өзгертеді."},
  "logic-10-reasoning": {"ru":"# Логические задачи: кто прав\n\n## Метод «а что, если?» (перебор гипотез)\n\n1. Выпиши гипотезы: «виновен X», «X — рыцарь».\n2. В каждой проверь все фразы: правда — **1**, ложь — **0**.\n3. Сосчитай единицы в строке и сравни с условием.\n4. Подошла **одна** строка — ответ.\n\n> Подозреваемых n → n гипотез. Рыцарь/лжец у n человек → **2ⁿ** строк.\n\n## Рыцари и лжецы\n\n- Рыцарь = 1 (всегда правда), лжец = 0 (всегда ложь). Для фразы S всегда **X ↔ S**.\n- «Я лжец» не скажет никто. «Я рыцарь» скажут оба.\n- «Ровно один из A, B, C» — **A + B + C = 1**.\n\n## Лайфхаки для ЕНТ\n\n- Две фразы противоречат друг другу → хотя бы одна ложна.\n- Пары «X» и «не X» — ровно одна правдива.\n- После ответа **проверь** его подстановкой во все фразы.\n\n## Частые ошибки\n\n- Ложь «все» ≠ «никто»: правильно — **хотя бы один не**.\n- Ложь «X или Y» = **не X и не Y** (де Морган).\n- Не останавливайся на первой подошедшей гипотезе: проверь все.","kk":"# Логикалық есептер: кім дұрыс\n\n## «Ал егер?» әдісі (болжамдарды түгел тексеру)\n\n1. Болжамдарды жаз: «кінәлі X», «X — рыцарь».\n2. Әрқайсысында барлық сөйлемді тексер: ақиқат — **1**, жалған — **0**.\n3. Жолдағы бірліктерді сана да, шартпен салыстыр.\n4. **Бір** жол сәйкес келсе — жауап.\n\n> Күдікті n болса → n болжам. n адамның рыцарь/өтірікші болуы → **2ⁿ** жол.\n\n## Рыцарьлар мен өтірікшілер\n\n- Рыцарь = 1 (әрқашан ақиқат), өтірікші = 0 (әрқашан жалған). S сөйлемі үшін әрқашан **X ↔ S**.\n- «Мен өтірікшімін» деп ешкім айтпайды. «Мен рыцарьмін» деп екеуі де айтады.\n- «A, B, C-ның дәл біреуі» — **A + B + C = 1**.\n\n## ҰБТ-ға арналған кеңестер\n\n- Екі сөйлем бір-біріне қайшы болса → кемінде біреуі жалған.\n- «X» және «X емес» жұбында дәл біреуі ақиқат.\n- Жауап тапқан соң оны барлық сөйлемге қойып **тексер**.\n\n## Жиі кететін қателер\n\n- «Бәрі» жалған болса, бұл «ешкім» емес: дұрысы — **кемінде біреуі емес**.\n- «X немесе Y» жалған болса = **X емес және Y емес** (Де Морган).\n- Сәйкес келген бірінші болжамда тоқтама: барлығын тексер."},
  "logic-2-tables": {"ru":"# Таблицы истинности\n\n## Как составить\n\n1. Число строк — **2ⁿ** (n — число переменных): 2 → 4, 3 → 8, 4 → 16.\n2. Столбцы переменных: наборы идут как **двоичный счёт** 000, 001, …, 111.\n3. Промежуточные столбцы — по приоритету: **¬**, **∧**, **∨**, **→**, **↔**; скобки первыми.\n4. Последний столбец — итог F.\n\n> (A ∨ B) ∧ ¬C → 8 строк, F = 1 на наборах 010, 100, 110.\n\n## Лайфхаки для ЕНТ\n\n- Не всегда нужна вся таблица: **∧** ложно, если есть 0; **∨** истинно, если есть 1; **→** ложно только при 1 → 0.\n- «Какое выражение подходит фрагменту» — проверяй **каждую строку** и вычёркивай варианты, не совпавшие хотя бы в одной.\n- Два выражения равносильны, если их итоговые столбцы **одинаковы**.\n- После подсчёта единиц сверься: единиц + нулей = 2ⁿ.\n\n## Частые ошибки\n\n- Путают 2ⁿ и n² (для 4 переменных они случайно равны, для 5 — нет).\n- Нарушен порядок наборов: строки пропущены или повторены.\n- ¬(A ∧ B) и ¬A ∧ B — разные выражения.\n- ∧ выполняется раньше ∨: A ∨ B ∧ C — это A ∨ (B ∧ C).\n- Импликация: 0 → что угодно даёт 1.","kk":"# Ақиқат кестелері\n\n## Қалай құрастыру керек\n\n1. Жол саны — **2ⁿ** (n — айнымалылар саны): 2 → 4, 3 → 8, 4 → 16.\n2. Айнымалылар бағандары: жиындар **екілік санау** бойынша жүреді: 000, 001, …, 111.\n3. Аралық бағандар — басымдық бойынша: **¬**, **∧**, **∨**, **→**, **↔**; жақшалар бірінші.\n4. Соңғы баған — F қорытындысы.\n\n> (A ∨ B) ∧ ¬C → 8 жол, F = 1: 010, 100, 110 жиындарында.\n\n## ҰБТ-ға арналған кеңестер\n\n- Кестенің бәрі әрдайым қажет емес: **∧** 0 болса жалған; **∨** 1 болса ақиқат; **→** тек 1 → 0 болғанда жалған.\n- «Қай өрнек үзіндіге сәйкес» — **әр жолды** тексеріп, кемінде бір жолда сәйкес келмеген нұсқаларды сызып таста.\n- Екі өрнектің қорытынды бағандары **бірдей** болса, олар пара-пар.\n- Бірліктерді санаған соң тексер: бірліктер + нөлдер = 2ⁿ.\n\n## Жиі кететін қателер\n\n- 2ⁿ мен n² шатастырады (4 айнымалыда олар кездейсоқ тең, 5-те — жоқ).\n- Жиындар реті бұзылады: жолдар түсіп қалады немесе қайталанады.\n- ¬(A ∧ B) және ¬A ∧ B — әртүрлі өрнектер.\n- ∧ ∨ амалынан бұрын орындалады: A ∨ B ∧ C — бұл A ∨ (B ∧ C).\n- Импликация: 0 → кез келген мән 1 береді."},
  "logic-3-circuits": {"ru":"# Логические схемы\n\n## Элементы (вентили)\n\n- **И** (A ∧ B): 1 только при 1 и 1 — «оба».\n- **ИЛИ** (A ∨ B): 0 только при 0 и 0 — «хотя бы один».\n- **НЕ** (¬A): переворачивает сигнал.\n- **И-НЕ** — ¬(A ∧ B), **ИЛИ-НЕ** — ¬(A ∨ B).\n- **Исключающее ИЛИ** (XOR, A ⊕ B): 1, когда входы разные.\n- Значки на схеме: И — &, ИЛИ — 1, XOR — =1; кружок на выходе — НЕ.\n\n## Как читать схему\n\n1. Иди **от входов к выходу**, слева направо.\n2. Для каждого элемента записывай, что он считает, и подставляй результат в следующий.\n3. Формула последнего элемента — это F.\n\nПример: И → НЕ → ИЛИ с входом C даёт F = ¬(A ∧ B) ∨ C.\n\n## Значение и обратная задача\n\n- Значение: подставь 0 и 1 и считай по проводам слева направо.\n- Когда F = 1: иди **от выхода назад** — что должно быть на входах последнего элемента.\n- При 3 входах всего 8 наборов: таблица помогает не ошибиться.\n\n## Полусумматор\n\nСумма = A ⊕ B, перенос = A ∧ B. Поэтому 1 + 1 = 10₂.\n\n## Частые ошибки\n\n- ¬(A ∧ B) и ¬A ∧ B — разные формулы: смотри, к чему идёт НЕ.\n- Исключающее ИЛИ при 1 и 1 даёт **0**, а не 1.\n- Забыты скобки вокруг результата элемента.","kk":"# Логикалық схемалар\n\n## Элементтер (вентильдер)\n\n- **ЖӘНЕ** (A ∧ B): тек 1 және 1 болғанда 1 — «екеуі де».\n- **НЕМЕСЕ** (A ∨ B): тек 0 және 0 болғанда 0 — «кемінде біреуі».\n- **ЕМЕС** (¬A): сигналды терістейді.\n- **ЖӘНЕ-ЕМЕС** — ¬(A ∧ B), **НЕМЕСЕ-ЕМЕС** — ¬(A ∨ B).\n- **Ерекшелеуші НЕМЕСЕ** (XOR, A ⊕ B): кірістер әртүрлі болғанда 1.\n- Схемадағы белгілер: ЖӘНЕ — &, НЕМЕСЕ — 1, XOR — =1; шығыстағы дөңгелек — ЕМЕС.\n\n## Схеманы қалай оқу керек\n\n1. **Кірістен шығысқа** қарай, солдан оңға жүр.\n2. Әр элемент нені есептейтінін жазып, нәтижені келесі элементке қой.\n3. Соңғы элементтің формуласы — F.\n\nМысал: ЖӘНЕ → ЕМЕС → НЕМЕСЕ (C кірісімен) тізбегі F = ¬(A ∧ B) ∨ C береді.\n\n## Мән және кері есеп\n\n- Мән: 0 мен 1-ді қойып, сымдар бойынша солдан оңға есепте.\n- F = 1 қашан: **шығыстан кері қарай** жүр — соңғы элементтің кірістерінде не болуы керек.\n- 3 кіріс болса, барлығы 8 жиын: кесте қателеспеуге көмектеседі.\n\n## Жартылай сумматор\n\nҚосынды = A ⊕ B, ауысу = A ∧ B. Сондықтан 1 + 1 = 10₂.\n\n## Жиі қателер\n\n- ¬(A ∧ B) және ¬A ∧ B — әртүрлі формулалар: ЕМЕС неге барып тұрғанына қара.\n- Ерекшелеуші НЕМЕСЕ 1 және 1 кезінде **0** береді, 1 емес.\n- Элемент нәтижесін жақшаға алу ұмытылады."},
  "logic-4-laws": {"ru":"# Законы логики и упрощение\n\n## Равносильность\nВыражения **равносильны**, если их итоговые столбцы в таблице истинности совпадают. Упростить — значит заменить выражение более коротким равносильным: схема получится из меньшего числа вентилей.\n\n## Законы\n- ¬¬A = A; A ∨ ¬A = 1; A ∧ ¬A = 0\n- A ∧ 1 = A; A ∨ 0 = A; A ∨ 1 = 1; A ∧ 0 = 0\n- A ∧ B = B ∧ A; (A ∧ B) ∧ C = A ∧ (B ∧ C)\n- A ∧ (B ∨ C) = (A ∧ B) ∨ (A ∧ C); A ∨ (B ∧ C) = (A ∨ B) ∧ (A ∨ C)\n- **Де Морган:** ¬(A ∧ B) = ¬A ∨ ¬B; ¬(A ∨ B) = ¬A ∧ ¬B\n- **Поглощение:** A ∨ (A ∧ B) = A; A ∧ (A ∨ B) = A\n- **Импликация:** A → B = ¬A ∨ B\n\n## Как упрощать\n1. Замени → на ¬A ∨ B, раскрой ¬ перед скобкой.\n2. Вынеси общую часть за скобку.\n3. Найди пары B ∨ ¬B (= 1) и B ∧ ¬B (= 0), убери 1 и 0.\n\n## Лайфхаки для ЕНТ\n- Сомневаешься — подставь один набор значений в исходное выражение и в вариант. Результаты разные — вариант неверный.\n- В задаче «кто есть кто» предположи одно высказывание верным и ищи противоречие.\n\n## Частые ошибки\n- ¬(A ∧ B) = ¬A ∧ ¬B — забыто поменять ∧ на ∨.\n- Забыто двойное отрицание: ¬(¬B) = B.","kk":"# Логика заңдары және ықшамдау\n\n## Пара-парлық\nАқиқат кестесіндегі қорытынды бағандары сәйкес келсе, өрнектер **пара-пар**. Ықшамдау — өрнекті одан қысқа пара-пар өрнекпен ауыстыру: схема аз вентильден құралады.\n\n## Заңдар\n- ¬¬A = A; A ∨ ¬A = 1; A ∧ ¬A = 0\n- A ∧ 1 = A; A ∨ 0 = A; A ∨ 1 = 1; A ∧ 0 = 0\n- A ∧ B = B ∧ A; (A ∧ B) ∧ C = A ∧ (B ∧ C)\n- A ∧ (B ∨ C) = (A ∧ B) ∨ (A ∧ C); A ∨ (B ∧ C) = (A ∨ B) ∧ (A ∨ C)\n- **Де Морган:** ¬(A ∧ B) = ¬A ∨ ¬B; ¬(A ∨ B) = ¬A ∧ ¬B\n- **Жұтылу:** A ∨ (A ∧ B) = A; A ∧ (A ∨ B) = A\n- **Импликация:** A → B = ¬A ∨ B\n\n## Қалай ықшамдау керек\n1. → амалын ¬A ∨ B деп ауыстыр, жақшаның алдындағы ¬ белгісін аш.\n2. Ортақ бөлікті жақшаның сыртына шығар.\n3. B ∨ ¬B (= 1) және B ∧ ¬B (= 0) жұптарын тауып, 1 мен 0-ді алып таста.\n\n## ҰБТ-ға арналған кеңестер\n- Күмән болса — бастапқы өрнекке және нұсқаға мәндердің бір жиынын қойып көр. Нәтижелер әртүрлі болса — нұсқа қате.\n- «Кім кім» есебінде бір пікірді ақиқат деп ұйғарып, қайшылық іздеу керек.\n\n## Жиі кететін қателер\n- ¬(A ∧ B) = ¬A ∧ ¬B — ∧ амалын ∨ амалына ауыстыру ұмытылған.\n- Қос терістеу ұмытылған: ¬(¬B) = B."},
  "logic-5-impl": {"ru":"# Импликация и эквиваленция\n\n## Импликация A → B («если A, то B»)\n- A — условие, B — следствие.\n- **Ложна только при 1 → 0** (условие есть, следствия нет). Если условие ложно, импликация истинна.\n- A → B = ¬A ∨ B = ¬(A ∧ ¬B).\n- Порядок важен: B → A — другое выражение (обратное). Контрапозиция ¬B → ¬A равносильна A → B.\n\n## Эквиваленция A ↔ B (A ≡ B)\n«Тогда и только тогда»: 1, когда A и B **одинаковы**. A ↔ B = (A → B) ∧ (B → A).\n\n## Исключающее ИЛИ A ⊕ B\n1, когда A и B **разные**. A ⊕ B = ¬(A ↔ B).\n\n## Приоритет\n¬, ∧, ∨, →, ↔. Импликация считается почти последней: ¬A ∨ B → C = (¬A ∨ B) → C. Цепочку → и знак ⊕ пиши со скобками.\n\n## Слова в формулы\n- «X, только если Y» = X → Y\n- «X, если Y» = Y → X\n- «X тогда и только тогда, когда Y» = X ↔ Y\n\n## Лайфхаки ЕНТ\n- Хочешь получить 0 у импликации — ищи «1 слева, 0 справа».\n- В Python A → B пишут `not A or B`.\n\n## Частые ошибки\n- Считать 0 → 1 ложью (на самом деле 1).\n- Считать → слева направо, не по приоритету.\n- Путать «если» и «только если».","kk":"# Импликация және эквиваленция\n\n## Импликация A → B («егер A болса, онда B»)\n- A — шарт, B — салдар.\n- **Тек 1 → 0 болғанда жалған** (шарт бар, салдар жоқ). Шарт жалған болса, импликация ақиқат.\n- A → B = ¬A ∨ B = ¬(A ∧ ¬B).\n- Реті маңызды: B → A — басқа өрнек (кері). ¬B → ¬A контрапозициясы A → B өрнегіне пара-пар.\n\n## Эквиваленция A ↔ B (A ≡ B)\n«Сонда және тек сонда»: A мен B **бірдей** болғанда 1. A ↔ B = (A → B) ∧ (B → A).\n\n## Ерекшелеуші НЕМЕСЕ A ⊕ B\nA мен B **әртүрлі** болғанда 1. A ⊕ B = ¬(A ↔ B).\n\n## Басымдық\n¬, ∧, ∨, →, ↔. Импликация дерлік соңында есептеледі: ¬A ∨ B → C = (¬A ∨ B) → C. → тізбегін және ⊕ белгісін жақшамен жаз.\n\n## Сөздерден формулаға\n- «X, тек Y болса ғана» = X → Y\n- «X, егер Y болса» = Y → X\n- «Y болғанда және тек сонда ғана X» = X ↔ Y\n\n## ҰБТ лайфхактары\n- Импликацияда 0 алғың келсе, «сол жағы 1, оң жағы 0» жағдайын ізде.\n- Python-да A → B өрнегін `not A or B` деп жазады.\n\n## Жиі қателер\n- 0 → 1 өрнегін жалған деп санау (шын мәнінде 1).\n- → амалын басымдық бойынша емес, солдан оңға есептеу.\n- «Егер» мен «тек … ғана» тіркестерін шатастыру."},
  "logic-6-build": {"ru":"# Таблица истинности сложного выражения\n\n## Как собрать\n\n1. Строк **2ⁿ**: 3 переменные — 8, 4 — 16, 5 — 32.\n2. Столбцы переменных — **двоичный счёт, блоками**: A — по 8, B — по 4, C — по 2, D — 0, 1, 0, 1…\n3. Помощники в порядке выполнения: скобки, ¬, ∧, ∨, →, ↔. Затем итог F.\n4. Контроль: единиц + нулей = 2ⁿ.\n\n## Короткие пути\n\n- ∧ = 0, если есть 0; ∨ = 1, если есть 1; → = 0 только при 1 → 0.\n- Единиц много — считай нули и вычитай из 2ⁿ.\n- Цепочка (A → B) ∧ (B → C) ∧ (C → D): n + 1 набор — 0000, 0001, 0011, 0111, 1111. Кольцо из импликаций — 2 набора (все равны).\n\n## По таблице — выражение\n\n- **По единицам**: для каждой строки с F = 1 запиши ключ (переменная 0 — с ¬), ключи соедини **∨**.\n- **По нулям** (если нулей мало): для строки с F = 0 — скобка из ∨, где переменная 1 берётся с ¬; скобки через ∧.\n- Проверь **все** строки: совпавшие единицы ничего не доказывают.\n\n## Частые ошибки\n\n- ключи через ∧ вместо ∨;\n- потеряна строка (нет контроля 2ⁿ);\n- ¬ перед скобкой применяют к каждой букве.","kk":"# Күрделі өрнектің ақиқат кестесі\n\n## Қалай құрастыру керек\n\n1. Жол саны **2ⁿ**: 3 айнымалы — 8, 4 — 16, 5 — 32.\n2. Айнымалылар бағандары — **екілік санау, блоктармен**: A — 8-ден, B — 4-тен, C — 2-ден, D — 0, 1, 0, 1…\n3. Көмекшілер орындалу ретімен: жақшалар, ¬, ∧, ∨, →, ↔. Сосын F қорытындысы.\n4. Бақылау: бірліктер + нөлдер = 2ⁿ.\n\n## Қысқа жолдар\n\n- Кемінде бір 0 болса ∧ = 0; кемінде бір 1 болса ∨ = 1; → = 0 тек 1 → 0 болғанда.\n- Бірлік көп болса — нөлдерді санап, 2ⁿ санынан шегер.\n- (A → B) ∧ (B → C) ∧ (C → D) тізбегі: n + 1 жиын — 0000, 0001, 0011, 0111, 1111. Импликациялар сақинасы — 2 жиын (бәрі тең).\n\n## Кестеден — өрнек\n\n- **Бірліктер бойынша**: F = 1 болатын әр жолға кілт жаз (0-ге тең айнымалы — ¬ белгісімен), кілттерді **∨** арқылы қос.\n- **Нөлдер бойынша** (нөл аз болса): F = 0 жолы үшін ∨ жақшасы, мұнда 1-ге тең айнымалы ¬ белгісімен алынады; жақшалар ∧ арқылы.\n- **Барлық** жолды тексер: сәйкес келген бірліктер ештеңені дәлелдемейді.\n\n## Жиі кететін қателер\n\n- ∨ орнына ∧ арқылы біріктірілген кілттер;\n- жол жоғалған (2ⁿ бақылауы жоқ);\n- жақша алдындағы ¬ әр әріпке қолданылады."},
  "logic-7-schemes": {"ru":"# Схемы и формулы\n\n## Схема → формула\n- Иди от входов к выходу. Каждый вентиль — маленькая формула из формул его входов.\n- Результат вентиля бери в скобки, особенно ¬(…).\n- Вентилей столько же, сколько операций в формуле; И-НЕ и ИЛИ-НЕ — один вентиль, но две операции.\n\n## Формула → схема\n1. Найди **последнюю** операцию: это выходной вентиль.\n2. Её части — входы вентиля; для каждой части повтори шаг 1.\n3. Одна переменная — один вход, провод разветвляется.\n4. В схеме нет →: заменяй A → B на ¬A ∨ B.\n\n## Когда на выходе 1\nИди от выхода назад: И даёт 1 только при 1 и 1; ИЛИ даёт 0 только при 0 и 0; ⊕ даёт 1 при разных входах. При n входах всего 2ⁿ наборов.\n\n## Совпадают ли две схемы\n- Составь таблицы обеих и сравни столбцы **целиком**.\n- Один набор с разными значениями доказывает «не совпадают».\n- «Совпадают» — только после проверки всех 2ⁿ наборов.\n- Пример: (A ∨ B) ∧ ¬(A ∧ B) и A ⊕ B совпадают.\n\n## Лайфхаки ЕНТ\n- Подставь в варианты один «подозрительный» набор: лишние отсеются.\n- Чаще всего ошибаются с НЕ: смотри, к чему именно оно относится.","kk":"# Схемалар мен формулалар\n\n## Схема → формула\n- Кірістен шығысқа қарай жүр. Әр вентиль — өз кірістерінің формулаларынан құралған шағын формула.\n- Вентиль нәтижесін жақшаға ал, әсіресе ¬(…).\n- Вентильдер саны формуладағы амалдар санындай; ЖӘНЕ-ЕМЕС, НЕМЕСЕ-ЕМЕС — бір вентиль, бірақ екі амал.\n\n## Формула → схема\n1. **Соңғы** амалды тап: бұл — шығыс вентилі.\n2. Оның бөліктері — вентиль кірістері; әр бөлікке 1-қадамды қайтала.\n3. Бір айнымалы — бір кіріс, сым тармақталады.\n4. Схемада → жоқ: A → B өрнегін ¬A ∨ B түріне ауыстыр.\n\n## Шығыста 1 қашан болады\nШығыстан кері қарай жүр: ЖӘНЕ тек 1 және 1 болғанда 1 береді; НЕМЕСЕ тек 0 және 0 болғанда 0 береді; ⊕ кірістер әртүрлі болғанда 1 береді. n кіріс болса, барлығы 2ⁿ жиын.\n\n## Екі схема бірдей ме\n- Екеуінің кестесін құрып, бағандарды **толығымен** салыстыр.\n- Мәндері әртүрлі бір жиын «бірдей емес» дегенді дәлелдейді.\n- «Бірдей» — тек барлық 2ⁿ жиынды тексергеннен кейін.\n- Мысал: (A ∨ B) ∧ ¬(A ∧ B) және A ⊕ B бірдей.\n\n## ҰБТ лайфхактары\n- Нұсқаларға бір «күдікті» жиынды қой: артығы түсіп қалады.\n- Көбіне ЕМЕС-те қателеседі: ол нақты неге қатысты екеніне қара."},
  "logic-8-numbers": {"ru":"# Логика с числами: при каком X истинно\n\n## Условие с X\n(X > 3) — не высказывание, пока X неизвестен. Подставили число — получили 1 или 0. Из таких скобок строим выражения с ¬, ∧, ∨, →.\n\n## Отрицание неравенства\nЗнак меняется на противоположный, граница переходит на другую сторону:\n- ¬(X > 7) = X ≤ 7, ¬(X < 5) = X ≥ 5\n- ¬(X ≥ 4) = X < 4, ¬(X ≤ 4) = X > 4, ¬(X = 3) = X ≠ 3\n\n## Числовая ось\n- ∧ — общая часть промежутков, ∨ — объединение.\n- A → B ложно только там, где A истинно, а B ложно (или A → B = ¬A ∨ B).\n- Для целых X: X > 3 — это X ≥ 4, X < 8 — это X ≤ 7.\n- Целых чисел в a ≤ X ≤ b ровно b − a + 1.\n\n## Параметр A («при любом X»)\nНайди X, который портит выражение, и подбери A так, чтобы такого X не было. Проверь соседние значения A.\n\n## Лайфхаки для ЕНТ\n- Проверяй границы подстановкой самого числа-границы.\n- Решение можно сверить циклом for в Python.\n\n## Частые ошибки\n- ¬(X > 7) пишут как X < 7: потеряно число 7.\n- Считают b − a вместо b − a + 1.\n- Забывают вычесть число из условия «≠».","kk":"# Сандармен логика: X қандай болғанда ақиқат\n\n## X бар шарт\n(X > 3) — X белгісіз болса, пікір емес. Санды қойдық — 1 немесе 0 шықты. Осындай жақшалардан ¬, ∧, ∨, → бар өрнектер құрамыз.\n\n## Теңсіздікті терістеу\nТаңба қарама-қарсысына ауысады, шекара басқа жаққа өтеді:\n- ¬(X > 7) = X ≤ 7, ¬(X < 5) = X ≥ 5\n- ¬(X ≥ 4) = X < 4, ¬(X ≤ 4) = X > 4, ¬(X = 3) = X ≠ 3\n\n## Сан осі\n- ∧ — аралықтардың ортақ бөлігі, ∨ — бірігу.\n- A → B тек A ақиқат, ал B жалған болғанда жалған (немесе A → B = ¬A ∨ B).\n- Бүтін X үшін: X > 3 — бұл X ≥ 4, X < 8 — бұл X ≤ 7.\n- a ≤ X ≤ b аралығындағы бүтін сандар дәл b − a + 1.\n\n## A параметрі («кез келген X үшін»)\nӨрнекті бұзатын X мәнін тауып, ондай X болмайтындай A таңда. A параметрінің көршілес мәндерін тексер.\n\n## ҰБТ-ға арналған кеңестер\n- Шекараларды шекара санының өзін қойып тексер.\n- Шешімді Python-дағы for циклімен салыстыруға болады.\n\n## Жиі кететін қателер\n- ¬(X > 7) өрнегін X < 7 деп жазады: 7 саны жоғалады.\n- b − a санайды, ал b − a + 1 керек.\n- «≠» шартындағы санды алып тастауды ұмытады."},
  "logic-9-sets": {"ru":"# Множества и запросы: круги Эйлера\n\n## Главное\n- **Множество** — группа объектов, **элемент** — один объект. |A| — число элементов, |U| — всего (весь класс, все страницы).\n- **A ∩ B** (И, в запросе **&**) — пересечение: есть и в A, и в B.\n- **A ∪ B** (ИЛИ, в запросе **|**) — объединение: есть хотя бы в одном.\n- **~A** (НЕ) — всё вне A. **A & ~B** — «A, но не B».\n\n## Формулы\n- |A ∪ B| = |A| + |B| − |A ∩ B|\n- |A & ~B| = |A| − |A ∩ B|\n- вне обоих: |U| − |A ∪ B|\n- три множества: |A ∪ B ∪ C| = |A| + |B| + |C| − |A ∩ B| − |A ∩ C| − |B ∩ C| + |A ∩ B ∩ C|\n\n## Лайфхаки для ЕНТ\n- Проверка ответа: **A & B ≤ A ≤ A | B**.\n- Рисуй круги и заполняй области, начиная с центра: центр → пары (минус центр) → одиночные.\n- В Python: `a & b`, `a | b`, `a - b`, `len(...)`.\n\n## Частые ошибки\n- Сложить |A| + |B| и забыть вычесть общих.\n- Принять «и» из жизни за знак & (часто это |).\n- Не заметить, что один круг внутри другого: если B целиком внутри A, то A & B = B, а A | B = A.\n- В формуле для трёх множеств забыть прибавить |A ∩ B ∩ C|.","kk":"# Жиындар және сұраныстар: Эйлер дөңгелектері\n\n## Негізгі\n- **Жиын** — объектілер тобы, **элемент** — бір объект. |A| — элементтер саны, |U| — барлығы (бүкіл сынып, барлық бет).\n- **A ∩ B** (ЖӘНЕ, сұраныста **&**) — қиылысу: A жиынында да, B жиынында да бар.\n- **A ∪ B** (НЕМЕСЕ, сұраныста **|**) — бірігу: кемінде біреуінде бар.\n- **~A** (ЕМЕС) — A жиынынан тыс барлығы. **A & ~B** — «A бар, B жоқ».\n\n## Формулалар\n- |A ∪ B| = |A| + |B| − |A ∩ B|\n- |A & ~B| = |A| − |A ∩ B|\n- екеуінен де тыс: |U| − |A ∪ B|\n- үш жиын: |A ∪ B ∪ C| = |A| + |B| + |C| − |A ∩ B| − |A ∩ C| − |B ∩ C| + |A ∩ B ∩ C|\n\n## ҰБТ-ға арналған кеңестер\n- Жауапты тексеру: **A & B ≤ A ≤ A | B**.\n- Дөңгелектерді сызып, аумақтарды орталықтан бастап толтыр: орталық → жұптар (орталықты шегеріп) → жекелері.\n- Python-да: `a & b`, `a | b`, `a - b`, `len(...)`.\n\n## Жиі кететін қателер\n- |A| + |B| қосып, ортақтарды шегеруді ұмыту.\n- Өмірдегі «және» сөзін & белгісі деп санау (көбіне ол |).\n- Бір дөңгелек екіншісінің ішінде екенін байқамау: B толығымен A ішінде жатса, A & B = B, ал A | B = A.\n- Үш жиынның формуласында |A ∩ B ∩ C| қосуды ұмыту."},
  "net-1-basics": {"ru":"# Компьютерные сети\n\n**Сеть** — компьютеры и устройства, соединённые для обмена данными и общих ресурсов (принтер, файлы, интернет).\n\n## Виды по охвату\n\n| Сеть | Охват | Пример |\n|---|---|---|\n| LAN | Локальная: комната, школа, дом | Класс информатики |\n| MAN | Городская | Сеть банка в городе |\n| WAN | Глобальная | Интернет |\n\n## Топологии\n\n- **Шина** — один общий кабель; обрыв ломает сеть.\n- **Звезда** — все к центру (коммутатор); отказ центра отключает всех, а кабеля одного компьютера — только его.\n- **Кольцо** — каждый с двумя соседями по кругу.\n- **Сетка** — много путей, надёжно, но дорого: в полной сетке из n компьютеров n(n − 1)/2 кабелей.\n\n## Устройства\n\n- **Сетевая карта** — в каждом компьютере.\n- **Коммутатор** — внутри одной сети. **Маршрутизатор** — между сетями, шлюз в интернет.\n- **Модем**, **точка доступа Wi-Fi**, **сервер**.\n\n## Лайфхаки для ЕНТ\n\n- «Связывает локальную сеть с интернетом» — **маршрутизатор**.\n- Архитектуры: **клиент–сервер** (есть сервер) и **одноранговая** (все равны).\n- Среда: витая пара, **оптоволокно** (свет, самое быстрое), радиоканал.\n\n## Частые ошибки\n\n- Путают коммутатор и маршрутизатор.\n- Считают Wi-Fi и интернет одним и тем же.\n- Забывают поделить на 2 в полной сетке.","kk":"# Компьютерлік желілер\n\n**Желі** — деректермен алмасу және ортақ ресурстарды (принтер, файлдар, интернет) пайдалану үшін жалғанған компьютерлер мен құрылғылар.\n\n## Қамту аумағы бойынша түрлері\n\n| Желі | Қамту аумағы | Мысал |\n|---|---|---|\n| LAN | Жергілікті: бөлме, мектеп, үй | Информатика кабинеті |\n| MAN | Қалалық | Қаладағы банк желісі |\n| WAN | Ғаламдық | Интернет |\n\n## Топологиялар\n\n- **Шина** — бір ортақ кабель; үзілу желіні бұзады.\n- **Жұлдыз** — бәрі орталыққа (коммутатор); орталық істен шықса, бәрі ажырайды, ал бір компьютердің кабелі үзілсе — тек сол.\n- **Сақина** — әрқайсысы шеңбер бойымен екі көршімен.\n- **Тор** — жолдар көп, сенімді, бірақ қымбат: n компьютерден тұратын толық торда n(n − 1)/2 кабель.\n\n## Құрылғылар\n\n- **Желілік карта** — әр компьютерде.\n- **Коммутатор** — бір желі ішінде. **Маршрутизатор** — желілер арасында, интернетке шлюз.\n- **Модем**, **Wi-Fi қол жеткізу нүктесі**, **сервер**.\n\n## ҰБТ-ға арналған кеңестер\n\n- «Жергілікті желіні интернетпен байланыстырады» — **маршрутизатор**.\n- Архитектуралар: **клиент–сервер** (сервер бар) және **бір рангілі** (бәрі тең).\n- Орта: есілген жұп, **оптикалық талшық** (жарық, ең жылдам), радиоарна.\n\n## Жиі кететін қателер\n\n- Коммутатор мен маршрутизаторды шатастырады.\n- Wi-Fi мен интернетті бір нәрсе деп санайды.\n- Толық торда 2-ге бөлуді ұмытады."},
  "net-10-crypto": {"ru":"# Шифрование и цифровая подпись\n\n## Термины\n\n**Открытый текст → шифрование (ключ) → шифртекст → расшифровка (ключ).** Секретным должен быть ключ, а не шифр.\n\n## Шифр Цезаря\n\n- Шифруем: номер + ключ, расшифровываем: номер − ключ; вышли за 0…25 — прибавь или вычти 26. Ключ ≥ 26 → остаток от деления на 26.\n- Найти ключ: номер шифра − номер буквы. Два шифрования подряд = ключ-сумма.\n- Взлом: перебор 25 ключей или частотный анализ. Надёжность = число ключей.\n\n## Ключи\n\n- **Симметричное** — один ключ, быстро, на n человек n(n − 1)/2 ключей. **Асимметричное** — пара, на n человек 2n ключей.\n- Письмо шифруют **открытым** ключом получателя; подпись ставят **закрытым** ключом автора, проверяют **открытым**.\n- **HTTPS** = HTTP + TLS: сертификат → проверка → общий ключ сеанса → быстрая симметричная передача. Замочек не гарантирует честность сайта.\n- **Хэш** — короткий отпечаток данных, обратно не восстановить. **ЭЦП** — хэш документа + закрытый ключ: автор и неизменность; на eGov.\n\n## Пароли\n\n- Вариантов **Nᴸ**; разные места — перемножаем. Время в худшем случае = Nᴸ / скорость.\n- **2FA** = два фактора **разных** типов (знание, владение, свойство). Пароль + секретный вопрос — не 2FA.","kk":"# Шифрлау және цифрлық қолтаңба\n\n## Терминдер\n\n**Ашық мәтін → шифрлау (кілт) → шифрмәтін → шифрды ашу (кілт).** Құпия болатыны — шифр емес, кілт.\n\n## Цезарь шифры\n\n- Шифрлаймыз: нөмір + кілт, шифрды ашамыз: нөмір − кілт; 0…25 аралығынан шықса — 26-ны қос немесе азайт. Кілт ≥ 26 болса — 26-ға бөлгендегі қалдық.\n- Кілтті табу: шифр нөмірі − әріп нөмірі. Қатарынан екі шифрлау = кілттер қосындысы.\n- Бұзу: 25 кілтті іріктеу немесе жиілік талдауы. Беріктік = кілттер саны.\n\n## Кілттер\n\n- **Симметриялық** — бір кілт, жылдам, n адамға n(n − 1)/2 кілт. **Асимметриялық** — жұп, n адамға 2n кілт.\n- Хатты алушының **ашық** кілтімен шифрлайды; қолтаңбаны автордың **жабық** кілтімен қояды, **ашық** кілтімен тексереді.\n- **HTTPS** = HTTP + TLS: сертификат → тексеру → сеанстың ортақ кілті → жылдам симметриялық жіберу. Құлыпша сайт адалдығына кепіл емес.\n- **Хэш** — деректердің қысқа ізі, кері қайтпайды. **ЭЦҚ** — құжат хэші + жабық кілт: автор және өзгермегені; eGov-та.\n\n## Құпиясөздер\n\n- Нұсқалар саны **Nᴸ**; орындар әртүрлі болса — көбейтеміз. Ең нашар жағдайдағы уақыт = Nᴸ / жылдамдық.\n- **2FA** = **әртүрлі** түрдегі екі фактор (білім, иелену, тән белгі). Құпиясөз + құпия сұрақ — 2FA емес."},
  "net-2-internet": {"ru":"# IP-адреса, URL и DNS\n\n## IP-адрес\n\n- **IPv4**: ровно **4 числа от 0 до 255** через точки, например 192.168.1.10. Каждое число — 1 байт, весь адрес — 32 бита.\n- Ошибки: 3 или 5 чисел, число больше 255, лишние точки, запятые вместо точек.\n- **IPv6**: 128 бит, 8 групп через двоеточие.\n- **Адрес сети = IP И маска** (побитово). Где в маске 255 — число сохраняется, где 0 — обнуляется.\n\n## Имя, DNS и URL\n\n- **DNS** — «телефонная книга» интернета: имя сайта → IP-адрес.\n- **URL**: протокол **://** сервер **/** путь **/** файл, например https://edu.gov.kz/docs/plan.pdf.\n- Домен читают справа налево: **kz** — верхнего уровня.\n- Почта: **имя@домен**, например aman@school.kz.\n\n## Протоколы\n\n- **HTTP / HTTPS** — веб (S — шифрование); **FTP** — файлы.\n- **SMTP** — отправка писем; **POP3** — получение; **IMAP** — чтение на сервере.\n- **TCP/IP** — основа интернета.\n\n## Лайфхаки для ЕНТ\n\n- Собирая адрес из кусочков, смотри на точки по краям и на число 255.\n- В вопросах «выберите все» не отмечай сомнительное: лишний ответ стоит балла.","kk":"# IP мекенжайлар, URL және DNS\n\n## IP мекенжай\n\n- **IPv4**: нүктелермен бөлінген дәл **0-ден 255-ке дейінгі 4 сан**, мысалы 192.168.1.10. Әр сан — 1 байт, бүкіл мекенжай — 32 бит.\n- Қателер: 3 немесе 5 сан, 255-тен үлкен сан, артық нүктелер, нүктенің орнына үтір.\n- **IPv6**: 128 бит, қос нүктемен бөлінген 8 топ.\n- **Желі мекенжайы = IP ЖӘНЕ маска** (биттер бойынша). Маскада 255 тұрған жерде сан сақталады, 0 тұрған жерде нөлге айналады.\n\n## Ат, DNS және URL\n\n- **DNS** — интернеттің «телефон кітапшасы»: сайт аты → IP мекенжай.\n- **URL**: хаттама **://** сервер **/** жол **/** файл, мысалы https://edu.gov.kz/docs/plan.pdf.\n- Доменді оңнан солға қарай оқиды: **kz** — жоғарғы деңгейлі.\n- Пошта: **аты@домен**, мысалы aman@school.kz.\n\n## Хаттамалар\n\n- **HTTP / HTTPS** — веб (S — шифрлау); **FTP** — файлдар.\n- **SMTP** — хаттарды жіберу; **POP3** — алу; **IMAP** — серверде оқу.\n- **TCP/IP** — интернеттің негізі.\n\n## ҰБТ-ға арналған кеңестер\n\n- Мекенжайды үзінділерден жинағанда, шеттердегі нүктелерге және 255 санына қара.\n- «Барлығын таңдаңыз» сұрақтарында күмәнді нұсқаны белгілеме: артық жауап баллды алып тастайды."},
  "net-3-speed": {"ru":"# Скорость передачи данных\n\n## Формулы\n\n**I = v · t**, откуда **t = I / v** и **v = I / t**.\n\n- **I** — объём файла, **v** — скорость (пропускная способность канала), **t** — время в секундах.\n- Скорость измеряют в **бит/с**, **Кбит/с**, **Мбит/с**.\n\n## Главное правило: одни единицы\n\nПеред делением приведи объём и скорость к одним единицам (чаще всего к битам), время — к секундам.\n\n| Единица | Значение |\n|---|---|\n| 1 байт | 8 бит = 2³ бит |\n| 1 Кбайт | 1024 байта = 2¹⁰ байт |\n| 1 Кбит | 1024 бит |\n| 1 минута | 60 секунд |\n\n## Типы задач\n\n- время передачи файла, размер файла за время t, сравнение двух каналов;\n- **несколько этапов** (промежуточный узел, сжатие → передача → распаковка): время этапов считаем отдельно и **складываем**.\n\n## Лайфхаки для ЕНТ\n\n- Запиши числа как степени двойки: 8 = 2³, 1024 = 2¹⁰ — сокращать проще, чем делить.\n- Демо ЕНТ: 1050 Кбайт при 8400 байт/с → 1050 · 1024 / 8400 = **128 с**.\n- Проверка: v · t должно дать исходный объём.\n\n## Частые ошибки\n\n- Забыт переход **байты → биты** (× 8) или сделан дважды.\n- **Минуты** не переведены в секунды.\n- Вместо 1024 взято 1000, если в условии указано 1024.","kk":"# Деректерді беру жылдамдығы\n\n## Формулалар\n\n**I = v · t**, одан **t = I / v** және **v = I / t**.\n\n- **I** — файл көлемі, **v** — жылдамдық (арнаның өткізу қабілеті), **t** — секундпен уақыт.\n- Жылдамдықты **бит/с**, **Кбит/с**, **Мбит/с** бірліктерімен өлшейді.\n\n## Басты ереже: бірліктер бірдей болсын\n\nБөлу алдында көлем мен жылдамдықты бір бірлікке (көбіне битке), уақытты секундқа келтір.\n\n| Бірлік | Мәні |\n|---|---|\n| 1 байт | 8 бит = 2³ бит |\n| 1 Кбайт | 1024 байт = 2¹⁰ байт |\n| 1 Кбит | 1024 бит |\n| 1 минут | 60 секунд |\n\n## Есеп түрлері\n\n- файлды беру уақыты, t уақыттағы файл көлемі, екі арнаны салыстыру;\n- **бірнеше кезең** (аралық түйін, сығу → беру → ашу): кезеңдердің уақытын жеке есептеп, **қосамыз**.\n\n## ҰБТ-ға арналған кеңестер\n\n- Сандарды екінің дәрежесі ретінде жаз: 8 = 2³, 1024 = 2¹⁰ — қысқарту бөлуден оңай.\n- ҰБТ демоверсиясы: 1050 Кбайт, 8400 байт/с → 1050 · 1024 / 8400 = **128 с**.\n- Тексеру: v · t бастапқы көлемді беруі керек.\n\n## Жиі кететін қателер\n\n- **Байт → бит** (× 8) ұмытылған немесе екі рет жасалған.\n- **Минуттар** секундқа аударылмаған.\n- Шартта 1024 көрсетілсе де, 1024 орнына 1000 алынған."},
  "net-4-security": {"ru":"# Информационная безопасность\n\n## Угрозы\n\n- **Вирус** — заражает файлы и размножается.\n- **Червь** — сам распространяется по сети.\n- **Троян** — маскируется под полезную программу.\n- **Шпионская программа** — тайно собирает пароли и данные.\n- **Программа-вымогатель** — шифрует файлы и требует выкуп.\n- **Фишинг** — поддельный сайт или сообщение; признаки: срочность, странный адрес, просьба прислать код.\n\n## Защита\n\nАнтивирус, брандмауэр (firewall), обновления, резервные копии (отдельно от компьютера), надёжный пароль, двухфакторная аутентификация, HTTPS. Личные данные не публикуем.\n\n## Шифрование\n\n- **Симметричное** — один ключ. **Асимметричное** — открытый (шифрует, его можно показывать) и закрытый (расшифровывает, хранится у владельца).\n- **ЭЦП** — подтверждает автора и неизменность документа, но не прячет текст. Используется на eGov.\n- **Шифр Цезаря**: A = 0, …, Z = 25. Шифруем: номер + ключ, расшифровываем: номер − ключ; вышли за 0…25 — прибавь или вычти 26.\n\n## Расчёты и ловушки ЕНТ\n\n- Вариантов пароля: **Nᴸ**. Каждый новый символ — в N раз больше.\n- Замочек HTTPS не значит, что сайт честный.\n- Копия на том же компьютере от вымогателя не спасёт.","kk":"# Ақпараттық қауіпсіздік\n\n## Қауіптер\n\n- **Вирус** — файлдарды залалдайды және көбейеді.\n- **Құрт** — желі арқылы өздігінен таралады.\n- **Троян** — пайдалы бағдарлама болып көрінеді.\n- **Тыңшы бағдарлама** — құпиясөздер мен деректерді жасырын жинайды.\n- **Бопсалаушы бағдарлама** — файлдарды шифрлап, төлем талап етеді.\n- **Фишинг** — жалған сайт немесе хабарлама; белгілері: асығыстық, оғаш мекенжай, код жіберуді сұрау.\n\n## Қорғаныс\n\nАнтивирус, брандмауэр (firewall), жаңартулар, резервтік көшірмелер (компьютерден бөлек), сенімді құпиясөз, екі факторлы аутентификация, HTTPS. Жеке деректерді жарияламаймыз.\n\n## Шифрлау\n\n- **Симметриялық** — бір кілт. **Асимметриялық** — ашық (шифрлайды, оны көрсетуге болады) және жабық (шифрды ашады, иесінде сақталады).\n- **ЭЦҚ** — автор мен құжаттың өзгермегенін растайды, бірақ мәтінді жасырмайды. eGov-та қолданылады.\n- **Цезарь шифры**: A = 0, …, Z = 25. Шифрлаймыз: нөмір + кілт, шифрды ашамыз: нөмір − кілт; 0…25 аралығынан шықса — 26-ны қос немесе азайт.\n\n## Есептеулер және ҰБТ тұзақтары\n\n- Құпиясөз нұсқалары: **Nᴸ**. Әр жаңа символ — N есе көп.\n- HTTPS құлыбы сайттың адал екенін білдірмейді.\n- Сол компьютердегі көшірме бопсалаушы бағдарламадан құтқармайды."},
  "net-5-topology": {"ru":"# Виды сетей и топологии\n\n## Сети по охвату\n\n| Сеть | Охват | Пример |\n|---|---|---|\n| PAN | Один человек, несколько метров | Телефон и Bluetooth-наушники |\n| LAN | Комната, школа, дом | Кабинет информатики |\n| MAN | Город | Видеокамеры города |\n| WAN | Страны | Интернет («сеть сетей») |\n\n## Что при поломке\n\n- **Звезда**: обрыв кабеля отключает один компьютер, отказ центра отключает всех.\n- **Шина**: обрыв общего кабеля ломает сеть; на концах терминаторы.\n- **Кольцо** (в одну сторону): любой обрыв останавливает передачу. Двустороннее кольцо переживает один обрыв, два обрыва делят его на две группы.\n- **Дерево**: отказ коммутатора этажа отключает этаж, отказ главного разъединяет этажи.\n- **Полная сетка**: обрыв кабеля не страшен, данные идут в обход; минус — дорого.\n\n## Сколько кабелей\n\n- Звезда и кольцо: n. Полная сетка: n(n − 1) / 2, портов у каждого n − 1. Дерево: устройств − 1.\n- Обратная задача: n(n − 1) / 2 = 28, значит n = 8.\n\n## Архитектуры\n\nКлиент–сервер: единый контроль, копии, много пользователей. Одноранговая: дёшево, до 10 компьютеров.\n\n## Ловушки\n\nWi-Fi не размер сети. В звезде компьютеры не соединены друг с другом. Не забывай делить на 2.","kk":"# Желі түрлері және топологиялар\n\n## Желілердің көлемі\n\n| Желі | Қамту аумағы | Мысал |\n|---|---|---|\n| PAN | Бір адам, бірнеше метр | Телефон және құлаққап |\n| LAN | Бөлме, мектеп, үй | Информатика кабинеті |\n| MAN | Қала | Қаладағы бейнекамералар |\n| WAN | Елдер | Интернет («желілер желісі») |\n\n## Бұзылғанда не болады\n\n- **Жұлдыз**: кабель үзілсе, бір компьютер ажырайды, орталық істен шықса, бәрі ажырайды.\n- **Шина**: ортақ кабель үзілсе, желі бұзылады; шеттерінде терминаторлар.\n- **Сақина** (бір бағытта): кез келген үзіліс беруді тоқтатады. Екі бағытты сақина бір үзілісте жұмыс істейді, екі үзіліс оны екі топқа бөледі.\n- **Ағаш**: қабат коммутаторы істен шықса, қабат ажырайды; басты коммутатор істен шықса, қабаттар ажырасады.\n- **Толық тор**: кабель үзілсе, деректер айналып өтеді; кемшілігі — қымбат.\n\n## Неше кабель\n\n- Жұлдыз және сақина: n. Толық тор: n(n − 1) / 2, әрқайсысында n − 1 порт. Ағаш: құрылғы саны − 1.\n- Кері есеп: n(n − 1) / 2 = 28, демек n = 8.\n\n## Архитектуралар\n\nКлиент–сервер: біртұтас бақылау, көшірмелер, көп пайдаланушы. Бір рангілі: арзан, 10 компьютерге дейін.\n\n## Тұзақтар\n\nWi-Fi — желі көлемі емес. Жұлдызда компьютерлер өзара жалғанбаған. 2-ге бөлуді ұмытпа."},
  "net-6-hardware": {"ru":"# Сетевое оборудование\n\n**Главный вопрос: что устройство соединяет?**\n\n- **Сетевая карта** — в каждом устройстве, у неё заводской **MAC-адрес**: 6 байт = 48 бит (`00-1A-2B-3C-4D-5E`).\n- **Коммутатор** — устройства внутри одной сети; хранит таблицу «порт — MAC» и шлёт данные только адресату. **Хаб** шлёт всем.\n- **Маршрутизатор** — разные сети, шлюз в интернет.\n- **Модем** — переводит сигнал компьютера в сигнал линии связи и обратно.\n- **Точка доступа Wi-Fi** — радио вместо провода: имя сети SSID, защита WPA2/WPA3; 2,4 ГГц дальше, 5 ГГц быстрее.\n- **Провайдер** — даёт доступ в интернет по тарифу.\n\n## Кабели\n\nВитая пара: медь, RJ-45, до 100 м на отрезок. Оптоволокно: свет, километры, нет помех, дороже.\n\n## Расчёты\n\n- Компьютеров на коммутатор: порты − 1 (порт к маршрутизатору).\n- Коммутаторов: n : (порты − 1), округлять **вверх**.\n- Кабелей: устройства + кабели от коммутаторов к маршрутизатору.\n- Мбит/с ÷ 8 = МБ/с.\n\n## Ловушки\n\nКоммутатор ≠ маршрутизатор; модем ≠ роутер; Wi-Fi ≠ интернет; MAC ≠ IP.","kk":"# Желілік жабдықтар\n\n**Басты сұрақ: құрылғы нені жалғайды?**\n\n- **Желілік карта** — әр құрылғыда бар, оның зауыттық **MAC мекенжайы** болады: 6 байт = 48 бит (`00-1A-2B-3C-4D-5E`).\n- **Коммутатор** — бір желі ішіндегі құрылғылар; «порт — MAC» кестесін сақтайды және деректерді тек адресатқа жібереді. **Хаб** бәріне жібереді.\n- **Маршрутизатор** — әртүрлі желілер, интернетке шлюз.\n- **Модем** — компьютер сигналын байланыс желісінің сигналына және кері түрлендіреді.\n- **Wi-Fi қол жеткізу нүктесі** — сымның орнына радио: желі атауы SSID, қорғау WPA2/WPA3; 2,4 ГГц алысқа, 5 ГГц жылдамырақ.\n- **Провайдер** — тариф бойынша интернетке қолжетімділік береді.\n\n## Кабельдер\n\nЕсілген жұп: мыс, RJ-45, бір кесіндіге 100 м-ге дейін. Оптикалық талшық: жарық, километрлер, кедергі жоқ, қымбатырақ.\n\n## Есептеулер\n\n- Бір коммутаторға компьютер саны: порттар − 1 (маршрутизаторға баратын порт).\n- Коммутатор саны: n : (порттар − 1), **жоғары** қарай дөңгелектеу.\n- Кабель саны: құрылғылар + коммутаторлардан маршрутизаторға баратын кабельдер.\n- Мбит/с ÷ 8 = МБ/с.\n\n## Тұзақтар\n\nКоммутатор ≠ маршрутизатор; модем ≠ роутер; Wi-Fi ≠ интернет; MAC ≠ IP."},
  "net-7-protocols": {"ru":"# Протоколы и модель TCP/IP\n\n## Главное\n\n- **Протокол** — договорённость об обмене данными. Файл режут на **пакеты**: в заголовке — IP отправителя и получателя, номер пакета.\n- **TCP/IP — 4 уровня** (сверху вниз): **прикладной** (HTTP, HTTPS, FTP, SMTP, POP3, IMAP, DNS, DHCP), **транспортный** (TCP, UDP, порты), **сетевой** (IP), **канальный** (Wi-Fi, Ethernet). Отправитель идёт вниз, получатель — вверх.\n- **TCP** — надёжно: нумерация, подтверждение, повтор потерянных (веб, почта, файлы). **UDP** — быстро, без гарантий (видеозвонки, игры). **IP** доставляет по адресу, но ничего не гарантирует.\n- **Порт** — число 0…65535 (16 бит): номер программы на устройстве. HTTP 80, HTTPS 443, FTP 21, SMTP 25, POP3 110, IMAP 143, DNS 53.\n- **DHCP** автоматически выдаёт IP, маску, шлюз и DNS-сервер. **DNS** переводит имя в IP.\n\n## Лайфхаки для ЕНТ\n\n- Открываем сайт после подключения к Wi-Fi: **DHCP → DNS → TCP → HTTP(S)**.\n- «Кто следит за потерей пакетов?» — TCP, а не IP.\n- SMTP — отправка писем, POP3 и IMAP — получение.\n- Байты пакета: размер данных плюс заголовок, умножить на число пакетов.","kk":"# Хаттамалар және TCP/IP моделі\n\n## Басты ұғымдар\n\n- **Хаттама** — деректер алмасу келісімі. Файлды **пакеттерге** бөледі: тақырыпта — жіберуші мен алушының IP мекенжайы, пакет нөмірі.\n- **TCP/IP — 4 деңгей** (жоғарыдан төмен): **қолданбалы** (HTTP, HTTPS, FTP, SMTP, POP3, IMAP, DNS, DHCP), **тасымалдау** (TCP, UDP, порттар), **желілік** (IP), **арналық** (Wi-Fi, Ethernet). Жіберуші төмен түседі, алушы жоғары көтеріледі.\n- **TCP** — сенімді: нөмірлеу, растау, жоғалғанды қайталау (веб, пошта, файлдар). **UDP** — жылдам, кепілдіксіз (бейнеқоңыраулар, ойындар). **IP** мекенжай бойынша жеткізеді, бірақ ештеңеге кепілдік бермейді.\n- **Порт** — 0…65535 аралығындағы сан (16 бит): құрылғыдағы программаның нөмірі. HTTP 80, HTTPS 443, FTP 21, SMTP 25, POP3 110, IMAP 143, DNS 53.\n- **DHCP** IP мекенжайды, маска мен шлюзді және DNS серверін автоматты түрде береді. **DNS** атты IP мекенжайға айналдырады.\n\n## ҰБТ-ға арналған кеңестер\n\n- Wi-Fi желісіне қосылғаннан кейін сайтты ашу: **DHCP → DNS → TCP → HTTP(S)**.\n- «Пакеттің жоғалуын кім қадағалайды?» — IP емес, TCP.\n- SMTP — хат жіберу, POP3 және IMAP — хат алу.\n- Пакет байттары: деректер көлемі плюс тақырып, пакеттер санына көбейту."},
  "net-8-mask": {"ru":"# IP-адрес и маска сети\n\n## Сеть и устройство\n- IP-адрес = **номер сети + номер устройства**. Границу задаёт **маска**.\n- В маске 32 бита: сначала **единицы**, потом **нули**. Префикс **/n** — число единиц: /8 = 255.0.0.0, /16 = 255.255.0.0, /24 = 255.255.255.0.\n- Число маски — только 255, 254, 252, 248, 240, 224, 192, 128 или 0. Маски 255.255.250.0 не бывает.\n\n## Расчёты\n- **Адрес сети = IP И маска** (побитово): где в маске 255 — число сохраняется, где 0 — обнуляется, «пограничное» число считаем в двоичном виде.\n- **Широковещательный адрес** — все биты устройства равны 1 (последний в сети). Ему и адресу сети устройства не дают.\n- h = 32 − n бит под устройства: адресов **2ʰ**, устройств **2ʰ − 2**. /24 → 254, /25 → 126, /26 → 62, /27 → 30, /28 → 14, /29 → 6, /30 → 2.\n- Под N устройств: наименьшее h с 2ʰ − 2 ≥ N, префикс 32 − h.\n- Два компьютера в одной сети, если **адреса их сетей (IP И маска) совпадают**.\n\n## IPv6\n- 128 бит: 8 групп по 4 шестнадцатеричные цифры через «:». «::» — серия нулевых групп. Префикс обычно /64.\n\n## Лайфхаки для ЕНТ\n- Не забывай «минус 2».\n- «Пограничное» число — в двоичную систему и И по разрядам.","kk":"# IP мекенжай және желі маскасы\n\n## Желі және құрылғы\n- IP мекенжай = **желі нөмірі + құрылғы нөмірі**. Шекараны **маска** анықтайды.\n- Маскада 32 бит: алдымен **бірлер**, содан кейін **нөлдер**. **/n** префиксі — бірлер саны: /8 = 255.0.0.0, /16 = 255.255.0.0, /24 = 255.255.255.0.\n- Маска саны: 255, 254, 252, 248, 240, 224, 192, 128 немесе 0. 255.255.250.0 маскасы болмайды.\n\n## Есептеулер\n- **Желі мекенжайы = IP ЖӘНЕ маска** (биттер бойынша): 255 тұрған жерде сан сақталады, 0 тұрған жерде нөлге айналады, «шекаралық» санды екілік жүйеде есептейміз.\n- **Тарату мекенжайы** — құрылғының барлық биті 1 (желідегі соңғы). Оны және желі мекенжайын құрылғыларға бермейді.\n- Құрылғыға h = 32 − n бит: мекенжай **2ʰ**, құрылғы **2ʰ − 2**. /24 → 254, /25 → 126, /26 → 62, /27 → 30, /28 → 14, /29 → 6, /30 → 2.\n- N құрылғыға: 2ʰ − 2 ≥ N болатын ең кіші h, префикс 32 − h.\n- Екі компьютер бір желіде, егер **желі мекенжайлары (IP ЖӘНЕ маска) сәйкес болса**.\n\n## IPv6\n- 128 бит: 4 он алтылық цифрдан 8 топ, «:» арқылы. «::» — нөлдік топтардың бір қатары. Префикс әдетте /64.\n\n## ҰБТ-ға арналған кеңестер\n- «Минус 2» дегенді ұмытпа: құрылғы саны 2ʰ − 2.\n- «Шекаралық» санды екілікке аударып, ЖӘНЕ орында."},
  "net-9-malware": {"ru":"# Вредоносные программы\n\n## Как попадают и размножаются\n- **Вирус** — прячется в файле-«хозяине», размножается при его запуске.\n- **Червь** — сам распространяется по сети, человек не нужен.\n- **Троян** — не размножается; человек запускает его, приняв за полезную программу.\n\n## Что делают\n- **Шпион (кейлоггер)** — записывает клавиши и пароли.\n- **Вымогатель** — шифрует файлы, требует выкуп.\n- **Рекламное ПО** — навязчивая реклама.\n- **Ботнет** — заражённые компьютеры под чужим управлением (DDoS, спам).\n\n## Защита слоями\nОбновления (закрывают уязвимости), антивирус (сигнатуры + поведение, карантин), брандмауэр, резервные копии по правилу **3-2-1**: 3 копии, 2 носителя, 1 отдельно.\n\n## Социальная инженерия\nФишинг, вишинг, приманка. Признаки: срочность, страх, награда, просьба о коде. Код из SMS не сообщаем никому.\n\n## Расчёты и ловушки ЕНТ\n- Рост заражения: **(1 + k)ᵗ**.\n- Адрес: хост — между https:// и следующей «/», читаем справа налево, домен — две последние части.\n- Копия на всегда подключённом диске от вымогателя не спасёт.","kk":"# Зиянды программалар\n\n## Қалай түседі және көбейеді\n- **Вирус** — «қожайын» файлда жасырынады, файл іске қосылғанда көбейеді.\n- **Құрт** — желі арқылы өзі таралады, адам керек емес.\n- **Троян** — көбеймейді; адам оны пайдалы программа деп ойлап іске қосады.\n\n## Не істейді\n- **Тыңшы (кейлоггер)** — пернелер мен құпиясөздерді жазады.\n- **Бопсалаушы** — файлдарды шифрлап, төлем талап етеді.\n- **Жарнамалық программа** — үнемі шығатын жарнама.\n- **Ботнет** — бөтен адам басқаратын залалданған компьютерлер (DDoS, спам).\n\n## Қабатты қорғаныс\nЖаңартулар (осалдықтарды жабады), антивирус (сигнатуралар + мінез-құлық, карантин), брандмауэр, **3-2-1** ережесі бойынша резервтік көшірмелер: 3 көшірме, 2 тасығыш, 1 бөлек.\n\n## Әлеуметтік инженерия\nФишинг, вишинг, жем. Белгілері: асығыстық, қорқыныш, сыйлық, кодты сұрау. SMS-тегі кодты ешкімге айтпаймыз.\n\n## Есептеулер және ҰБТ тұзақтары\n- Залалдану өсімі: **(1 + k)ᵗ**.\n- Мекенжай: хост — https:// мен келесі «/» арасы, оңнан солға оқимыз, домен — соңғы екі бөлік.\n- Үнемі қосулы дисктегі көшірме бопсалаушыдан құтқармайды."},
  "ns-5-oct-hex": {"ru":"# Восьмеричная и шестнадцатеричная системы\n\n## Цифры\n- **8-я:** 0–7, одна цифра = **3 бита** (5₈ = 101, 1₈ = 001).\n- **16-я:** 0–9 и A–F (A = 10 … F = 15), одна цифра = **4 бита** (3₁₆ = 0011, B₁₆ = 1011).\n\n## Алгоритмы\n**2 → 8 / 2 → 16:** режь на группы по 3 / по 4 бита **справа налево**, слева допиши нули, замени каждую группу цифрой.\n\n> 1101011₂ → 001 101 011 → **153₈**; 0110 1011 → **6B₁₆**\n\n**8 → 2 / 16 → 2:** замени каждую цифру тройкой / четвёркой бит **с нулями слева**, лишние нули в начале числа убери.\n\n> 205₈ → 010 000 101 → **10000101₂**; 4B₁₆ → 0100 1011 → **1001011₂**\n\n**8 ↔ 16:** через двоичную: 205₈ → 10000101₂ → **85₁₆**.\n\n## Лайфхаки для ЕНТ\n- Среди ответов часто есть вариант с группами, взятыми **слева**, — он неверный.\n- Проверка по весам: 6B₁₆ = 6 · 16 + 11 = 107.\n\n## Частые ошибки\n- Группы режутся слева, а не справа.\n- Потеряны нули внутри числа: 205₈ → 100101 вместо 10000101.\n- B прочитана как «11» (две цифры); цифры 8 и 9 в восьмеричной записи.","kk":"# Сегіздік және он алтылық жүйелер\n\n## Цифрлар\n- **Сегіздік:** 0–7, бір цифр = **3 бит** (5₈ = 101, 1₈ = 001).\n- **Он алтылық:** 0–9 және A–F (A = 10 … F = 15), бір цифр = **4 бит** (3₁₆ = 0011, B₁₆ = 1011).\n\n## Алгоритмдер\n**2 → 8 / 2 → 16:** **оңнан солға қарай** 3 / 4 биттен топтарға бөл, сол жағына нөл жаз, әр топты цифрмен ауыстыр.\n\n> 1101011₂ → 001 101 011 → **153₈**; 0110 1011 → **6B₁₆**\n\n**8 → 2 / 16 → 2:** әр цифрды үш / төрт бит тобымен **сол жағындағы нөлдермен** ауыстыр, санның басындағы артық нөлдерді алып таста.\n\n> 205₈ → 010 000 101 → **10000101₂**; 4B₁₆ → 0100 1011 → **1001011₂**\n\n**8 ↔ 16:** екілік арқылы: 205₈ → 10000101₂ → **85₁₆**.\n\n## ҰБТ-ға арналған кеңестер\n- Жауаптар арасында топтары **сол жақтан** алынған нұсқа жиі кездеседі — ол қате.\n- Салмақ бойынша тексеру: 6B₁₆ = 6 · 16 + 11 = 107.\n\n## Жиі кететін қателер\n- Топтар оңнан емес, солдан бөлінеді.\n- Санның ішіндегі нөлдер жоғалады: 205₈ → 10000101 орнына 100101.\n- B «11» деп оқылады (екі цифр); сегіздік жазбада 8 және 9 цифрлары."},
  "ns-6-any-base": {"ru":"# Любая система счисления (q ↔ 10)\n\n## Основание и цифры\n\n- **Основание** — количество цифр в системе. Цифры идут **от 0 до q − 1**.\n- Вес разряда — степень основания: …, q³, q², q¹, q⁰ = 1 (справа налево).\n\n## q → 10: развёрнутая форма\n\n> 213₄ = 2·4² + 1·4¹ + 3·4⁰ = 32 + 4 + 3 = **39**\n\n## 10 → q: лесенка\n\nДели на основание, пока частное не станет 0. Остатки читай **снизу вверх**. Остаток 10 и больше пиши буквой: 10 = A, 11 = B…\n\n> 39 → 213₄; 250 → 18A₁₂\n\n## Лайфхаки для ЕНТ\n\n- Числа из разных систем сравнивай в **десятичной**.\n- Наименьшее основание для записи = **наибольшая цифра + 1**.\n- Ищешь основание x: запиши развёрнутую форму и составь уравнение; при трёх цифрах пробуй x = наибольшая цифра + 1, +2…\n- Запись оканчивается на 0 — число делится на основание.\n\n## Частые ошибки\n\n- В записи цифра, не меньшая основания (5 в троичной системе).\n- Остатки прочитаны **сверху вниз**.\n- Степени начаты с 1, а не с 0: у правой цифры вес 1.\n- Числа из разных систем сравнены «на глаз».","kk":"# Кез келген санау жүйесі (q ↔ 10)\n\n## Негіз және цифрлар\n\n- **Негіз** — жүйедегі цифрлар саны. Цифрлар **0-ден q − 1-ге дейін** болады.\n- Разряд салмағы — негіздің дәрежесі: …, q³, q², q¹, q⁰ = 1 (оңнан солға қарай).\n\n## q → 10: жайылған түрі\n\n> 213₄ = 2·4² + 1·4¹ + 3·4⁰ = 32 + 4 + 3 = **39**\n\n## 10 → q: баспалдақ\n\nБөлінді 0 болғанша негізге бөл. Қалдықтарды **төменнен жоғары** оқы. 10 және одан үлкен қалдықты әріппен жаз: 10 = A, 11 = B…\n\n> 39 → 213₄; 250 → 18A₁₂\n\n## ҰБТ-ға арналған кеңестер\n\n- Әртүрлі жүйедегі сандарды **ондық** жүйеде салыстыр.\n- Жазбаның ең кіші негізі = **ең үлкен цифр + 1**.\n- x негізін іздесең: жайылған түрін жазып, теңдеу құр; үш цифр болса, x = ең үлкен цифр + 1, +2… мәндерін сына.\n- Жазба 0-мен аяқталса — сан негізге бөлінеді.\n\n## Жиі кететін қателер\n\n- Жазбада негізден кіші емес цифр бар (үштік жүйеде 5).\n- Қалдықтар **жоғарыдан төмен** оқылған.\n- Дәрежелер 0-ден емес, 1-ден басталған: оң жақ цифрдың салмағы 1.\n- Әртүрлі жүйедегі сандар «көзбен» салыстырылған."},
  "ns-7-arith": {"ru":"# Арифметика в двоичной системе\n\n## Сложение столбиком\nЧисла — по правому краю, считаем справа налево:\n\n- 0 + 0 = 0, 0 + 1 = 1\n- 1 + 1 = 10₂ → пишем 0, 1 переносим\n- 1 + 1 + 1 = 11₂ → пишем 1, 1 переносим\n\nПоследний перенос даёт новую старшую цифру: 111₂ + 1₂ = 1000₂.\n\n## Вычитание\nЕсли сверху цифра меньше, занимаем 1 у соседа слева: она стоит 2 (10₂). Пример: 1010₂ − 11₂ = 111₂.\n\n## Сдвиг\n- · 2ᵏ — приписать справа k нулей;\n- : 2ᵏ нацело — отбросить k последних цифр (они и есть остаток).\n\n## Другие системы\nПеренос — когда сумма достигла основания: при 8 (восьмеричная) или 16 (шестнадцатеричная).\n\n## Лайфхаки для ЕНТ\n- Проверяй в десятичной системе: переведи слагаемые и результат.\n- Считай единицы в самой **сумме**, а не в слагаемых.\n- Ответ нужен в 8-й или 16-й? Сложи в двоичной, потом группируй по 3 или 4 бита справа налево.\n\n## Частые ошибки\n- Написана цифра 2 (1 + 1 = 2).\n- Потерян перенос или последний перенос.\n- Числа из разных систем сложены «как есть».","kk":"# Екілік жүйедегі арифметика\n\n## Бағанмен қосу\nСандар — оң жақ шетінен теңдеп, оңнан солға қарай есептейміз:\n\n- 0 + 0 = 0, 0 + 1 = 1\n- 1 + 1 = 10₂ → 0 жазамыз, 1 ауысады\n- 1 + 1 + 1 = 11₂ → 1 жазамыз, 1 ауысады\n\nСоңғы ауысу сол жақта жаңа цифр береді: 111₂ + 1₂ = 1000₂.\n\n## Азайту\nҮстіндегі цифр кіші болса, сол жақтағы көршіден 1 қарыз аламыз: ол 2 (10₂) тұрады. Мысалы: 1010₂ − 11₂ = 111₂.\n\n## Жылжыту\n- · 2ᵏ — оң жаққа k нөл жазу;\n- : 2ᵏ бүтін бөлу — соңғы k цифрды алып тастау (олар қалдық болады).\n\n## Басқа жүйелер\nҚосынды негізге жеткенде ауысу болады: 8-де (сегіздік) немесе 16-да (он алтылық).\n\n## ҰБТ-ға арналған кеңестер\n- Ондық жүйеде тексер: қосылғыштарды және нәтижені аудар.\n- Бірліктерді қосылғыштардан емес, **қосындының** өзінен сана.\n- Жауап сегіздік немесе он алтылық жүйеде керек пе? Екілікте қосып, содан кейін оңнан солға қарай 3 немесе 4 биттен топта.\n\n## Жиі кететін қателер\n- 2 цифры жазылған (1 + 1 = 2).\n- Ауысу немесе соңғы ауысу жоғалған.\n- Әртүрлі жүйедегі сандар «сол қалпында» қосылған."},
  "ns-8-compare": {"ru":"# Сравнение чисел в разных системах\n\n## Главное правило\n\nЧисла с разными основаниями по записи **не сравнивают**. Сначала — одна система, потом сравнение.\n\n## Два способа\n\n- **В десятичную** (всегда работает): цифра · вес, сумма. 101101₂ = 45, 57₈ = 47, 2E₁₆ = 46 → наибольшее 57₈.\n- **В двоичную** (для 2, 8, 16): цифра → 3 бита (8-я) или 4 бита (16-я), нули слева убрать, сравнить слева направо. 175₈ = 1111101₂ > 1111100₂ = 7C₁₆.\n\n## Одна система — без перевода\n\nБольше цифр (без нулей слева) — больше число. Цифр поровну — первая разная цифра слева. 1F₁₆ < 20₁₆.\n\n## Сколько целых X между a и b\n\n- a < X < b → b − a − 1\n- одна граница входит → b − a\n- a ≤ X ≤ b → b − a + 1\n\n## Ловушки ЕНТ\n\n- **10 в системе q равно q**: 10₂ = 2, 10₈ = 8, 10₁₆ = 16.\n- Числа могут быть **равны**: 1111₂ = 17₈ = F₁₆ = 15.\n- Самая длинная запись не обязана быть наибольшим числом.\n- Нули слева не меняют значение; буква — цифра (A = 10 … F = 15).","kk":"# Әртүрлі жүйедегі сандарды салыстыру\n\n## Басты ереже\n\nНегіздері әртүрлі сандарды жазбасы бойынша **салыстырмайды**. Алдымен — бір жүйе, содан кейін салыстыру.\n\n## Екі тәсіл\n\n- **Ондыққа** (әрқашан жұмыс істейді): цифр · салмақ, қосынды. 101101₂ = 45, 57₈ = 47, 2E₁₆ = 46 → ең үлкені 57₈.\n- **Екілікке** (2, 8, 16 үшін): цифр → 3 бит (сегіздік) немесе 4 бит (он алтылық), сол жақтағы нөлдерді алып тастап, солдан оңға салыстыр. 175₈ = 1111101₂ > 1111100₂ = 7C₁₆.\n\n## Бір жүйе — аудармай\n\nЦифры көп (сол жақтағы нөлсіз) сан үлкен. Цифр саны тең болса — солдан бірінші әртүрлі цифр. 1F₁₆ < 20₁₆.\n\n## a және b арасындағы бүтін X саны\n\n- a < X < b → b − a − 1\n- бір шек кіреді → b − a\n- a ≤ X ≤ b → b − a + 1\n\n## ҰБТ тұзақтары\n\n- **q жүйесіндегі 10 — q**: 10₂ = 2, 10₈ = 8, 10₁₆ = 16.\n- Сандар **тең** болуы мүмкін: 1111₂ = 17₈ = F₁₆ = 15.\n- Ең ұзын жазба ең үлкен сан болуы міндетті емес.\n- Сол жақтағы нөлдер мәнді өзгертпейді; әріп — цифр (A = 10 … F = 15)."},
  "ns-9-count": {"ru":"# Сколько единиц в двоичной записи\n\nСчитаем **без перевода**: сначала всё приводим к степеням двойки.\n\n| Число | Запись | Единиц | Нулей |\n|---|---|---|---|\n| 2ⁿ | 1 и n нулей | 1 | n |\n| 2ⁿ − 1 | одни единицы | n | 0 |\n| 2ⁿ − 2ᵐ (n > m) | n − m единиц, затем m нулей | n − m | m |\n| 2ⁿ + 2ᵐ − 1 (n > m) | 1, нули, m единиц | 1 + m | n − m |\n| сумма разных степеней | по единице на слагаемое | число слагаемых | цифр − единиц |\n\n## Приведение к основанию 2\n4ᵏ = 2²ᵏ, 8ᵏ = 2³ᵏ, 16ᵏ = 2⁴ᵏ — показатели **умножаются**: 4⁵ = 2¹⁰.\n\n## Лайфхаки для ЕНТ\n- Приведи слагаемые к 2ⁿ и выпиши показатели: **одинаковые склеиваются** (2ⁿ + 2ⁿ = 2ⁿ⁺¹; три одинаковых — две единицы).\n- Цифр = старший показатель + 1; нулей = цифр − единиц.\n- 2ⁿ − k = (2ⁿ − 1) − (k − 1): единицы пропадают там, где у k − 1 стоит 1.\n- 4²⁰ + 2¹⁰ − 1 = 2⁴⁰ + (2¹⁰ − 1): 11 единиц, 30 нулей, 41 цифра.\n- В Python bin(n)[2:] — запись без приставки 0b.\n\n## Частые ошибки\n- Не заметить склеивание одинаковых степеней.\n- Оставить показатель у 4ᵏ как есть (4⁵ ≠ 2⁵).\n- Перепутать n − m (единицы) и m (нули) у 2ⁿ − 2ᵐ.","kk":"# Екілік жазбада неше бірлік бар\n\n**Аудармай-ақ** санаймыз: алдымен бәрін екінің дәрежелеріне келтіреміз.\n\n| Сан | Жазба | Бірлік | Нөл |\n|---|---|---|---|\n| 2ⁿ | 1 және n нөл | 1 | n |\n| 2ⁿ − 1 | тек бірліктер | n | 0 |\n| 2ⁿ − 2ᵐ (n > m) | n − m бірлік, сосын m нөл | n − m | m |\n| 2ⁿ + 2ᵐ − 1 (n > m) | 1, нөлдер, m бірлік | 1 + m | n − m |\n| әртүрлі дәрежелердің қосындысы | әр қосылғышқа бір бірлік | қосылғыш саны | цифр − бірлік |\n\n## Негізі 2 болатын дәрежеге келтіру\n4ᵏ = 2²ᵏ, 8ᵏ = 2³ᵏ, 16ᵏ = 2⁴ᵏ — көрсеткіштер **көбейтіледі**: 4⁵ = 2¹⁰.\n\n## ҰБТ-ға арналған кеңестер\n- Қосылғыштарды 2ⁿ түріне келтіріп, көрсеткіштерді жаз: **бірдейлері бірігеді** (2ⁿ + 2ⁿ = 2ⁿ⁺¹; үш бірдей — екі бірлік).\n- Цифр = ең үлкен көрсеткіш + 1; нөл = цифр − бірлік.\n- 2ⁿ − k = (2ⁿ − 1) − (k − 1): бірліктер k − 1 санында 1 тұрған жерде жоғалады.\n- 4²⁰ + 2¹⁰ − 1 = 2⁴⁰ + (2¹⁰ − 1): 11 бірлік, 30 нөл, 41 цифр.\n- Python-да bin(n)[2:] — 0b префиксінсіз жазба.\n\n## Жиі кететін қателер\n- Бірдей дәрежелердің бірігуін байқамау.\n- 4ᵏ көрсеткішін сол күйінде қалдыру (4⁵ ≠ 2⁵).\n- 2ⁿ − 2ᵐ санында n − m (бірлік) пен m (нөл) шатастыру."},
  "pc-1-devices": {"ru":"# Устройства компьютера\n\n## Четыре действия\n\n**Ввод** (в компьютер) → **обработка** (процессор) → **вывод** (из компьютера). **Хранение** — запись данных в память.\n\n## Группы устройств\n\n- **Ввод:** клавиатура, мышь, сенсорная панель, сканер, микрофон, веб-камера, джойстик, графический планшет, датчики.\n- **Вывод:** монитор, принтер, колонки, наушники, проектор, плоттер.\n- **Ввод-вывод:** сенсорный экран, модем, сетевая карта, гарнитура.\n- **Хранение:** HDD, SSD, флешка, CD/DVD, облако.\n\n## Принтеры\n\n- **Матричный** — иголки и красящая лента, делает копии через копирку.\n- **Струйный** — микрокапли чернил, цветные фото.\n- **Лазерный** — лазер и тонер, быстро и чётко.\n\n## Лайфхаки для ЕНТ\n\n- Спроси: информация идёт **в** компьютер или **из** него? В обе стороны — ввод-вывод.\n- **SSD** и флешка — **без движущихся частей**, HDD — вращающиеся магнитные пластины.\n- Единицы: разрешение монитора — пиксели, принтера и сканера — **dpi**, накопителя — Гбайт.\n\n## Частые ошибки\n\n- Сканер принимают за вывод, а принтер за ввод: наоборот.\n- Наушники без микрофона считают устройством ввода-вывода: это только вывод.","kk":"# Компьютердің құрылғылары\n\n## Төрт әрекет\n\n**Енгізу** (компьютерге) → **өңдеу** (процессор) → **шығару** (компьютерден). **Сақтау** — деректерді жадқа жазу.\n\n## Құрылғы топтары\n\n- **Енгізу:** пернетақта, тінтуір, сенсорлық тақта, сканер, микрофон, веб-камера, джойстик, графикалық планшет, датчиктер.\n- **Шығару:** монитор, принтер, колонкалар, құлаққап, проектор, плоттер.\n- **Енгізу-шығару:** сенсорлық экран, модем, желілік карта, гарнитура.\n- **Сақтау:** HDD, SSD, флешка, CD/DVD, бұлт.\n\n## Принтерлер\n\n- **Матрицалық** — инелер мен бояу таспасы, көшірме қағазбен көшірме жасайды.\n- **Сиялы** — сияның микротамшылары, түрлі-түсті фото.\n- **Лазерлік** — лазер және тонер, жылдам әрі анық.\n\n## ҰБТ-ға арналған кеңестер\n\n- Сұра: ақпарат компьютерге **кіре** ме, әлде одан **шыға** ма? Екі жаққа да жүрсе — енгізу-шығару.\n- **SSD** және флешка — **қозғалмалы бөлшексіз**, HDD — айналатын магниттік пластиналар.\n- Бірліктер: монитордың ажыратымдылығы — пиксель, принтер мен сканердікі — **dpi**, жинақтауыштыкі — Гбайт.\n\n## Жиі кететін қателер\n\n- Сканерді шығару, принтерді енгізу деп қателеседі: керісінше.\n- Микрофонсыз құлаққапты енгізу-шығару құрылғысы деп санайды: бұл тек шығару."},
  "pc-2-cpu": {"ru":"# Процессор и память\n\n## Процессор (CPU)\n- **АЛУ** — считает и сравнивает.\n- **Устройство управления** — читает команды и руководит их выполнением.\n- **Регистры** — сверхбыстрая память внутри процессора.\n- **Тактовая частота** — в ГГц (1 ГГц = миллиард тактов в секунду), **ядра** — несколько процессоров в одном, **разрядность** — сколько бит за раз (32, 64).\n- Цикл команды: **выборка → декодирование → выполнение → запись**, и по кругу.\n\n## Память\nБыстрее, меньше и дороже — ближе к процессору: **регистры → кэш (L1–L3) → ОЗУ → внешняя память**.\n- **Кэш** — быстрая память между процессором и ОЗУ.\n- **Регистры, кэш и ОЗУ стираются** при выключении.\n- **ПЗУ** (BIOS/UEFI), HDD, SSD, флешка — **сохраняют** данные.\n- Как выглядят: ОЗУ — длинная планка с чипами, SSD — плата, HDD — коробка с пластиной.\n\n## Шины и адреса\nШины: **данных**, **адреса**, **управления**. Шина адреса из k разрядов даёт **2ᵏ** ячеек (1 ячейка = 1 байт).\n- 2¹⁰ = 1 Кбайт, 2²⁰ = 1 Мбайт, 2³⁰ = 1 Гбайт, **2³² = 4 Гбайт**.\n\n## Принципы фон Неймана\nДвоичное кодирование, программное управление, **однородность памяти** (программы и данные в одной памяти), адресность.\n\n## Частые ошибки\n- Путать ОЗУ с диском: программа лежит на диске, а работает в ОЗУ.\n- Думать, что 32-разрядная шина адресует 32 Гбайт: на самом деле 4 Гбайт.","kk":"# Процессор және жад\n\n## Процессор (CPU)\n- **АЛҚ** — есептейді және салыстырады.\n- **Басқару құрылғысы** — командалардың орындалуын басқарады.\n- **Регистрлер** — процессордың ішіндегі өте жылдам жад.\n- **Тактілік жиілік** — ГГц-пен (1 ГГц = секундына миллиард такт), **ядролар** — бір процессордағы бірнеше процессор, **разрядтылық** — бір мезгілде неше бит.\n- Команда циклі: **алу → декодтау → орындау → жазу**, сосын қайтадан басынан.\n\n## Жад\nПроцессорға жақын сайын жылдам, аз әрі қымбат: **регистрлер → кэш (L1–L3) → жедел жад → сыртқы жад**.\n- **Кэш** — процессор мен жедел жад арасындағы жылдам жад.\n- **Регистрлер, кэш және жедел жад өшірілгенде жойылады**.\n- **Тұрақты жад** (BIOS/UEFI), HDD, SSD, флешка деректерді **сақтайды**.\n- Қандай көрінеді: жедел жад — чиптері бар ұзын планка, SSD — тақша, HDD — пластинасы бар қорап.\n\n## Шиналар және мекенжайлар\nШиналар: **деректер**, **мекенжай**, **басқару**. k разрядты мекенжай шинасы **2ᵏ** ұяшық береді (1 ұяшық = 1 байт).\n- 2¹⁰ = 1 Кбайт, 2²⁰ = 1 Мбайт, 2³⁰ = 1 Гбайт, **2³² = 4 Гбайт**.\n\n## Фон Нейман принциптері\nЕкілік кодтау, программалық басқару, **жад біртектілігі** (программалар мен деректер бір жадта), мекенжайлылық.\n\n## Жиі кететін қателер\n- Жедел жадты дискімен шатастыру: программа дискіде тұрады, жұмыс кезінде жедел жадта болады.\n- 32 разрядты шина 32 Гбайт мекенжайлайды деп ойлау: дұрысы — 4 Гбайт."},
  "pc-3-software": {"ru":"# Программное обеспечение\n\n## Три вида ПО\n- **Системное** — для компьютера: ОС (Windows, Linux, macOS, Android, iOS), драйверы, утилиты (антивирус, архиватор).\n- **Прикладное** — для человека: Word, Excel, браузер, игры, Paint, СУБД.\n- **Инструментальное** — для программиста: компилятор, интерпретатор Python, отладчик, IDE.\n\nОС делает три дела: управляет ресурсами, управляет файлами, даёт интерфейс. Где есть процессор (телефон, банкомат, машина, часы), там есть ОС и программы.\n\n## Файлы\n- Имя файла = **имя.расширение**: `report.docx`.\n- Путь идёт от корня до файла: `C:\\Users\\Ali\\Docs\\report.docx`.\n- **Переместили** — старый путь исчез. **Скопировали** — остались оба.\n\n## Маски\n- `*` — любое количество символов (и ноль), `?` — ровно один.\n- Маска сверяется со **всем** именем, вместе с расширением.\n\n## Лицензии и архивы\n- Платное, freeware, shareware, свободное (open source, GPL). **Бесплатное — не значит свободное.**\n- Без потерь: ZIP, RAR, 7z. С потерями: JPEG, MP3.\n- Коэффициент сжатия = размер до : размер после.\n\n## Лайфхаки для ЕНТ\n- Вид ПО определяй вопросом «для кого программа?».\n- В маске проверяй имя по частям: начало, конец, длина.\n\n## Частые ошибки\n- Антивирус и архиватор считают прикладными, а они системные.\n- `?` читают как «сколько угодно», а это ровно один символ.","kk":"# Программалық қамтамасыз ету\n\n## ПҚ-ның үш түрі\n- **Жүйелік** — компьютер үшін: ОЖ (Windows, Linux, macOS, Android, iOS), драйверлер, утилиталар (антивирус, архиватор).\n- **Қолданбалы** — адам үшін: Word, Excel, браузер, ойындар, Paint, ДҚБЖ.\n- **Құралдық (аспаптық)** — программалаушы үшін: компилятор, Python интерпретаторы, түзеткіш (отладчик), IDE.\n\nОЖ үш іс атқарады: ресурстарды басқарады, файлдарды басқарады, интерфейс береді. Процессор бар жерде (телефон, банкомат, көлік, сағат) ОЖ мен программалар бар.\n\n## Файлдар\n- Файл аты = **аты.кеңейтілім**: `report.docx`.\n- Жол түбірден файлға дейін жүреді: `C:\\Users\\Ali\\Docs\\report.docx`.\n- **Жылжытылса** — ескі жол жоғалады. **Көшірілсе** — екеуі де қалады.\n\n## Маскалар\n- `*` — таңбалардың кез келген саны (нөл де), `?` — дәл бір таңба.\n- Маска файл атымен **толық**, кеңейтілімімен бірге салыстырылады.\n\n## Лицензиялар және архивтер\n- Ақылы, freeware, shareware, еркін (open source, GPL). **Тегін дегеніміз еркін дегенді білдірмейді.**\n- Шығынсыз: ZIP, RAR, 7z. Шығынмен: JPEG, MP3.\n- Сығу коэффициенті = сығуға дейінгі көлем : сығудан кейінгі көлем.\n\n## ҰБТ-ға арналған кеңестер\n- ПҚ түрін «программа кім үшін?» деген сұрақпен анықта.\n- Маскада атты бөліктермен тексер: басы, соңы, ұзындығы.\n\n## Жиі кететін қателер\n- Антивирус пен архиваторды қолданбалы деп санайды, ал олар жүйелік.\n- `?` белгісін «қанша болса да» деп оқиды, ал ол дәл бір таңба."},
  "pc-4-neumann": {"ru":"# Принципы фон Неймана и магистраль\n\n## Четыре принципа (1945)\n- **Двоичное кодирование** — всё записано нулями и единицами.\n- **Программное управление** — команды выполняются автоматически, по порядку.\n- **Однородность памяти** — программы и данные в одной памяти и записаны одинаково: по записи команду от числа не отличить.\n- **Адресность** — память состоит из пронумерованных ячеек.\n\n## Регистры\n- **Счётчик команд** — адрес следующей команды; **регистр команды** — выполняемая команда; **аккумулятор** — промежуточный результат.\n- Команда = **что делать** + **над чем** (адрес ячейки).\n\n## Магистраль\n- **Шина адреса** — номер ячейки, в одну сторону. **Шина данных** — числа и команды, в обе стороны. **Шина управления** — сигналы «читать», «записать».\n- n разрядов адреса: **N = 2ⁿ** ячеек. 2¹⁰ = 1 Кбайт, 2²⁰ = 1 Мбайт, 2³⁰ = 1 Гбайт, 2³² = 4 Гбайт.\n- Ширина шины данных — бит за одно обращение.\n\n## Лайфхаки для ЕНТ\n- От a до b включительно: b − a + 1 ячеек; последний адрес — N − 1.\n- Объём не степень двойки: разряды округляй вверх.\n- Объём памяти задаёт только шина адреса.\n\n## Частые ошибки\n- Путать шины; читать «32 разряда» как «32 Гбайт» (на деле 4).","kk":"# Фон Нейман принциптері және магистраль\n\n## Төрт принцип (1945)\n- **Екілік кодтау** — бәрі нөлдер мен бірлермен жазылады.\n- **Программалық басқару** — командалар өздігінен, ретімен орындалады.\n- **Жад біртектілігі** — программа мен деректер бір жадта: жазуына қарап команданы саннан ажыратуға болмайды.\n- **Мекенжайлылық** — жад нөмірленген ұяшықтардан тұрады.\n\n## Регистрлер\n- **Команда санауышы** — келесі команданың мекенжайы; **команда регистрі** — орындалып жатқан команда; **аккумулятор** — аралық нәтиже.\n- Команда = **не істеу** + **нені** (ұяшық мекенжайы).\n\n## Магистраль\n- **Мекенжай шинасы** — ұяшық нөмірі, бір бағытта. **Деректер шинасы** — сандар мен командалар, екі бағытта. **Басқару шинасы** — «оқы», «жаз» сигналдары.\n- Мекенжайдың n разряды: **N = 2ⁿ** ұяшық. 2¹⁰ = 1 Кбайт, 2²⁰ = 1 Мбайт, 2³⁰ = 1 Гбайт, 2³² = 4 Гбайт.\n- Деректер шинасының разрядтылығы — бір жүгінудегі бит.\n\n## ҰБТ лайфхактары\n- a мен b аралығы (шеттері кіреді): b − a + 1 ұяшық; соңғы мекенжай — N − 1.\n- Көлем екінің дәрежесі емес болса: разрядты жоғары дөңгелекте.\n- Жад көлемін тек мекенжай шинасы белгілейді.\n\n## Жиі кететін қателер\n- Шиналарды шатастыру; «32 разряд» — «32 Гбайт» емес (4 Гбайт)."},
  "pc-5-memory": {"ru":"# Виды памяти\n\n## Лесенка в цифрах\nБлиже к процессору: **быстрее, меньше и дороже**. Регистры (< 1 нс) → кэш L1 (≈ 1 нс, десятки КБ) → L2 → L3 (10–20 нс, десятки МБ) → ОЗУ (50–100 нс, ГБ) → SSD (≈ 0,1 мс) → HDD (5–10 мс, ТБ) → облако.\n\n## Кэш и ОЗУ\n- Кэш: L1 самый быстрый и маленький (у каждого ядра), L3 самый большой (общий). Поиск: L1 → L2 → L3 → ОЗУ. **Попадание** — нашли в кэше, **промах** — идём в ОЗУ.\n- Кэш = **SRAM** (быстрая, дорогая), ОЗУ = **DRAM** (конденсаторы, нужна регенерация). Обе стираются без тока.\n\n## ПЗУ, флеш, диски\n- **ПЗУ**: UEFI/BIOS, не стирается. **CMOS** хранит время и настройки (батарейка).\n- **Флеш** (SSD, флешка, microSD): заряд в ячейках, без питания держится, число перезаписей ограничено. **HDD**: магнитные пластины, дешевле за ГБ.\n\n## Загрузка\nПЗУ (UEFI) → POST → загрузочный диск → загрузчик → ядро ОС копируется в ОЗУ → драйверы и рабочий стол.\n\n## Формулы\nЦена за ГБ = цена : объём (1 ТБ = 1024 ГБ). Время = объём : скорость. Время с кэшем = попадания · t₁ + промахи · t₂.\n\n## Частые ошибки\n- ОС лежит на накопителе, а работает в ОЗУ.\n- ПЗУ на экзамене — программа запуска, а не «память телефона».","kk":"# Жад түрлері\n\n## Баспалдақ сандармен\nПроцессорға жақын сайын **жылдамырақ, кішірек, қымбатырақ**. Регистрлер (< 1 нс) → L1 кэші (≈ 1 нс, ондаған КБ) → L2 → L3 (10–20 нс, ондаған МБ) → жедел жад (50–100 нс, ГБ) → SSD (≈ 0,1 мс) → HDD (5–10 мс, ТБ) → бұлт.\n\n## Кэш және жедел жад\n- Кэш: L1 ең жылдам әрі кіші (әр ядрода), L3 ең үлкен (ортақ). Іздеу: L1 → L2 → L3 → жедел жад. **Табылу** — кэштен таптық, **табылмау** — кэште жоқ, жедел жадқа барамыз.\n- Кэш = **SRAM** (жылдам, қымбат), жедел жад = **DRAM** (конденсаторлар, регенерация керек). Екеуі де токсыз өшеді.\n\n## Тұрақты жад, флеш, дискілер\n- **Тұрақты жад**: UEFI/BIOS, жойылмайды. **CMOS**: уақыт пен параметрлер (батарейка).\n- **Флеш** (SSD, флешка, microSD): ұяшықтағы заряд, қуатсыз тұрады, қайта жазу саны шектеулі. **HDD**: магнит пластиналар, 1 ГБ арзан.\n\n## Жүктеу\nТұрақты жад (UEFI) → POST → жүктеу дискісі → жүктегіш → ОЖ ядросы жедел жадқа → драйверлер, жұмыс үстелі.\n\n## Формулалар\n1 ГБ бағасы = баға : көлем (1 ТБ = 1024 ГБ). Уақыт = көлем : жылдамдық. Кэшпен: табылғандар · t₁ + табылмағандар · t₂.\n\n## Жиі кететін қателер\n- ОЖ жинақтауышта тұрады, жедел жадта жұмыс істейді.\n- Емтиханда тұрақты жад — іске қосу программасы, телефон жады емес."},
  "pc-6-os": {"ru":"# Операционные системы и файловые системы\n\n## Из чего состоит ОС\n- **Ядро** делит процессор и память, запускает программы, следит за файлами.\n- **Драйвер** — программа-переводчик для одного устройства.\n- **Интерфейс**: GUI (окна) и CLI (команды: cd, dir / ls, copy / cp, del / rm; с масками: dir *.txt).\n- **Многозадачность**: ОС по кругу даёт процессам кванты времени. Зависшую программу закрывают в Диспетчере задач (Ctrl + Shift + Esc).\n\n## Файловая система\n- FAT32 — флешки, файл не больше 4 ГБ; exFAT — большие файлы; NTFS — Windows; ext4 — Linux; APFS — Apple.\n- Файл занимает целое число **кластеров**: место на диске = ⌈размер : кластер⌉ · кластер.\n- Форматирование создаёт файловую систему и стирает файлы.\n\n## Путь\n- Абсолютный — от корня, относительный — от текущей папки: `.` — текущая, `..` — на уровень выше.\n- Windows: `\\` и диски C:, D:. Linux: `/`, регистр важен.\n- В имени файла Windows нельзя: \\ / : * ? \" < > |\n\n## Лайфхаки ЕНТ\n- Файл не копируется? Проверь место и предел файловой системы.\n- Место на диске считай по кластерам, округляя вверх.\n\n## Частые ошибки\n- Файл в 1 байт «занимает 1 байт»: на деле целый кластер.\n- «..» принимают за вложенную папку.","kk":"# Операциялық жүйелер және файлдық жүйелер\n\n## ОЖ неден тұрады\n- **Ядро** процессор мен жадты бөледі, программаларды іске қосады, файлдарды бақылайды.\n- **Драйвер** — бір құрылғыға арналған программа-аудармашы.\n- **Интерфейс**: GUI (терезелер) және CLI (командалар: cd, dir / ls, copy / cp, del / rm; маскамен: dir *.txt).\n- **Көп тапсырмалылық**: ОЖ процестерге кезекпен кванттар береді. Қатып қалғанды Тапсырмалар диспетчерінде жабады (Ctrl + Shift + Esc).\n\n## Файлдық жүйе\n- FAT32 — флешкалар, файл ең көбі 4 ГБ; exFAT — үлкен файлдар; NTFS — Windows; ext4 — Linux; APFS — Apple.\n- Файл бүтін санды **кластерді** алады: дискідегі орын = ⌈көлем : кластер⌉ · кластер.\n- Форматтау файлдық жүйе жасайды және файлдарды жояды.\n\n## Жол\n- Абсолютті — түбірден, салыстырмалы — ағымдағы қалтадан: `.` — ағымдағы, `..` — бір деңгей жоғары.\n- Windows: `\\` және C:, D: дискілері. Linux: `/`, регистр маңызды.\n- Windows файл атында болмайды: \\ / : * ? \" < > |\n\n## ҰБТ кеңестері\n- Файл көшірілмей ме? Орынды және файлдық жүйе шегін тексер.\n- Дискідегі орынды кластерлермен, жоғары қарай дөңгелектеп есепте.\n\n## Жиі кететін қателер\n- 1 байттық файл 1 байт емес, тұтас кластер алады.\n- «..» — ішкі қалта емес."},
  "pc-7-licenses": {"ru":"# Виды программ и лицензии\n\n## Виды ПО\n- **Системное:** ОС, драйверы, утилиты (антивирус, архиватор).\n- **Прикладное:** общего назначения (Word, браузер) и специального (бухгалтерия, САПР).\n- **Инструментальное:** компилятор, интерпретатор, отладчик, IDE.\n\n## Три вопроса о лицензии\nКод открыт? → **open source** (GPL, copyleft). Бесплатно навсегда? → **freeware**. Сначала бесплатно (trial, demo)? → **shareware**. Иначе → **проприетарное**.\n\n## Важно\n- Покупаешь **лицензию**, то есть право пользоваться, а не авторские права.\n- Подписка — способ оплаты. Облачное приложение работает на сервере, нужен интернет.\n- Пакет на группу компьютеров дешевле отдельных лицензий: перебирай все варианты.\n- Подписка и покупка сравняются при n = цена покупки : цена месяца.\n\n## Пиратство\nКряки, ключи из генератора, копии на лишние компьютеры: вирусы, нет обновлений, штрафы. Выход: свободные аналоги, пробные и школьные лицензии.\n\n## Ловушки ЕНТ\n- Бесплатное ≠ свободное, а свободное можно продавать.\n- Shareware ≠ freeware.\n- Облачное ≠ свободное.\n- Антивирус и архиватор — системные утилиты.","kk":"# Программа түрлері және лицензиялар\n\n## ПҚ түрлері\n- **Жүйелік:** ОЖ, драйверлер, утилиталар (антивирус, архиватор).\n- **Қолданбалы:** жалпы мақсатты (Word, браузер) және арнайы (бухгалтерия, АЖЖ).\n- **Құралдық:** компилятор, интерпретатор, түзеткіш (отладчик), IDE.\n\n## Лицензия туралы үш сұрақ\nКод ашық па? → **open source** (GPL, copyleft). Мәңгі тегін бе? → **freeware**. Алғашында тегін бе (trial, demo)? → **shareware**. Әйтпесе → **проприетарлық**.\n\n## Маңызды\n- Сен **лицензияны**, яғни пайдалану құқығын сатып аласың, авторлық құқықты емес.\n- Жазылым — төлем тәсілі. Бұлтты қосымша серверде жұмыс істейді, интернет керек.\n- Компьютерлер тобына арналған пакет жеке лицензиялардан арзан: барлық нұсқаны қарап шық.\n- Жазылым мен сатып алу n = сатып алу бағасы : айлық баға болғанда теңеседі.\n\n## Қарақшылық\nКряктар, генератордан алынған кілттер, артық компьютерлердегі көшірмелер: вирустар, жаңартулар жоқ, айыппұлдар. Шығу жолы: еркін баламалар, сынақ және мектеп лицензиялары.\n\n## ҰБТ тұзақтары\n- Тегін ≠ еркін, ал еркін программаны сатуға болады.\n- Shareware ≠ freeware.\n- Бұлтты ≠ еркін.\n- Антивирус пен архиватор — жүйелік утилиталар."},
  "pc-8-archives": {"ru":"# Архивация и форматы файлов\n\n## Два вида сжатия\n- **Без потерь:** после распаковки данные точно прежние. ZIP, RAR, 7z, PNG, FLAC. Для текстов, программ, скриншотов.\n- **С потерями:** мелкие детали выброшены навсегда. JPEG (фото), MP3 (звук), MP4 (видео).\n- **Без сжатия:** BMP, WAV — самые большие файлы.\n\n## Коэффициент сжатия\n- k = размер до : размер после (во сколько раз), а не разность.\n- Размер после = до : k. Размер до = после · k.\n- «До» для рисунка: пиксели · i бит, затем ÷ 8 и ÷ 1024.\n\n## RLE\n- Серия = число + символ, одиночный символ тоже с числом: AAAABBBCCD → 4A3B2C1D.\n- Длина исходной строки = сумма чисел (12A — это 12 символов). Без серий код длиннее: ABAB → 1A1B1A1B.\n\n## Лайфхаки для ЕНТ\n- Уже сжатое (JPEG, MP3, MP4, ZIP, DOCX) архиватор почти не уменьшает: сжимай только то, что сжимается.\n- Фото — JPEG, скриншот и логотип — PNG, рисунок из формул — SVG; документы — TXT, DOCX, PDF.\n\n## Частые ошибки\n- Вычитают размеры вместо деления: 90 − 15 вместо 90 : 15.\n- Думают, что переименование .bmp в .jpg сжимает файл.\n- Складывают цифры кода вместо чисел повторов.","kk":"# Мұрағаттау және файл пішімдері\n\n## Сығудың екі түрі\n- **Шығынсыз:** ашқаннан кейін деректер дәл бұрынғыдай. ZIP, RAR, 7z, PNG, FLAC. Мәтін, программа, скриншот үшін.\n- **Шығынмен:** ұсақ бөлшектер мәңгіге тасталады. JPEG (фото), MP3 (дыбыс), MP4 (бейне).\n- **Сығусыз:** BMP, WAV — ең үлкен файлдар.\n\n## Сығу коэффициенті\n- k = бұрынғы көлем : кейінгі көлем (неше есе), айырма емес.\n- Кейінгі көлем = бұрын : k. Бұрынғы көлем = кейін · k.\n- Суреттің «бұрынғы» көлемі: пиксель саны · i бит, содан кейін ÷ 8 және ÷ 1024.\n\n## RLE\n- Серия = сан + таңба, жалғыз таңба да санмен: AAAABBBCCD → 4A3B2C1D.\n- Бастапқы жолдың ұзындығы = сандардың қосындысы (12A — бұл 12 таңба). Сериялар болмаса, код ұзын: ABAB → 1A1B1A1B.\n\n## ҰБТ-ға арналған кеңестер\n- Бұрыннан сығылғанды (JPEG, MP3, MP4, ZIP, DOCX) архиватор дерлік кішірейтпейді: тек сығылатынды сық.\n- Фото — JPEG, скриншот пен логотип — PNG, формулалардан тұратын сурет — SVG; құжаттар — TXT, DOCX, PDF.\n\n## Жиі кететін қателер\n- Бөлудің орнына көлемдерді азайтады: 90 : 15 орнына 90 − 15.\n- .bmp файлын .jpg деп қайта атау файлды сығады деп ойлайды.\n- Қайталану сандарының орнына кодтың цифрларын қосады."},
  "py-0-start": {"ru":"# Первая программа: print и input\n\n## Программа\n- **Программа** — список команд, выполняется **сверху вниз**, строка за строкой. Её запускает **интерпретатор** Python.\n- «Вывод» блок-схемы — `print`, «Ввод» — `input`.\n\n## print\n- `print(2 + 3)` даёт 5 (вычисление), `print(\"2 + 3\")` — текст 2 + 3. Кавычки на экран не попадают.\n- Запятая ставит пробел: `print(1, 2)` даёт `1 2`.\n- `sep` — что стоит **между** значениями (`sep=\"\"` — слитно), `end` — что **в конце** (`end=\"\"` — без новой строки). `print()` — пустая строка.\n\n## input\n- `input()` ждёт ввод и **всегда возвращает текст**: `'7'`, а не 7.\n- Число: `int(input())`. `'7' * 2` — это `'77'`, а `7 * 2` — 14.\n\n## Комментарии и ошибки\n- `# ...` — комментарий, Python его пропускает. Регистр важен: `Print` ≠ `print`.\n- **SyntaxError**, **IndentationError** (кавычка, скобка, пробел): ошибка до запуска, не выведется ничего.\n- **NameError**, **TypeError**: ошибка во время выполнения, строки выше успевают вывестись.\n\n## Лайфхаки ЕНТ\n- Есть кавычки? Тогда это текст, а не вычисление.\n- Одно значение в `print`: `sep` ничего не меняет.\n- Строки на экране считай по `end`: перевод строки там, где нет `end=\"\"`.","kk":"# Алғашқы программа: print және input\n\n## Программа\n- **Программа** — командалар тізімі, **жоғарыдан төмен**, жолма-жол орындалады. Оны **интерпретатор** іске қосады.\n- Блок-сызбадағы «Шығару» — `print`, «Енгізу» — `input`.\n\n## print\n- `print(2 + 3)` 5 береді (есептеу), `print(\"2 + 3\")` — 2 + 3 мәтінін береді. Тырнақша экранға түспейді.\n- Үтір бос орын қояды: `print(1, 2)` — `1 2`.\n- `sep` — мәндердің **арасында** тұратыны (`sep=\"\"` — тұтас), `end` — **соңында** тұратыны (`end=\"\"` — жаңа жолсыз). `print()` — бос жол.\n\n## input\n- `input()` **әрқашан мәтін қайтарады**: 7 емес, `'7'`.\n- Сан: `int(input())`. `'7' * 2` — бұл `'77'`, ал `7 * 2` — 14.\n\n## Түсініктеме және қателер\n- `# ...` — түсініктеме, Python оны өткізіп жібереді. Регистр маңызды: `Print` ≠ `print`.\n- **SyntaxError**, **IndentationError** (тырнақша, жақша, бос орын): қате іске қосқанға дейін табылады, ештеңе шықпайды.\n- **NameError**, **TypeError**: қате орындау кезінде, жоғарыдағы жолдар шығып үлгереді.\n\n## ҰБТ-ға арналған кеңестер\n- Тырнақша бар ма? Онда бұл — мәтін.\n- Мән біреу болса, `sep` ештеңені өзгертпейді.\n- Экрандағы жолдарды `end` бойынша сана: жаңа жол `end=\"\"` жоқ жерде."},
  "py-1-vars": {"ru":"# Переменные и выражения в Python\n\n## Переменная\n- **Переменная** — коробка с именем: `x = 5`. Знак `=` — «положи», а не «равно».\n- Новое значение стирает старое: `x = x + 1` — «увеличь x на 1».\n- Обмен значений: `a, b = b, a`.\n\n## Типы\n`int` (42), `float` (3.5), `str` ('текст'), `bool` (True). Тип покажет `type(x)`.\n\n## Ввод и вывод\n- `print(a, b)` — через пробел, `sep=''` — слитно.\n- `input()` **всегда строка**: число читай так — `int(input())`.\n\n## Операции\n`+ - *`, `/` (всегда дробное: 6 / 2 = 3.0), `//` (целая часть), `%` (остаток), `**` (степень). Порядок: скобки, `**`, `* / // %`, затем `+ -`.\n\n## Цифры числа\n- Последняя цифра: `n % 10`; число без последней: `n // 10`.\n- Трёхзначное: сотни `n // 100`, десятки `n // 10 % 10`, единицы `n % 10`.\n\n## Лайфхаки ЕНТ\n- Трассировка: запиши значения всех переменных после каждой строки.\n- Видишь `/` — в ответе дробное число (3.0).\n- Строки: `'5' + '5'` = `'55'`, `'ab' * 3` = `'ababab'`.\n- Остаток `17 % 5 = 2`, а не цифра после точки в `3.4`.","kk":"# Python-дағы айнымалылар және өрнектер\n\n## Айнымалы\n- **Айнымалы** — атауы бар қорап: `x = 5`. `=` белгісі «сал» дегенді білдіреді, «тең» емес.\n- Жаңа мән ескісін өшіреді: `x = x + 1` — «x мәнін 1-ге арттыр».\n- Мәндерді ауыстыру: `a, b = b, a`.\n\n## Типтер\n`int` (42), `float` (3.5), `str` ('мәтін'), `bool` (True). Типті `type(x)` көрсетеді.\n\n## Енгізу және шығару\n- `print(a, b)` — бос орынмен бөліп, `sep=''` — тұтас.\n- `input()` **әрқашан жол**: санды былай оқы — `int(input())`.\n\n## Амалдар\n`+ - *`, `/` (әрқашан бөлшек: 6 / 2 = 3.0), `//` (бүтін бөлігі), `%` (қалдық), `**` (дәреже). Реті: жақша, `**`, `* / // %`, содан кейін `+ -`.\n\n## Санның цифрлары\n- Соңғы цифр: `n % 10`; соңғы цифрсыз сан: `n // 10`.\n- Үш таңбалы сан: жүздіктер `n // 100`, ондықтар `n // 10 % 10`, бірліктер `n % 10`.\n\n## ҰБТ-ға арналған кеңестер\n- Трассировка: әр жолдан кейін барлық айнымалылардың мәндерін жаз.\n- `/` көрсең — жауап бөлшек сан болады (3.0).\n- Жолдар: `'5' + '5'` = `'55'`, `'ab' * 3` = `'ababab'`.\n- Қалдық `17 % 5 = 2`, ал `3.4` ішіндегі нүктеден кейінгі цифр емес."},
  "py-1b-types": {"ru":"# Типы данных в Python\n\n## Четыре типа\n- `int` — целое: `7`; `float` — дробное, с точкой: `7.0`; `str` — текст в кавычках: `\"7\"`; `bool` — `True` или `False`.\n- Тип покажет `type(x)`. `5 == 5.0` — True, но `5 == \"5\"` — False.\n\n## Превращения\n- `int(\"42\")` → 42, `float(\"2.5\")` → 2.5, `str(15)` → `'15'`.\n- `int(3.9)` → 3: дробная часть **отбрасывается**. `round(3.9)` → 4: округление. Для отрицательных: `int(-3.9)` = −3, `round(-3.9)` = −4. Ровно посередине — к чётному: `round(2.5)` = 2, `round(3.5)` = 4.\n- `bool()` даёт False только для `0`, `0.0` и `\"\"`. А `bool(\"0\")` и `bool(\"False\")` — True.\n- `input()` всегда возвращает `str`: число читай так — `int(input())`.\n\n## Плюс и звёздочка\n- `2 + 3` = 5, `\"2\" + \"3\"` = `\"23\"`, `\"ab\" * 3` = `\"ababab\"`, `\"2\" * 3` = `\"222\"`.\n- Текст + число — **TypeError**: `\"5\" + 5`.\n- `int(\"abc\")` и `int(\"3.5\")` — **ValueError**. Для дробного текста: `int(float(\"3.5\"))` = 3.\n\n## Лайфхаки ЕНТ\n- Сначала определи тип каждого значения (кавычки? точка?), потом считай.\n- Сколько цифр в числе n: `len(str(n))`.\n- Дробные числа через `==` не сравнивай: `0.1 + 0.2 == 0.3` — False.","kk":"# Python-дағы деректер типтері\n\n## Төрт тип\n- `int` — бүтін сан: `7`; `float` — бөлшек сан, нүктесі бар: `7.0`; `str` — тырнақшадағы мәтін: `\"7\"`; `bool` — `True` немесе `False`.\n- Типті `type(x)` көрсетеді. `5 == 5.0` — True, бірақ `5 == \"5\"` — False.\n\n## Түрлендіру\n- `int(\"42\")` → 42, `float(\"2.5\")` → 2.5, `str(15)` → `'15'`.\n- `int(3.9)` → 3: бөлшек бөлігі **алып тасталады**. `round(3.9)` → 4: дөңгелектеу. Теріс сандар үшін: `int(-3.9)` = −3, `round(-3.9)` = −4. Дәл ортасында — жұп санға: `round(2.5)` = 2, `round(3.5)` = 4.\n- `bool()` тек `0`, `0.0` және `\"\"` үшін False береді. Ал `bool(\"0\")` және `bool(\"False\")` — True.\n- `input()` әрқашан `str` қайтарады: санды былай оқы — `int(input())`.\n\n## Плюс және жұлдызша\n- `2 + 3` = 5, `\"2\" + \"3\"` = `\"23\"`, `\"ab\" * 3` = `\"ababab\"`, `\"2\" * 3` = `\"222\"`.\n- Мәтін + сан — **TypeError**: `\"5\" + 5`.\n- `int(\"abc\")` және `int(\"3.5\")` — **ValueError**. Бөлшек мәтін үшін: `int(float(\"3.5\"))` = 3.\n\n## ҰБТ-ға арналған кеңестер\n- Алдымен әр мәннің типін анықта (тырнақша? нүкте?), содан кейін есепте.\n- n санында неше цифр бар: `len(str(n))`.\n- Бөлшек сандарды `==` арқылы салыстырма: `0.1 + 0.2 == 0.3` — False."},
  "py-1c-ops": {"ru":"# Операции: //, %, ** и порядок действий\n\n## Три главные операции\n- `a // b` — целая часть деления (сколько полных), `a % b` — остаток (сколько осталось), `a ** b` — степень.\n- Остаток от деления на b — всегда от 0 до b − 1. Остаток 0 значит «делится без остатка»: `n % 2 == 0` — чётное, `n % 5 == 0` — кратно 5.\n- Если a < b: `a // b = 0`, `a % b = a`.\n\n## Типовые приёмы\n- Цифры: `n % 10` — последняя, `n // 10` — число без неё.\n- Время: `t // 60` и `t % 60`; по кругу — `(h + k) % 24`, дни недели — `% 7`.\n- Сокращённая запись: `x += 3` — это `x = x + 3`; так же `-= *= //= %= **=`.\n\n## Порядок действий\nСкобки → `**` (справа налево) → минус перед числом → `* / // %` (слева направо) → `+ -`. Например, `2 ** 3 ** 2 = 512`, `-2 ** 2 = -4`.\n\n## Лайфхаки ЕНТ\n- Отрицательные числа: `//` округляет вниз (`-7 // 2 = -4`), `-7 % 2 = 1`. Проверка: `a = (a // b) * b + a % b`.\n- Есть дробное число — результат float: `7 // 2.0 = 3.0`.\n- Деление на ноль (`// 0`, `% 0`) — ошибка ZeroDivisionError.\n- Длинное выражение считай по шагам и записывай, что осталось.","kk":"# Амалдар: //, %, ** және амалдар реті\n\n## Үш басты амал\n- `a // b` — бөлудің бүтін бөлігі (қанша толық), `a % b` — қалдық (қанша қалды), `a ** b` — дәреже.\n- b санына бөлгендегі қалдық әрқашан 0 мен b − 1 аралығында. Қалдық 0 болса — «қалдықсыз бөлінеді»: `n % 2 == 0` — жұп, `n % 5 == 0` — 5 санына еселі.\n- Егер a < b болса: `a // b = 0`, `a % b = a`.\n\n## Типтік тәсілдер\n- Цифрлар: `n % 10` — соңғы цифр, `n // 10` — соңғы цифрсыз сан.\n- Уақыт: `t // 60` және `t % 60`; айналып жүру — `(h + k) % 24`, апта күндері — `% 7`.\n- Қысқартылған жазба: `x += 3` — бұл `x = x + 3`; дәл солай `-= *= //= %= **=`.\n\n## Амалдар реті\nЖақша → `**` (оңнан солға) → санның алдындағы минус → `* / // %` (солдан оңға) → `+ -`. Мысалы, `2 ** 3 ** 2 = 512`, `-2 ** 2 = -4`.\n\n## ҰБТ-ға арналған кеңестер\n- Теріс сандар: `//` төмен қарай дөңгелектейді (`-7 // 2 = -4`), `-7 % 2 = 1`. Тексеру: `a = (a // b) * b + a % b`.\n- Бөлшек сан болса — нәтиже float: `7 // 2.0 = 3.0`.\n- Нөлге бөлу (`// 0`, `% 0`) — ZeroDivisionError қатесі.\n- Ұзын өрнекті қадам-қадаммен есепте және не қалғанын жазып отыр."},
  "py-2-if": {"ru":"# Ветвления: if, elif, else\n\n## Как устроено\n\n```python\nif условие1:\n    ...   # условие1 верно\nelif условие2:\n    ...   # первое неверно, второе верно\nelse:\n    ...   # все условия неверны\n```\n\n- После условия и после `else` — **двоеточие**.\n- Тело ветки — строки с **отступом 4 пробела**.\n- Выполняется **не больше одной** ветки: первая, у которой условие верно. Остальные не проверяются. С `else` всегда срабатывает ровно одна.\n- `elif` и `else` можно не писать.\n\n## Условия\n\n- Сравнения: `==`  `!=`  `<`  `>`  `<=`  `>=`. Равенство — **двойной** знак `==`.\n- `and` — оба верны, `or` — хотя бы одно, `not` — наоборот.\n- Диапазон: `5 <= x <= 10`. Чётное: `x % 2 == 0`.\n\n## Лайфхаки ЕНТ\n\n- Подставь данные и иди по строкам сверху вниз, записывая переменные.\n- В цепочке `elif` порядок важен: сначала самые строгие условия.\n- Отдельные `if` проверяются все, а `elif` — только пока ничего не сработало.\n- `and` выполняется раньше `or`.\n\n## Частые ошибки\n\n- `=` вместо `==`; забытое двоеточие.\n- `print` без отступа выполняется всегда.\n- `x > 5 and < 10` — нужно `x > 5 and x < 10`.","kk":"# Тармақталу: if, elif, else\n\n## Қалай құрылады\n\n```python\nif шарт1:\n    ...   # шарт1 ақиқат\nelif шарт2:\n    ...   # біріншісі жалған, екіншісі ақиқат\nelse:\n    ...   # барлық шарт жалған\n```\n\n- Шарттан кейін және `else` сөзінен кейін — **қос нүкте**.\n- Тармақтың ішіндегі жолдар — **4 бос орын шегінісімен**.\n- **Бір ғана** тармақ орындалады: шарты ақиқат бірінші тармақ. Қалғандары тексерілмейді. Шарттардың бәрі жалған болып, `else` жоқ болса, ешбір тармақ орындалмайды.\n- `elif` пен `else` жазбауға болады.\n\n## Шарттар\n\n- Салыстыру: `==`  `!=`  `<`  `>`  `<=`  `>=`. Теңдік — **қосарланған** `==` белгісі.\n- `and` — екеуі де ақиқат, `or` — кемінде біреуі, `not` — керісінше.\n- Диапазон: `5 <= x <= 10`. Жұп сан: `x % 2 == 0`.\n\n## ҰБТ-ға арналған кеңестер\n\n- Деректерді қойып, жолдармен жоғарыдан төмен жүр, айнымалыларды жазып отыр.\n- `elif` тізбегінде реттілік маңызды: алдымен ең қатаң шарттар.\n- Жеке `if` операторларының бәрі тексеріледі, ал `elif` — әзірге ештеңе орындалмаған кезде ғана.\n- `and` `or`-дан бұрын орындалады.\n\n## Жиі кететін қателер\n\n- `==` орнына `=`; ұмытылған қос нүкте.\n- Шегінісіз `print` әрдайым орындалады.\n- `x > 5 and < 10` емес, `x > 5 and x < 10` болуы керек."},
  "py-2a-elif": {"ru":"# elif: выбор из нескольких\n\n```python\nif условие1:\n    ...   # условие1 верно\nelif условие2:\n    ...   # первое неверно, второе верно\nelse:\n    ...   # все условия неверны\n```\n\n- Условия проверяются **сверху вниз**; выполняется **только первая верная** ветка, остальные не проверяются.\n- `elif` можно ставить сколько нужно; `else` — последним, без условия.\n- Порядок важен: сначала самые строгие условия (90, 70, 50).\n\n## Лайфхаки ЕНТ\n\n- «Что выведет при x = …»: иди по условиям сверху вниз до первого верного и остановись.\n- Проверяй границы: `>` и `>=`.\n\n## Частые ошибки\n\n- Мягкое условие поставлено выше строгого.\n- Отдельные `if` вместо `elif`: тогда проверяются все.","kk":"# elif: бірнеше нұсқадан таңдау\n\n```python\nif шарт1:\n    ...   # шарт1 ақиқат\nelif шарт2:\n    ...   # біріншісі жалған, екіншісі ақиқат\nelse:\n    ...   # барлық шарт жалған\n```\n\n- Шарттар **жоғарыдан төмен** тексеріледі; **тек бірінші ақиқат** тармақ орындалады, қалғандары тексерілмейді.\n- `elif` қажетінше көп қоюға болады; `else` — соңында, шартсыз.\n- Реттілік маңызды: алдымен ең қатаң шарттар (90, 70, 50).\n\n## ҰБТ-ға арналған кеңестер\n\n- «x = … болғанда не шығарады»: шарттармен жоғарыдан төмен бірінші ақиқатқа дейін жүріп, тоқта.\n- Шектерді тексер: `>` және `>=`.\n\n## Жиі кететін қателер\n\n- Жұмсақ шарт қатаңнан жоғары қойылған.\n- `elif` орнына бөлек `if`: онда бәрі тексеріледі."},
  "py-2a-else": {"ru":"# if–else: два пути\n\n```python\nif условие:\n    ...   # условие верно\nelse:\n    ...   # условие неверно\n```\n\n- Выполняется **ровно одна** ветка: никогда обе и никогда ни одной.\n- После `else` — **двоеточие** и **никакого условия**. Тело — с отступом 4 пробела.\n- Чётность: `x % 2 == 0` — чётное; остаток 1 — нечётное.\n\n## Лайфхаки ЕНТ\n\n- Сначала вычисли то, что проверяет условие (например, y = x + 3), потом выбери ветку.\n\n## Частые ошибки\n\n- `else x < 5:` — условие после `else` не пишут.\n- Забытое двоеточие после `else`.","kk":"# if–else: екі жол\n\n```python\nif шарт:\n    ...   # шарт ақиқат\nelse:\n    ...   # шарт жалған\n```\n\n- **Дәл бір** тармақ орындалады: екеуі бірден ешқашан орындалмайды, біреуі әрқашан орындалады.\n- `else` сөзінен кейін — **қос нүкте** және **ешқандай шарт жоқ**. Ішіндегі жолдар — 4 бос орын шегінісімен.\n- Жұптық: `x % 2 == 0` — жұп; қалдық 1 — тақ.\n\n## ҰБТ-ға арналған кеңестер\n\n- Алдымен шарт тексеретін мәнді есепте (мысалы, y = x + 3), содан кейін тармақты таңда.\n\n## Жиі кететін қателер\n\n- `else x < 5:` — `else` сөзінен кейін шарт жазылмайды.\n- `else` соңындағы ұмытылған қос нүкте."},
  "py-2a-if": {"ru":"# if: если условие верно\n\n- `if условие:` — тело выполняется, только если условие верно (True).\n- В конце строки с `if` — **двоеточие**. Тело — строки с **отступом 4 пробела**.\n- Условие неверно (False) — тело пропускается, программа идёт дальше. Строка без отступа выполняется всегда.\n- Сравнения: `==`  `!=`  `>`  `<`  `>=`  `<=`. Равенство — **двойной** знак `==`; одиночный `=` кладёт значение в переменную.\n\n## Лайфхаки ЕНТ\n\n- Проверяй границу: `>` число не включает, `>=` включает.\n- Подставь значения и иди по строкам сверху вниз, записывая переменные.\n\n## Частые ошибки\n\n- `=` вместо `==`; забытое двоеточие.\n- Строка без отступа не входит в if.","kk":"# if: шарт ақиқат болса\n\n- `if шарт:` — ішіндегі жолдар тек шарт ақиқат (True) болғанда орындалады.\n- `if` бар жолдың соңында — **қос нүкте**. Ішіндегі жолдар — **4 бос орын шегінісімен**.\n- Шарт жалған (False) болса — ішіндегі жолдар өткізіліп кетеді, программа әрі қарай жалғасады. Шегінісіз жол әрдайым орындалады.\n- Салыстыру: `==`  `!=`  `>`  `<`  `>=`  `<=`. Теңдік — **қосарланған** `==` белгісі; жалғыз `=` мәнді айнымалыға салады.\n\n## ҰБТ-ға арналған кеңестер\n\n- Шекті тексер: `>` санды қоспайды, `>=` қосады.\n- Мәндерді қойып, жолдармен жоғарыдан төмен жүр, айнымалыларды жазып отыр.\n\n## Жиі кететін қателер\n\n- `==` орнына `=`; ұмытылған қос нүкте.\n- Шегінісіз жол if құрамына кірмейді."},
  "py-2b-logic": {"ru":"# Сложные условия: and, or, not, elif\n\n## Приоритет\nСкобки → арифметика → сравнения → `not` → `and` → `or`. Сомневаешься — ставь скобки.\n\n## Слова → Python\n- «от 3 до 8»: `3 <= x <= 8`\n- «вне отрезка»: `x < 3 or x > 8` (через or, не and)\n- «равно 3 или 7»: `x == 3 or x == 7` (запись `x == 3 or 7` верна всегда)\n- «делится на 2 и на 3»: `x % 2 == 0 and x % 3 == 0`\n\n## Законы\n- `not (a and b)` = `not a or not b`, `not (a or b)` = `not a and not b`\n- `not (x > 5)` = `x <= 5`: знак меняется на противоположный\n- вложенные `if` без `else` = `and`\n- високосный год: `(y % 4 == 0 and y % 100 != 0) or y % 400 == 0`\n\n## Лайфхаки ЕНТ\n- Цепочка `if/elif/else` — сработает **одна** ветка, первая верная; узкое условие ставь выше широкого. Два `if` подряд — независимые проверки.\n- `and` идёт слева направо до первого False: `x != 0 and 10 // x > 2` не даст деления на ноль.\n- Обратная задача: сделай все условия выше нужной ветки ложными (по де Моргану).\n\n## Частые ошибки\n- `=` вместо `==`; `x > 5 and < 10`; `not` без скобок меняет только первое сравнение.","kk":"# Күрделі шарттар: and, or, not, elif\n\n## Басымдық\nЖақша → арифметика → салыстырулар → `not` → `and` → `or`. Күмәнің болса, жақша қой.\n\n## Сөз → Python\n- «3 пен 8 аралығында»: `3 <= x <= 8`\n- «аралықтан тыс»: `x < 3 or x > 8` (or арқылы, and емес)\n- «3 немесе 7 тең»: `x == 3 or x == 7` (`x == 3 or 7` жазбасы әрдайым ақиқат)\n- «2 және 3 санына бөлінеді»: `x % 2 == 0 and x % 3 == 0`\n\n## Заңдар\n- `not (a and b)` = `not a or not b`, `not (a or b)` = `not a and not b`\n- `not (x > 5)` = `x <= 5`: белгі қарама-қарсысына ауысады\n- `else` жоқ кірістірілген `if` = `and`\n- кібісе жыл: `(y % 4 == 0 and y % 100 != 0) or y % 400 == 0`\n\n## ҰБТ-ға арналған кеңестер\n- `if/elif/else` тізбегінде **бір** тармақ орындалады — шарты ақиқат бірінші тармақ; тар шартты кең шарттан жоғары қой. Қатар тұрған екі `if` — тәуелсіз тексеру.\n- `and` солдан оңға бірінші False-қа дейін жүреді: `x != 0 and 10 // x > 2` нөлге бөлуді бермейді.\n- Кері есеп: қажетті тармақтан жоғарыдағы барлық шартты жалған ет (де Морган бойынша).\n\n## Жиі кететін қателер\n- `==` орнына `=`; `x > 5 and < 10`; жақшасыз `not` тек бірінші салыстыруды өзгертеді."},
  "py-3-loops": {"ru":"# Циклы: for и while\n\n## for\n\n```python\nfor i in range(a, b, шаг):\n    ...   # тело цикла\n```\n\n- `range(b)`: 0 … b−1. `range(a, b)`: a … b−1. **Правая граница не входит.**\n- Повторений: b − a (при шаге 1). Шаг бывает отрицательным: `range(5, 0, -1)` → 5 4 3 2 1.\n\n## while\n\n- `while условие:` — пока условие верно. Переменную из условия меняй в теле, иначе цикл бесконечный.\n\n## Приёмы\n\n- Сумма: `s = 0` … `s = s + i` (коротко `s += i`). Счётчик: `k = k + 1`. Произведение: `p = 1` … `p = p * i`.\n- `break` — выйти из цикла, `continue` — перейти к следующему шагу.\n- Цифры числа: `n % 10` — последняя цифра, `n = n // 10` — убрать её; цикл `while n > 0`.\n\n## Лайфхаки ЕНТ\n\n- Веди трассировочную таблицу: столбец на каждую переменную, строка на каждый круг.\n- Проверяй границы: `<` или `<=`, `range(a, b)` или `range(a, b + 1)`.\n\n## Частые ошибки\n\n- Считать, что правая граница range входит.\n- Забыть, что `range(5)` начинается с 0.\n- Не задать начальное значение накопителя (`s = 0`).\n- `continue` в while до изменения переменной — программа зависает.","kk":"# Циклдер: for және while\n\n## for\n\n```python\nfor i in range(a, b, қадам):\n    ...   # цикл денесі\n```\n\n- `range(b)`: 0 … b−1. `range(a, b)`: a … b−1. **Оң жақ шек кірмейді.**\n- Қайталану саны: b − a (қадам 1 болса). Қадам теріс болуы мүмкін: `range(5, 0, -1)` → 5 4 3 2 1.\n\n## while\n\n- `while шарт:` — шарт ақиқат болғанша. Шарттағы айнымалыны цикл денесінде өзгерт, әйтпесе цикл шексіз болады.\n\n## Тәсілдер\n\n- Қосынды: `s = 0` … `s = s + i` (қысқаша `s += i`). Санауыш: `k = k + 1`. Көбейтінді: `p = 1` … `p = p * i`.\n- `break` — циклден шығу, `continue` — келесі қадамға өту.\n- Санның цифрлары: `n % 10` — соңғы цифр, `n = n // 10` — оны алып тастау; цикл `while n > 0`.\n\n## ҰБТ-ға арналған кеңестер\n\n- Трассировка кестесін жүргіз: әр айнымалыға баған, әр айналымға жол.\n- Шектерді тексер: `<` немесе `<=`, `range(a, b)` немесе `range(a, b + 1)`.\n\n## Жиі кететін қателер\n\n- range-дің оң жақ шегі кіреді деп ойлау.\n- `range(5)` нөлден басталатынын ұмыту.\n- Жинақтауыштың бастапқы мәнін қоймау (`s = 0`).\n- while циклінде айнымалыны өзгертпей тұрып `continue` қою — программа қатып қалады."},
  "py-3a-range": {"ru":"# range(n): повторить n раз\n\n```python\nfor i in range(n):\n    ...   # тело цикла\n```\n\n- `range(n)` — **n кругов**: тело выполнится n раз.\n- Значения `i`: 0, 1, …, **n − 1**. Счёт с нуля, самого n среди значений нет.\n- `range(5)` → 0, 1, 2, 3, 4: пять значений, наибольшее 4.\n- `range(0)` — ноль кругов, ошибки нет.\n- В скобках может быть выражение: `range(n + 1)` — n + 1 кругов.\n\n## Частые ошибки\n\n- Считать, что `i` начинается с 1.\n- Путать последнее значение (n − 1) с числом кругов (n).","kk":"# range(n): n рет қайталау\n\n```python\nfor i in range(n):\n    ...   # цикл денесі\n```\n\n- `range(n)` — **n айналым**: дене n рет орындалады.\n- `i` мәндері: 0, 1, …, **n − 1**. Санау нөлден басталады, n санының өзі мәндердің ішінде жоқ.\n- `range(5)` → 0, 1, 2, 3, 4: бес мән, ең үлкені — 4.\n- `range(0)` — нөл айналым, қате жоқ.\n- Жақша ішінде өрнек болуы мүмкін: `range(n + 1)` — n + 1 айналым.\n\n## Жиі кететін қателер\n\n- `i` мәні 1 санынан басталады деп ойлау.\n- Соңғы мәнді (n − 1) айналым санымен (n) шатастыру."},
  "py-3a-range2": {"ru":"# range(a, b): от и до\n\n```python\nfor i in range(a, b):\n    ...   # тело цикла\n```\n\n- Значения `i`: от **a** до **b − 1**. Старт входит, стоп **не входит**.\n- Кругов: **b − a**. Если a ≥ b — диапазон пуст, ноль кругов, ошибки нет.\n- `range(n)` — то же, что `range(0, n)`.\n- Включить правую границу: `range(1, 11)` — числа от 1 до 10.\n- Сумма от a до b включительно: `range(a, b + 1)` и `s = s + i`.\n\n## Частые ошибки\n\n- Считать, что стоп входит в диапазон.\n- Ждать ошибку от пустого диапазона или отрицательное число кругов.","kk":"# range(a, b): бастау мен тоқтау\n\n```python\nfor i in range(a, b):\n    ...   # цикл денесі\n```\n\n- `i` мәндері: **a** санынан **b − 1** санына дейін. Бастау кіреді, тоқтау **кірмейді**.\n- Айналым саны: **b − a**. a ≥ b болса — диапазон бос, нөл айналым, қате жоқ.\n- `range(n)` — `range(0, n)` жазбасымен бірдей.\n- Оң жақ шекті қосу: `range(1, 11)` — 1 мен 10 аралығындағы сандар.\n- a мен b аралығындағы қосынды (қоса алғанда): `range(a, b + 1)` және `s = s + i`.\n\n## Жиі кететін қателер\n\n- Тоқтау диапазонға кіреді деп ойлау.\n- Бос диапазоннан қате немесе теріс айналым санын күту."},
  "py-3a-step": {"ru":"# range с шагом и счёт вниз\n\n```python\nfor i in range(a, b, s):\n    ...   # тело цикла\n```\n\n- Старт `a`, стоп `b` (**не входит**), шаг `s` (по умолчанию 1).\n- Вниз: шаг **отрицательный**, старт больше стопа: `range(5, 0, -1)` → 5, 4, 3, 2, 1.\n- Последнее значение — не обязательно b − 1: `range(4, 30, 7)` → 4, 11, 18, 25.\n- Число кругов: (b − a) / s, округлить вверх; `len(range(...))` считает за тебя.\n- Направление не совпало (`range(30, 5, 5)`) — ноль кругов, без ошибки. Шаг 0 — `ValueError`.\n\n## Частые ошибки\n\n- Включить стоп в значения; забыть минус при счёте вниз; округлить число кругов вниз.","kk":"# Қадамы бар range және кері санау\n\n```python\nfor i in range(a, b, s):\n    ...   # цикл денесі\n```\n\n- Бастау `a`, тоқтау `b` (**кірмейді**), қадам `s` (әдепкі 1).\n- Төмен қарай: қадам **теріс**, бастау тоқтаудан үлкен: `range(5, 0, -1)` → 5, 4, 3, 2, 1.\n- Соңғы мән міндетті түрде b − 1 емес: `range(4, 30, 7)` → 4, 11, 18, 25.\n- Айналым саны: (b − a) / s, жоғары қарай дөңгелекте; `len(range(...))` оны сен үшін санайды.\n- Бағыт сәйкес келмесе (`range(30, 5, 5)`) — нөл айналым, қате жоқ. Қадам 0 — `ValueError`.\n\n## Жиі кететін қателер\n\n- Тоқтауды мәндерге қосу; кері санағанда минусты ұмыту; айналым санын төмен дөңгелектеу."},
  "py-3b-for": {"ru":"# for и range подробно\n\n## range(a, b, s)\n\n```python\nfor i in range(a, b, s):\n    ...   # тело цикла\n```\n\n- Старт `a` (по умолчанию 0), стоп `b` (**не входит**), шаг `s` (по умолчанию 1).\n- Кругов: (b − a) / s, **округлить вверх**. Вниз: шаг меньше 0 и старт больше стопа.\n- Последнее значение при шаге больше 1 — не b − 1: выпиши значения.\n- Направление не совпало (`range(6, 1)`) — ноль кругов, без ошибки. Шаг 0 — ошибка.\n- Включить границу: `range(1, 11)`, `range(10, 0, -1)`.\n\n## По строке и списку\n\n- `for ch in \"код\"` — по символам, `for x in [5, 2, 9]` — по элементам. Кругов столько, сколько элементов.\n\n## Тонкости\n\n- После цикла переменная хранит последнее значение.\n- `range(n)` считается один раз: менять n внутри бесполезно.\n- Присваивание счётчику живёт до конца круга.\n\n## Накопители\n\n- Сумма `s = 0`, счётчик `k = 0`, произведение `p = 1`; условие внутри цикла отбирает, что копить.\n- Двоичная строка в число: `t = t * 2 + int(c)`.\n\n## Частые ошибки\n\n- Округлить число кругов вниз; включить стоп; забыть минус при счёте вниз.","kk":"# for және range толығырақ\n\n## range(a, b, s)\n\n```python\nfor i in range(a, b, s):\n    ...   # цикл денесі\n```\n\n- Бастау `a` (әдепкі 0), тоқтау `b` (**кірмейді**), қадам `s` (әдепкі 1).\n- Айналым саны: (b − a) / s, **жоғары дөңгелекте**. Төмен жүру: қадам 0-ден кіші, бастау тоқтаудан үлкен.\n- Қадам 1-ден үлкен болса, соңғы мән b − 1 емес: мәндерді жазып шық.\n- Бағыт сәйкес келмесе (`range(6, 1)`) — нөл айналым, қате жоқ. Қадам 0 — қате.\n- Шекті қосу: `range(1, 11)`, `range(10, 0, -1)`.\n\n## Жол мен тізім бойынша\n\n- `for ch in \"код\"` — символдар бойынша, `for x in [5, 2, 9]` — элементтер бойынша. Айналым элемент санындай.\n\n## Нәзік тұстары\n\n- Циклден кейін айнымалы соңғы мәнін сақтайды.\n- `range(n)` бір рет есептеледі: ішінде n өзгертудің пайдасы жоқ.\n- Санауышқа меншіктеу тек айналым соңына дейін күшінде болады.\n\n## Жинақтауыштар\n\n- Қосынды `s = 0`, санауыш `k = 0`, көбейтінді `p = 1`; цикл ішіндегі шарт нені жинау керегін іріктейді.\n- Екілік жолды санға айналдыру: `t = t * 2 + int(c)`.\n\n## Жиі кететін қателер\n\n- Айналым санын төмен дөңгелектеу; тоқтауды қосу; төмен санағанда минусты ұмыту."},
  "py-3c-while": {"ru":"# Цикл while, break и continue\n\n```python\nwhile условие:\n    ...   # тело, которое меняет переменную из условия\n```\n\n- Порядок: **проверка → тело → проверка**. Условие ложно сразу — тело не выполнится ни разу.\n- После выхода условие **ложно**: в `while money < 100` останется 120, а не 100.\n- Число повторений известно — `for`; неизвестно (копим, вводим до 0) — `while`.\n- Бесконечный цикл: переменная не меняется, меняется не в ту сторону, `while True` без `break`.\n- `break` — выйти из цикла. `continue` — пропустить остаток и вернуться к проверке условия. В `while` перед `continue` меняй переменную.\n- `while True:` + `break` — ввод до сигнала («0 — конец»). Проверку выхода ставь раньше остальных.\n- Цифры числа: `n % 10` — последняя, `n // 10` — без неё, цикл `while n > 0`; тело выполнится столько раз, сколько цифр. Переворот: `r = r * 10 + d`.\n\n## Лайфхаки ЕНТ\n\n- Веди таблицу: столбец на переменную и столбец «условие верно?». Проверяй условие **перед** каждым кругом.\n- Смотри на знак: `<` и `<=` дают разное число кругов. Условие из двух частей через `and` ломается от любой.\n- Первым делом проверь: приближает ли тело условие к ложному — иначе вариант «зависнет».","kk":"# while циклі, break және continue\n\n```python\nwhile шарт:\n    ...   # шарттағы айнымалыны өзгертетін дене\n```\n\n- Реті: **тексеру → дене → тексеру**. Шарт басынан жалған болса — дене бір рет те орындалмайды.\n- Шыққаннан кейін шарт **жалған**: `while money < 100` циклінде 100 емес, 120 қалады.\n- Қайталану саны белгілі болса — `for`; белгісіз болса (жинаймыз, 0 болғанша енгіземіз) — `while`.\n- Шексіз цикл: айнымалы өзгермейді, қате бағытта өзгереді, `break` жоқ `while True`.\n- `break` — циклден шығу. `continue` — қалғанын өткізіп, шартты тексеруге оралу. `while` циклінде `continue` алдында айнымалыны өзгерт.\n- `while True:` + `break` — белгіге дейін енгізу («0 — соңы»). Шығуды тексеруді басқалардан бұрын қой.\n- Санның цифрлары: `n % 10` — соңғысы, `n // 10` — соңғысыз сан, цикл `while n > 0`; дене цифр санындай рет орындалады. Кері жазу: `r = r * 10 + d`.\n\n## ҰБТ-ға арналған кеңестер\n\n- Кесте жүргіз: әр айнымалыға баған және «шарт ақиқат па?» бағаны. Шартты әр айналымнан **бұрын** тексер.\n- Белгіге қара: `<` және `<=` әртүрлі айналым санын береді. `and` арқылы екі бөлікті шарт кез келгенінен бұзылады.\n- Алдымен тексер: дене шартты жалғандыққа жақындата ма."},
  "py-3d-nested": {"ru":"# Вложенные циклы\n\n## Идея\n\nЦикл внутри цикла. Внешний меняется **медленно**, внутренний — **быстро** и на каждом круге внешнего начинает заново. Тело внутреннего пишется с отступом 8 пробелов.\n\n```python\nfor i in range(3):          # строки\n    for j in range(4):      # звёздочки в строке\n        print(\"*\", end=\"\")\n    print()                 # после ряда\n```\n\nТаблица умножения: `print(i * j, end=\" \")` во внутреннем цикле.\n\n## Сколько раз выполнится тело\n\n- Границы внутреннего не зависят от внешнего: **n · m** (3 · 4 = 12).\n- Внутри `range(i)` — «лесенка»: складывай круги по каждому i. 1 + 2 + … + n = **n · (n + 1) / 2**.\n- Команда в теле внешнего цикла выполнится столько раз, сколько кругов у внешнего.\n\n## Лайфхаки ЕНТ\n\n- Выпиши, сколько кругов делает внутренний цикл при каждом i, и сложи.\n- Трассировочная таблица: строка на каждое выполнение тела.\n- Если k растёт при условии `i * j == n` — это счёт делителей числа n.\n\n## Частые ошибки\n\n- `break` и `continue` действуют только на внутренний цикл.\n- Отступ у `print()`: 4 пробела — после ряда, 8 — после каждой звёздочки.\n- Складывать круги вместо умножения (3 + 4 вместо 3 · 4).\n- Забыть, что `range(i)` начинается с 0.","kk":"# Кірістірілген циклдер\n\n## Негізгі ой\n\nЦикл ішіндегі цикл. Сыртқы цикл **баяу**, ішкі цикл **тез** өзгереді және сыртқы циклдің әр айналымында қайтадан басталады. Ішкі цикл денесі 8 бос орын шегінісімен жазылады.\n\n```python\nfor i in range(3):          # жолдар\n    for j in range(4):      # жолдағы жұлдызшалар\n        print(\"*\", end=\"\")\n    print()                 # қатардан кейін\n```\n\nКөбейту кестесі: ішкі циклде `print(i * j, end=\" \")`.\n\n## Дене неше рет орындалады\n\n- Ішкі циклдің шектері сыртқы циклге тәуелді емес: **n · m** (3 · 4 = 12).\n- Ішінде `range(i)` болса — «баспалдақ»: әр i бойынша айналымдарды қос. 1 + 2 + … + n = **n · (n + 1) / 2**.\n- Сыртқы цикл денесіндегі команда сыртқы циклдің айналым санындай рет орындалады.\n\n## ҰБТ кеңестері\n\n- Әр i үшін ішкі цикл неше айналым жасайтынын жазып, қос.\n- Трассировка кестесі: дененің әр орындалуына бір жол.\n- `i * j == n` шартында k өссе — бұл n санының бөлгіштерін санау.\n\n## Жиі кететін қателер\n\n- `break` және `continue` тек ішкі циклге әсер етеді.\n- `print()` шегінісі: 4 бос орын — қатардан кейін, 8 — әр жұлдызшадан кейін.\n- Айналымдарды көбейтудің орнына қосу (3 · 4 орнына 3 + 4).\n- `range(i)` 0-ден басталатынын ұмыту."},
  "py-3e-patterns": {"ru":"# Типовые алгоритмы в цикле\n\n## Шесть заготовок\n\n- **Сумма:** `s = 0` … `s += x`. **Произведение:** `p = 1` … `p *= x`.\n- **Счётчик:** `k = 0` … `k += 1` — прибавляется единица, а не число.\n- **По условию:** строки накопителя стоят внутри `if`. **Среднее:** `s / k` (результат дробный; при k = 0 — ZeroDivisionError).\n- **Максимум/минимум:** старт `m = a[0]` (не 0!), условие `x > m` / `x < m`. Номер — `k = i`: при `>` индекс первого из равных, при `>=` последнего.\n- **Цифры:** `d = n % 10`, `n = n // 10`, цикл `while n > 0`. Сумма `s += d`, количество `k += 1`, переворот `r = r * 10 + d` (нули в начале теряются).\n- **Простое число:** ищем делитель `n % d == 0` для d от 2 до n − 1; нашли — `ok = False` и `break`. 1 не простое. Или считаем делители: простое, если их ровно 2.\n\n## Как узнать шаблон (три вопроса)\n\n1. Что до цикла? 2. Что в условии `if`? 3. Что меняется в теле?\n\n## Лайфхаки ЕНТ\n\n- Трассировочная таблица на 2–3 первых элемента.\n- Смотри на отступ: `k += 1` внутри `if` или снаружи, `print` внутри цикла или после.\n\n## Частые ошибки\n\n- Максимум со стартом 0 на отрицательных числах.\n- Для 1 «простое» — нет, а программа без `n > 1` скажет «да».\n- `k += x` вместо `k += 1`.","kk":"# Циклдегі типтік алгоритмдер\n\n## Алты үлгі\n\n- **Қосынды:** `s = 0` … `s += x`. **Көбейтінді:** `p = 1` … `p *= x`.\n- **Санауыш:** `k = 0` … `k += 1` — санның өзі емес, бір қосылады.\n- **Шарт бойынша:** жинақтауыш жолдары `if` ішінде тұрады. **Орташа мән:** `s / k` (нәтиже бөлшек; k = 0 болса — ZeroDivisionError).\n- **Максимум/минимум:** бастауы `m = a[0]` (0 емес!), шарты `x > m` / `x < m`. Нөмірі — `k = i`: `>` болса, тең сандардың біріншісінің индексі, `>=` болса — соңғысының.\n- **Цифрлар:** `d = n % 10`, `n = n // 10`, цикл `while n > 0`. Қосынды `s += d`, саны `k += 1`, кері жазу `r = r * 10 + d` (басындағы нөлдер жоғалады).\n- **Жай сан:** d = 2-ден n − 1-ге дейін `n % d == 0` бөлгішін іздейміз; тапсақ — `ok = False` және `break`. 1 жай емес. Немесе бөлгіштерді санаймыз: дәл 2 болса — жай.\n\n## Үлгіні тану (үш сұрақ)\n\n1. Циклге дейін не бар? 2. `if` шартында не бар? 3. Цикл денесінде не өзгереді?\n\n## ҰБТ кеңестері\n\n- 2–3 элементке трассировка кестесін жүргіз; шегінісіне қара: `k += 1` — `if` ішінде ме, `print` — цикл ішінде ме.\n\n## Жиі жіберілетін қателер\n\n- Теріс сандарда максимумның бастауын 0 алу.\n- `n > 1` шартсыз программа 1 санын жай дейді.\n- `k += 1` орнына `k += x`."},
  "py-4-strings": {"ru":"# Строки в Python\n\n## Индексы\n- Строка — ряд символов в кавычках: `s = 'Python'`. Пробел и знаки — тоже символы.\n- Номера идут **с нуля**: `s[0]` — первый символ. `s[-1]` — последний, `s[-2]` — предпоследний.\n- `len(s)` — длина. Последний индекс — `len(s) - 1`; `s[len(s)]` — ошибка `IndexError`.\n\n## Срезы\n- `s[a:b]` — от индекса `a` **до `b`, не включая `b`**. Для 'Python': `s[1:4]` = 'yth'.\n- `s[:3]` — с начала, `s[2:]` — до конца, `s[-2:]` — два последних.\n- `s[::2]` — через один, `s[::-1]` — переворот. Срез не даёт ошибку, если границы вышли за строку.\n\n## Методы (не меняют строку, а возвращают новую)\n- `upper()`, `lower()`, `replace(a, b)` (заменяет **все** a), `count(x)`, `find(x)` (индекс первого x или **-1**), `strip()`, `split()`, `'-'.join(список)`.\n- `x in s` — есть ли кусок в строке; палиндром: `s == s[::-1]`.\n- `ord('A')` = 65, `chr(97)` = 'a'.\n\n## Перебор\n`for ch in s:` — тело цикла выполняется `len(s)` раз. Гласные: `ch in 'aeiou'`; цифры: `ch.isdigit()`.\n\n## Ловушки ЕНТ\n- Счёт с единицы вместо нуля.\n- Правая граница среза **не входит**.\n- `s.upper()` без записи результата ничего не меняет; `s[0] = 'A'` — ошибка.","kk":"# Python-дағы жолдар\n\n## Индекстер\n- Жол — тырнақшадағы символдар қатары: `s = 'Python'`. Бос орын мен белгілер де — символ.\n- Нөмірлер **нөлден** басталады: `s[0]` — бірінші символ. `s[-1]` — соңғы, `s[-2]` — соңғысының алдындағысы.\n- `len(s)` — ұзындық. Соңғы индекс — `len(s) - 1`; `s[len(s)]` — `IndexError` қатесі.\n\n## Тілімдер\n- `s[a:b]` — `a` индексінен **`b` индексіне дейін, `b` қосылмайды**. 'Python' үшін: `s[1:4]` = 'yth'.\n- `s[:3]` — басынан, `s[2:]` — соңына дейін, `s[-2:]` — соңғы екеуі.\n- `s[::2]` — біреуін аралатып, `s[::-1]` — төңкеру. Тілім шекарадан асса да қате бермейді.\n\n## Әдістер (жолды өзгертпейді, жаңасын қайтарады)\n- `upper()`, `lower()`, `replace(a, b)` (**барлық** `a` әрпін ауыстырады), `count(x)`, `find(x)` (бірінші x индексі немесе **-1**), `strip()`, `split()`, `'-'.join(тізім)`.\n- `x in s` — бөлік жолда бар ма; палиндром: `s == s[::-1]`.\n- `ord('A')` = 65, `chr(97)` = 'a'.\n\n## Аралау\n`for ch in s:` — цикл денесі `len(s)` рет орындалады. Дауыстылар: `ch in 'aeiou'`; цифрлар: `ch.isdigit()`.\n\n## ҰБТ тұзақтары\n- Нөлдің орнына бірден санау.\n- Тілімнің оң жақ шекарасы **кірмейді**.\n- Нәтиже жазылмаса, `s.upper()` ештеңені өзгертпейді; `s[0] = 'A'` — қате."},
  "py-4a-index": {"ru":"# Индексы строки\n\n- У каждой буквы строки есть номер — **индекс**: `s[0]` — первая буква.\n- Счёт с начала идёт **с нуля**, с конца — **с минус единицы**: `s[-1]` — последняя буква, `s[-2]` — предпоследняя.\n- `len(s)` — длина строки; последний индекс — `len(s) - 1`.\n- `s[-k]` и `s[len(s) - k]` — одно и то же место.\n- Номера нет в строке — ошибка `IndexError`: `s[len(s)]`, `s[-len(s) - 1]`.\n\n## Ловушки ЕНТ\n- `s[1]` — **вторая** буква, а не первая.\n- Последняя буква — `s[len(s) - 1]`, а не `s[len(s)]`.","kk":"# Жол индекстері\n\n- Жолдың әр әрпінің нөмірі бар — **индекс**: `s[0]` — бірінші әріп.\n- Басынан санау **нөлден**, соңынан санау **минус бірден** басталады: `s[-1]` — соңғы әріп, `s[-2]` — соңғысының алдындағысы.\n- `len(s)` — жолдың ұзындығы; соңғы индекс — `len(s) - 1`.\n- `s[-k]` және `s[len(s) - k]` — бір орын.\n- Жолда жоқ нөмір — `IndexError` қатесі: `s[len(s)]`, `s[-len(s) - 1]`.\n\n## ҰБТ тұзақтары\n- `s[1]` — **екінші** әріп, бірінші емес.\n- Соңғы әріп — `s[len(s) - 1]`, ал `s[len(s)]` емес."},
  "py-4a-slice": {"ru":"# Срез [a:b]\n\n- `s[a:b]` берёт буквы с номерами от `a` до `b - 1`: левая граница **входит**, правая — **нет**.\n- Букв в срезе — `b - a`: в `s[1:4]` их три.\n- Нет начала — считаем с 0: `s[:3]`. Нет конца — до самого конца: `s[4:]`. Нет обоих — вся строка: `s[:]`.\n- Граница больше длины — **не ошибка**: `s[4:100]` берёт, сколько есть. Нечего брать — пустая строка `''`.\n- Сама строка `s` от среза не меняется.\n\n## Ловушки ЕНТ\n- Чтобы буква с номером `k` вошла последней, правая граница — `k + 1`.\n- Срез не ломается, а одиночный индекс `s[100]` — ошибка `IndexError`.","kk":"# [a:b] тілімі\n\n- `s[a:b]` `a` мен `b - 1` аралығындағы нөмірлі әріптерді алады: сол жақ шекара **кіреді**, оң жақ шекара — **кірмейді**.\n- Тілімдегі әріп саны — `b - a`: `s[1:4]` ішінде үш әріп бар.\n- Басы жоқ — нөлден санаймыз: `s[:3]`. Соңы жоқ — ең соңына дейін: `s[4:]`. Екеуі де жоқ — бүкіл жол: `s[:]`.\n- Шекара ұзындықтан үлкен болса — **қате емес**: `s[4:100]` бар болғанын алады. Алатын ештеңе жоқ — бос жол `''`.\n- `s` жолының өзі тілімнен өзгермейді.\n\n## ҰБТ тұзақтары\n- `k` нөмірлі әріп соңғы болып кіруі үшін оң жақ шекара — `k + 1`.\n- Тілім бұзылмайды, ал жеке индекс `s[100]` — `IndexError` қатесі."},
  "py-4a-step": {"ru":"# Срез с шагом\n\n- `s[a:b:c]` — третье число `c` — **шаг**. Нет шага — он равен 1.\n- Положительный шаг идёт вправо: `s[::2]` — каждая вторая буква с номера 0, `s[1::2]` — с номера 1.\n- Отрицательный шаг идёт **влево**: `s[::-1]` — строка наоборот, `s[::-2]` — с конца через одну букву.\n- Минус в границе — счёт **с конца**: `s[-3:]` — три последние буквы, `s[:-1]` — без последней.\n- Правая граница по-прежнему **не входит**.\n- Шаг `0` — ошибка `ValueError`.\n\n## Ловушки ЕНТ\n- `s[:-1]` отрезает последнюю букву, а `s[-1]` берёт только её.\n- Цепочку `s[::-1][1:4]` читай слева направо: сначала переворот.","kk":"# Қадамды тілім\n\n- `s[a:b:c]` ішіндегі үшінші сан `c` — **қадам**. Қадам көрсетілмесе, ол бірге тең.\n- Оң қадам оңға жүреді: `s[::2]` — 0 нөмірінен әр екінші әріп, `s[1::2]` — 1 нөмірінен бастап.\n- Теріс қадам **солға** жүреді: `s[::-1]` — жолды төңкеру, `s[::-2]` — соңынан бір әріпті аралатып.\n- Шекарадағы минус — **соңынан** санау: `s[-3:]` — соңғы үш әріп, `s[:-1]` — соңғысынсыз.\n- Оң жақ шекара бұрынғыдай **кірмейді**.\n- `0` қадамы — `ValueError` қатесі.\n\n## ҰБТ тұзақтары\n- `s[:-1]` соңғы әріпті кеседі, ал `s[-1]` тек соңғы әріпті алады.\n- `s[::-1][1:4]` тізбегін солдан оңға оқы: алдымен төңкеру."},
  "py-4b-methods": {"ru":"# Срезы и методы строк\n\n## Срез с шагом\n- `s[a:b:c]`: от `a` до `b` (**b не входит**) с шагом `c`.\n- `c > 0` — вправо, `c < 0` — **влево** (начало правее конца). `s[::-1]` — переворот, `s[::-2]` — с конца через один.\n- Идти нельзя — пустая строка `''`, не ошибка. Вылет за границы тоже не ошибка.\n- Минус в границе — счёт с конца: `s[-3:]` — три последних символа.\n\n## Поиск\n- `find(x)` — индекс первого `x` или **-1**; `find(x, k)` — искать с индекса `k`; `index(x)` — как find, но `ValueError`.\n- `count(x)` — без пересечений: `'aaa'.count('aa')` = 1.\n- `startswith(x)`, `endswith(x)` — True/False.\n\n## Преобразование (возвращают новую строку!)\n- `strip()` — пробелы с краёв; `replace(a, b, n)` — первые `n` замен.\n- `split()` — по любым пробелам, без пустых частей; `split(' ')` и `split(',')` — пустые части остаются.\n- `'-'.join(части)` — склеить (только строки).\n\n## Заготовки\n- `s == s[::-1]` — палиндром; `len(s.split())` — число слов; `s[k:] + s[:k]` — сдвиг.\n\n## Ловушки ЕНТ\n- `s[find(...)]` при -1 даёт последний символ.\n- `s.upper()` без записи ничего не меняет.\n- Цепочку читай слева направо.","kk":"# Жол тілімдері және әдістері\n\n## Қадамды тілім\n- `s[a:b:c]`: `a` индексінен `b` индексіне дейін (**b кірмейді**), қадам `c`.\n- `c > 0` — оңға, `c < 0` — **солға** (басы соңынан оңырақ). `s[::-1]` — төңкеру, `s[::-2]` — соңынан біреуін аралатып.\n- Жүруге болмаса — бос жол `''`, қате емес. Шекарадан асу да қате емес.\n- Шекарадағы минус — соңынан санау: `s[-3:]` — соңғы үш символ.\n\n## Іздеу\n- `find(x)` — бірінші `x` индексі немесе **-1**; `find(x, k)` — `k` индексінен бастап іздеу; `index(x)` — find сияқты, бірақ `ValueError`.\n- `count(x)` — қиылыспай санайды: `'aaa'.count('aa')` = 1.\n- `startswith(x)`, `endswith(x)` — True/False.\n\n## Түрлендіру (жаңа жол қайтарады!)\n- `strip()` — шеттеріндегі бос орындар; `replace(a, b, n)` — алғашқы `n` ауыстыру.\n- `split()` — кез келген бос орын бойынша, бос бөліксіз; `split(' ')` және `split(',')` — бос бөліктер қалады.\n- `'-'.join(бөліктер)` — жалғау (тек жолдар).\n\n## Үлгілер\n- `s == s[::-1]` — палиндром; `len(s.split())` — сөз саны; `s[k:] + s[:k]` — жылжыту.\n\n## ҰБТ тұзақтары\n- -1 болғанда `s[find(...)]` соңғы символды береді.\n- Нәтиже жазылмаса, `s.upper()` ештеңені өзгертпейді.\n- Тізбекті солдан оңға оқы."},
  "py-5-lists": {"ru":"# Списки в Python\n\n## Основное\n\n- `a = [5, 2, 8]` — список. Индексы идут **с нуля**: `a[0]` = 5, `a[-1]` — последний.\n- `len(a)` — число элементов; последний индекс = `len(a) - 1`.\n- Список можно менять: `a[0] = 10`.\n\n## Методы\n\n- `append(x)` — в конец; `insert(i, x)` — на место i.\n- `pop()` — убрать последний и **вернуть**; `pop(i)` — убрать элемент с индексом i.\n- `remove(x)` — убрать **первое** значение x.\n- `sort()` и `reverse()` меняют список и возвращают `None`; `sorted(a)` — новый список.\n- `count(x)`, `index(x)`, `sum`, `min`, `max`.\n\n## Перебор и алгоритмы\n\n- `for x in a` — по значениям; `for i in range(len(a))` — по индексам. Присваивание `x = …` в цикле по значениям список **не меняет**.\n- Сумма: `s += x`. Максимум: `m = a[0]`, затем `if a[i] > m`. Счёт: `c += 1` при условии.\n- Срез `a[1:3]` — индексы 1 и 2 (конец не входит). Генератор: `[x * 2 for x in a if x > 0]`.\n\n## Ловушки ЕНТ\n\n- `b = a.sort()` даёт `b = None`.\n- `b = a` — **один и тот же** список; копия — `a.copy()` или `a[:]`.\n- `a[len(a)]` — ошибка `IndexError`.","kk":"# Python-дағы тізімдер\n\n## Негізгі\n\n- `a = [5, 2, 8]` — тізім. Индекстер **нөлден** басталады: `a[0]` = 5, `a[-1]` — соңғы элемент.\n- `len(a)` — элементтер саны; соңғы индекс = `len(a) - 1`.\n- Тізімді өзгертуге болады: `a[0] = 10`.\n\n## Әдістер\n\n- `append(x)` — соңына; `insert(i, x)` — i орнына.\n- `pop()` — соңғысын алып тастап, **қайтарады**; `pop(i)` — i индексті элементті алып тастайды.\n- `remove(x)` — x мәнінің **бірінші** кездесуін алып тастайды.\n- `sort()` және `reverse()` тізімді өзгертеді және `None` қайтарады; `sorted(a)` — жаңа тізім.\n- `count(x)`, `index(x)`, `sum`, `min`, `max`.\n\n## Аралау және алгоритмдер\n\n- `for x in a` — мәндер бойынша; `for i in range(len(a))` — индекстер бойынша. Мәндер бойынша циклде `x = …` меншіктеуі тізімді **өзгертпейді**.\n- Қосынды: `s += x`. Максимум: `m = a[0]`, сосын `if a[i] > m`. Санау: шарт орындалса `c += 1`.\n- `a[1:3]` тілімі — 1 және 2 индекстер (соңы кірмейді). Генератор: `[x * 2 for x in a if x > 0]`.\n\n## ҰБТ тұзақтары\n\n- `b = a.sort()` нәтижесінде `b = None`.\n- `b = a` — **бір** тізім; көшірме — `a.copy()` немесе `a[:]`.\n- `a[len(a)]` — `IndexError` қатесі."},
  "py-5b-listops": {"ru":"# Списки: методы и обработка\n\n## Собрать\n\n- `[0] * n` — n нулей (повторяет список целиком); `a + b` — **новый** склеенный список.\n- `a.extend(b)` — дописать элементы b по одному; `a.append(b)` — добавить b **одним** элементом.\n- `list(range(1, 6))` → `[1, 2, 3, 4, 5]`; `[int(x) for x in s.split()]` — числа из строки.\n\n## Искать и убирать\n\n- `x in a` — есть ли; `x not in a` — нет ли; итоги — `len`, `sum`, `min`, `max`.\n- По номеру: `del a[i]`, `a.pop(i)`; по значению: `a.remove(x)` (только первое); `a.clear()` — всё.\n- Нет значения — `ValueError`; нет номера — `IndexError`.\n\n## Сортировка и перебор\n\n- `a.sort(reverse=True)` — по убыванию на месте; `sorted(a, reverse=True)` — новый список.\n- `for x in a` — только читать; `for i in range(len(a))` — менять `a[i]` и брать соседей `a[i + 1]`.\n- `[x * 2 for x in a if x > 5]` — отбор и преобразование одной строкой.\n\n## Ловушки ЕНТ\n\n- Удаление из списка внутри `for x in a` **пропускает** элементы: перебирай копию `a[:]` или собирай новый список.\n- `remove(x)` убирает первое `x` в списке, а не то, на котором стоит цикл.\n- `a = a.append(1)` даёт `None`; `b = a + [1]` не меняет `a`.","kk":"# Тізімдер: әдістер және өңдеу\n\n## Жинау\n\n- `[0] * n` — n нөл (тізімді тұтас қайталайды); `a + b` — **жаңа** жалғанған тізім.\n- `a.extend(b)` — b элементтерін бір-бірлеп қосу; `a.append(b)` — b тізімін **бір** элемент ретінде қосу.\n- `list(range(1, 6))` → `[1, 2, 3, 4, 5]`; `[int(x) for x in s.split()]` — жолдан сандар алу.\n\n## Іздеу және алып тастау\n\n- `x in a` — бар ма; `x not in a` — жоқ па; қорытынды — `len`, `sum`, `min`, `max`.\n- Нөмір бойынша: `del a[i]`, `a.pop(i)`; мән бойынша: `a.remove(x)` (тек біріншісі); `a.clear()` — бәрі.\n- Мән жоқ — `ValueError`; нөмір жоқ — `IndexError`.\n\n## Сұрыптау және аралау\n\n- `a.sort(reverse=True)` — кему бойынша орнында; `sorted(a, reverse=True)` — жаңа тізім.\n- `for x in a` — тек оқу; `for i in range(len(a))` — `a[i]` мәнін өзгерту және `a[i + 1]` көршісін алу.\n- `[x * 2 for x in a if x > 5]` — іріктеу мен түрлендіруді бір жолда жазу.\n\n## ҰБТ тұзақтары\n\n- `for x in a` ішінде тізімнен алып тастау элементтерді **өткізіп жібереді**: `a[:]` көшірмесін аралау немесе жаңа тізім жинау керек.\n- `remove(x)` тізімдегі бірінші `x` мәнін алады, цикл тұрған мәнді емес.\n- `a = a.append(1)` — `None` береді; `b = a + [1]` — `a` тізімін өзгертпейді."},
  "py-5c-matrix": {"ru":"# Двумерные списки\n\n- Матрица — список списков: `a = [[5, 2, 8], [1, 7, 4]]`. `a[i]` — целая строка, `a[i][j]` — элемент: **сначала строка, потом столбец**, оба номера с нуля.\n- Размеры: `len(a)` — число строк, `len(a[0])` — число столбцов, всего `len(a) * len(a[0])` элементов. Последний элемент — `a[-1][-1]`.\n- Обход: `for i in range(n): for j in range(m): … a[i][j]`. Тело внутреннего цикла выполнится n · m раз. Пустой `print()` после внутреннего цикла — переход на новую строку.\n- Сумма строки i: `s += a[i][j]` (бежит j). Сумма столбца j: `s += a[i][j]` (бежит i).\n- Главная диагональ: `a[i][i]`. Побочная: `a[i][n - 1 - i]`. Над главной: `j > i`, то есть `for j in range(i + 1, n)`.\n\n## Ловушки ЕНТ\n\n- `[[0] * 3] * 3` — три ссылки на **одну** строку. Правильно: `[[0] * 3 for i in range(3)]`.\n- Выход за границы: строк `len(a)`, последний индекс `len(a) - 1`; `a[3][0]` в матрице из трёх строк — `IndexError`.\n- Перепутанные `i` и `j` дают чужой элемент, а в неквадратной матрице могут дать `IndexError`.","kk":"# Екіөлшемді тізімдер\n\n- Матрица — тізімдер тізімі: `a = [[5, 2, 8], [1, 7, 4]]`. `a[i]` — тұтас жол, `a[i][j]` — элемент: **алдымен жол, сосын баған**, екі нөмір де нөлден басталады.\n- Өлшемдері: `len(a)` — жолдар саны, `len(a[0])` — бағандар саны, барлығы `len(a) * len(a[0])` элемент. Соңғы элемент — `a[-1][-1]`.\n- Аралау: `for i in range(n): for j in range(m): … a[i][j]`. Ішкі циклдің денесі n · m рет орындалады. Ішкі циклден кейінгі бос `print()` — жаңа жолға өту.\n- i-жол қосындысы: `s += a[i][j]` (j жүгіреді). j-баған қосындысы: `s += a[i][j]` (i жүгіреді).\n- Бас диагональ: `a[i][i]`. Қосалқы: `a[i][n - 1 - i]`. Бас диагональ үстінде: `j > i`, яғни `for j in range(i + 1, n)`.\n\n## ҰБТ тұзақтары\n\n- `[[0] * 3] * 3` — **бір** жолға үш сілтеме. Дұрысы: `[[0] * 3 for i in range(3)]`.\n- Шектен шығу: жолдар саны `len(a)`, соңғы индекс `len(a) - 1`; үш жолды матрицада `a[3][0]` — `IndexError`.\n- `i` мен `j` шатастырылса, басқа элемент алынады, ал шаршы емес матрицада `IndexError` шығуы мүмкін."},
  "py-6-functions": {"ru":"# Функции и рекурсия\n\n## Функция\n\n- `def f(x):` — **определение**: записывает правило, но не запускает его.\n- `f(3)` — **вызов**: 3 — **аргумент**, он попадает в **параметр** x.\n- `return` отдаёт результат и **сразу завершает** функцию — строки после него не выполняются.\n- Нет `return` — функция возвращает **None**.\n- **print ≠ return**: print только показывает на экране.\n- Переменные внутри функции **локальные**: снаружи их нет (будет ошибка NameError).\n\n## Рекурсия\n\nФункция вызывает **саму себя**. Нужны две части: **базовый случай** (ответ известен, вызова нет) и **шаг** (вызов с **меньшим** аргументом).\n\n> fact(n) = n * fact(n − 1), fact(1) = 1 → fact(4) = 4 · 3 · 2 · 1 = **24**\n\n## Лайфхаки для ЕНТ\n\n- Выписывай вызовы в столбик: вниз — до базового случая, вверх — возврат ответов.\n- Число вызовов при f(n) = f(n − 1) + f(n − 2) считай по дереву вызовов: для f(5) с базовым случаем n ≤ 2 — 9 вызовов.\n- `print` **до** рекурсивного вызова даёт «вниз» (3, 2, 1), **после** — «вверх» (1, 2, 3).\n- В `print(f(x))` функция без `return` даёт **None**.\n\n## Частые ошибки\n\n- Забыт базовый случай — бесконечная рекурсия (RecursionError).\n- `print` вместо `return`.\n- Перепутан порядок аргументов.","kk":"# Функциялар және рекурсия\n\n## Функция\n\n- `def f(x):` — **анықтама**: ережені жазады, бірақ іске қоспайды.\n- `f(3)` — **шақыру**: 3 — **аргумент**, ол x **параметріне** түседі.\n- `return` нәтиже береді және функцияны **бірден аяқтайды** — одан кейінгі жолдар орындалмайды.\n- `return` жоқ — функция **None** қайтарады.\n- **print ≠ return**: print тек экранға көрсетеді.\n- Функция ішіндегі айнымалылар **жергілікті**: сыртта олар жоқ (NameError).\n\n## Рекурсия\n\nФункция **өзін-өзі** шақырады. Екі бөлік керек: **базалық жағдай** (жауап белгілі, шақыру жоқ) және **қадам** (**кішірек** аргументпен шақыру).\n\n> fact(n) = n * fact(n − 1), fact(1) = 1 → fact(4) = 4 · 3 · 2 · 1 = **24**\n\n## ҰБТ-ға арналған кеңестер\n\n- Шақыруларды бағанға жаз: төмен — базалық жағдайға дейін, жоғары — жауаптарды қайтару.\n- f(n) = f(n − 1) + f(n − 2) болғанда шақырулар санын шақырулар ағашы бойынша сана: n ≤ 2 базалық жағдайымен f(5) үшін — 9 шақыру.\n- Рекурсивті шақыруға **дейінгі** `print` «төмен» (3, 2, 1), **одан кейінгі** — «жоғары» (1, 2, 3) береді.\n- `print(f(x))` ішінде `return` жоқ функция **None** береді.\n\n## Жиі кететін қателер\n\n- Базалық жағдай ұмытылған — шексіз рекурсия (RecursionError).\n- `return` орнына `print`.\n- Аргументтер реті шатастырылған."},
  "py-6b-params": {"ru":"# Функции: параметры и return\n\n## Параметры и аргументы\n\n- Аргументы попадают в параметры **по порядку**: `diff(5, 2)` ≠ `diff(2, 5)`.\n- По имени: `diff(b=2, a=5)` — порядок не важен.\n- **Значение по умолчанию**: `def f(a, b=10)`. Не передан — берётся 10, передан — заменяет. Такие параметры идут **в конце**.\n- Лишний или недостающий аргумент — TypeError.\n\n## Возврат\n\n- `return a, b` отдаёт пару (кортеж): `x, y = f(…)`.\n- Нет `return` (или сработала ветка без него) — результат **None**. `print` ≠ `return`.\n- `f(a)` без присваивания не меняет a: пиши `a = f(a)`.\n\n## Область видимости\n\n- Параметры и переменные внутри функции — **локальные**, снаружи их нет.\n- Глобальную можно **читать** без `global`; `x = …` внутри создаёт новую локальную x.\n- Изменить глобальную: `global x`.\n\n## Лайфхаки для ЕНТ\n\n- Для каждого вызова выпиши таблицу a, b, c.\n- Вызов в вызове считай изнутри наружу.\n- Две x с одним именем — разные: ищи, где объявлена.","kk":"# Функциялар: параметрлер және return\n\n## Параметрлер мен аргументтер\n\n- Аргументтер параметрлерге **ретімен** түседі: `diff(5, 2)` ≠ `diff(2, 5)`.\n- Атымен: `diff(b=2, a=5)` — рет маңызды емес.\n- **Әдепкі мән**: `def f(a, b=10)`. Берілмесе — 10 алынады, берілсе — ауыстырады. Мұндай параметрлер **соңында** тұрады.\n- Артық немесе жетпейтін аргумент — TypeError.\n\n## Қайтару\n\n- `return a, b` жұп (кортеж) береді: `x, y = f(…)`.\n- `return` жоқ (немесе `return` жоқ тармақ орындалды) — нәтиже **None**. `print` ≠ `return`.\n- `f(a)` меншіктеусіз a мәнін өзгертпейді: `a = f(a)` деп жаз.\n\n## Көріну аймағы\n\n- Параметрлер мен функция ішіндегі айнымалылар — **жергілікті**, сыртта жоқ.\n- Глобалды айнымалыны `global` сөзінсіз де **оқуға** болады; ішінде `x = …` жаңа жергілікті x жасайды.\n- Глобалды айнымалыны өзгерту: `global x`.\n\n## ҰБТ-ға арналған кеңестер\n\n- Әр шақыру үшін a, b, c кестесін жаз.\n- Шақыру ішіндегі шақыруды ішінен сыртқа қарай есепте.\n- Аты бірдей екі x — әртүрлі: олардың қайда жарияланғанын тап."},
  "py-6c-recursion": {"ru":"# Рекурсия по шагам\n\n## Три вопроса к любой рекурсии\n\n1. **База**: когда вызовов больше нет?\n2. **Шаг**: с каким аргументом функция зовёт себя, приближается ли он к базе?\n3. **До и после**: что стоит до вызова (спуск), что после (подъём)?\n\n## Правила\n\n- Код **до** вызова идёт на спуске: n от большого к малому. Код **после** — на подъёме: от малого к большому.\n- Ответ с `return` собирается на подъёме: `pw(a, n) = a * pw(a, n - 1)`, база `n == 0` даёт 1 (у `fact` база `n == 1`).\n- Забытый `return` в шаге даёт **None**.\n- Аргумент должен дойти до базы: `n + f(n - 2)` с базой `n == 0` для нечётного n даёт **RecursionError**.\n- Два вызова подряд: `f(n - 1); print(n); f(n - 1)` выводит 2ⁿ − 1 чисел при 2ⁿ⁺¹ − 1 вызовах.\n\n## Шаблоны ЕНТ\n\n- Сумма цифр: `n % 10 + s(n // 10)`, база n == 0.\n- НОД: `gcd(b, a % b)`, база b == 0 → a.\n- Двоичная запись: `b(n // 2)`, затем `print(n % 2, end=\"\")`. Печать **до** вызова даёт цифры в обратном порядке.\n- Фибоначчи: `f(n - 1) + f(n - 2)`, база n <= 1. Вызовов C(n) = 1 + C(n − 1) + C(n − 2): для f(6) их 25.","kk":"# Рекурсия қадам бойынша\n\n## Кез келген рекурсияға үш сұрақ\n\n1. **База**: шақырулар қашан бітеді?\n2. **Қадам**: функция өзін қандай аргументпен шақырады, ол базаға жақындай ма?\n3. **Дейін және кейін**: шақыруға дейін не тұр (түсу), одан кейін не тұр (көтерілу)?\n\n## Ережелер\n\n- Шақыруға **дейінгі** код түсу кезінде орындалады: n үлкеннен кішіге қарай. **Кейінгі** код — көтерілу кезінде: кішіден үлкенге қарай.\n- `return` бар жауап көтерілу кезінде жиналады: `pw(a, n) = a * pw(a, n - 1)`, `n == 0` базасы 1 береді (`fact` базасы — `n == 1`).\n- Қадамда ұмытылған `return` **None** береді.\n- Аргумент базаға жетуі керек: тақ n үшін `n == 0` базалы `n + f(n - 2)` **RecursionError** береді.\n- Қатар екі шақыру: `f(n - 1); print(n); f(n - 1)` 2ⁿ⁺¹ − 1 шақыруда 2ⁿ − 1 сан шығарады.\n\n## ҰБТ үлгілері\n\n- Цифрлар қосындысы: `n % 10 + s(n // 10)`, база n == 0.\n- ЕҮОБ: `gcd(b, a % b)`, база b == 0 → a.\n- Екілік жазба: `b(n // 2)`, содан кейін `print(n % 2, end=\"\")`. Шақыруға **дейінгі** шығару цифрларды кері тәртіппен береді.\n- Фибоначчи: `f(n - 1) + f(n - 2)`, база n <= 1. Шақырулар C(n) = 1 + C(n − 1) + C(n − 2): f(6) үшін 25."},
  "py-7-algos": {"ru":"# Сортировка, поиск, файлы и графы\n\n## Поиск\n- **Линейный** — по одному; в худшем случае **n** сравнений.\n- **Двоичный** — только в **отсортированном** списке: берём середину, отбрасываем половину. Для 1000 элементов не более **10** сравнений (2¹⁰ = 1024 > 1000).\n\n## Сортировка\n- **Пузырёк:** сравниваем соседей, левый больше — меняем; после каждого прохода наибольший «всплывает» в конец. Проходов не больше n − 1.\n- **Выбор:** на каждом проходе ставим наименьшее из оставшихся на своё место.\n- `sorted(a)` — новый список; `a.sort()` — сортирует `a` и возвращает `None`; `reverse=True`, `key=len`.\n\n## Файлы\n- `with open(\"data.txt\", \"r\", encoding=\"utf-8\") as f:`; `f.read()`, `f.readline()`, `for line in f`; `strip()` убирает `\\n`.\n- **'r'** — чтение; **'w'** — запись с нуля (**стирает** файл); **'a'** — дописать в конец.\n\n## Графы\n- Вершины и рёбра, вес ребра; таблица: строка — откуда, столбец — куда, прочерк — дороги нет.\n- **Кратчайший путь:** выпиши пути или ставь метки; меньше дорог не значит короче.\n- **Число путей** (без циклов): для вершины складываем числа путей предшественников.\n\n## Ловушки ЕНТ\n- Одного прохода пузырька мало для полной сортировки.\n- `a = a.sort()` даёт `None`.\n- Дописать — 'a', а не 'w'.","kk":"# Сұрыптау, іздеу, файлдар және графтар\n\n## Іздеу\n- **Сызықтық** — бір-бірлеп қарау; ең нашар жағдайда **n** салыстыру.\n- **Екілік** — тек **сұрыпталған** тізімде: ортасын аламыз, жартысын тастаймыз. 1000 элемент үшін ең көбі **10** салыстыру (2¹⁰ = 1024 > 1000).\n\n## Сұрыптау\n- **Көпіршік:** көршілерді салыстырамыз, сол жақтағысы үлкен болса — ауыстырамыз; әр өтуден кейін ең үлкені соңына «қалқып» шығады. Өтулер саны n − 1-ден көп емес.\n- **Таңдау:** әр өтуде қалғандарының ең кішісін өз орнына қоямыз.\n- `sorted(a)` — жаңа тізім; `a.sort()` — `a` тізімін сұрыптайды және `None` қайтарады; `reverse=True`, `key=len`.\n\n## Файлдар\n- `with open(\"data.txt\", \"r\", encoding=\"utf-8\") as f:`; `f.read()`, `f.readline()`, `for line in f`; `strip()` `\\n` таңбасын алып тастайды.\n- **'r'** — оқу; **'w'** — басынан жазу (файлды **өшіреді**); **'a'** — соңына жалғау.\n\n## Графтар\n- Төбелер мен қабырғалар, қабырғаның салмағы; кесте: жол — қайдан, баған — қайда, сызықша — жол жоқ.\n- **Ең қысқа маршрут:** маршруттарды жаз немесе белгілер қой; жолы аз маршрут қысқа бола бермейді.\n- **Маршруттар саны** (циклсіз): төбе үшін алдыңғы төбелердің маршрут сандарын қосамыз.\n\n## ҰБТ тұзақтары\n- Толық сұрыптау үшін көпіршіктің бір өтуі аз.\n- `a = a.sort()` `None` береді.\n- Соңына жалғау — 'a', 'w' емес."},
  "py-7a-sort": {"ru":"# Сортировки\n\n## Пузырёк\n- Идём слева направо, сравниваем **соседей**, левый больше — меняем. После k проходов **k наибольших стоят в конце**.\n- Сравнений всегда **n(n − 1) / 2** (n = 5 → 10, n = 10 → 45), от чисел это не зависит. Обменов столько, сколько «неправильных пар» (левое больше правого): у упорядоченного списка 0, у списка по убыванию n(n − 1) / 2.\n- Проход без обменов — список уже упорядочен.\n\n## Выбор\n- На проходе ищем **наименьшее** в неупорядоченной части и меняем с первым. После k проходов **k наименьших стоят в начале**. Обменов не больше n − 1.\n\n## Python\n- `sorted(a)` — новый список; `a.sort()` — меняет `a` и даёт `None`; `reverse=True` — по убыванию; `key=len` — по длине.\n- Сортировка **устойчивая**: равные ключи остаются в исходном порядке (и при `reverse=True`).\n- Строки сравниваются посимвольно: `['10', '100', '2', '9']`.\n\n## Ловушки ЕНТ\n- Один и тот же список после 2 проходов у пузырька и у выбора выглядит по-разному.\n- `a = a.sort()` даёт `None`.","kk":"# Сұрыптау\n\n## Көпіршік\n- Солдан оңға қарай жүріп, **көршілерді** салыстырамыз, сол жағы үлкен болса — ауыстырамыз. k өтуден кейін **k ең үлкені соңында тұрады**.\n- Салыстыру әрқашан **n(n − 1) / 2** (n = 5 → 10, n = 10 → 45), ол сандарға байланысты емес. Алмасу саны «дұрыс емес жұптар» санына тең (сол жағы үлкен): реттелген тізімде 0, кему ретіндегі тізімде n(n − 1) / 2.\n- Алмасусыз өту — тізім реттелген.\n\n## Таңдау\n- Өтуде сұрыпталмаған бөліктен **ең кішісін** тауып, бірінші элементпен ауыстырамыз. k өтуден кейін **k ең кішісі басында тұрады**. Алмасу n − 1-ден көп емес.\n\n## Python\n- `sorted(a)` — жаңа тізім; `a.sort()` — `a` тізімін өзгертеді және `None` береді; `reverse=True` — кему ретімен; `key=len` — ұзындығы бойынша.\n- Сұрыптау **тұрақты**: тең кілттер бастапқы ретімен қалады (`reverse=True` болса да).\n- Жолдар таңба бойынша салыстырылады: `['10', '100', '2', '9']`.\n\n## ҰБТ тұзақтары\n- Бір тізімнің 2 өтуден кейінгі күйі көпіршікте және таңдауда әртүрлі болады.\n- `a = a.sort()` `None` береді."},
  "py-7b-search": {"ru":"# Линейный и бинарный поиск\n\n## Линейный поиск\n- Элементы по одному; список **любой**. Лучший случай — 1 сравнение, худший — **n**.\n- `x in a` — есть ли; `a.index(x)` — индекс первого, а если нет — ошибка `ValueError` (не `-1`).\n- С `break` — первое вхождение; без `break` в переменной остаётся последнее.\n\n## Двоичный поиск\n- Только в **отсортированном** списке. Для неотсортированного даёт неверный `-1`.\n- `l = 0`, `r = len(a) - 1`; пока `l <= r`: `m = (l + r) // 2`.\n- `a[m] == x` — нашли; `a[m] < x` — `l = m + 1`; иначе — `r = m - 1`; не нашли — `-1`.\n- С `while l < r` вместо `l <= r` последний оставшийся элемент (l = r) не проверяется.\n\n## Сколько шагов\n- Наибольшее число шагов k — наименьшее, при котором **2ᵏ > n**.\n- За k шагов проверяется до **2ᵏ − 1** элементов: 7, 15, 31, 63, …, 1023.\n- Ловушка: n = 8 → 4 шага, n = 1024 → 11 шагов (⌈log₂ n⌉ для степеней двойки на 1 меньше).\n- Ровно за k шагов находится 2ᵏ⁻¹ элементов.\n\n## Ловушки ЕНТ\n- Двоичный поиск не работает в неотсортированном списке и в списке по убыванию без правки кода.\n- Сортировка стоит дороже одного прохода: для одного поиска — линейный.","kk":"# Сызықтық және екілік іздеу\n\n## Сызықтық іздеу\n- Элементтер бір-бірлеп; тізім **кез келген**. Ең жақсы жағдай — 1 салыстыру, ең нашар — **n**.\n- `x in a` — бар ма; `a.index(x)` — бірінші элементтің индексі, ал жоқ болса — `ValueError` қатесі (`-1` емес).\n- `break` болса — бірінші кездесуі; `break` болмаса, айнымалыда соңғысы қалады.\n\n## Екілік іздеу\n- Тек **сұрыпталған** тізімде. Сұрыпталмағанда қате `-1` береді.\n- `l = 0`, `r = len(a) - 1`; `l <= r` болғанда: `m = (l + r) // 2`.\n- `a[m] == x` — таптық; `a[m] < x` — `l = m + 1`; әйтпесе — `r = m - 1`; таппасақ — `-1`.\n- `l <= r` орнына `while l < r` болса, қалған соңғы элемент (l = r) тексерілмейді.\n\n## Қанша қадам\n- Қадамның ең көп саны k — **2ᵏ > n** болатын ең кіші сан.\n- k қадамда **2ᵏ − 1** элементке дейін тексеріледі: 7, 15, 31, 63, …, 1023.\n- Тұзақ: n = 8 → 4 қадам, n = 1024 → 11 қадам (екінің дәрежелері үшін ⌈log₂ n⌉ 1-ге аз).\n- Дәл k қадамда 2ᵏ⁻¹ элемент табылады.\n\n## ҰБТ тұзақтары\n- Екілік іздеу сұрыпталмаған және кему ретіндегі тізімде кодты түзетпей жұмыс істемейді.\n- Сұрыптау бір рет өтуден қымбат: бір рет іздеу үшін — сызықтық іздеу."},
  "py-7c-files": {"ru":"# Работа с файлами\n\n## Открыть — работать — закрыть\n- `with open(\"data.txt\") as f:` закрывает файл сам; без `with` пишем `f.close()`.\n- Режимы: **'r'** читать (файла нет — ошибка), **'w'** писать с нуля (**стирает**), **'a'** дописать в конец. Без режима — `'r'`.\n\n## Чтение\n- `f.read()` — весь файл одной строкой; `f.readline()` — одна строка; `f.readlines()` — список строк; `for line in f` — по строке.\n- Каждая строка приходит с `\\n` (один символ). `print(line)` даёт лишнюю пустую строку, её убирает `strip()`.\n- Пустая строка `''` — признак конца файла. Читать из файла второй раз нечего («закладка» в конце): откройте заново или сохраните в список.\n\n## Числа и слова\n- `int('12\\n')` = 12; `'12 7 30\\n'.split()` = `['12', '7', '30']` (строки!). Перед сложением — `int(x)`.\n\n## Запись\n- `f.write(s)` принимает **только строку** и **не ставит `\\n`**: `f.write(str(x) + \"\\n\")`.\n- `print(x, file=f)` пишет в файл и сам ставит `\\n`.\n\n## Ловушки ЕНТ\n- Записи без `\\n` склеиваются в одну строку.\n- `'w'` вместо `'a'` стирает данные.\n- Число в `write` без `str()` — TypeError; пустая строка в `int()` — ValueError.","kk":"# Файлдармен жұмыс\n\n## Ашу — жұмыс істеу — жабу\n- `with open(\"data.txt\") as f:` файлды өзі жабады; `with` болмаса, `f.close()` жазамыз.\n- Режимдер: **'r'** оқу (файл жоқ болса — қате), **'w'** басынан жазу (**өшіреді**), **'a'** соңына жалғау. Режимсіз — `'r'`.\n\n## Оқу\n- `f.read()` — бүкіл файл бір жол болып; `f.readline()` — бір жол; `f.readlines()` — жолдар тізімі; `for line in f` — жолма-жол.\n- Әр жол `\\n` таңбасымен келеді (бір таңба). `print(line)` артық бос жол береді, оны `strip()` жояды.\n- Бос жол `''` — файл соңының белгісі. Файлдан екінші рет оқитын ештеңе жоқ («бетбелгі» соңында): қайта ашыңыз немесе тізімге сақтаңыз.\n\n## Сандар және сөздер\n- `int('12\\n')` = 12; `'12 7 30\\n'.split()` = `['12', '7', '30']` (жолдар!). Қосудан бұрын — `int(x)`.\n\n## Жазу\n- `f.write(s)` **тек жол** қабылдайды және **`\\n` қоймайды**: `f.write(str(x) + \"\\n\")`.\n- `print(x, file=f)` файлға жазады және `\\n` таңбасын өзі қояды.\n\n## ҰБТ тұзақтары\n- `\\n` таңбасы жоқ жазбалар бір жолға жабысады.\n- `'a'` орнына `'w'` деректерді өшіреді.\n- `write` ішінде `str()` арқылы аударылмаған сан — TypeError; `int()` ішіндегі бос жол — ValueError."},
  "py-7d-graphs": {"ru":"# Графы: матрица, степень, кратчайший путь\n\n## Виды графов\n- **Неориентированный** — линии, связь в обе стороны (дружба). **Ориентированный** — стрелки (подписка). **Взвешенный** — на рёбрах числа.\n- **Степень вершины** — число рёбер у неё. В ориентированном графе отдельно: выходят и входят стрелки.\n\n## Матрица смежности\n- Строка — откуда, столбец — куда, **1** — ребро есть. На диагонали нули.\n- Неориентированный: матрица **симметрична**, сумма всех чисел = 2 × число рёбер, сумма строки = степень.\n- Ориентированный: несимметрична, сумма = числу стрелок; сумма строки — выходящие, сумма столбца — входящие.\n\n## В Python\n- `m[i][j]`, степень — `sum(m[i])`, рёбра — `cnt // 2`. Номера вершин с нуля.\n\n## Кратчайший путь\n- Выпиши **все** маршруты без повторов вершин, сложи длины, возьми наименьшую. Прямая дорога не всегда короче.\n- «Через пункт D» или «дорога закрыта»: оставь подходящие маршруты.\n\n## Число путей (граф без циклов)\n- A = 1; путей в вершину = сумма путей в вершины, из которых в неё входят стрелки.\n\n## Ловушки ЕНТ\n- Сумма симметричной матрицы — вдвое больше числа рёбер.\n- `>` оставляет первую из равных вершин, `>=` — последнюю.","kk":"# Графтар: матрица, дәреже, ең қысқа маршрут\n\n## Графтың түрлері\n- **Бағытталмаған** — сызықтар, байланыс екі жаққа (достық). **Бағытталған** — көрсеткілер (жазылу). **Салмақты** — қабырғаларда сандар бар.\n- **Төбенің дәрежесі** — оған келетін қабырғалар саны. Бағытталған графта шығатын және кіретін көрсеткілер бөлек.\n\n## Көршілестік матрицасы\n- Жол — қайдан, баған — қайда, **1** — қабырға бар. Диагональда нөлдер.\n- Бағытталмаған: матрица **симметриялы**, барлық сандар қосындысы = 2 × қабырғалар саны, жол қосындысы = дәреже.\n- Бағытталған: симметриялы емес, қосынды = көрсеткілер саны; жол қосындысы — шығатындар, баған — кіретіндер.\n\n## Python-да\n- `m[i][j]`, дәреже — `sum(m[i])`, қабырғалар — `cnt // 2`. Нөмірлер нөлден.\n\n## Ең қысқа маршрут\n- Төбелері қайталанбайтын **барлық** маршрутты жаз, ұзындықтарын қос, ең кішісін ал. Тікелей жол әрдайым қысқа емес.\n- «D арқылы» не «жол жабық»: лайықты маршруттарды ғана қалдыр.\n\n## Маршруттар саны (циклсіз граф)\n- A = 1; төбеге баратын маршруттар = оған көрсеткі келетін төбелер маршруттарының қосындысы.\n\n## ҰБТ тұзақтары\n- Симметриялы матрицаның қосындысы қабырғалардан екі есе көп.\n- `>` тең төбелердің біріншісін, `>=` — соңғысын қалдырады."},
  "py-8-trace": {"ru":"# Что выведет программа\n\n## Пять шагов\n\n1. **Прочитай** программу целиком и пойми, что она делает.\n2. **Заведи таблицу:** столбец на каждую переменную, строка на каждый круг цикла.\n3. **Иди по строкам** сверху вниз, ничего не пропуская.\n4. **Проверь границы:** range, //, %, отступы, break, continue, порядок elif.\n5. **Вопросы «что, если…»:** меняй одну вещь и прогоняй заново.\n\n## Ловушки ЕНТ\n\n- `range(1, 4)` — это 1, 2, 3: конец **не входит**. При шаге 1 кругов: конец минус начало.\n- `n // 10` убирает последнюю цифру, `n % 10` — берёт её.\n- `print` с отступом — внутри цикла (на каждом круге), без отступа — после цикла (один раз).\n- `continue` — перейти к следующему кругу, `break` — выйти из цикла совсем; после `break` строки до конца круга не выполняются.\n- В `if / elif` срабатывает **первое** верное условие.\n- `>` и `>=` дают разные результаты при равных числах.\n\n## Лайфхаки\n\n- Лист А4 на ЕНТ — для таблицы; не считай в уме то, что можно записать.\n- На вопрос «что изменится» не пересчитывай всё: найди строку, которая влияет на ответ.\n- Проверь крайний случай: первый круг, последний круг и момент выхода из цикла.","kk":"# Программа не шығарады\n\n## Бес қадам\n\n1. Программаны толық **оқы** да, ол не істейтінін түсін.\n2. **Кесте жаса:** әр айнымалыға бір баған, циклдің әр айналымына бір жол.\n3. Жоғарыдан төмен **жолдар бойынша жүр**, ештеңені өткізіп алма.\n4. **Шектерді тексер:** range, //, %, шегіністер, break, continue, elif реті.\n5. **«Не болса…» сұрақтары:** бір нәрсені өзгертіп, қайта орында.\n\n## ҰБТ тұзақтары\n\n- `range(1, 4)` — бұл 1, 2, 3: соңы **кірмейді**. Қадам 1 болса, айналым саны: соңы минус басы.\n- `n // 10` соңғы цифрды алып тастайды, `n % 10` — оны алады.\n- Шегінісі бар `print` — циклдің ішінде (әр айналымда), шегінісіз — циклден кейін (бір рет).\n- `continue` — келесі айналымға өту, `break` — циклден толық шығу; `break` орындалған соң айналым соңына дейінгі жолдар орындалмайды.\n- `if / elif` ішінде **бірінші** ақиқат шарт орындалады.\n- `>` және `>=` тең сандарда әртүрлі нәтиже береді.\n\n## Кеңестер\n\n- ҰБТ-дағы А4 парағы — кесте үшін; жазуға болатынды ойша санама.\n- «Не өзгереді» сұрағында бәрін қайта санама: жауапқа әсер ететін жолды тап.\n- Шеткі жағдайды тексер: бірінші айналым, соңғы айналым және циклден шығу сәті."},
  "py-8b-context": {"ru":"# Контекстные задания: касса\n\nКонтекстное задание ЕНТ: **описание, программа на Python и пять вопросов**. Программу читаем один раз, потом отвечаем на всё.\n\n## План\n\n1. Прочитай описание и программу **по-человечески**: что значат переменные, что делает каждый блок.\n2. Выполни программу один раз с таблицей (столбец на переменную, строка на круг).\n3. Каждый `input()` берёт **следующее** число ввода; каждый `print` — отдельная строка вывода.\n\n## Шесть видов вопросов\n\n- **Что выведет** — трассировка при заданном вводе.\n- **Сколько раз** выполнится строка — отметь круги, где выполнение до неё доходит.\n- **Зачем** строка — мысленно убери её и сравни результаты.\n- **Что изменится** — меняй одну вещь и пересчитай.\n- **Какую строку изменить** — найди строку, отвечающую за нужное правило.\n- **Какой ввод** даст вывод — иди от результата назад, проверь подстановкой.\n\n## Ловушки\n\n- `<` и `<=`: на границе ответ меняется.\n- `x == 0` с `break` проверяй раньше `x < 100` с `continue`.\n- Скидка `x // 10` отбрасывает дробную часть.\n- Если описание и код спорят, верь коду.","kk":"# Контекстік тапсырмалар: касса\n\nҰБТ-ның контекстік тапсырмасы: **сипаттама, Python программасы және бес сұрақ**. Программаны бір рет оқимыз, содан кейін бәріне жауап береміз.\n\n## Жоспар\n\n1. Сипаттаманы және программаны **адамша** оқы: айнымалылар не білдіреді, әр блок не істейді.\n2. Программаны кестемен бір рет орында (әр айнымалыға баған, әр айналымға жол).\n3. Әр `input()` енгізудің **келесі** санын алады; әр `print` — шығарудың бөлек жолы.\n\n## Сұрақтың алты түрі\n\n- **Не шығарады** — берілген енгізуде трассировка.\n- **Неше рет** жол орындалады — орындалу оған жететін айналымдарды белгіле.\n- **Не үшін** жол керек — оны ойша алып тастап, нәтижелерді салыстыр.\n- **Не өзгереді** — бір нәрсені өзгертіп, қайта есепте.\n- **Қай жолды өзгерту керек** — қажетті ережеге жауап беретін жолды тап.\n- **Қандай енгізу** шығару береді — нәтижеден кері қарай жүр, қойып тексер.\n\n## Тұзақтар\n\n- `<` және `<=`: шекарада жауап өзгереді.\n- `break` бар `x == 0` шартын `continue` бар `x < 100` шартынан бұрын тексер.\n- `x // 10` жеңілдігі бөлшек бөлігін алып тастайды.\n- Сипаттама мен код қайшы болса, кодқа сен."},
  "py-8c-debug": {"ru":"# Ошибки в программах и отладка\n\n## Три вида ошибок\n\n- **Синтаксическая** (`SyntaxError`, `IndentationError`): программа не стартует, не выполняется ни одной строки. Нет двоеточия, не закрыта скобка, неверный отступ, `=` вместо `==`.\n- **Ошибка выполнения**: программа падает на одной строке, а всё напечатанное раньше остаётся на экране.\n- **Логическая**: сообщения нет, ответ неверный. Находят сравнением с ожидаемым.\n\n## Пять частых ошибок выполнения\n\n- `NameError` — неизвестное имя: опечатка, `Print`, `true`, переменная не создана.\n- `TypeError` — операция не подходит типу: `\"5\" + 3`, `input()` без `int`.\n- `ValueError` — не то значение: `int(\"abc\")`.\n- `IndexError` — номера от 0 до `len(a) - 1`.\n- `ZeroDivisionError` — делитель равен 0 (`/`, `//`, `%`).\n\n## Порядок отладки\n\nПоследняя строка сообщения → номер строки (и строки выше) → причина → исправить **одну** вещь → запустить заново → проверить границы.\n\n## Лайфхаки ЕНТ\n\n- Строка падения не всегда строка причины.\n- `>` и `>=` различаются только на границе: подставь значение ровно на ней.\n- Один тест не доказывает верность: проверь первый и последний элементы.","kk":"# Программадағы қателер және жөндеу\n\n## Қателердің үш түрі\n\n- **Синтаксистік** (`SyntaxError`, `IndentationError`): программа іске қосылмайды, бірде-бір жол орындалмайды. Қос нүкте жоқ, жақша жабылмаған, шегініс дұрыс емес, `==` орнына `=`.\n- **Орындау кезіндегі қате**: программа бір жолда құлайды, ал бұрын басылғанның бәрі экранда қалады.\n- **Логикалық**: хабарлама жоқ, жауап қате. Күтілетін нәтижемен салыстырып табады.\n\n## Орындау кезіндегі бес жиі қате\n\n- `NameError` — белгісіз атау: әріп қатесі, `Print`, `true`, айнымалы жасалмаған.\n- `TypeError` — амал типке сәйкес емес: `\"5\" + 3`, `int` жоқ `input()`.\n- `ValueError` — мән сәйкес емес: `int(\"abc\")`.\n- `IndexError` — нөмірлер 0-ден `len(a) - 1`-ге дейін.\n- `ZeroDivisionError` — бөлгіш 0-ге тең (`/`, `//`, `%`).\n\n## Жөндеу реті\n\nХабарламаның соңғы жолы → жол нөмірі (және жоғарыдағы жолдар) → себебі → **бір** нәрсені түзету → қайта іске қосу → шекараларды тексеру.\n\n## ҰБТ кеңестері\n\n- Құлаған жол әрдайым себеп жолы емес.\n- `>` және `>=` тек шекарада ерекшеленеді: дәл сол мәнді қойып көр.\n- Бір тест дұрыстықты дәлелдемейді: бірінші және соңғы элементтерді тексер."},
  "school-blockchain": {"ru":"# Блокчейн: цепочка, которую не подделать\n\n## Блок и цепочка\n\n- **Блок** хранит данные, номер и **хэш предыдущего блока**. Хэш блока считают по всему его содержимому, поэтому блоки сцеплены в **цепочку**.\n- Изменили блок → поменялся его хэш → сломалась связь со следующим блоком. Чтобы скрыть подделку, пересчитывают **все следующие блоки**: изменён блок k из n → пересчёт блоков k…n, то есть n − k + 1.\n\n## Узлы и консенсус\n\n- **Узел** хранит полную копию цепочки и проверяет записи. Главного сервера нет: система **децентрализована**.\n- **Консенсус** — правило согласия узлов: простое большинство (больше половины), **доказательство работы** (подобрать число, чтобы хэш начинался с нулей: найти трудно, проверить легко), залог.\n\n## Применение и границы\n\n- Криптовалюты (биткоин: идея 2008, сеть 2009), хэши документов и дипломов, цепочки поставок, смарт-контракты. Это не совет вкладывать деньги.\n- Плюсы: подделка видна, нет единого владельца. Ограничения: энергия и скорость, «удалить нельзя», **правду не гарантирует** (защищает от правки, а не от неправды), потерян закрытый ключ — потерян доступ.","kk":"# Блокчейн: бұрмалау мүмкін емес тізбек\n\n## Блок және тізбек\n\n- **Блок** деректерді, нөмірді және **алдыңғы блоктың хэшін** сақтайды. Блок хэшін оның бүкіл мазмұны бойынша есептейді, сондықтан блоктар **тізбекке** байланысқан.\n- Блокты өзгертті → оның хэші өзгерді → келесі блокпен байланыс үзілді. Бұрмалауды жасыру үшін **келесі блоктардың бәрін** қайта есептейді: n блоктың ішінде k нөмірлі блок өзгертілсе → k…n блоктарын қайта есептеу, яғни n − k + 1 блок.\n\n## Түйіндер және консенсус\n\n- **Түйін** тізбектің толық көшірмесін сақтайды және жазбаларды тексереді. Басты сервер жоқ: жүйе **орталықсыздандырылған**.\n- **Консенсус** — түйіндердің келісім ережесі: қарапайым көпшілік (жартысынан көбі), **жұмыс дәлелі** (хэш нөлдермен басталатындай сан іріктеу: табу қиын, тексеру оңай), кепіл.\n\n## Қолданылуы және шектері\n\n- Криптовалюталар (биткоин: идея 2008, желі 2009), құжаттар мен дипломдардың хэштері, жеткізу тізбектері, смарт-контрактілер. Бұл ақша салу туралы кеңес емес.\n- Артықшылықтары: бұрмалау көрінеді, жалғыз ие жоқ. Шектеулері: энергия және жылдамдық, «өшіруге болмайды», **шындыққа кепілдік бермейді** (түзетуден қорғайды, өтіріктен емес), жабық кілт жоғалса — кіру мүмкіндігі де жоғалады."},
  "school-design": {"ru":"# Хороший дизайн\n\n## Что такое дизайн\n- **Дизайн** — продуманный вид и устройство вещи. Хороший дизайн отвечает: понятно ли? удобно ли?\n- **Применимость** (usability) — насколько легко и быстро человек получает результат.\n- Виды визуального дизайна: **графический** (афиша, логотип, упаковка), **веб и интерфейс** (сайты, приложения), **промышленный** (предметы), **дизайн пространства** (интерьер, указатели).\n\n## Принципы\n- **Иерархия:** главное — крупнее, ярче, жирнее; второстепенное — меньше и тише.\n- **Контраст:** заметная разница; тёмное на светлом, крупное рядом с мелким.\n- **Выравнивание:** края элементов на одной линии.\n- **Повтор:** одинаковое оформляется одинаково — единый стиль.\n- **Близость:** связанное — рядом, разное — отдельно.\n- **Пространство:** пустое место отделяет группы и даёт отдохнуть глазу.\n- **Цвет:** 2–3 основных и нейтральный; не передавай смысл только цветом.\n- **Шрифты:** не больше двух.\n\n## Дизайн для людей\nПонятно с первого взгляда; кнопки не меньше подушечки пальца (около 1 см); хороший контраст и подписи; проверка на человеке, который макет не видел.\n\n## Частые ошибки\n- Всё одного размера, нет главного.\n- Светлый текст на светлом фоне.\n- Шрифты «для разнообразия».\n- Связанное разнесено по углам.","kk":"# Жақсы дизайн\n\n## Дизайн деген не\n- **Дизайн** — заттың ойластырылған көрінісі мен құрылымы. Жақсы дизайн жауап береді: түсінікті ме? ыңғайлы ма?\n- **Қолданылуы** (пайдалануға ыңғайлылығы, usability) — адамның нәтижеге қаншалықты оңай және тез жетуі.\n- Визуалды дизайн түрлері: **графикалық** (афиша, логотип, қаптама), **веб және интерфейс** (сайттар, қолданбалар), **өнеркәсіптік** (заттар), **кеңістік дизайны** (интерьер, нұсқағыштар).\n\n## Принциптер\n- **Иерархия:** басты нәрсе — үлкенірек, жарқынырақ, жуанырақ; екінші кезектегісі — кішірек және көзге азырақ түседі.\n- **Контраст:** байқалатын айырмашылық; ашық түстегі қою, ұсақтың жанындағы ірі.\n- **Туралау:** элементтердің жиектері бір сызықта.\n- **Қайталау:** бірдей нәрсе бірдей ресімделеді — бірыңғай стиль.\n- **Жақындық:** байланысты нәрсе — қатар, әртүрлісі — бөлек.\n- **Бос орын:** бос жер топтарды бөліп, көзге демалыс береді.\n- **Түс:** 2–3 негізгі және бейтарап түс; мағынаны тек түспен жеткізбе.\n- **Қаріптер:** екіден аспайды.\n\n## Адамдарға арналған дизайн\nБір қарағанда түсінікті; түймелер саусақ ұшынан кем емес (шамамен 1 см); жақсы контраст және жазулар; макетті көрмеген адамда тексеру.\n\n## Жиі кететін қателер\n- Бәрі бірдей өлшемде, басты нәрсе жоқ.\n- Ашық фондағы ашық мәтін.\n- «Әртүрлілік үшін» қаріптер.\n- Байланысты нәрсе бұрыштарға жайылған."},
  "school-digital-kz": {"ru":"# Цифровой Казахстан и eGov\n\n## Цифровизация\n\n- **Оцифровка** — бумага превращена в файл. **Цифровизация** — меняется сам процесс: данные берутся из баз, бумаги не нужны.\n- С 2018 года действовала программа «Цифровой Казахстан» (до 2022 года), цифровизация продолжается в новых государственных документах. Тенденции: услуги онлайн, телефон вместо «папки с документами», данные и ИИ, безопасность. Риски: цифровое неравенство, утечки данных.\n\n## Электронное правительство\n\n- **eGov.kz** и **eGov mobile**: услуги и справки, цифровые документы, электронная очередь, обращения, открытые данные. **ЦОН** — услуги очно.\n- Путь услуги: вход → заявка → подпись (ЭЦП или код SMS) → органы сверяют данные в базах → электронный документ с QR-кодом.\n\n## Открытое правительство\n\n- Открытые данные, открытый бюджет, обращения граждан, обсуждение проектов актов. Персональные данные не открывают.\n\n## Безопасность\n\n- Код из SMS, ключ ЭЦП и пароль — **никому**. Портал открывай сам; в адресе смотри на последние два слова до первой «/». Срочность и просьба «продиктовать код» — признаки обмана.\n- **Astana Hub** — международный технопарк IT-стартапов; стартапы, хакатоны, олимпиады — путь в IT.","kk":"# Цифрлық Қазақстан және eGov\n\n## Цифрландыру\n\n- **Цифрлау** — қағаз файлға айналды. **Цифрландыру** — үдерістің өзі өзгереді: деректер базалардан алынады, қағаз керек емес.\n- 2018 жылдан бастап «Цифрлық Қазақстан» бағдарламасы жұмыс істеді (2022 жылға дейін), цифрландыру жаңа мемлекеттік құжаттар бойынша жалғасуда. Үрдістер: онлайн қызметтер, «құжаттар қалтасының» орнына телефон, деректер және ЖИ, қауіпсіздік. Қатерлер: цифрлық теңсіздік, деректердің ағып кетуі.\n\n## Электрондық үкімет\n\n- **eGov.kz** және **eGov mobile**: қызметтер мен анықтамалар, цифрлық құжаттар, электрондық кезек, өтініштер, ашық деректер. **ХҚКО** — қызметті жүзбе-жүз алу.\n- Қызмет жолы: кіру → өтініш → қол қою (ЭЦҚ немесе SMS-код) → органдар деректерді базалардан салыстырады → QR-коды бар электрондық құжат.\n\n## Ашық үкімет\n\n- Ашық деректер, ашық бюджет, азаматтардың өтініштері, актілер жобаларын талқылау. Дербес деректер ашылмайды.\n\n## Қауіпсіздік\n\n- SMS-тағы код, ЭЦҚ кілті және құпиясөз — **ешкімге**. Порталды өзің аш; мекенжайда алғашқы «/» белгісіне дейінгі соңғы екі сөзге қара. Шұғылдық пен «кодты айт» деген сұрау — алдаудың белгілері.\n- **Astana Hub** — IT-стартаптардың халықаралық технопаркі; стартаптар, хакатондар, олимпиадалар — IT-ге апаратын жол."},
  "school-health-1": {"ru":"**Эргономика** — подгоняем рабочее место под человека, а не человека под вещи.\n\n**Как сидеть и расставить вещи**\n- Сиди глубоко: спина опирается на спинку, стопы стоят на полу.\n- Локти согнуты почти под прямым углом, руки лежат на столе, кисти ровные.\n- Экран на вытянутой руке (50–70 см), верх на уровне глаз или чуть ниже.\n- Свет сбоку, без бликов на экране; яркость экрана как в комнате.\n- Телефон не ближе 30–40 см, голову не склоняй.\n\n**Отдых**\n- Правило **20-20-20**: каждые 20 минут — 20 секунд смотри вдаль (около 6 метров).\n- Перерыв каждые 30–45 минут: встань, потянись, пройдись.\n- Разминка для глаз и кистей — плавно и без боли.\n\n**Безопасность**\n- Мокрые руки не к розетке и проводам.\n- Еда и напитки не у клавиатуры.\n- Не включай много приборов в один удлинитель и не чини технику самостоятельно.\n- Запах гари, дым, искры: не трогай и позови взрослого.\n\n**Ловушка:** «чем ближе экран, тем лучше видно». Нет: чем ближе, тем сильнее устают глаза.","kk":"**Эргономика** — жұмыс орнын адамға қарай келтіреміз, адамды заттарға емес.\n\n**Қалай отыру және заттарды қалай қою**\n- Терең отыр: арқа арқалыққа сүйенеді, табан еденде тұрады.\n- Шынтақтар шамамен тік бұрыш жасап бүгілген, қолдар үстелде жатады, қол басы түзу.\n- Экран созылған қолдың қашықтығында (50–70 см), жиегі көз деңгейінде немесе сәл төмен.\n- Жарық бүйірден, экранда шағылыссыз; экранның жарықтығы бөлмедегідей.\n- Телефон 30–40 см-ден жақын емес, басыңды имеме.\n\n**Демалыс**\n- **20-20-20** ережесі: әр 20 минут сайын 20 секунд алысқа (шамамен 6 метрге) қара.\n- Әр 30–45 минут сайын үзіліс: тұр, керіл, жүр.\n- Көз бен қол басына жаттығу — жайлап әрі ауыртпай.\n\n**Қауіпсіздік**\n- Ылғал қол розеткаға және сымдарға емес.\n- Тамақ пен сусын пернетақтаның жанында емес.\n- Бір ұзартқышқа көп құрал қоспа және техниканы өзің жөндеме.\n- Күйік иісі, түтін, ұшқын: тиіспе және үлкендерді шақыр.\n\n**Тұзақ:** «экран жақын болған сайын жақсы көрінеді». Жоқ: жақын болған сайын көз көбірек шаршайды."},
  "school-health-2": {"ru":"**Что может навредить и как защититься**\n\n**Глаза.** Цифровая усталость (сухость, жжение, размытость, головная боль): за экраном мы реже моргаем, мышцы глаза напряжены. Защита: **20-20-20**, экран на 50–70 см, верх на уровне глаз, свет сбоку.\n\n**Шея, спина, запястья.** «Текстовая шея»: держи телефон на уровне глаз. **Лучшая поза — следующая:** вставай каждые 30–45 минут. Кисти ровно, разминка рук.\n\n**Сон.** Подростку нужно 8–10 часов. Убирай экран за 30–60 минут до сна; ночной режим его не заменяет.\n\n**Слух и движение.** Правило 60/60: громкость до 60 % и не дольше 60 минут подряд. ВОЗ: не менее 60 минут движения в день.\n\n**Зависимость.** Признаки: время «уплывает», раздражение без телефона, страдают сон, учёба и общение. Помощь себе: экранное время, таймер, меньше уведомлений, живые занятия, разговор со взрослым или школьным психологом.\n\n**Баланс.** Свободное время = 24 − сон − школа − домашние задания − дела; экран в неделю = часы в день · 7.\n\n**Мифы.** Излучение современных мониторов для здоровья не опасно, кактус не «впитывает вред»: вредят привычки. При частой боли — к врачу.","kk":"**Не зиян келтіруі мүмкін және қалай қорғануға болады**\n\n**Көз.** Цифрлық шаршау (құрғау, ашу, бұлыңғырлану, бас ауыруы): экран алдында сирек жыпылықтаймыз, көз бұлшық еттері ширығады. Қорғану: **20-20-20**, экран 50–70 см қашықтықта, жиегі көз деңгейінде, жарық бүйірден.\n\n**Мойын, арқа, білек.** «Телефон мойны»: телефонды көз деңгейінде ұста. **Ең жақсы қалып — келесі қалып:** әр 30–45 минут сайын тұр. Қол басы түзу, қолға жаттығу.\n\n**Ұйқы.** Жасөспірімге 8–10 сағат керек. Экранды ұйқыға 30–60 минут қалғанда өшіріп қой; түнгі режим оны алмастырмайды.\n\n**Есту қабілеті және қозғалыс.** 60/60 ережесі: дыбыс деңгейі 60 пайызға дейін, қатарынан 60 минуттан ұзақ емес. ДДСҰ: күніне кемінде 60 минут қозғалыс.\n\n**Тәуелділік.** Белгілері: уақыт «зымырап өтеді», телефонсыз ашу, ұйқы, оқу және араласу зардап шегеді. Өзіңе көмек: экран уақыты, таймер, хабарландыруды азайту, экрансыз істер, үлкенмен немесе мектеп психологымен сөйлесу.\n\n**Баланс.** Бос уақыт = 24 − ұйқы − мектеп − үй тапсырмасы − шаруа; аптасына экран = күніне сағат · 7.\n\n**Қате түсініктер.** Қазіргі мониторлардың сәулеленуі денсаулыққа қауіпті емес, кактус «зиянды сіңірмейді»: зиян келтіретін — әдеттер. Жиі ауырса — дәрігерге бар."},
  "school-info-props": {"ru":"**Свойства информации** — её качества: по ним можно понять, стоит ли ей верить и годится ли она для дела.\n\n**Можно ли верить:**\n- **достоверность** — соответствует действительности (источник известен и надёжен);\n- **точность** — сказано определённо: «−5 °C», а не «холодно»;\n- **объективность** — факты, а не мнение или выгода автора.\n\n**Годится ли для дела:**\n- **полнота** — сведений хватает, чтобы решить задачу;\n- **актуальность** — не устарела, нужна сейчас;\n- **ценность (полезность)** — помогает решить именно твою задачу;\n- **понятность** (доступность) — изложена языком и на уровне, понятным получателю.\n\n**Что от чего зависит:** достоверность и объективность — свойства самого сообщения; понятность и ценность зависят от получателя, актуальность — от времени, полнота — от задачи.\n\n**Ловушки:** верное сообщение может устареть; свежее сообщение может оказаться ложным; похвала от продавца — не объективная оценка.\n\n**Три вопроса перед пересылкой:** кто автор? когда написано? хватает ли для моей задачи?","kk":"**Ақпарат қасиеттері** — оның сапалары: олар арқылы ақпаратқа сену керек пе және ол іске жарай ма, соны түсінеміз.\n\n**Сенуге бола ма:**\n- **сенімділік** (анықтық) — шындыққа сәйкес (дереккөзі белгілі және сенімді);\n- **дәлдік** — нақты айтылған: «суық» емес, «−5 °C»;\n- **объективтілік** — автордың пікірі не пайдасы емес, фактілер.\n\n**Іске жарай ма:**\n- **толықтық** — міндетті шешуге мәлімет жеткілікті;\n- **өзектілік** — ескірмеген, дәл қазір керек;\n- **құндылық (пайдалылық)** — дәл сенің міндетіңді шешуге көмектеседі;\n- **түсініктілік** (қолжетімділік) — алушыға түсінікті тілде және деңгейде баяндалған.\n\n**Не неге байланысты:** сенімділік пен объективтілік — хабарламаның өзінің қасиеттері; түсініктілік пен құндылық алушыға, өзектілік уақытқа, толықтық міндетке байланысты.\n\n**Тұзақтар:** дұрыс хабарлама ескіруі мүмкін; жаңа хабарлама жалған болуы мүмкін; сатушының мақтауы — объективті баға емес.\n\n**Жібермес бұрын үш сұрақ:** авторы кім? қашан жазылған? менің міндетіме жете ме?"},
  "school-pc-cost": {"ru":"**Конфигурация** — набор деталей компьютера и их характеристик. Её подбирают **под задачу**: на главном для задачи не экономят, на неважном не переплачивают.\n\n**Ориентиры (условные):**\n- учёба и офис — 4 ядра, 8 ГБ ОЗУ, SSD 256 ГБ, встроенная видеокарта;\n- программирование — 16 ГБ ОЗУ, быстрый SSD;\n- монтаж видео — много ядер, 32 ГБ ОЗУ, большой SSD, видеокарта;\n- игры — мощная видеокарта.\n\n**Совместимость:** процессор — по сокету платы; ОЗУ — того же типа, что поддерживает плата (DDR4 и DDR5 не заменяют друг друга); блок питания — достаточной мощности; корпус — по размеру платы.\n\n**Программы:** операционная система, прикладные программы, среда программирования. Есть бесплатные (Linux, LibreOffice, Python) и платные; перед покупкой ищи бесплатную замену. Взломанные копии — нарушение лицензии.\n\n**Стоимость:** сложи цены всех деталей (и монитор, клавиатуру, мышь) и сравни с бюджетом. Не хватает — замени второстепенное, а не главное для задачи. Цены в уроке примерные.","kk":"**Конфигурация** — компьютер бөлшектерінің жиынтығы және олардың сипаттамалары. Оны **міндетке қарай** таңдайды: міндет үшін маңызды нәрседе үнемдемейді, маңызсызға артық төлемейді.\n\n**Бағдарлар (шартты):**\n- оқу және кеңсе — 4 ядро, 8 ГБ жедел жад, 256 ГБ SSD, кіріктірілген бейнекарта;\n- программалау — 16 ГБ жедел жад, жылдам SSD;\n- бейне монтаждау — көп ядро, 32 ГБ жедел жад, үлкен SSD, бейнекарта;\n- ойындар — қуатты бейнекарта.\n\n**Үйлесімділік:** процессор — тақшаның сокетіне қарай; жедел жад — тақша қолдайтын түрде (DDR4 және DDR5 бір-бірін алмастырмайды); қуат блогы — жеткілікті қуатта; корпус — тақшаның өлшеміне қарай.\n\n**Программалар:** операциялық жүйе, қолданбалы программалар, программалау ортасы. Тегін (Linux, LibreOffice, Python) және ақылы программалар бар; сатып алмас бұрын тегін алмастырғышты іздеу керек. Бұзылған көшірмелер — лицензияны бұзу.\n\n**Құны:** барлық бөлшектердің (монитор, пернетақта, тінтуірді де) бағасын қосып, бюджетпен салыстыр. Жетпесе — міндет үшін басты нәрсені емес, екінші дәрежелісін ауыстыр. Сабақтағы бағалар шамамен."},
  "school-robots-1": {"ru":"**Робот** — машина, которая сама действует по программе: замечает мир, решает, что делать, и выполняет действие.\n\n**Три части робота** (как у человека):\n- **датчики** — «глаза и уши» (свет, расстояние, поворот, касание);\n- **контроллер** — «мозг», маленький компьютер с программой;\n- **моторы** — «руки и ноги», двигают колёса и детали.\n\nНет датчиков, программы или моторов — это не робот, а обычная машина.\n\n**Виды роботов:** промышленные (заводы), сервисные, медицинские, бытовые (пылесос), транспортные (дроны, марсоходы), образовательные (наборы для школьников).\n\n**Где работают:** заводы, склады, больницы, поля, космос, школьные соревнования.\n\n**История:** автоматы древности (Герон, Аль-Джазари) → слово «робот» у Чапека (1921) → первый промышленный робот (1961) → «Луноход-1» (1970) → марсоходы (с 1997) → роботы-пылесосы и дроны.\n\n**Профессии:** инженер-робототехник, программист, специалист по ИИ, оператор и наладчик, дизайнер-конструктор, оператор дронов.\n\nДальше: «Как робот чувствует мир: датчики».","kk":"**Робот** — программа бойынша өзі әрекет ететін машина: әлемді байқайды, не істейтінін шешеді және әрекетті орындайды.\n\n**Роботтың үш бөлігі** (адамдағыдай):\n- **датчиктер** — «көз бен құлақ» (жарық, қашықтық, бұрылыс, жанасу);\n- **контроллер** — «ми», программасы бар шағын компьютер;\n- **қозғалтқыштар** — «қол мен аяқ», дөңгелектер мен бөлшектерді қозғалтады.\n\nДатчиктер, программа немесе қозғалтқыштар болмаса, бұл — робот емес, қарапайым машина.\n\n**Роботтардың түрлері:** өнеркәсіптік (зауыттар), қызмет көрсететін, медициналық, тұрмыстық (шаңсорғыш), транспорттық (дрондар, марсоходтар), білім беру (оқушыларға арналған жинақтар).\n\n**Қайда жұмыс істейді:** зауыттар, қоймалар, ауруханалар, егістіктер, ғарыш, мектеп жарыстары.\n\n**Тарихы:** ежелгі автоматтар (Герон, Әл-Жазари) → Чапектегі «робот» сөзі (1921) → алғашқы өнеркәсіптік робот (1961) → «Луноход-1» (1970) → марсоходтар (1997 жылдан) → робот-шаңсорғыштар мен дрондар.\n\n**Мамандықтар:** робототехника инженері, программист, жасанды интеллект маманы, оператор және реттеуші, дизайнер-конструктор, дрондар операторы.\n\nӘрі қарай: «Робот әлемді қалай сезінеді: датчиктер»."},
  "school-robots-2": {"ru":"**Гироскоп** измеряет, как быстро робот поворачивается. **Угол = скорость поворота × время** (30°/с за 3 с — 90°). Перед поворотом гироскоп **обнуляют**. Полный оборот 360°, прямой угол 90°, разворот 180°.\n\n**Повороты.** На месте: колёса вращаются в разные стороны (левое вперёд, правое назад — вправо). Плавный: оба вперёд, но одно быстрее; быстрее колесо снаружи.\n\n**Поворот на 90°:** обнулить гироскоп → крутить моторы, пока угол < 90° → остановить. Из-за инерции робот может «проскочить» на градус-другой.\n\n**Датчик цвета** измеряет отражённый свет: белое — много (≈ 90), чёрное — мало (≈ 5). **Порог** (например 50) превращает число в «чёрное / белое».\n\n**Движение по линии:** едем вдоль левого края (слева белое, справа чёрное). Видит чёрное — чуть влево, видит белое — чуть вправо. Проверка повторяется много раз в секунду.\n\n**Ультразвук:** расстояние = время эха × 34 : 2 (звук идёт туда и обратно, ≈ 34 см за 1 мс).\n\n**Робо-сумо:** порядок проверок важен: 1) белая линия → назад и поворот; 2) соперник близко → вперёд; 3) иначе крутиться и искать.\n\nЛовушки: забыть обнулить гироскоп; не поделить на 2 в ультразвуке; перепутать «чёрное → влево» с «белое → влево».","kk":"**Гироскоп** роботтың қаншалықты жылдам бұрылатынын өлшейді. **Бұрыш = бұрылу жылдамдығы × уақыт** (30°/с жылдамдықпен 3 с — 90°). Бұрылыс алдында гироскопты **нөлдейді**. Толық айналым 360°, тік бұрыш 90°, кері бұрылу 180°.\n\n**Бұрылыстар.** Орнында: дөңгелектер әр жаққа айналады (сол алға, оң артқа — оңға). Тегіс: екеуі де алға, бірақ біреуі жылдамырақ; сырттағы дөңгелек жылдамырақ.\n\n**90° бұрылыс:** гироскопты нөлдеу → бұрыш < 90° болғанша қозғалтқыштарды айналдыру → тоқтату. Инерциядан робот бір-екі градус «асып кетуі» мүмкін.\n\n**Түс датчигі** шағылған жарықты өлшейді: ақ — көп (≈ 90), қара — аз (≈ 5). **Шек** (мысалы, 50) санды «қара / ақ» деген жауапқа айналдырады.\n\n**Сызық бойымен жүру:** сол шеті бойымен жүреміз (сол жақта ақ, оң жақта қара). Қараны көрсе — сәл солға, ақты көрсе — сәл оңға. Тексеру секундына көп рет қайталанады.\n\n**Ультрадыбыс:** қашықтық = жаңғырық уақыты × 34 : 2 (дыбыс барып-қайтады, әрбір миллисекундта ≈ 34 см).\n\n**Робо-сумо:** тексерулердің реті маңызды: 1) ақ сызық → артқа жүріп, бұрылу; 2) қарсылас жақын → алға; 3) әйтпесе айналып іздеу.\n\nТұзақтар: гироскопты нөлдеуді ұмыту; ультрадыбыста екіге бөлуді ұмыту; «қара → солға» мен «ақ → солға» дегенді шатастыру."},
  "school-vm": {"ru":"**Виртуальная машина (ВМ)** — «компьютер внутри компьютера»: программа, которая ведёт себя как настоящий компьютер, со своими процессором, памятью, диском и ОС.\n\n**Термины:**\n- **хост** — реальный компьютер, на котором запускают ВМ;\n- **гость** — ВМ и операционная система внутри неё;\n- **гипервизор** — программа, которая создаёт ВМ, запускает их и делит ресурсы (VirtualBox, Hyper-V, KVM);\n- **снимок** — сохранённое состояние ВМ, «точка восстановления».\n\n**Зачем:** другая ОС без переустановки; «песочница» для проверки подозрительных программ; обучение и тесты; серверы и облака (много виртуальных серверов на одном физическом).\n\n**Ресурсы** ВМ (ОЗУ, ядра, диск) берутся у хоста: сумма ресурсов всех ВМ плюс запас хоста не больше имеющегося.\n\n**Ограничения:** ВМ чуть медленнее реального компьютера, ресурсы общие, нужна лицензия для платной гостевой ОС, тяжёлая графика работает плохо, защита не абсолютная (общие папки и сеть — лазейки).\n\n**Родственники:** эмулятор имитирует другое устройство и обычно медленнее; облачная ВМ живёт в дата-центре и арендуется по интернету.","kk":"**Виртуалды машина (ВМ)** — «компьютердің ішіндегі компьютер»: нағыз компьютер сияқты әрекет ететін, өз процессоры, жады, дискісі және ОЖ-сі бар программа.\n\n**Терминдер:**\n- **хост** — ВМ іске қосылатын нақты компьютер;\n- **қонақ** — ВМ және оның ішіндегі операциялық жүйе;\n- **гипервизор** — ВМ жасайтын, іске қосатын және ресурстарды бөлетін программа (VirtualBox, Hyper-V, KVM);\n- **снапшот** — ВМ-нің сақталған күйі, «қалпына келтіру нүктесі».\n\n**Не үшін:** қайта орнатусыз басқа ОЖ; күмәнді программаларды тексеруге арналған «құмсалғыш»; оқу және сынақ; серверлер мен бұлттар (бір физикалық серверде көп виртуалды сервер).\n\nВМ **ресурстары** (жедел жад, ядро, диск) хосттан алынады: барлық ВМ ресурстарының қосындысы мен хост қоры бар нәрседен аспауы керек.\n\n**Шектеулер:** ВМ нақты компьютерден сәл баяу, ресурстар ортақ, ақылы қонақ ОЖ үшін лицензия керек, ауыр графика нашар жұмыс істейді, қорғаныс абсолютті емес (ортақ қалталар мен желі — саңылаулар).\n\n**Туыстары:** эмулятор басқа құрылғыны бейнелейді және әдетте баяу; бұлттағы ВМ деректер орталығында тұрады және интернет арқылы жалға алынады."},
  "school-vr": {"ru":"# Виртуальная и дополненная реальность\n\n## Три вида\n- **VR** (виртуальная реальность): шлем закрывает настоящий мир, всё вокруг создаёт компьютер. VR **заменяет** мир.\n- **AR** (дополненная реальность): к настоящему миру на экране (чаще телефона) добавлены объекты. AR **добавляет** к миру.\n- **MR** (смешанная реальность): виртуальные объекты «знают» о настоящих и взаимодействуют с ними.\n\n## Как это работает\nДатчики (гироскоп и другие) замечают поворот головы → компьютер пересчитывает вид → строятся **два кадра** (для левого и правого глаза) → экраны показывают их, а мозг складывает в объём. Кадров нужно много в секунду (обычно 72–120), иначе картинка отстаёт.\n\n## Где применяют\nТренажёры (пилоты, водители), медицина, музеи и туры, игры, архитектура, подсказки при ремонте (AR).\n\n## Здоровье\n- укачивание: глаза видят движение, а орган равновесия нет;\n- усталость и сухость глаз;\n- удар о предметы: нужно свободное место и граница;\n- перерывы (например, 10–15 минут после каждых 30), остановиться при головокружении или тошноте;\n- возрастные ограничения производителя — в инструкции.\n\n## 3D-панорама и виртуальный тур\n- панорама 360° — снимок всего вокруг точки; развёртка — прямоугольник 2 : 1;\n- тур = панорамы + **точки перехода** (стрелка ведёт в одну сторону, для пути туда и обратно нужны две);\n- этапы: план → съёмка → склейка → переходы → проверка → публикация.\n\n## Частые ошибки\n- Путают VR и AR.\n- Забывают обратные переходы, и получаются тупики.","kk":"# Виртуалды және толықтырылған шындық\n\n## Үш түрі\n- **VR** (виртуалды шындық): шлем нақты әлемді жабады, айналадағының бәрін компьютер жасайды. VR әлемді **ауыстырады**.\n- **AR** (толықтырылған шындық): нақты әлемге экранда (көбіне телефонда) нысандар қосылады. AR әлемге **қосады**.\n- **MR** (аралас шындық): виртуалды нысандар нақты заттарды «біледі» және олармен әрекеттеседі.\n\n## Бұл қалай жұмыс істейді\nДатчиктер (гироскоп және басқалары) бастың бұрылғанын байқайды → компьютер көріністі қайта есептейді → **екі кадр** құрылады (сол және оң көзге) → экрандар оларды көрсетеді, ал ми көлемге біріктіреді. Секундына кадр көп керек (әдетте 72–120), әйтпесе сурет кешігеді.\n\n## Қайда қолданылады\nТренажёрлер (ұшқыштар, жүргізушілер), медицина, музейлер мен турлар, ойындар, сәулет, жөндеудегі нұсқаулар (AR).\n\n## Денсаулық\n- жүрек айну: көз қозғалысты көреді, ал тепе-теңдік мүшесі — жоқ;\n- көздің шаршауы мен құрғауы;\n- заттарға соғылу: бос орын және шекара керек;\n- үзілістер (мысалы, әр 30 минуттан кейін 10–15 минут), бас айналса немесе жүрегі айнып кетсе тоқтау;\n- өндірушінің жас шектеулері — нұсқаулықта.\n\n## 3D-панорама және виртуалды тур\n- 360° панорама — нүктенің айналасындағы бәрінің суреті; жазбасы — 2 : 1 тіктөртбұрыш;\n- тур = панорамалар + **өту нүктелері** (көрсеткі бір бағытқа апарады, барып-қайту үшін екеуі керек);\n- кезеңдер: жоспар → түсіру → біріктіру → өту нүктелері → тексеру → жариялау.\n\n## Жиі кететін қателер\n- VR мен AR шатастырылады.\n- Кері өту нүктелері ұмытылады, сөйтіп тұйық жерлер пайда болады."},
  "web-1-html": {"ru":"# HTML: структура страницы\n\n## Теги\n\n- Страница — текстовый файл; браузер читает **теги** и рисует страницу.\n- **Парные** теги: `<p>` … `</p>`. **Одиночные**: `<br>`, `<hr>`, `<img>` — закрывающего нет.\n- Закрывать в обратном порядке: `<b><i>Hi</i></b>`.\n\n## Скелет\n\n`<!DOCTYPE html>` → `<html>` → `<head>` (`<title>`, `<meta charset>`) → `<body>`. **head — для браузера, body — для человека.**\n\n## Что запомнить\n\n- Заголовки `<h1>`–`<h6>`: h1 самый крупный.\n- `<p>` абзац, `<br>` перенос, `<b>` жирный, `<i>` курсив, `<u>` подчёркнутый.\n- `<ul>` маркированный список, `<ol>` нумерованный, `<li>` пункт.\n- `<a href=\"адрес\">текст</a>` ссылка (`target=\"_blank\"` — в новой вкладке); `<img src=\"файл\" alt=\"текст\" width=\"200\">` рисунок.\n- `<table>` → `<tr>` строка → `<th>` / `<td>` ячейка.\n- Выравнивание: `<p align=\"center\">` и `<center>` устарели, но есть на ЕНТ; сейчас — CSS `text-align`.\n\n## Лайфхаки для ЕНТ\n\n- Имя тега — английское слово: bold, break, unordered / ordered list, table header / data.\n- В «найди ошибку» ищи пропущенную `/` и неверный порядок закрытия.","kk":"# HTML: беттің құрылымы\n\n## Тегтер\n\n- Бет — мәтіндік файл; браузер **тегтерді** оқып, бетті салады.\n- **Жұп** тегтер: `<p>` … `</p>`. **Жалғыз** тегтер: `<br>`, `<hr>`, `<img>` — жабатыны жоқ.\n- Кері ретпен жабу керек: `<b><i>Hi</i></b>`.\n\n## Қаңқа\n\n`<!DOCTYPE html>` → `<html>` → `<head>` (`<title>`, `<meta charset>`) → `<body>`. **head — браузерге, body — адамға.**\n\n## Не есте сақтау керек\n\n- `<h1>`–`<h6>` тақырыптары: h1 ең үлкен.\n- `<p>` абзац, `<br>` жаңа жолға көшу, `<b>` қалың, `<i>` көлбеу, `<u>` асты сызылған.\n- `<ul>` маркерлі тізім, `<ol>` нөмірленген, `<li>` тармақ.\n- `<a href=\"мекенжай\">мәтін</a>` сілтеме (`target=\"_blank\"` — жаңа қойындыда); `<img src=\"файл\" alt=\"мәтін\" width=\"200\">` сурет.\n- `<table>` → `<tr>` жол → `<th>` / `<td>` ұяшық.\n- Туралау: `<p align=\"center\">` және `<center>` ескірген, бірақ ҰБТ-да кездеседі; қазір — CSS `text-align`.\n\n## ҰБТ-ға арналған кеңестер\n\n- Тегтің аты — ағылшын сөзі: bold, break, unordered / ordered list, table header / data.\n- «Қатені тап» тапсырмасында түсіп қалған `/` белгісін және жабу ретін тексер."},
  "web-2-css": {"ru":"# CSS: оформление страницы\n\n**HTML** — что на странице, **CSS** — как она выглядит.\n\n## Правило\n`селектор { свойство: значение; }`, например `p { color: red; }`.\n\n## Свойства\n- `color` — цвет текста; `background-color` — цвет фона\n- `font-size` (px), `font-family`, `font-weight`\n- `text-align`: left, center, right, justify\n- `border`, `width`, `height`\n- `padding` — **внутренний** отступ, `margin` — **внешний**\n\n## Цвета\nИмя (`red`), `#RRGGBB` (16-ричная система: FF = 255), `rgb(255, 0, 0)`.\n\n## Селекторы\n`p` — тег, `.note` — класс, `#title` — id (уникальный). Приоритет: **id > класс > тег**; при равенстве побеждает правило ниже.\n\n## Где писать\nАтрибут `style` (один элемент), тег `<style>` в `<head>` (страница), файл `style.css` и `<link rel=\"stylesheet\" href=\"style.css\">` (весь сайт).\n\n## Этапы сайта\nЦель → структура (карта сайта, навигация) → дизайн → вёрстка → тестирование → публикация (хостинг и домен). Адаптивность — удобство на телефоне.\n\n## Ловушки ЕНТ\nmargin и padding не путать; color — текст, background-color — фон; место блока по горизонтали = width + 2·padding + 2·border + 2·margin; `margin: 10px 20px 30px 40px` — сверху, справа, снизу, слева (по часовой стрелке).","kk":"# CSS: бетті безендіру\n\n**HTML** — бетте не бар, **CSS** — бет қандай көрінеді.\n\n## Ереже\n`селектор { қасиет: мән; }`, мысалы `p { color: red; }`.\n\n## Қасиеттер\n- `color` — мәтін түсі; `background-color` — фон түсі\n- `font-size` (px), `font-family`, `font-weight`\n- `text-align`: left, center, right, justify\n- `border`, `width`, `height`\n- `padding` — **ішкі** шегініс, `margin` — **сыртқы** шегініс\n\n## Түстер\nАтауы (`red`), `#RRGGBB` (он алтылық жүйе: FF = 255), `rgb(255, 0, 0)`.\n\n## Селекторлар\n`p` — тег, `.note` — класс, `#title` — id (бірегей). Басымдық: **id > класс > тег**; тең болса төменгі ереже жеңеді.\n\n## Қайда жазады\n`style` атрибуты (бір элемент), `<head>` ішіндегі `<style>` тегі (бет), `style.css` файлы және `<link rel=\"stylesheet\" href=\"style.css\">` (бүкіл сайт).\n\n## Сайт кезеңдері\nМақсат → құрылым (сайт картасы, навигация) → дизайн → беттеу → тестілеу → жариялау (хостинг және домен). Адаптивтілік — телефонда ыңғайлылық.\n\n## ҰБТ тұзақтары\nmargin мен padding-ті шатастырма; color — мәтін, background-color — фон; блоктың көлденең алатын орны = width + 2·padding + 2·border + 2·margin; `margin: 10px 20px 30px 40px` — жоғарыдан, оңнан, төменнен, солдан (сағат тілі бойымен)."},
  "web-3-content": {"ru":"# HTML: текст, списки, ссылки, рисунки\n\n## Как браузер читает текст\n- Пробелы и Enter в коде схлопываются в **один пробел**.\n- Новая строка — `<br>` (закрывающего нет), новый абзац — `<p>`.\n\n## Текст\n- Заголовки `<h1>`–`<h6>`: чем больше цифра, тем мельче.\n- `<b>` / `<strong>` — жирный, `<i>` / `<em>` — курсив, `<sub>` — нижний индекс, `<sup>` — верхний, `<hr>` — линия.\n- Выравнивание (устарело, но есть на ЕНТ): `align=\"left | center | right | justify\"`, `<center>`; `<img align=\"right\">` — рисунок у края, текст обтекает.\n\n## Списки\n- `<ul>` — маркеры, `<ol>` — номера (`type=\"a\"`, `start=\"5\"`), пункт — `<li>`.\n- Вложенный список — **внутри** `<li>`. Тегов `<li>` — столько, сколько пунктов на всех уровнях.\n\n## Ссылки и рисунки\n- `<a href=\"адрес\" target=\"_blank\">текст</a>`, `<img src=\"файл\" alt=\"текст\" width=\"100\">`.\n- `href` — куда ведёт, `src` — откуда взять файл, `alt` — что показать вместо рисунка.\n- Путь: `menu.html` — та же папка, `img/a.png` — подпапка, `../a.html` — папкой выше.\n\n## Лайфхаки для ЕНТ\n- В «что покажет браузер» сначала схлопни пробелы, потом считай `<br>` и `<p>`.\n- Путь считай от папки страницы, а не от корня сайта.","kk":"# HTML: мәтін, тізімдер, сілтемелер, суреттер\n\n## Браузер мәтінді қалай оқиды\n- Кодтағы бос орындар мен Enter **бір бос орынға** жиырылады.\n- Жаңа жол — `<br>` (жабатын тегі жоқ), жаңа абзац — `<p>`.\n\n## Мәтін\n- `<h1>`–`<h6>`: сан неғұрлым үлкен болса, тақырып соғұрлым кіші.\n- `<b>` / `<strong>` — қалың, `<i>` / `<em>` — көлбеу, `<sub>` / `<sup>` — төменгі / жоғарғы индекс, `<hr>` — сызық.\n- Туралау (ескірген, бірақ ҰБТ-да бар): `align=\"left | center | right | justify\"`, `<center>`; `<img align=\"right\">` — сурет шетте, мәтін айнала орналасады.\n\n## Тізімдер\n- `<ul>` — маркерлер, `<ol>` — нөмірлер (`type=\"a\"`, `start=\"5\"`), тармақ — `<li>`.\n- Ішкі тізім `<li>` **ішінде**. `<li>` саны — барлық деңгейдегі тармақтар саны.\n\n## Сілтемелер және суреттер\n- `<a href=\"мекенжай\" target=\"_blank\">мәтін</a>`, `<img src=\"файл\" alt=\"мәтін\" width=\"100\">`.\n- `href` — қайда апарады, `src` — файл қайдан, `alt` — сурет орнындағы мәтін.\n- Жол: `menu.html` — сол қалта, `img/a.png` — ішкі қалта, `../a.html` — бір қалта жоғары.\n\n## ҰБТ кеңестері\n- «Браузер не көрсетеді»: алдымен бос орындарды біреуге қысқарт, сосын `<br>` мен `<p>` сана.\n- Жолды сайттың түбірінен емес, беттің қалтасынан есепте."},
  "web-4-tables": {"ru":"# HTML: таблицы и формы\n\n## Таблицы\n\n- `<table border=\"1\">` → `<tr>` строка → `<th>` / `<td>` ячейка.\n- `colspan=\"n\"` — ячейка на n столбцов (вправо), `rowspan=\"n\"` — на n строк (вниз).\n- На места растянутой ячейки новые не пишут: в её строке (colspan) или в строках ниже (rowspan) ячеек меньше.\n- **Записано ячеек = строки × столбцы − лишние места** (colspan=3 даёт 2 лишних, rowspan=2 — 1).\n- Столбцы — по первой строке: сумма `colspan` (обычная ячейка — 1).\n\n## Формы\n\n- `<form action=\"…\" method=\"post\">`: `get` — данные в адресной строке, `post` — не видны там.\n- `<input>` — одиночный тег; вид задаёт `type`: `text` (по умолчанию), `password` (точки), `checkbox` (флажок, любое число), `radio` (переключатель, один из группы), `submit` (кнопка).\n- Кружки в одной группе — **одинаковый `name`**.\n- Парные: `<select>` + `<option>` (выпадающий список), `<textarea>` (много строк), `<label for=\"id\">` (подпись), `<button>`.\n\n## Лайфхаки для ЕНТ\n\n- В «сколько ячеек» считай по тегам, а не по сетке.\n- В «сколько можно выбрать» каждая группа radio и каждый select — по одному, checkbox — каждый.","kk":"# HTML: кестелер және формалар\n\n## Кестелер\n\n- `<table border=\"1\">` → `<tr>` жол → `<th>` / `<td>` ұяшық.\n- `colspan=\"n\"` — ұяшық n бағанға (оңға), `rowspan=\"n\"` — n жолға (төмен) созылады.\n- Созылған ұяшықтың орындарына жаңа ұяшық жазылмайды: оның жолында (colspan) немесе төменгі жолдарда (rowspan) ұяшық аз болады.\n- **Жазылған ұяшықтар = жол × баған − артық орындар** (colspan=3 — 2 артық, rowspan=2 — 1 артық орын береді).\n- Бағандар — бірінші жол бойынша: `colspan` мәндерінің қосындысы (қарапайым ұяшық — 1).\n\n## Формалар\n\n- `<form action=\"…\" method=\"post\">`: `get` — деректер мекенжай жолында, `post` — ол жерде көрінбейді.\n- `<input>` — жалғыз тег; түрін `type` береді: `text` (әдепкі), `password` (нүктелер), `checkbox` (жалауша, қалағанша), `radio` (ауыстырып-қосқыш, топтан біреуі), `submit` (түйме).\n- Бір топтағы дөңгелектердің `name` мәні **бірдей**.\n- Жұп тегтер: `<select>` + `<option>` (ашылмалы тізім), `<textarea>` (көп жол), `<label for=\"id\">` (жазу), `<button>`.\n\n## ҰБТ-ға арналған кеңестер\n\n- «Неше ұяшық» есебінде торды емес, тегтерді сана.\n- «Неше нұсқаны таңдауға болады» есебінде әр radio тобы мен әр select — біреуден, checkbox — әрқайсысы."},
  "web-5-layout": {"ru":"# CSS: блоки, отступы, выравнивание\n\n## Блочная модель\nИзнутри наружу: содержимое → `padding` → `border` → `margin`. `width` — только содержимое.\n- **ширина блока = width + 2·padding + 2·border**\n- **место на странице = ширина блока + 2·margin**\n- `box-sizing: border-box`: `width` уже включает padding и border.\n- Значения идут по часовой стрелке: сверху, справа, снизу, слева; два значения — верх/низ и право/лево.\n- Вертикальные margin соседних блоков не складываются: берётся большее.\n\n## display и выравнивание\n`block` — с новой строки, на всю ширину; `inline` — в строке, width не действует; `none` — убран и места не занимает.\n`text-align: center` — текст внутри блока; `margin: 0 auto` + `width` — сам блок.\n\n## Цвета\n`#RRGGBB`, `#RGB` (`#F80` = `#FF8800`), `rgb(R, G, B)`; `88` = 136.\n\n## Приоритет\n**style > id > класс > тег**; при равенстве побеждает правило ниже. Унаследованное (`color`, `font`, `text-align`) — самое слабое.\n\n## Ловушки ЕНТ\nwidth ≠ ширина блока; `margin: 0 auto` без width не работает; порядок имён в `class` не важен.","kk":"# CSS: блоктар, шегіністер, туралау\n\n## Блоктық модель\nІшкіден сыртқа: мазмұн → `padding` → `border` → `margin`. `width` — тек мазмұн.\n- **блок ені = width + 2·padding + 2·border**\n- **беттегі орын = блок ені + 2·margin**\n- `box-sizing: border-box`: `width` padding пен border-ді қамтиды.\n- Мәндер сағат тілі бойымен жүреді: жоғарыдан, оңнан, төменнен, солдан; екі мән — жоғары/төмен және оң/сол.\n- Көрші блоктардың тік margin мәндері қосылмайды: үлкені алынады.\n\n## display және туралау\n`block` — жаңа жолдан, бүкіл енімен; `inline` — жолда, width әрекет етпейді; `none` — алынады және орын алмайды.\n`text-align: center` — блок ішіндегі мәтін; `margin: 0 auto` + `width` — блоктың өзі.\n\n## Түстер\n`#RRGGBB`, `#RGB` (`#F80` = `#FF8800`), `rgb(R, G, B)`; `88` = 136.\n\n## Басымдық\n**style > id > класс > тег**; тең болса төменгі ереже жеңеді. Мұраланған мән (`color`, `font`, `text-align`) — ең әлсізі.\n\n## ҰБТ тұзақтары\nwidth ≠ блок ені; `margin: 0 auto` width-сіз жұмыс істемейді; `class` ішіндегі атаулар реті маңызды емес."},
};
